window.AI200_COMMUNITY = {"sets":[{"id":"suralmk:advanced-scenarios","name":"Advanced Scenarios","group":"suralmk","source":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/advanced-scenarios.json"},{"id":"suralmk:ai200-practice-set","name":"AI-200 Practice Set","group":"suralmk","source":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/ai200-practice-set.json"},{"id":"suralmk:azure-services-160","name":"Azure Services · Extended","group":"suralmk","source":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/azure-services-160.json"},{"id":"suralmk:azure-services","name":"Azure Services","group":"suralmk","source":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/azure-services.json"},{"id":"suralmk:containers-160","name":"Containers · Extended","group":"suralmk","source":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/containers-160.json"},{"id":"suralmk:containers","name":"Containers","group":"suralmk","source":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/containers.json"},{"id":"suralmk:data-management-160","name":"Data Management · Extended","group":"suralmk","source":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/data-management-160.json"},{"id":"suralmk:data-management","name":"Data Management","group":"suralmk","source":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/data-management.json"},{"id":"suralmk:sdk-cli-part1","name":"SDK CLI Part 1","group":"suralmk","source":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/sdk-cli-part1.json"},{"id":"suralmk:sdk-cli-part2","name":"SDK CLI Part 2","group":"suralmk","source":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/sdk-cli-part2.json"},{"id":"suralmk:secure-monitor-160","name":"Secure Monitor · Extended","group":"suralmk","source":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/secure-monitor-160.json"},{"id":"suralmk:secure-monitor","name":"Secure Monitor","group":"suralmk","source":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/secure-monitor.json"},{"id":"bouvet:acr","name":"ACR","group":"bouvet","source":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/acr.json"},{"id":"bouvet:aks","name":"AKS","group":"bouvet","source":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/aks.json"},{"id":"bouvet:app-service-containers","name":"App Service Containers","group":"bouvet","source":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/app-service-containers.json"},{"id":"bouvet:container-apps-keda","name":"Container Apps KEDA","group":"bouvet","source":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/container-apps-keda.json"},{"id":"bouvet:azure-managed-redis","name":"Azure Managed Redis","group":"bouvet","source":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/azure-managed-redis.json"},{"id":"bouvet:cosmos-db-nosql","name":"Cosmos DB NoSQL","group":"bouvet","source":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/cosmos-db-nosql.json"},{"id":"bouvet:postgresql-pgvector","name":"PostgreSQL pgvector","group":"bouvet","source":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/postgresql-pgvector.json"},{"id":"bouvet:azure-functions","name":"Azure Functions","group":"bouvet","source":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/03-connect-consume/azure-functions.json"},{"id":"bouvet:event-grid","name":"Event Grid","group":"bouvet","source":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/03-connect-consume/event-grid.json"},{"id":"bouvet:service-bus","name":"Service Bus","group":"bouvet","source":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/03-connect-consume/service-bus.json"},{"id":"bouvet:app-configuration","name":"App Configuration","group":"bouvet","source":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/app-configuration.json"},{"id":"bouvet:key-vault","name":"Key Vault","group":"bouvet","source":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/key-vault.json"},{"id":"bouvet:kql","name":"KQL","group":"bouvet","source":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/kql.json"},{"id":"bouvet:opentelemetry","name":"OpenTelemetry","group":"bouvet","source":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/opentelemetry.json"},{"id":"quizplay-set-3","name":"Question set 3","group":"quizplay-set-3","source":"https://github.com/quizplay-io/quiz-player-quizzes-ai-200-question-set-3/blob/b158ee5f8717ecd671bf6ea2b748cf09e83e048b/README.md"}],"questions":[{"id":"suralmk:adv-001","prompt":"An ACR pipeline must rebuild an image after its base image changes and assess the resulting registry image for vulnerabilities. What should be configured?","explanation":"Use an ACR Task base-image trigger and Defender for Cloud vulnerability assessment. Scanning is asynchronous and does not itself quarantine images or block deployment. If promotion must wait for a pass, implement a separate verified promotion/admission gate.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/defender-for-cloud/agentless-vulnerability-assessment-azure","topic":"acr","type":"single","options":["Configure an ACR Task with a source-repository commit trigger only, then use Azure Policy to deny pulls of non-compliant images after publish","Configure a base image update trigger on the ACR Task, and enable Microsoft Defender for Cloud container image scanning on the registry","Configure a scheduled cron ACR Task that rebuilds nightly from the base tag, then manually run az acr repository show-manifests after each rebuild","Configure a webhook from Azure DevOps that starts an ACR build on release approval, and scan images with a custom container scan step in the CI pipeline"],"answer":1,"setId":"suralmk:advanced-scenarios","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/advanced-scenarios.json","reviewDate":"2026-10-11","reviewNote":"Defender scanning after push does not automatically block pulls until a scan passes."},{"id":"suralmk:adv-002","prompt":"A containerized inference API on Azure App Service (Linux, custom container) needs a database connection string and a third-party API key at startup. Security requires that no secret value is ever stored as plain text in App Service configuration, and that the values automatically reflect the current version in Key Vault after rotation, without redeploying the app.\n\nWhat should you configure?","explanation":"Managed identity and versionless Key Vault references keep literal secret values out of persisted app settings. The resolved value is available to the app at runtime. Refresh can take up to 24 hours unless forced; rotation automation must also update the backing credential.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/app-service/app-service-key-vault-references","topic":"key-vault","type":"single","options":["Store both secrets as plain Application Settings values and update those settings manually whenever Key Vault rotations occur in the environment","Assign a system-assigned managed identity to the App Service, grant it Key Vault access, and use Key Vault references in Application Settings","Pass the secret values as Docker build-time ARG/ENV instructions so they are baked into image layers and never appear in App Service settings","Mount an Azure Files share containing a secrets text file into the container and have the entrypoint script read credentials at startup"],"answer":1,"setId":"suralmk:advanced-scenarios","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/advanced-scenarios.json","reviewDate":"2026-10-11","reviewNote":"Added secret refresh timing and runtime exposure."},{"id":"suralmk:adv-003","prompt":"A document-classification workload runs in Azure Container Apps and reads from a Service Bus queue. Volume varies from zero overnight to several thousand messages during business hours. Security does not want the Service Bus connection string stored as plain text anywhere in the Container App definition.\n\nWhich combination should you configure?","explanation":"In Container Apps, configure the scale rule identity and Service Bus namespace/queue metadata. Grant the identity appropriate access. Kubernetes TriggerAuthentication is a KEDA resource for Kubernetes; it is not deployed directly into the managed Container Apps API.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/container-apps/scale-app","topic":"service-bus","type":"single","options":["Configure an azure-servicebus custom scale rule with a managed identity granted Service Bus Data Receiver and minReplicas=0","A CPU utilization scale rule with minReplicas set to 1, storing the Service Bus connection string directly in a Container App environment variable value","A KEDA cron scale rule that increases replica count during business hours only, ignoring actual Service Bus queue depth when scaling decisions run","An HTTP scale rule targeting the Service Bus REST management endpoint, with the connection string placed in the scale rule metadata fields"],"answer":0,"setId":"suralmk:advanced-scenarios","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/advanced-scenarios.json","reviewDate":"2026-10-11","reviewNote":"Container Apps scale rules use identity/auth configuration, not a user-deployed TriggerAuthentication resource."},{"id":"suralmk:adv-004","prompt":"Pods running an AI inference container in AKS intermittently show a Running status but stop responding to requests. Container Insights shows no CPU or memory pressure. You suspect the issue may be DNS resolution to an internal Cosmos DB private endpoint intermittently failing.\n\nWhat is the most effective sequence to isolate the root cause?","explanation":"Isolate suspected DNS/network issues by **testing connectivity from inside the affected pod** (`kubectl exec`, `nslookup`, `curl`) and correlating with logs and network rules — not by guessing at resource or infrastructure causes.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/cosmos-db/nosql/","topic":"cosmos-db-nosql","type":"single","options":["Raise the Deployment CPU and memory requests and limits, then roll out a new revision, treating intermittent failures as resource contention","Exec into an affected pod to test DNS and private-endpoint connectivity, then correlate results with Container Insights logs and network policy or NSG rules","Delete and recreate the AKS user node pool that hosts the inference pods, assuming intermittent failures usually originate from unhealthy nodes","Disable the Cosmos DB private endpoint and temporarily allow public network access so you can rule out private networking as a factor"],"answer":1,"setId":"suralmk:advanced-scenarios","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/advanced-scenarios.json","reviewDate":"2026-10-11"},{"id":"suralmk:adv-005","prompt":"You are rolling out a new revision of a RAG API in Azure Container Apps. You want 90% of production traffic to keep going to the stable revision and 10% to the new revision, want both revisions addressable by a fixed label for internal testing regardless of which is \"latest,\" and want to shift more traffic gradually over several days without redeploying.\n\nWhat should you configure?","explanation":"**Multiple revisions mode** with **revision labels** and configurable **traffic-weight percentages** lets you split traffic precisely, test via label URLs, and adjust weights gradually without redeploying.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/container-apps/scale-app","topic":"container-apps-keda","type":"single","options":["Single active revision mode that deactivates the previous revision as soon as the new revision is healthy and takes all production traffic","Multiple revisions with revision labels on both, traffic-weight percentages split 90/10, then adjust weights gradually without redeploying the app","A second Container App hosting only the new revision, with Azure Front Door weighted routing splitting traffic between the two Container App endpoints","HTTP concurrency scale rules on both revisions so replica counts indirectly determine how much production traffic each revision receives"],"answer":1,"setId":"suralmk:advanced-scenarios","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/advanced-scenarios.json","reviewDate":"2026-10-11"},{"id":"suralmk:adv-006","prompt":"You are writing AKS manifests for a stateless embedding-generation service that must scale horizontally based on CPU load, has no need for stable network identities or per-replica persistent storage, and should be evenly load-balanced across replicas.\n\nWhat should the manifest define?","explanation":"A stateless, horizontally scalable workload with no per-replica identity or storage maps to a **Deployment** plus **HPA**, fronted by a **Service** — not a StatefulSet or DaemonSet.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/aks/concepts-clusters-workloads","topic":"aks","type":"single","options":["A StatefulSet with volumeClaimTemplates and a headless Service so each embedding replica keeps stable network identity and dedicated storage","A DaemonSet scheduled on every node so exactly one embedding replica runs per node regardless of observed CPU utilization across the cluster","A Deployment with a HorizontalPodAutoscaler targeting CPU utilization, fronted by a ClusterIP or LoadBalancer Service for even distribution","A bare Pod manifest plus a manual kubectl scale workflow that operators update whenever CPU utilization exceeds an agreed operational threshold value"],"answer":2,"setId":"suralmk:advanced-scenarios","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/advanced-scenarios.json","reviewDate":"2026-10-11"},{"id":"suralmk:adv-007","prompt":"A company deploys AI inference containers to AKS clusters in three Azure regions and wants each region to pull images from a registry replica in its own region to reduce latency and cross-region egress, while also requiring the registry to be reachable only via Private Link, with no public endpoint at all.\n\nWhich ACR configuration is required?","explanation":"**Geo-replication** and **Private Link** with public access disabled both require **Premium tier** ACR. Basic/Standard cannot provide either capability together.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/aks/concepts-clusters-workloads","topic":"aks","type":"single","options":["Basic tier ACR with three separate registries, one in each region, kept in sync by a custom pipeline that copies tags between registries","Standard tier ACR with a registry firewall allowlisting the outbound IPs of each regional AKS cluster subnet for image pull operations","Premium tier ACR with geo-replication to all three regions, private endpoints enabled, and public network access disabled on the registry","Standard tier ACR fronted by Azure Traffic Manager, which routes each AKS pull request to the geographically nearest registry hostname"],"answer":2,"setId":"suralmk:advanced-scenarios","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/advanced-scenarios.json","reviewDate":"2026-10-11"},{"id":"suralmk:adv-008","prompt":"You store 1536-dimension embeddings for several million documents in an Azure Cosmos DB for NoSQL container. You need the lowest possible query latency and RU cost at this scale, and you are willing to accept a small amount of approximation to get there.\n\nWhich vector index type should you configure in the container's indexing policy?","explanation":"**diskANN** is the approximate index designed for large, high-dimensional datasets — trading a small amount of accuracy for significantly lower latency and RU cost than flat or quantizedFlat at millions of vectors.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/cosmos-db/nosql/","topic":"cosmos-db-nosql","type":"single","options":["flat, which performs an exact brute-force vector comparison and is recommended mainly for smaller embedding collections with modest query volume","quantizedFlat, which balances accuracy and cost by quantizing vectors and suits moderate-sized datasets better than a full diskANN index","diskANN, an approximate nearest-neighbor index optimized for large-scale, high-dimensional search with lower latency and RU cost at scale","None — omit a vector index and compute cosine similarity in the application after a full container scan returns candidate documents"],"answer":2,"setId":"suralmk:advanced-scenarios","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/advanced-scenarios.json","reviewDate":"2026-10-11"},{"id":"suralmk:adv-009","prompt":"A Cosmos DB for NoSQL container storing chat-session documents uses sessionId as the partition key. As the app scales, most reads and writes concentrate on a small number of very active sessions, creating hot partitions, while an indexing policy that indexes every property is also driving up write RU cost.\n\nWhat should you do to address both issues?","explanation":"Fix **hot partitions** with a better-distributed partition key, and reduce write RU by **narrowing the indexing policy** to only queried paths. More RU/s or TTL alone does not fix either root cause.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/cosmos-db/nosql/","topic":"cosmos-db-nosql","type":"single","options":["Use a higher-cardinality synthetic partition key for even access distribution, and narrow the indexing policy to only paths used by actual queries","Increase provisioned throughput (RU/s) on the container until hot-partition throttling stops, leaving partition key and indexing unchanged","Collapse all session documents into a single logical partition so query patterns stay simple, then scale compute on the application tier","Enable a short TTL on every item so older session data expires quickly, assuming reduced item count alone will eliminate hot partitions"],"answer":0,"setId":"suralmk:advanced-scenarios","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/advanced-scenarios.json","reviewDate":"2026-10-11"},{"id":"suralmk:adv-010","prompt":"You need multiple instances of a serverless function to process the Cosmos DB change feed for a container in parallel, with automatic load balancing across instances and the ability to resume from where processing left off after a restart.\n\nWhat must you configure?","explanation":"The change feed processor requires a **lease container** to persist checkpoints — this enables multiple instances to divide partitions and resume correctly after a restart.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/azure-functions/functions-overview","topic":"azure-functions","type":"single","options":["A lease container that the change feed processor uses for checkpoints so parallel instances can divide partitions and resume after restarts","An in-memory polling loop that queries documents by _ts on a timer and stores the last processed timestamp only inside each function instance","A Service Bus queue that receives every Cosmos DB write via a stored trigger, replacing the change feed processor with queue-based fan-out","A pre-trigger stored procedure that runs on each write and synchronously copies the changed document into Blob Storage for later batch processing"],"answer":0,"setId":"suralmk:advanced-scenarios","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/advanced-scenarios.json","reviewDate":"2026-10-11"},{"id":"suralmk:adv-011","prompt":"A globally distributed Cosmos DB account, replicated across three regions, backs an AI recommendation service. The team wants reads within a single client session to always reflect that client's own most recent writes, while keeping cross-region read latency low. They accept that a read from a different session might briefly lag behind a very recent write made by another session.\n\nWhich consistency level best fits this requirement?","explanation":"**Session consistency** guarantees read-your-own-writes within a session with low latency — better than Strong (higher latency) or Eventual/Consistent Prefix (no read-your-writes guarantee).","domain":"data","source":"https://learn.microsoft.com/en-us/azure/cosmos-db/nosql/","topic":"cosmos-db-nosql","type":"single","options":["Strong consistency, which guarantees every read in every region always reflects the most recent committed write across the entire account","Eventual consistency, which allows reads to return any previously written value with no session affinity or ordering guarantees for client sessions","Session consistency, which guarantees read-your-own-writes within a client session at low latency while other sessions may briefly see stale data","Consistent prefix, which ensures clients never observe out-of-order writes but does not guarantee a session always sees its own latest writes"],"answer":2,"setId":"suralmk:advanced-scenarios","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/advanced-scenarios.json","reviewDate":"2026-10-11"},{"id":"suralmk:adv-012","prompt":"A team is choosing a vector index for an embeddings table in Azure Database for PostgreSQL with pgvector. The table receives continuous inserts, and query-time recall and speed matter more than index build time or memory footprint.\n\nWhich index type and consideration is most appropriate?","explanation":"**HNSW** incrementally accommodates new data and generally delivers better recall/speed than **IVFFlat**, which can become stale as clusters age with continuous inserts.","domain":"data","source":"https://github.com/pgvector/pgvector","topic":"postgresql-pgvector","type":"single","options":["An IVFFlat index with a small lists parameter, because it rebuilds quickly after each insert batch and keeps memory usage lower than graph indexes","An HNSW index, which typically offers better query recall and speed than IVFFlat, accepts incremental inserts, and avoids periodic full re-clustering as data grows","No vector index, relying on sequential scans of the embedding column, which remain efficient for any table size when the server has sufficient RAM","A B-tree index on the embedding column, because PostgreSQL default indexes support arbitrary column types and nearest-neighbor lookups efficiently"],"answer":1,"setId":"suralmk:advanced-scenarios","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/advanced-scenarios.json","reviewDate":"2026-10-11"},{"id":"suralmk:adv-013","prompt":"Query latency for a pgvector similarity search has degraded as the embeddings table has grown, and monitoring shows the working set for the HNSW index no longer fits in memory, causing frequent disk reads during searches.\n\nWhat is the most direct fix?","explanation":"Add sufficient RAM for the workload and measure buffer/OS-cache effectiveness. shared_buffers allocates shared database buffers; effective_cache_size is an optimizer estimate of available caching, not an allocation and not a promise the index stays resident.","domain":"data","source":"https://www.postgresql.org/docs/current/runtime-config-query.html","topic":"postgresql-pgvector","type":"single","options":["Replace the HNSW index with IVFFlat, assuming IVFFlat always uses less memory than HNSW for any dataset size and query pattern","Set ef_search to zero for similarity queries so the planner skips HNSW graph traversal and returns results without reading index pages","Scale to a compute tier with more memory and tune shared_buffers and effective_cache_size so the HNSW working set stays resident in RAM","Move the embedding column into a separate table without a vector index so the primary table stays smaller and scans fewer pages"],"answer":2,"setId":"suralmk:advanced-scenarios","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/advanced-scenarios.json","reviewDate":"2026-10-11","reviewNote":"effective_cache_size is a planner estimate, not allocated RAM."},{"id":"suralmk:adv-014","prompt":"Your RAG application must retrieve the top-k most similar chunks, but only from documents belonging to the current tenant. Testing shows that running the vector similarity search across the whole table and filtering by tenant afterward returns too few relevant results when a tenant has few documents relative to the whole table.\n\nWhat should you do?","explanation":"Put the authorized tenant predicate in the SQL query with vector ORDER BY and LIMIT. With an approximate index, filtering can still occur after candidate retrieval and return fewer than k rows. Consider iterative scans, higher search effort, partial indexes/partitioning, or exact search for small subsets; measure recall.","domain":"data","source":"https://github.com/pgvector/pgvector","topic":"postgresql-pgvector","type":"single","options":["Increase the global top-k value so that after client-side tenant filtering, enough tenant-specific chunks remain for small tenants","Apply the tenant_id predicate in the same SQL query with the vector ORDER BY and LIMIT k so ranking occurs within the tenant subset","Create a separate embeddings table for each tenant so every similarity query runs against an isolated table that never needs filtering","Download the full embeddings table into application memory and run cosine similarity plus tenant filtering entirely outside PostgreSQL queries"],"answer":1,"setId":"suralmk:advanced-scenarios","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/advanced-scenarios.json","reviewDate":"2026-10-11","reviewNote":"Same-query metadata filters do not guarantee ANN top-k recall."},{"id":"suralmk:adv-015","prompt":"A serverless AI function opens a connection to Azure Database for PostgreSQL on each short-lived invocation, issues one or two simple queries, and closes the connection. Under load, the database reports connection exhaustion even though most connections are idle most of the time.\n\nWhat should you implement?","explanation":"**PgBouncer in transaction pooling mode** returns server connections to the pool after each transaction — ideal for many short-lived serverless invocations doing one or two statements.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/azure-functions/functions-overview","topic":"azure-functions","type":"single","options":["A PgBouncer-style connection pooler in transaction pooling mode that returns server connections to the pool after each short transaction","A connection pooler in session pooling mode that keeps a dedicated server connection for the entire lifetime of each client session","A much higher max_connections setting on PostgreSQL with no pooler, accepting more concurrent sockets to avoid any pooling overhead on short queries","A single permanently open Npgsql connection shared by all concurrent function invocations through a static singleton in process memory"],"answer":0,"setId":"suralmk:advanced-scenarios","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/advanced-scenarios.json","reviewDate":"2026-10-11"},{"id":"suralmk:adv-016","prompt":"An Azure Managed Redis cache stores a mix of session data with explicit TTLs and frequently recomputed AI response fragments with no TTL set. Memory usage is approaching capacity, and the team wants Redis to evict least-recently-used keys, but only from the subset of keys that actually have a TTL, leaving keys without a TTL untouched even under memory pressure.\n\nWhich eviction policy should you configure?","explanation":"**volatile-lru** evicts LRU keys **only among keys with a TTL**, protecting untimed AI response fragments from eviction under memory pressure.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/redis/","topic":"azure-managed-redis","type":"single","options":["noeviction, which refuses new writes with an error when memory is full and never removes existing keys under pressure","allkeys-lru, which evicts the least recently used key among all keys in the dataset, including keys without a TTL","volatile-lru, which evicts the least recently used key only among keys that have a TTL set, leaving keys without a TTL intact under pressure","allkeys-random, which deletes a randomly selected key from the entire keyspace whenever Redis needs memory for a write"],"answer":2,"setId":"suralmk:advanced-scenarios","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/advanced-scenarios.json","reviewDate":"2026-10-11"},{"id":"suralmk:adv-017","prompt":"You are configuring vector search in Azure Managed Redis for a recommendation feature that needs approximate nearest-neighbor search with strong query throughput on a large, frequently updated dataset, using cosine similarity between embeddings.\n\nWhat should you configure?","explanation":"**HNSW** with **COSINE** distance is the approximate-search index built for large, frequently updated datasets with cosine similarity requirements.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/redis/","topic":"azure-managed-redis","type":"single","options":["A FLAT index with the L2 distance metric, assuming exact search is always faster than approximate search for large, frequently updated embedding collections","An HNSW index with the COSINE distance metric for approximate nearest-neighbor search suited to large, frequently updated embedding datasets","A Redis Sorted Set that stores precomputed dot-product scores as member scores and rebuilds those scores on every embedding write operation","A Redis Hash holding raw embedding vectors with no index, using SCAN plus client-side cosine similarity for each recommendation query"],"answer":1,"setId":"suralmk:advanced-scenarios","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/advanced-scenarios.json","reviewDate":"2026-10-11"},{"id":"suralmk:adv-018","prompt":"An order-processing system must guarantee that all messages for a single customer are processed strictly in the order they were sent, even though many customers' messages interleave on the same queue. Messages that fail processing after several attempts must be removed from the main queue automatically so they don't block that customer's remaining messages, while still being retained for manual review.\n\nWhat should you configure?","explanation":"**Sessions** guarantee strict per-customer ordering on a shared queue. **Max delivery count** routes exhausted messages to the **dead-letter queue** without blocking the rest of that customer's session.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/service-bus-messaging/service-bus-messaging-overview","topic":"service-bus","type":"single","options":["A session-enabled Service Bus queue with session ID per customer, plus max delivery count so exhausted messages move to the dead-letter queue","A non-sessioned Service Bus queue with a single consumer thread, relying only on FIFO delivery order across all customers on that shared queue endpoint","A Service Bus topic with one subscription per customer and no dead-letter configuration, expecting failed messages to stay invisible after retries","An Azure Storage queue with visibility timeout set to zero so failed messages become immediately available to any other competing consumer"],"answer":0,"setId":"suralmk:advanced-scenarios","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/advanced-scenarios.json","reviewDate":"2026-10-11"},{"id":"suralmk:adv-019","prompt":"A Service Bus topic publishes events for all order-state changes. One subscriber needs only events where a custom property priority equals \"high\" AND region equals \"EU\"; a second subscriber needs only events matching a specific correlationId tied to one workflow instance.\n\nWhich filter types should you configure, respectively?","explanation":"SQL filters support Boolean expressions. Correlation filters efficiently match CorrelationId and can combine multiple equality properties. They are not restricted to a single property. Remove an existing default true rule when it would bypass the intended filtering.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/service-bus-messaging/topic-filters","topic":"service-bus","type":"single","options":["Correlation filters on both subscriptions, because correlation filters can evaluate arbitrary boolean expressions on custom properties","A SQL filter on the first subscription for the priority and region expression, and a correlation filter on the second matching CorrelationId exactly","SQL filters on both subscriptions, because correlation filters are deprecated in Service Bus and can no longer match CorrelationId values","No subscription filters; publish high-priority EU events and correlation-scoped events to two separate topics that each subscriber reads"],"answer":1,"setId":"suralmk:advanced-scenarios","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/advanced-scenarios.json","reviewDate":"2026-10-11","reviewNote":"Correlation filters can match multiple equality properties."},{"id":"suralmk:adv-020","prompt":"A company publishes blob-upload events from Azure Storage and also needs a downstream partner system, running on a different cloud provider, to consume the same event stream using a vendor-neutral, standardized event format rather than a proprietary schema.\n\nWhat should you configure?","explanation":"Event Grid subscriptions can deliver events in the **CloudEvents v1.0** schema — a vendor-neutral standard for cross-platform interoperability.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/event-grid/overview","topic":"event-grid","type":"single","options":["An Event Grid custom topic that delivers using the Event Grid schema only, assuming that schema is universally supported across every cloud platform","An Event Grid subscription that delivers events using the CloudEvents v1.0 schema instead of the proprietary Event Grid event schema","A Service Bus topic replacing Event Grid, assuming Service Bus message bodies are inherently vendor-neutral across cloud providers without mapping","An Azure Function that reformats each event manually and writes it to Blob Storage for the partner to poll, without using Event Grid delivery schemas"],"answer":1,"setId":"suralmk:advanced-scenarios","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/advanced-scenarios.json","reviewDate":"2026-10-11"},{"id":"suralmk:adv-021","prompt":"An AI orchestration function needs to call a database only reachable via VNET integration, must avoid cold-start delays for latency-sensitive requests, and occasionally runs single invocations longer than the 10-minute maximum execution limit on the Consumption plan.\n\nWhich hosting plan should you choose?","explanation":"Premium supports VNet integration and prewarmed capacity with configurable longer execution timeouts. Classic Consumption defaults to five minutes and has a ten-minute maximum. HTTP response limits and platform restarts still apply independently.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/azure-functions/functions-scale","topic":"azure-functions","type":"single","options":["Consumption plan, because automatic scale-to-zero and per-execution billing make it the best fit for any latency-sensitive, long-running VNET-integrated workload","Premium plan, which supports VNET integration, pre-warmed instances to avoid cold starts, and longer execution durations than the Consumption plan","Dedicated (App Service) plan only, because Azure Functions cannot use VNET integration on Premium or Flex Consumption under any configuration","Flex Consumption with the default timeout unchanged, treating VNET integration and cold-start avoidance as unrelated to the chosen hosting plan"],"answer":1,"setId":"suralmk:advanced-scenarios","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/advanced-scenarios.json","reviewDate":"2026-10-11","reviewNote":"Consumption default timeout is five minutes; ten minutes is its configurable maximum."},{"id":"suralmk:adv-022","prompt":"You need to generate embeddings for 10,000 documents. Each document's embedding can be computed independently and in parallel, but you must wait until all 10,000 are complete before writing a single aggregated summary record.\n\nWhich Durable Functions pattern fits this requirement?","explanation":"**Fan-out/fan-in** launches many independent parallel activities and waits for all to complete before aggregation — matching this embedding workload exactly.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/azure-functions/functions-overview","topic":"azure-functions","type":"single","options":["Function chaining, where each document embedding activity runs only after the previous document finishes, forming one sequential pipeline","Fan-out/fan-in, where an orchestrator starts many activity instances in parallel and waits for all to complete before aggregating results","Human interaction, where the orchestration waits for an external approval event before continuing to the aggregation step after all embeddings finish","Monitor, where a single activity polls one resource on a fixed interval until a condition is met, then writes the aggregated summary record"],"answer":1,"setId":"suralmk:advanced-scenarios","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/advanced-scenarios.json","reviewDate":"2026-10-11"},{"id":"suralmk:adv-023","prompt":"An Event Grid subscription occasionally fails to deliver events to an Azure Function endpoint due to transient errors. Events must be retried automatically for a bounded period, and any event that still cannot be delivered after retries are exhausted should be captured durably for later inspection rather than silently dropped.\n\nWhat should you configure on the subscription?","explanation":"Event Grid's **retry policy** (max attempts, TTL) governs bounded retries, and a configured **dead-letter destination** captures events that still fail — rather than dropping them silently.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/event-grid/overview","topic":"event-grid","type":"single","options":["A shorter event time-to-live with no dead-letter destination, assuming Event Grid retries forever until the endpoint accepts delivery","A retry policy with max delivery attempts and event TTL, plus a dead-letter destination such as a Storage container for events that still fail after retries","A Service Bus-style native dead-letter queue on the Event Grid topic itself, because Event Grid topics expose the same DLQ as Service Bus","Retries disabled on the subscription, plus a health probe against the Function endpoint before every delivery attempt to avoid failures"],"answer":1,"setId":"suralmk:advanced-scenarios","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/advanced-scenarios.json","reviewDate":"2026-10-11"},{"id":"suralmk:adv-024","prompt":"A telemetry pipeline for an AI-powered IoT solution ingests several million small events per second from many devices; multiple downstream consumers need to read at their own pace and be able to replay from an earlier point in the stream. This differs from other workloads in the same system — discrete business events like \"order placed\" needing pub/sub fan-out to a handful of services, and transactional processing with strict per-customer ordering.\n\nWhich service is the best fit specifically for the high-throughput telemetry ingestion requirement, and why?","explanation":"**Event Hubs** is built for massive-scale event streaming with partitions and offset-based replay — distinct from Service Bus (business messaging) or Event Grid (discrete notifications).","domain":"services","source":"https://learn.microsoft.com/en-us/azure/azure-monitor/app/opentelemetry-overview","topic":"opentelemetry","type":"single","options":["Service Bus topics, because they support many subscriptions and are optimized for multi-million EPS streaming with consumer-controlled offset replay","Event Grid, because it is designed for continuous high-throughput telemetry streams and lets consumers replay from earlier offsets in the stream","Event Hubs, because it supports high-throughput partitioned streaming with retention so multiple consumers can read and replay from earlier offsets","Azure Queue Storage, because it scales without a practical throughput ceiling and provides partitioned offset-based replay for multiple concurrent consumers"],"answer":2,"setId":"suralmk:advanced-scenarios","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/advanced-scenarios.json","reviewDate":"2026-10-11"},{"id":"suralmk:adv-025","prompt":"You are provisioning several Container Apps that all need identical Key Vault access permissions. You want to grant the Key Vault role assignment once, before any of the Container Apps exist, and then attach the same identity to each Container App as it's created, without repeating the role assignment for every app.\n\nWhich identity type should you use?","explanation":"A **user-assigned managed identity** exists independently of any single resource — grant access once, then attach the same identity to multiple Container Apps.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/key-vault/general/overview","topic":"key-vault","type":"single","options":["A system-assigned managed identity on each Container App, created with the resource and granted Key Vault access separately for every newly provisioned app","A user-assigned managed identity created independently, granted the Key Vault role once, then attached to each Container App as it is provisioned","A shared Microsoft Entra application whose client secret is stored in each Container App environment variable for Key Vault access","No managed identity; instead a Key Vault access policy that allows anonymous get operations from the Container Apps subnet ranges"],"answer":1,"setId":"suralmk:advanced-scenarios","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/advanced-scenarios.json","reviewDate":"2026-10-11"},{"id":"suralmk:adv-026","prompt":"Your app loads dozens of configuration values from Azure App Configuration at startup, and you want it to automatically pick up changes to any of those values while running, without polling every individual key on every request, and only refresh when something has actually changed.\n\nWhat should you implement?","explanation":"Monitor a sentinel key, update it after the configuration batch, and invoke provider refresh from the application. The provider throttles checks to the configured interval and reloads selected settings when the sentinel changes. Python does not automatically start a polling thread.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/azure-app-configuration/enable-dynamic-configuration-python","topic":"app-configuration","type":"single","options":["A dedicated sentinel key that the app monitors; when that key changes, the app refreshes its full cached configuration set from Azure App Configuration","A middleware path that calls GetConfigurationSetting for every registered key on each incoming HTTP request before the handler runs","Disabled client-side caching so every configuration read issues a direct GetConfigurationSetting call to Azure App Configuration","An automated redeployment pipeline that restarts the app whenever any App Configuration key changes, because runtime refresh is unsupported"],"answer":0,"setId":"suralmk:advanced-scenarios","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/advanced-scenarios.json","reviewDate":"2026-10-11","reviewNote":"A sentinel pattern needs application-driven refresh."},{"id":"suralmk:adv-027","prompt":"You want distributed traces from an Azure Function, a Container App, and an external REST API to appear as a single connected trace in Application Insights, with parent-child span relationships preserved across the HTTP calls between services.\n\nWhat must be true for this to work correctly?","explanation":"Preserve trace IDs and parent relationships across boundaries and ensure the spans reach the backend. OpenTelemetry is a suitable implementation, but compatible instrumentation can also participate. An uninstrumented external API will not supply internal spans.","domain":"operations","source":"https://opentelemetry.io/docs/concepts/context-propagation/","topic":"opentelemetry","type":"single","options":["Each service writes independent local log files, and Application Insights stitches those files into one trace by matching timestamps","Instrument the participating services, propagate compatible W3C trace context, and export correlated telemetry to the monitored backend","Only the entry-point service needs OpenTelemetry; Azure automatically instruments downstream Functions and Container Apps into the same trace","All participating services must be deployed in the same Azure region and resource group for Application Insights to correlate parent and child spans correctly"],"answer":1,"setId":"suralmk:advanced-scenarios","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/advanced-scenarios.json","reviewDate":"2026-10-11","reviewNote":"Interoperable tracing does not require every service to use the same SDK."},{"id":"suralmk:adv-028","prompt":"You need to visualize how the count of exceptions, grouped by exception type, has changed over the last 24 hours in 1-hour buckets, using the exceptions table in Application Insights/Log Analytics.\n\nWhich KQL query structure achieves this?","explanation":"`summarize count() by type, bin(timestamp, 1h)` buckets counts hourly per exception type; `render timechart` visualizes the time series.\n\n```kusto\nexceptions\n| where timestamp > ago(24h)\n| summarize count() by type, bin(timestamp, 1h)\n| render timechart\n```","domain":"operations","source":"https://learn.microsoft.com/en-us/kusto/query/","topic":"kql","type":"single","options":["exceptions | where timestamp > ago(24h) | summarize count() by type, bin(timestamp, 1h) | render timechart","exceptions | where timestamp > ago(24h) | summarize dcount(operation_Id) by cloud_RoleName, bin(timestamp, 1h) | render barchart","exceptions | where timestamp > ago(24h) | summarize avg(itemCount) by bin(timestamp, 1d) | render piechart","exceptions | where timestamp > ago(24h) | top 50 by timestamp desc | project type, outerMessage | render table"],"answer":0,"setId":"suralmk:advanced-scenarios","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/advanced-scenarios.json","reviewDate":"2026-10-11"},{"id":"suralmk:adv-029","prompt":"You want a secret in Key Vault to rotate automatically on a schedule before it expires, and you want an Event Grid-based notification sent to a Function so the team can proactively handle downstream systems that cache the secret — rather than discovering the rotation only after something breaks.\n\nWhat should you configure?","explanation":"Built-in rotation policies apply to keys. Arbitrary secrets require custom or service-specific rotation logic. Update the credential at its issuing system, store the new version, and ensure clients refresh safely.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/key-vault/secrets/tutorial-rotation","topic":"key-vault","type":"single","options":["A shared calendar reminder for operators to rotate the secret manually, because Key Vault has no native rotation policy or Event Grid hooks","Set secret expiry and route Key Vault near-expiry events through Event Grid to a Function that rotates the backing credential and writes a new secret version","A Logic App that polls each secret value daily, compares it to a cached copy in storage, and alerts only after detecting that a rotation has already occurred","Move the secret into App Configuration feature flags, because only App Configuration emits native rotation notifications that Functions can subscribe to"],"answer":1,"setId":"suralmk:advanced-scenarios","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/advanced-scenarios.json","reviewDate":"2026-10-11","reviewNote":"Replaced nonexistent secret rotation policies with a rotation handler."},{"id":"suralmk:adv-030","prompt":"Customers report slow responses from an AI service composed of an AKS-hosted API, an Azure Function, and Cosmos DB. You need to determine which specific hop in the chain contributes the most latency, and whether the slowdown correlates with a specific dependency (e.g., Cosmos DB throttling) rather than application code.\n\nWhat is the most effective combination of tools/approach?","explanation":"**Application Map** and end-to-end transactions pinpoint the slow hop; **KQL** correlating dependency telemetry with Cosmos DB **429 throttling** confirms or rules out a specific dependency as the cause.","domain":"operations","source":"https://learn.microsoft.com/en-us/kusto/query/","topic":"kql","type":"single","options":["Review only AKS pod CPU and memory metrics in Container Insights, assuming multi-hop latency is almost always caused by node resource exhaustion","Use Application Map and end-to-end transactions to find the slow hop, then KQL-join dependency telemetry with Cosmos DB logs for HTTP 429 throttling correlation","Restart the AKS Deployment, the Function app, and the Cosmos DB account in sequence to see whether the latency complaint disappears after each restart","Collect customer-reported timestamps only and manually attribute each slow response to AKS, Functions, or Cosmos DB without distributed telemetry"],"answer":1,"setId":"suralmk:advanced-scenarios","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/advanced-scenarios.json","reviewDate":"2026-10-11"},{"id":"suralmk:practice-001","prompt":"A multi-stage Dockerfile uses a full Python image for compiling wheels and a slim Python image for its final stage. Only wheels and application code are copied to the final stage. Would changing only the builder base to slim necessarily reduce the published final image?","explanation":"Intermediate stage layers are not automatically included in the final image. A slim builder can reduce build-stage footprint but does not inherently reduce a separately defined final runtime image. Inspect copied artifacts and runtime dependencies.","domain":"containers","source":"https://docs.docker.com/build/building/multi-stage/","topic":"azure-functions","type":"single","options":["No; final-image size depends on its own base and the artifacts copied into it","Yes; every builder layer is included in the final image","Yes; builder and runtime layers are always merged","No; multi-stage builds cannot omit build tools"],"answer":0,"setId":"suralmk:ai200-practice-set","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/ai200-practice-set.json","reviewDate":"2026-10-11","reviewNote":"Corrected the multi-stage image-size answer."},{"id":"suralmk:practice-002","prompt":"CI tags an image with its Git commit SHA. How should production deployment ensure the exact image content is selected even if somebody later overwrites that tag?","explanation":"Tags, including Git-SHA tags, are mutable unless protected. A digest identifies content. Preserve build provenance and use repository/image write controls for release tags.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/container-registry/container-registry-image-tag-version","topic":"acr","type":"single","options":["Deploy the immutable image digest and protect release tags from overwrite","Assume any SHA-shaped tag is automatically immutable","Use latest without recording a digest","Rebuild the image independently in each region"],"answer":0,"setId":"suralmk:ai200-practice-set","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/ai200-practice-set.json","reviewDate":"2026-10-11","reviewNote":"A commit-derived tag alone does not enforce immutability."},{"id":"suralmk:practice-003","prompt":"You are deploying a container app that must pull its image from a private ACR without embedding registry credentials as secrets:\n```bicep\nresource containerApp 'Microsoft.App/containerApps@2024-03-01' = {\n  name: 'orders-api'\n  location: location\n  identity: {\n    type: 'UserAssigned'\n    userAssignedIdentities: {\n      '${uami.id}': {}\n    }\n  }\n  properties: {\n    configuration: {\n      registries: [\n        {\n          server: 'myregistry.azurecr.io'\n          identity: uami.id\n        }\n      ]\n    }\n    template: {\n      containers: [\n        {\n          name: 'orders-api'\n          image: 'myregistry.azurecr.io/orders-api:1.0'\n        }\n      ]\n    }\n  }\n}\n```\nDeployment fails with an image pull authorization error. What is missing?\nAssume classic registry RBAC, a valid image reference, and working network access.","explanation":"The user-assigned identity must be attached to the app, selected for registry authentication, and authorized to pull. AcrPull applies to classic RBAC registries. ABAC-enabled registries use repository roles instead.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/container-apps/managed-identity-image-pull","topic":"container-apps-keda","type":"single","options":["The user-assigned managed identity has not been granted the AcrPull role assignment on the ACR resource.","The registries array must include a username and passwordSecretRef even when using managed identity.","Container Apps do not support user-assigned identities for registry authentication; a system-assigned identity is required.","The image tag 1.0 must be replaced with latest for managed identity pulls to succeed."],"answer":0,"setId":"suralmk:ai200-practice-set","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/ai200-practice-set.json","reviewDate":"2026-10-11","reviewNote":"Scoped registry permission guidance to classic RBAC."},{"id":"suralmk:practice-004","prompt":"You need to gradually shift traffic to a new revision of a Container App, sending 20% of traffic to the new revision and 80% to the stable one, without deactivating the old revision.\n\nYou run:\n```bash\naz containerapp update \\\n  --name orders-api \\\n  --resource-group rg-orders \\\n  --image myregistry.azurecr.io/orders-api:2.0\n```\nAfter this command, all traffic still routes to the old revision. What must be done to achieve the 80/20 split?","explanation":"**Correct choice:** Traffic splitting between revisions requires (1) the Container App to be in Multiple revision mode (`revisionsMode: Multiple`) and (2) an explicit traffic weight assignment naming each revision via `az containerapp ingress traffic set` or Bicep traffic configuration.\n\n**Other choice:** By default, Container Apps in Single revision mode routes 100% of traffic to the newest revision.\n\n**Other choice:** Deleting the old revision removes the target you want to send 80% traffic to.\n\n**Other choice:** `minReplicas` controls scaling to zero, not traffic distribution.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/container-apps/scale-app","topic":"container-apps-keda","type":"single","options":["Nothing further; az containerapp update automatically splits traffic 50/50 between the two most recent revisions.","Run az containerapp ingress traffic set --name orders-api --resource-group rg-orders --revision-weight orders-api--old=80 orders-api--new=20 after confirming the app is in multiple-revision mode.","Delete the old revision and redeploy it with a --traffic-weight 80 flag.","Set minReplicas: 0 on the old revision so Container Apps automatically balances traffic based on load."],"answer":1,"setId":"suralmk:ai200-practice-set","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/ai200-practice-set.json","reviewDate":"2026-10-11"},{"id":"suralmk:practice-005","prompt":"A Container Apps environment has an internal load balancer. An API must be reachable from peered VNets with valid routes and private DNS, as well as from its own environment. Which app ingress setting fits?","explanation":"External app ingress means outside the environment. In an internal environment its endpoint remains private. App ingress external:false limits callers to the same environment, even if VNet connectivity exists.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/container-apps/ingress-overview","topic":"postgresql-pgvector","type":"single","options":["external: true on the app, within the internal environment","external: false on the app to allow every peered VNet","Disable ingress entirely","Make the environment public"],"answer":0,"setId":"suralmk:ai200-practice-set","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/ai200-practice-set.json","reviewDate":"2026-10-11","reviewNote":"Corrected internal environment versus internal app ingress."},{"id":"suralmk:practice-006","prompt":"You define a KEDA-based scale rule for a Container App that should scale out based on the depth of an Azure Storage Queue:\n```json\n{\n  \"scale\": {\n    \"minReplicas\": 0,\n    \"maxReplicas\": 10,\n    \"rules\": [\n      {\n        \"name\": \"queue-scale-rule\",\n        \"custom\": {\n          \"type\": \"azure-queue\",\n          \"metadata\": {\n            \"queueName\": \"orders-queue\",\n            \"queueLength\": \"5\"\n          },\n          \"auth\": [\n            {\n              \"secretRef\": \"storage-connection-string\",\n              \"triggerParameter\": \"connection\"\n            }\n          ]\n        }\n      }\n    ]\n  }\n}\n```\nThe app never scales beyond 1 replica even though the queue has 50 messages. What is the most likely cause?","explanation":"**Correct choice:** The `auth.secretRef` must reference a secret name that is actually declared in the Container App's top-level `secrets` array. If the referenced secret is missing or invalid, the KEDA `azure-queue` scaler cannot authenticate to poll queue depth and defaults to minimal scaling (1 replica).\n\n**Other choice:** Scale rule metadata values are conventionally strings in JSON/ARM representation (e.g. `\"5\"`).\n\n**Other choice:** The `azure-queue` scaler is built specifically for Azure Storage Queues.\n\n**Other choice:** `minReplicas: 0` enables scale-to-zero and event-driven scale-out; it does not block scaling.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/container-apps/scale-app","topic":"container-apps-keda","type":"single","options":["queueLength must be specified as an integer, not a string, in Container Apps scale rules.","KEDA queue scalers do not support Azure Storage Queues, only Service Bus.","The secretRef named storage-connection-string does not exist in the Container App's secrets array, or the connection string is invalid, causing the scaler to silently fail authentication and default to minimal scaling.","minReplicas: 0 prevents the KEDA scaler from ever activating; it must be set to at least 1."],"answer":2,"setId":"suralmk:ai200-practice-set","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/ai200-practice-set.json","reviewDate":"2026-10-11"},{"id":"suralmk:practice-007","prompt":"A pod in your AKS cluster is repeatedly restarting. `kubectl get pods` shows:\n```text\nNAME                          READY   STATUS            RESTARTS   AGE\ninference-api-7d4f9c6-2xk9j   0/1     CrashLoopBackOff  6          8m\n```\n`kubectl logs inference-api-7d4f9c6-2xk9j --previous` outputs:\n```text\nTraceback (most recent call last):\n...\nMemoryError: Unable to allocate 2.1 GiB for an array\n```\nThe pod definition has:\n```yaml\nresources:\n  requests:\n    memory: \"512Mi\"\n    cpu: \"250m\"\n  limits:\n    memory: \"1Gi\"\n    cpu: \"1\"\n```\nWhat is the correct fix?","explanation":"**Correct choice:** The `MemoryError` indicates the process needs more memory than the container's 1Gi limit allows. Raising `limits.memory` above actual peak usage (e.g., 3Gi), and increasing `requests.memory` so Kubernetes schedules the pod on a node that can satisfy the limit, directly fixes the issue.\n\n**Other choice:** Removing limits entirely risks the pod consuming all node memory and evicting other pods.\n\n**Other choice:** Lowering `requests.memory` does nothing to raise the ceiling the container can use.\n\n**Other choice:** Probe timing adjustments do not add memory to an out-of-memory container.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/aks/concepts-clusters-workloads","topic":"aks","type":"single","options":["Increase limits.memory to a value comfortably above the process's peak usage (e.g., 3Gi), and raise requests.memory proportionally so the scheduler places the pod on a node with sufficient capacity.","Remove the limits block entirely so the container can use unlimited memory.","Decrease requests.memory to 128Mi so the pod schedules on smaller nodes with more headroom.","Add a livenessProbe with a longer initialDelaySeconds to give the process more time to allocate memory before being restarted."],"answer":0,"setId":"suralmk:ai200-practice-set","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/ai200-practice-set.json","reviewDate":"2026-10-11"},{"id":"suralmk:practice-008","prompt":"A CronJob creates a new Job every night. Each Job has backoffLimit: 3 and restartPolicy: Never. A failed Job exhausts its retries. Will the next scheduled run receive a new retry budget?","explanation":"backoffLimit limits retries of one Job. History limits control how many finished Jobs are retained and are not a prerequisite for retrying the next scheduled Job.","domain":"containers","source":"https://kubernetes.io/docs/concepts/workloads/controllers/cron-jobs/","topic":"aks","type":"single","options":["Yes; each scheduled execution creates a separate Job","No; a failed Job permanently disables the CronJob","No; backoffLimit counts failures for the lifetime of the cluster","Yes, but only if failedJobsHistoryLimit is zero"],"answer":0,"setId":"suralmk:ai200-practice-set","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/ai200-practice-set.json","reviewDate":"2026-10-11","reviewNote":"Removed the unsupported inference that default history limits are missing."},{"id":"suralmk:practice-009","prompt":"You want zero-downtime rolling updates for a Deployment, ensuring at least 3 pods are always available (desired replicas = 4) and no more than 1 extra pod is created during the rollout.\n```yaml\napiVersion: apps/v1\nkind: Deployment\nmetadata:\n  name: web-frontend\nspec:\n  replicas: 4\n  strategy:\n    type: RollingUpdate\n    rollingUpdate:\n      maxUnavailable: ???\n      maxSurge: ???\n  template:\n    spec:\n      containers:\n      - name: web\n        image: myregistry.azurecr.io/web:2.0\n```\nWhich values correctly satisfy \"at least 3 always available\" and \"no more than 1 extra pod\"?","explanation":"**Correct choice:** With `replicas: 4`, `maxUnavailable: 1` guarantees at most 1 pod can be unavailable (meaning 4 - 1 = 3 remain available at all times). `maxSurge: 1` guarantees at most 1 extra pod beyond the desired 4 is created during rollout.\n\n**Other choice:** `maxUnavailable: 3` allows only 1 pod to remain available (4 - 3 = 1).\n\n**Other choice:** `maxUnavailable: 0` and `maxSurge: 0` together block the rollout completely.\n\n**Other choice:** While 25% of 4 equals 1, using explicit integer values directly specifies the contract without recalculating if replicas scale later.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/aks/concepts-clusters-workloads","topic":"aks","type":"single","options":["maxUnavailable: 3, maxSurge: 1","maxUnavailable: 1, maxSurge: 1","maxUnavailable: 0, maxSurge: 0","maxUnavailable: 25%, maxSurge: 25%"],"answer":1,"setId":"suralmk:ai200-practice-set","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/ai200-practice-set.json","reviewDate":"2026-10-11"},{"id":"suralmk:practice-010","prompt":"A pod fails to start with the following event:\n```text\nWarning  FailedScheduling  12s  default-scheduler  0/3 nodes are available:\n3 node(s) had taint {sku=gpu:NoSchedule} that the pod didn't tolerate.\n```\nPod spec:\n```yaml\napiVersion: v1\nkind: Pod\nmetadata:\n  name: inference-pod\nspec:\n  containers:\n  - name: inference\n    image: myregistry.azurecr.io/inference:1.0\n    resources:\n      limits:\n        nvidia.com/gpu: 1\n```\nWhat must be added to schedule this pod onto the GPU node pool?","explanation":"**Correct choice:** Taints on nodes repel pods unless the pod has a matching toleration. The GPU node pool is tainted `sku=gpu:NoSchedule` to prevent non-GPU workloads from landing there; the pod must declare a toleration matching that key/value/effect to schedule there.\n\n**Other choice:** A `nodeSelector` targets nodes but does not overcome a `NoSchedule` taint.\n\n**Other choice:** Increasing GPU requests does not bypass node taints.\n\n**Other choice:** Removing taints cluster-wide allows non-GPU pods to consume GPU nodes.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/aks/concepts-clusters-workloads","topic":"aks","type":"single","options":["A nodeSelector matching the GPU node pool's label; taints and tolerations are unrelated to GPU scheduling.","A tolerations entry matching the node taint, e.g. tolerations: [{ key: \"sku\", operator: \"Equal\", value: \"gpu\", effect: \"NoSchedule\" }].","Increase nvidia.com/gpu limit to 2 so the scheduler prioritizes GPU nodes.","Remove the taint from the GPU nodes using kubectl taint nodes --all sku-."],"answer":1,"setId":"suralmk:ai200-practice-set","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/ai200-practice-set.json","reviewDate":"2026-10-11"},{"id":"suralmk:practice-011","prompt":"A static PersistentVolume is Available and matches a Pending claim in storage class, access modes and capacity. Must the claim set volumeName just because storageClassName is an empty string?","explanation":"An empty storage class opts out of dynamic provisioning, but matching static PVs can still bind. Inspect claim events, selectors, modes and capacity before deciding why a claim is Pending.","domain":"containers","source":"https://kubernetes.io/docs/concepts/storage/persistent-volumes/","topic":"aks","type":"single","options":["No; compatible static volumes can bind automatically; volumeName explicitly selects one","Yes; every static claim must name a volume","Yes; an empty class forbids all static binding","No; an empty class enables dynamic provisioning"],"answer":0,"setId":"suralmk:ai200-practice-set","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/ai200-practice-set.json","reviewDate":"2026-10-11","reviewNote":"Corrected static PV/PVC binding behavior."},{"id":"suralmk:practice-012","prompt":"Container Insights collected KubePodInventory snapshots. Which query finds snapshots in the last day that report OOMKilled as the last container termination reason?","explanation":"ContainerLastStatus contains the last observed container state. Inventory is sampled and is not a complete event ledger, so corroborate it with pod events and node diagnostics. Do not invent Reason or RawJsonDescription columns in the wrong table.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/azure-monitor/reference/tables/kubepodinventory","topic":"kql","type":"single","options":["KubePodInventory | where TimeGenerated > ago(24h) | where ContainerLastStatus has \"OOMKilled\" | summarize arg_max(TimeGenerated, *) by ClusterId, Namespace, Name, ContainerName","KubePodInventory | where Reason == \"OOMKilled\"","KubeEvents | where ContainerLastStatus == \"OOMKilled\"","KubePodInventory | where StatusCode == 137"],"answer":0,"setId":"suralmk:ai200-practice-set","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/ai200-practice-set.json","reviewDate":"2026-10-11","reviewNote":"Replaced a query using unsupported table columns."},{"id":"suralmk:practice-013","prompt":"A Dapr subscription routes events to /events on an application listening on port 6001. Dapr logs show an HTTP 404 from that route. What should you check first?","explanation":"For HTTP pub/sub delivery, Dapr calls the configured application route. A confirmed 404 provides evidence for route diagnosis; a subscription manifest alone cannot prove the handler is missing.","domain":"containers","source":"https://docs.dapr.io/developing-applications/building-blocks/pubsub/howto-publish-subscribe/","topic":"aks","type":"single","options":["Implement or correct POST /events in the receiving application on port 6001","Increase the ACR image retention period","Change the pub/sub topic into a Key Vault secret","Remove the HTTP route because Dapr never calls application handlers"],"answer":0,"setId":"suralmk:ai200-practice-set","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/ai200-practice-set.json","reviewDate":"2026-10-11","reviewNote":"Added evidence instead of inferring an unseen missing handler."},{"id":"suralmk:practice-014","prompt":"You need to attach a custom domain `api.contoso.com` with a managed TLS certificate to a Container App:\n```bash\naz containerapp hostname add \\\n  --hostname api.contoso.com \\\n  --name orders-api \\\n  --resource-group rg-orders\n```\nThis command fails with a domain ownership validation error. What must be done before this command succeeds?","explanation":"**Correct choice:** Azure validates domain ownership via DNS records (a TXT record like `asuid.api` containing the verification ID or CNAME) before allowing hostname binding. Without that DNS record at the registrar, domain validation fails.\n\n**Other choice:** Container Apps custom domains work with any DNS registrar.\n\n**Other choice:** `internal: true` creates an internal-only environment, which is the opposite of public domain binding.\n\n**Other choice:** Managed TLS certificates are automatically issued by Azure after domain ownership validation; uploading a self-signed cert is unnecessary.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/container-apps/scale-app","topic":"container-apps-keda","type":"single","options":["Create a TXT record at the DNS provider for domain validation (or a CNAME/asuid TXT record as required), pointing to the values Azure provides, before Azure can verify ownership of api.contoso.com.","Purchase the domain through Azure App Service Domains first; custom domains from third-party registrars are not supported by Container Apps.","Enable internal: true on the Container Apps Environment.","Generate a self-signed certificate and upload it via az containerapp ssl upload before adding the hostname."],"answer":0,"setId":"suralmk:ai200-practice-set","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/ai200-practice-set.json","reviewDate":"2026-10-11"},{"id":"suralmk:practice-015","prompt":"A NetworkPolicy is intended to allow the frontend namespace to reach backend pods on TCP 8080. Which built-in namespace label can namespaceSelector match?","explanation":"Kubernetes populates the immutable namespace-name label. Also verify pod selectors, ports, DNS, other policies and CNI enforcement. Do not presume this built-in label is missing or overridden.","domain":"containers","source":"https://kubernetes.io/docs/concepts/services-networking/network-policies/","topic":"aks","type":"single","options":["kubernetes.io/metadata.name: frontend","app.kubernetes.io/pod-name: frontend","kubernetes.io/hostname: frontend","node-role.kubernetes.io/frontend: true"],"answer":0,"setId":"suralmk:ai200-practice-set","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/ai200-practice-set.json","reviewDate":"2026-10-11","reviewNote":"Removed an impossible missing/overridden immutable namespace-label diagnosis."},{"id":"suralmk:practice-016","prompt":"You configure liveness and readiness probes for a Node.js API that takes up to 45 seconds to warm up a large in-memory cache on startup:\n```yaml\nlivenessProbe:\n  httpGet:\n    path: /healthz\n    port: 3000\n  initialDelaySeconds: 5\n  periodSeconds: 10\n  failureThreshold: 3\nreadinessProbe:\n  httpGet:\n    path: /ready\n    port: 3000\n  initialDelaySeconds: 5\n  periodSeconds: 10\n  failureThreshold: 3\n```\nThe pod is repeatedly killed and restarted during the cache-warming phase, never reaching a healthy state. What is the best fix?","explanation":"**Correct choice:** A `startupProbe` disables `livenessProbe` and `readinessProbe` while it runs. Configuring `startupProbe` with a 60s budget (`failureThreshold: 30`, `periodSeconds: 2`) allows slow cache warming without premature kills, while preserving fast steady-state liveness checks.\n\n**Other choice:** Raising `initialDelaySeconds` permanently delays restart detection during steady-state crashes.\n\n**Other choice:** Removing liveness probes removes crash recovery guarantees.\n\n**Other choice:** Setting `failureThreshold: 100` delays detection of real deadlocks during normal operation by up to 16 minutes.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/aks/concepts-clusters-workloads","topic":"aks","type":"single","options":["Increase livenessProbe.initialDelaySeconds to 45 and increase readinessProbe.initialDelaySeconds to 45 as well.","Add a startupProbe with a generous failureThreshold × periodSeconds (e.g., failureThreshold: 30, periodSeconds: 2 = 60s budget) targeting /healthz, which disables liveness and readiness probes until it succeeds.","Remove the livenessProbe entirely since it is causing restarts.","Set failureThreshold: 100 on the existing livenessProbe to give it more retries."],"answer":1,"setId":"suralmk:ai200-practice-set","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/ai200-practice-set.json","reviewDate":"2026-10-11"},{"id":"suralmk:practice-017","prompt":"You deploy a Helm chart for a microservice with standard defaults:\n```yaml\n# values.yaml (default)\nreplicaCount: 2\nimage:\n  repository: myregistry.azurecr.io/orders-api\n  tag: latest\n```\nDeployment template:\n```yaml\napiVersion: apps/v1\nkind: Deployment\nmetadata:\n  name: {{ .Release.Name }}-orders-api\nspec:\n  replicas: {{ .Values.replicaCount }}\n  template:\n    spec:\n      containers:\n      - name: orders-api\n        image: \"{{ .Values.image.repository }}:{{ .Values.image.tag }}\"\n```\nYou execute:\n```bash\nhelm upgrade --install orders ./orders-chart \\\n  --set image.tag=2.0 \\\n  -f values-prod.yaml\n```\nWhere `values-prod.yaml` contains `replicaCount: 5` and no `image.tag` key. What image tag and replica count are actually applied?","explanation":"**Correct choice:** Helm merges values from `values.yaml`, `-f` files, and `--set` flags in order of precedence. `--set` flags have higher precedence than values files. `values-prod.yaml` sets `replicaCount: 5`, and `--set image.tag=2.0` sets the tag to `2.0`. Both merge into: `replicaCount=5` and `image.tag=2.0`.\n\n**Other choice:** `--set` flags take precedence over `-f` values files, not the other way around.\n\n**Other choice:** Helm merges value sources rather than ignoring non-overlapping keys.\n\n**Other choice:** Combining `-f` and `--set` is standard Helm usage.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/aks/concepts-clusters-workloads","topic":"aks","type":"single","options":["image.tag=latest, replicaCount=5 — because -f files always take precedence over --set flags.","image.tag=2.0, replicaCount=5 — --set and -f are merged, with values-prod.yaml overriding replicaCount and --set image.tag=2.0 overriding the image tag.","image.tag=2.0, replicaCount=2 — because supplying any -f file causes Helm to ignore replicaCount from prod values.","The command fails because --set and -f cannot be combined in the same helm upgrade invocation."],"answer":1,"setId":"suralmk:ai200-practice-set","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/ai200-practice-set.json","reviewDate":"2026-10-11"},{"id":"suralmk:practice-018","prompt":"You use Docker Compose for local development of a multi-container app:\n```yaml\nversion: \"3.9\"\nservices:\n  api:\n    build: ./api\n    ports:\n      - \"8080:8080\"\n    environment:\n      - REDIS_HOST=localhost\n      - REDIS_PORT=6379\n    depends_on:\n      - redis\n  redis:\n    image: redis:7\n    ports:\n      - \"6379:6379\"\n```\nThe API logs show `Connection refused to localhost:6379`, even though redis is running (`docker compose ps`). What is the correct fix?","explanation":"**Correct choice:** In Docker Compose, each service container runs in its own network namespace. `localhost` inside the `api` container refers to `api`, not `redis`. Docker Compose embedded DNS resolves service names (e.g. `redis`), so setting `REDIS_HOST=redis` allows container-to-container communication.\n\n**Other choice:** `network_mode: host` bypasses Docker network isolation and doesn't work reliably across all OS platforms.\n\n**Other choice:** There is no port conflict; changing host port mappings does not fix internal container DNS.\n\n**Other choice:** `links` is legacy syntax; service names resolve automatically via Docker DNS.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/redis/","topic":"azure-managed-redis","type":"single","options":["Change REDIS_HOST to redis (the Compose service name), since containers on the default Compose network resolve each other by service name, whereas localhost inside the API container refers to the API container itself.","Add network_mode: host to both services so localhost resolves correctly across containers.","Change the Redis port mapping to \"6379:6380\" to avoid a port conflict with the API container.","depends_on should be changed to links: [redis], which is required for DNS resolution in version 3.9."],"answer":0,"setId":"suralmk:ai200-practice-set","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/ai200-practice-set.json","reviewDate":"2026-10-11"},{"id":"suralmk:practice-019","prompt":"You provision a Cosmos DB container for a RAG application using the Python SDK:\n```python\nfrom azure.cosmos import CosmosClient, PartitionKey\n\nclient = CosmosClient(url, credential=key)\ndatabase = client.create_database_if_not_exists(id=\"ragdb\")\ncontainer = database.create_container_if_not_exists(\n    id=\"documents\",\n    partition_key=PartitionKey(path=\"/tenantId\"),\n    offer_throughput=400\n)\n```\nSix months later, a single large tenant accounts for 90% of all reads and writes, and RU consumption spikes cause 429 errors only for that tenant's operations. What is the underlying issue and best long-term fix?","explanation":"**Correct choice:** Concentrating a heavy tenant's data under one `/tenantId` value creates a hot logical partition. Physical partitions are capped in maximum throughput (10,000 RU/s max per physical partition). Using synthetic or hierarchical partition keys (`/tenantId`, `/documentType`) distributes the tenant's data across multiple logical partitions.\n\n**Other choice:** Raising overall container RU/s increases total aggregate throughput but does not raise the single physical partition RU cap.\n\n**Other choice:** Serverless mode still enforces logical and physical partition limits.\n\n**Other choice:** 429 errors are server-side throughput throttling responses, not client connection pool issues.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/cosmos-db/nosql/","topic":"cosmos-db-nosql","type":"single","options":["The container has a hot partition because /tenantId concentrates that tenant's data and RU load on a single logical partition; introduce a synthetic partition key (e.g., /tenantId_documentType) or hierarchical partition key.","Increase offer_throughput to a very high fixed RU/s value; this alone permanently fixes hot partition issues regardless of key design.","Switch the container to serverless mode, which automatically eliminates hot partitions.","The issue is unrelated to partitioning; it is caused by the SDK not using connection pooling."],"answer":0,"setId":"suralmk:ai200-practice-set","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/ai200-practice-set.json","reviewDate":"2026-10-11"},{"id":"suralmk:practice-020","prompt":"A Cosmos DB item must be replaced only if it has not changed since a previous read. Which Python SDK call implements optimistic concurrency?","explanation":"Read the item and retain _etag, import MatchConditions from azure.core, then condition the replacement on that version. A conflicting update produces 412. Do not assume every SDK patch version supports the same ETag parameters; use its documented conditional-patch features.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/cosmos-db/nosql/database-transactions-optimistic-concurrency","topic":"cosmos-db-nosql","type":"single","options":["container.replace_item(item=item[\"id\"], body=updated, etag=item[\"_etag\"], match_condition=MatchConditions.IfNotModified)","container.upsert_item(body=updated)","container.replace_item(item=item[\"id\"], body=updated) without a condition","container.read_item(item=item[\"id\"], partition_key=pk) without a conditional write"],"answer":0,"setId":"suralmk:ai200-practice-set","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/ai200-practice-set.json","reviewDate":"2026-10-11","reviewNote":"Used the documented ETag replacement path instead of assuming Python Patch If-Match support."},{"id":"suralmk:practice-021","prompt":"You define an indexing policy to optimize RU cost for a container where most queries filter on `/status` and `/category`, but the application never queries on the large `/rawPayload` field:\n```json\n{\n  \"indexingMode\": \"consistent\",\n  \"automatic\": true,\n  \"includedPaths\": [\n    { \"path\": \"/*\" }\n  ],\n  \"excludedPaths\": [\n    { \"path\": \"/_etag/?\" }\n  ]\n}\n```\nRU cost for writes is unexpectedly high. What change best reduces write RU cost while preserving query performance on `/status` and `/category`?","explanation":"**Correct choice:** Indexing large unqueried paths (like `/rawPayload/*`) incurs significant write RU overhead on every insert/update. Adding `/rawPayload/*` to `excludedPaths` stops Cosmos DB from building index entries for that subtree, cutting write RU cost while maintaining index lookups on `/status` and `/category`.\n\n**Other choice:** `indexingMode: none` breaks all queries filtering on indexed paths.\n\n**Other choice:** Lazy indexing is deprecated/removed in Cosmos DB SQL API.\n\n**Other choice:** Adding composite indexes including `/rawPayload` increases write RU costs further.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/cosmos-db/nosql/","topic":"cosmos-db-nosql","type":"single","options":["Set indexingMode to \"none\" to disable indexing entirely, then manually re-enable it before each query.","Add /rawPayload/* to excludedPaths while keeping /* included (or explicitly include only /status/? and /category/? in includedPaths and exclude /*).","Change indexingMode to \"lazy\" so indexing happens in the background.","Add a composite index on (/status, /category, /rawPayload)."],"answer":1,"setId":"suralmk:ai200-practice-set","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/ai200-practice-set.json","reviewDate":"2026-10-11"},{"id":"suralmk:practice-022","prompt":"A Cosmos DB query filters on status and sorts by shippedDate. Which optimization should you evaluate to combine the filter and sort efficiently?","explanation":"A single-property ORDER BY can run with a range index. A suitable composite index can improve equality-filter-plus-sort queries; the documented pattern may require including equality-filtered properties first in ORDER BY. Verify index metrics and request charges.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/cosmos-db/index-policy","topic":"cosmos-db-nosql","type":"single","options":["Add a suitable composite index and evaluate rewriting ORDER BY to include the equality-filtered status before shippedDate","Assume every one-field ORDER BY requires a composite index to execute","Remove all indexes and keep the same latency target","Increase TTL to sort records"],"answer":0,"setId":"suralmk:ai200-practice-set","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/ai200-practice-set.json","reviewDate":"2026-10-11","reviewNote":"Clarified composite-index optimization and query rewriting."},{"id":"suralmk:practice-023","prompt":"You are configuring a vector index for a RAG container storing 1536-dimension OpenAI embeddings, prioritizing low memory footprint at the cost of some recall, for a container expected to hold 50 million vectors.\n```json\n{\n  \"vectorEmbeddingPolicy\": {\n    \"vectorEmbeddings\": [\n      {\n        \"path\": \"/embedding\",\n        \"dataType\": \"float32\",\n        \"dimensions\": 1536,\n        \"distanceFunction\": \"cosine\"\n      }\n    ]\n  },\n  \"indexingPolicy\": {\n    \"vectorIndexes\": [\n      {\n        \"path\": \"/embedding\",\n        \"type\": \"???\"\n      }\n    ]\n  }\n}\n```\nGiven the scale (50 million vectors) and the priority on low memory footprint, which vector index type should replace \"???\"?","explanation":"**Correct choice:** `diskANN` is purpose-built for large-scale approximate nearest-neighbor (ANN) search, using a disk-resident graph structure that provides strong recall while keeping in-memory footprint far lower than fully in-memory exhaustive approaches — critical at 50 million vectors.\n\n**Other choice:** `flat` stores vectors uncompressed and performs brute-force search; at 50M vectors it is the most memory- and compute-intensive option (recommended under ~10,000 vectors).\n\n**Other choice:** `quantizedFlat` reduces memory versus `flat`, but is still fundamentally an exhaustive-style structure that scales poorly to tens of millions of vectors compared to `diskANN`.\n\n**Other choice:** Cosmos DB vector search explicitly requires configuring `vectorIndexes` to enable efficient vector queries.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/azure-functions/functions-overview","topic":"azure-functions","type":"single","options":["flat — flat indexes always have the lowest memory footprint regardless of scale.","quantizedFlat — reduces memory via vector quantization while remaining an exhaustive/near-exhaustive index, but this still scales poorly to 50 million vectors for latency.","diskANN — an approximate nearest-neighbor graph index designed specifically for very large vector datasets, offering strong recall with lower memory footprint (index data can reside on disk) at very large scale, making it the best fit for 50 million vectors prioritizing memory efficiency.","Vector indexes are not required in Cosmos DB; queries always perform full brute-force scans regardless of index type."],"answer":2,"setId":"suralmk:ai200-practice-set","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/ai200-practice-set.json","reviewDate":"2026-10-11"},{"id":"suralmk:practice-024","prompt":"In Cosmos DB for NoSQL, SELECT TOP 5 c.id FROM c ORDER BY VectorDistance(c.embedding, @v) omits ASC. Assuming valid policies, vectors and parameters, what does that omission mean?","explanation":"ORDER BY defaults to ascending. Explicit ASC can improve readability but its omission is not a vector-query syntax error.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/cosmos-db/nosql/query/order-by","topic":"cosmos-db-nosql","type":"single","options":["Ascending order is the default, so nearest distances are returned first","VectorDistance always requires an explicit ASC token","The query defaults to descending distance","The missing ASC forces a cross-partition security bypass"],"answer":0,"setId":"suralmk:ai200-practice-set","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/ai200-practice-set.json","reviewDate":"2026-10-11","reviewNote":"Corrected the false requirement for explicit ASC."},{"id":"suralmk:practice-025","prompt":"You need to page through query results using continuation tokens in a background export job that must resume after a restart:\n```python\nquery = \"SELECT * FROM c WHERE c.status = 'active'\"\nquery_iterable = container.query_items(\n    query=query,\n    partition_key=\"tenant-a\",\n    max_item_count=100\n)\npager = query_iterable.by_page(continuation_token=saved_token)\nfor page in pager:\n    for item in page:\n        process(item)\n    # TODO: persist token for resume\n```\nWhat is the correct way to persist the continuation token so the job can resume exactly where it left off after a crash?","explanation":"**Correct choice:** The `by_page()` iterator exposes a `continuation_token` property reflecting the position after the most recently fetched page. Persisting this value after successfully processing a page allows a new `by_page(continuation_token=saved_token)` call to resume fetching from that exact boundary.\n\n**Other choice:** Filtering on `c.id > @lastId` assumes a specific ordering that is not guaranteed without explicit `ORDER BY`.\n\n**Other choice:** Continuation tokens are fully supported in the Python SDK via `by_page()`.\n\n**Other choice:** Saving the token before processing would skip that page's data upon resumption.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/cosmos-db/nosql/","topic":"cosmos-db-nosql","type":"single","options":["Save pager.continuation_token after each page is fully processed, since by_page()'s pager object exposes the token needed to resume from that exact page boundary on the next by_page(continuation_token=...) call.","Save page[-1][\"id\"] (the last item's id) and use it as a WHERE c.id > @lastId filter on resume instead of a continuation token.","Continuation tokens are not supported by the Python SDK; use OFFSET/LIMIT instead for resumable pagination.","Save the token before processing each page (i.e., before the for item in page loop) rather than after."],"answer":0,"setId":"suralmk:ai200-practice-set","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/ai200-practice-set.json","reviewDate":"2026-10-11"},{"id":"suralmk:practice-026","prompt":"You run this Cosmos DB SQL query to find documents where a nested array contains a specific tag, using a subquery:\n```sql\nSELECT c.id, c.title\nFROM c\nWHERE EXISTS (\n  SELECT VALUE t\n  FROM t IN c.tags\n  WHERE t = \"urgent\"\n)\n```\nA colleague suggests rewriting it using ARRAY_CONTAINS for better performance. Which rewritten query is both correct and more efficient?","explanation":"**Correct choice:** `ARRAY_CONTAINS(array_expression, search_expression)` is the purpose-built Cosmos DB SQL function for checking membership of a scalar value in an array. It avoids the overhead of constructing and iterating a correlated subquery (`EXISTS`).\n\n**Other choice:** `CONTAINS()` is a string substring function, not an array membership function.\n\n**Other choice:** Cosmos DB SQL does not support bare `value IN array_expression` syntax for JSON arrays.\n\n**Other choice:** `JOIN t IN c.tags` can produce duplicate rows if `tags` contains \"urgent\" multiple times.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/azure-functions/functions-overview","topic":"azure-functions","type":"single","options":["SELECT c.id, c.title FROM c WHERE ARRAY_CONTAINS(c.tags, \"urgent\")","SELECT c.id, c.title FROM c WHERE c.tags CONTAINS \"urgent\"","SELECT c.id, c.title FROM c WHERE \"urgent\" IN c.tags","SELECT c.id, c.title FROM c JOIN t IN c.tags WHERE t = \"urgent\""],"answer":0,"setId":"suralmk:ai200-practice-set","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/ai200-practice-set.json","reviewDate":"2026-10-11"},{"id":"suralmk:practice-027","prompt":"You perform a transactional batch operation to insert an order and update inventory atomically within the same partition:\n```python\n\nbatch_operations = [\n    (\"create\", (order_item,)),\n    (\"replace\", (\"inventory-sku123\", updated_inventory_item))\n]\nbatch_response = container.execute_item_batch(\n    batch_operations=batch_operations,\n    partition_key=\"store-42\"\n)\n```\nThis raises an error at runtime. What is the most likely cause?","explanation":"Use container.execute_item_batch with all operations targeting one logical partition key. The Python batch API accepts operations rather than requiring a TransactionalBatch import. If any operation fails, the atomic batch fails.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/cosmos-db/transactional-batch","topic":"cosmos-db-nosql","type":"single","options":["Transactional batch operations require all items in the batch to belong to the same logical partition key, and if order_item or updated_inventory_item has a different /partitionKey value than \"store-42\" (e.g., the order is keyed by customerId instead of storeId), the batch fails.","execute_item_batch is not a real method; batches must be constructed as raw SQL transactions using BEGIN TRANSACTION.","Transactional batches are limited to create operations only; replace cannot be mixed into the same batch.","Batches require exactly 2 operations; adding a third would also fail."],"answer":0,"setId":"suralmk:ai200-practice-set","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/ai200-practice-set.json","reviewDate":"2026-10-11","reviewNote":"Removed an unused/nonportable SDK import; preserved same-partition batch requirement."},{"id":"suralmk:practice-028","prompt":"You need to run analytical, large-scale aggregations over your Cosmos DB transactional data (millions of documents) for a monthly reporting dashboard, without impacting the RU budget of the live OLTP workload.\nCurrent approach:\n```sql\nSELECT c.region, COUNT(1) AS orderCount, SUM(c.total) AS revenue\nFROM c\nGROUP BY c.region\n```\nThis consumes tens of thousands of RUs and throttles production traffic during report generation. What is the recommended architectural fix?","explanation":"**Correct choice:** Cosmos DB's Analytical Store maintains an isolated, auto-synced columnar copy of your data. Querying it via Azure Synapse Link does not consume provisioned RU/s from the transactional store, fully decoupling reporting workloads from OLTP performance.\n\n**Other choice:** Increasing RU/s still consumes throughput budget and incurs financial cost against the transactional store.\n\n**Other choice:** Composite indexes do not eliminate the massive RU cost of cross-partition aggregation over millions of documents.\n\n**Other choice:** Pagination spreads out the RU consumption over time but does not reduce overall RU usage.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/cosmos-db/nosql/","topic":"cosmos-db-nosql","type":"single","options":["Enable the Analytical Store on the container and query the data via Azure Synapse Link (Spark or serverless SQL pool) instead of running heavy aggregations directly against the transactional store, decoupling analytical workload RU/compute from the OLTP container.","Increase provisioned RU/s on the container specifically during report generation hours using autoscale.","Add a composite index on (/region, /total) to make the GROUP BY and SUM fully index-served with near-zero RU cost.","Rewrite the query using OFFSET/LIMIT pagination to break it into smaller RU-bounded chunks."],"answer":0,"setId":"suralmk:ai200-practice-set","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/ai200-practice-set.json","reviewDate":"2026-10-11"},{"id":"suralmk:practice-029","prompt":"You configure a vector embedding policy using int8 quantized embeddings to reduce storage cost, migrating from float32.\n```json\n{\n  \"vectorEmbeddingPolicy\": {\n    \"vectorEmbeddings\": [\n      {\n        \"path\": \"/embedding\",\n        \"dataType\": \"int8\",\n        \"dimensions\": 1536,\n        \"distanceFunction\": \"cosine\"\n      }\n    ]\n  }\n}\n```\nApplication code:\n```python\ncontainer.upsert_item({\n    \"id\": \"chunk1\",\n    \"embedding\": embedding_vector, # list of 1536 floats from OpenAI, e.g. [0.0123, -0.045, ...]\n    \"text\": \"...\"\n})\n```\nThe upsert fails validation. Why?","explanation":"**Correct choice:** Setting `dataType: int8` in the vector embedding policy specifies that Cosmos DB expects array elements to be 8-bit signed integers (-128 to 127). Inserting raw floats (e.g., `0.0123`) causes validation failure.\n\n**Other choice:** `int8` is a documented, supported `dataType` for Cosmos DB vector policies.\n\n**Other choice:** Cosine distance is compatible with `int8` vector types.\n\n**Other choice:** Vector `dimensions` (1536) reflects vector length, which is independent of element numeric representation.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/azure-functions/functions-overview","topic":"azure-functions","type":"single","options":["int8 embeddings require the stored array values to actually be 8-bit integers (typically in range -128 to 127) that have already been quantized by the application; raw float32 embeddings from an embeddings API cannot be inserted directly into an int8-typed vector path without an explicit quantization step first.","int8 is not a valid dataType value; only float32 is supported for dimensions: 1536.","cosine distance function is incompatible with int8 data type; only dotproduct works with quantized types.","The dimensions value must be reduced proportionally (e.g., to 384) when switching to int8."],"answer":0,"setId":"suralmk:ai200-practice-set","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/ai200-practice-set.json","reviewDate":"2026-10-11"},{"id":"suralmk:practice-030","prompt":"Which comparison correctly describes Cosmos DB vector index trade-offs?","explanation":"Choose the index using dimensions, corpus size, recall, latency and request-charge measurements. flat supports up to 505 dimensions; quantizedFlat and diskANN support up to 4096. Do not infer universal memory rankings.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/cosmos-db/nosql/vector-search","topic":"cosmos-db-nosql","type":"single","options":["flat performs exact search and supports up to 505 dimensions; diskANN supports higher-dimensional approximate search at scale","flat always consumes more memory than every approximate index","diskANN always returns exact nearest neighbors","All vector indexes have identical dimensionality limits"],"answer":0,"setId":"suralmk:ai200-practice-set","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/ai200-practice-set.json","reviewDate":"2026-10-11","reviewNote":"Removed universal memory claims and included dimensionality constraints."},{"id":"suralmk:practice-031","prompt":"A Cosmos DB RAG container partitions on /tenantId. How should a backend scope retrieval for an authenticated tenant?","explanation":"Partition routing can scope data access to the tenant logical partition, but trusted authorization determines which tenant may be queried. A SQL filter is useful defense in depth, not a replacement for authentication and authorization. A physical partition can contain many tenants.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/cosmos-db/partitioning-overview","topic":"cosmos-db-nosql","type":"single","options":["Derive the tenant from trusted authorization context, pass partition_key for that tenant, and apply any additional authorized filters","Trust an arbitrary tenant_id supplied by the caller","Enable cross-partition queries and remove all tenant checks","Rely on the embedding itself to encode tenant access rights"],"answer":0,"setId":"suralmk:ai200-practice-set","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/ai200-practice-set.json","reviewDate":"2026-10-11","reviewNote":"Distinguished logical partition routing from authorization and physical partitions."},{"id":"suralmk:practice-032","prompt":"A Cosmos DB container should support indexed hybrid ranking using both vector distance and full-text relevance. What configuration should you plan?","explanation":"Configure the appropriate vector and full-text policies and use the documented ORDER BY RANK RRF syntax. FullTextScore takes the search expressions in the documented form, not an invented array argument. Enable required account features and verify current support.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/cosmos-db/gen-ai/hybrid-search","topic":"cosmos-db-nosql","type":"single","options":["Matching vector embedding/index policies and full-text policy/index definitions for the queried paths","Only a scalar composite index","Only an App Configuration feature flag","Only client-side concatenation of unranked results"],"answer":0,"setId":"suralmk:ai200-practice-set","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/ai200-practice-set.json","reviewDate":"2026-10-11","reviewNote":"Removed invalid FullTextScore example syntax."},{"id":"suralmk:practice-033","prompt":"You need TTL-based automatic expiration for chat session documents 24 hours after last write, but some session documents (marked \"pinned\": true) must never expire.\nContainer-level defaultTtl is set to 86400 (24 hours).\n```json\n{\n  \"id\": \"session-123\",\n  \"pinned\": false,\n  \"ttl\": ???\n}\n```\nWhat value of the item-level ttl field for pinned sessions ensures they never expire, while unpinned sessions use the container default?\nYou must keep the container defaultTtl at 86400.","explanation":"With defaultTtl fixed at 86400, omit ttl on ordinary items and use ttl:-1 on pinned items. A container default of -1 with explicit per-item TTL is another valid design, but violates this question's fixed-default requirement.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/cosmos-db/time-to-live","topic":"cosmos-db-nosql","type":"single","options":["Set \"ttl\": -1 explicitly on pinned items to override and disable expiration for that item, while unpinned items omit ttl to inherit the container's defaultTtl.","Set \"ttl\": 0 on pinned items to disable expiration.","Set \"ttl\": null on pinned items to disable expiration.","Set defaultTtl to -1 at the container level and set \"ttl\": 86400 explicitly on every unpinned item instead."],"answer":0,"setId":"suralmk:ai200-practice-set","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/ai200-practice-set.json","reviewDate":"2026-10-11","reviewNote":"A different container TTL design can also work; fixed the container default as a requirement."},{"id":"suralmk:practice-034","prompt":"A Python Cosmos DB ingestion loop writes 500000 items sequentially. Which change can improve throughput while handling throttling responsibly?","explanation":"Python supports asynchronous I/O; do not copy a .NET bulk-execution switch into Python. Bound concurrency to capacity, respect 429 retry-after, and record/retry failures safely. Automatic retries are finite and do not guarantee success.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/cosmos-db/nosql/performance-tips-python-sdk","topic":"cosmos-db-nosql","type":"single","options":["Use the async SDK with bounded concurrent writes, observe SDK retry-after behavior, and handle exhausted retries","Set a generic allow_bulk_execution flag on the Python client","Pass a list of items to create_item as one item batch","Remove concurrency limits and retry forever without delay"],"answer":0,"setId":"suralmk:ai200-practice-set","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/ai200-practice-set.json","reviewDate":"2026-10-11","reviewNote":"Removed nonexistent Python bulk-execution mode and unbounded reliability claims."},{"id":"suralmk:practice-035","prompt":"You create a Redis vector index for RAG chunk retrieval using redis-py against Azure Managed Redis (Redis Stack-compatible):\n```python\nimport redis\nfrom redis.commands.search.field import VectorField, TextField\nfrom redis.commands.search.indexDefinition import IndexDefinition, IndexType\n\nr = redis.Redis(host=host, port=10000, password=key, ssl=True)\nschema = (\n    TextField(\"text\"),\n    VectorField(\n        \"embedding\",\n        \"HNSW\",\n        {\n            \"TYPE\": \"FLOAT32\",\n            \"DIM\": 1536,\n            \"DISTANCE_METRIC\": \"COSINE\"\n        }\n    )\n)\nr.ft(\"idx:chunks\").create_index(\n    schema,\n    definition=IndexDefinition(prefix=[\"chunk:\"], index_type=IndexType.HASH)\n)\n\nr.hset(\"chunk:1\", mapping={\n    \"text\": \"Azure Kubernetes Service overview\",\n    \"embedding\": embedding_list # a Python list of 1536 floats\n})\n```\nDocuments are stored like this, but FT.SEARCH returns zero results for a valid KNN query. What is the bug?","explanation":"**Correct choice:** Redis `VECTOR` fields expect vector data stored as raw binary blobs (e.g. `numpy.array(vector, dtype=np.float32).tobytes()`). Storing a Python list as a string in `hset` prevents RediSearch from indexing the vector.\n\n**Other choice:** `HNSW` is fully supported in Azure Managed Redis / Redis Stack.\n\n**Other choice:** `prefix=[\"chunk:\"]` matches any key starting with `chunk:`.\n\n**Other choice:** `DISTANCE_METRIC` is uppercase in RediSearch schema definitions (`COSINE`, `L2`, `IP`).","domain":"data","source":"https://learn.microsoft.com/en-us/azure/redis/","topic":"azure-managed-redis","type":"single","options":["The embedding field must be stored as raw bytes (e.g., numpy.array(embedding_list, dtype=numpy.float32).tobytes()), not as a native Python list — HSET with a list value is invalid for a Redis VECTOR field.","HNSW is not a valid algorithm for VectorField; only FLAT is supported in Azure Managed Redis.","The index prefix \"chunk:\" doesn't match; it should be \"chunk*\" with a wildcard.","DISTANCE_METRIC must be lowercase \"cosine\", not \"COSINE\"."],"answer":0,"setId":"suralmk:ai200-practice-set","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/ai200-practice-set.json","reviewDate":"2026-10-11"},{"id":"suralmk:practice-036","prompt":"You need to run a K-nearest-neighbor vector search combined with a metadata filter (category == \"networking\") against a Redis HASH-based index:\n```python\nfrom redis.commands.search.query import Query\n\nq = Query(\"(@category:{networking})=>[KNN 5 @embedding $vec AS score]\") \\\n    .sort_by(\"score\") \\\n    .return_fields(\"text\", \"score\") \\\n    .dialect(2)\n\nresults = r.ft(\"idx:chunks\").search(\n    q, query_params={\"vec\": query_vector_bytes}\n)\n```\nThis query returns a syntax error. Assuming category was indexed as a TextField, what is the correct fix?","explanation":"**Correct choice:** The `@field:{value}` curly brace syntax is RediSearch tag-filter syntax, which requires `TagField` in the schema. For `TextField`, standard text search syntax is required (`@category:networking`).\n\n**Other choice:** Hybrid pre-filtering syntax requires the filter expression before `=>[KNN ...]`, not after.\n\n**Other choice:** `DIALECT 2` (or 3) is required for vector search in RediSearch.\n\n**Other choice:** `query_params` is the standard method for passing binary vector parameters.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/redis/","topic":"azure-managed-redis","type":"single","options":["category must be indexed as a TagField, not a TextField, for exact-match filtering with the {value} tag-filter syntax (@category:{networking}) to be valid; TextField requires full-text search syntax instead.","The KNN clause must come before the filter clause: [KNN 5 @embedding $vec AS score]=>(@category:{networking}).","dialect(2) is invalid; hybrid filter+KNN queries require dialect(1).","query_params cannot be used with hybrid queries."],"answer":0,"setId":"suralmk:ai200-practice-set","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/ai200-practice-set.json","reviewDate":"2026-10-11"},{"id":"suralmk:practice-037","prompt":"A Redis FLAT vector index searches two million chunks too slowly. More index memory is acceptable if measured recall remains adequate. Which alternative should you evaluate?","explanation":"HNSW trades graph memory and approximation for faster search at scale. It does not inherently use less memory than FLAT. Benchmark query time, recall and memory together.","domain":"data","source":"https://redis.io/docs/latest/develop/ai/search-and-query/vectors/","topic":"azure-managed-redis","type":"single","options":["HNSW approximate search","Switch FLOAT32 vectors to plain text without an index","Disable every metadata filter to guarantee tenant isolation","Use GET instead of vector search"],"answer":0,"setId":"suralmk:ai200-practice-set","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/ai200-practice-set.json","reviewDate":"2026-10-11","reviewNote":"Separated HNSW latency benefits from memory consumption."},{"id":"suralmk:practice-038","prompt":"Embeddings are stored as Redis JSON arrays at $.embedding. Which index definition matches that representation?","explanation":"The index type and field paths must match JSON storage. HASH vectors use binary blobs, whereas JSON vectors are arrays. Changing only IndexType while leaving incompatible paths is insufficient.","domain":"data","source":"https://redis.io/docs/latest/develop/ai/search-and-query/vectors/","topic":"azure-managed-redis","type":"single","options":["An ON JSON index with a vector field at $.embedding, aliased as embedding","An ON HASH index over the JSON keys","A text-only index with no vector field","An ON JSON index that treats embedding as an integer counter"],"answer":0,"setId":"suralmk:ai200-practice-set","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/ai200-practice-set.json","reviewDate":"2026-10-11","reviewNote":"Required JSON paths as well as JSON index type."},{"id":"suralmk:practice-039","prompt":"You need a hybrid Redis query combining vector KNN search with a numeric metadata range filter (documents published in the last 30 days) and a tag filter on department:\n```python\nq = Query(\"(@department:{engineering} @publishedTs:[1700000000 +inf])=>[KNN 5 @embedding $vec AS score]\") \\\n    .sort_by(\"score\") \\\n    .return_fields(\"text\", \"score\") \\\n    .dialect(2)\n```\nGiven department is a TagField and publishedTs is a NumericField, is this query syntactically valid, and if not, what's wrong?","explanation":"**Correct choice:** RediSearch supports combining tag filters (`@dept:{val}`), numeric filters (`@num:[min max]`), and text filters using space-delimited implicit `AND` in the pre-filter clause before `=>[KNN ...]`. Space is the correct delimiter between numeric bounds.\n\n**Other choice:** Combining different field filter types in RediSearch pre-filters is fully supported.\n\n**Other choice:** RediSearch numeric range syntax uses a space between bounds (`[1700000000 +inf]`), not a comma.\n\n**Other choice:** `+inf` and `-inf` are valid upper/lower bounds in RediSearch numeric ranges.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/redis/","topic":"azure-managed-redis","type":"single","options":["It is valid: combining a tag filter and a numeric range filter with implicit AND (space-separated) inside the pre-filter expression, followed by =>[KNN ...], is correct RediSearch hybrid query syntax.","It is invalid: NumericField range filters cannot be combined with TagField filters in the same query.","It is invalid: numeric ranges require the syntax @publishedTs:[1700000000, +inf] with a comma separator, not a space.","It is invalid: +inf is not a valid upper bound."],"answer":0,"setId":"suralmk:ai200-practice-set","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/ai200-practice-set.json","reviewDate":"2026-10-11"},{"id":"suralmk:practice-040","prompt":"You are tuning an HNSW-based Redis vector index for a production RAG system and need to reduce query latency, currently seeing acceptable recall but slower-than-target FT.SEARCH response times under load:\n```python\nq = Query(\n    \"(@department:{engineering} @publishedTs:[1700000000 +inf])=>[KNN 10 @embedding $vec AS score]\"\n).sort_by(\"score\").dialect(2)\n\nVectorField(\n    \"embedding\",\n    \"HNSW\",\n    {\n        \"TYPE\": \"FLOAT32\",\n        \"DIM\": 1536,\n        \"DISTANCE_METRIC\": \"COSINE\",\n        \"M\": 64,\n        \"EF_CONSTRUCTION\": 500,\n        \"EF_RUNTIME\": 500\n    }\n)\n```\nWhich single parameter, if reduced, most directly improves per-query latency (at the cost of some recall) without requiring a full index rebuild?","explanation":"**Correct choice:** `EF_RUNTIME` controls the size of the dynamic candidate list explored during the HNSW graph traversal at search time. Reducing `EF_RUNTIME` directly reduces search latency per query at the cost of some recall, and can be overridden per search without rebuilding the index.\n\n**Other choice:** `M` is a structural parameter fixed at index build time.\n\n**Other choice:** `EF_CONSTRUCTION` governs candidate list size during index construction, not per-query search time.\n\n**Other choice:** `DIM` is fixed to the embedding model output dimensionality.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/redis/","topic":"azure-managed-redis","type":"single","options":["EF_RUNTIME — this controls the size of the dynamic candidate list explored at query time; it can be overridden per-query (or via a lower index default) without rebuilding the index, and directly trades recall for latency at search time.","M — this controls the number of bi-directional links per node in the HNSW graph and can be changed at query time without any rebuild.","EF_CONSTRUCTION — this controls query-time candidate list size and can be tuned live per search.","DIM — reducing the vector dimensionality at query time lowers per-query compute without needing a rebuild."],"answer":0,"setId":"suralmk:ai200-practice-set","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/ai200-practice-set.json","reviewDate":"2026-10-11"},{"id":"suralmk:practice-041","prompt":"You provision pgvector on Azure Database for PostgreSQL Flexible Server and create a table for embedding storage:\n```sql\nCREATE EXTENSION IF NOT EXISTS vector;\nCREATE TABLE chunks (\n  id BIGSERIAL PRIMARY KEY,\n  text TEXT,\n  embedding VECTOR(1536)\n);\n\nINSERT INTO chunks (text, embedding)\nVALUES ('AKS scaling guide', '[0.01, 0.02, ...]');\n\nSELECT id, text, embedding \u003c=> '[0.05, 0.01, ...]' AS distance\nFROM chunks\nORDER BY embedding \u003c=> '[0.05, 0.01, ...]'\nLIMIT 10;\n```\nSimilarity queries work correctly but are slow as the table grows past 1 million rows. What is the most effective fix to reduce query latency at this scale?","explanation":"**Correct choice:** Without an ANN index, pgvector queries compute exact distance for every row in a sequential scan ($O(N)$). Creating an `hnsw` or `ivfflat` index using the appropriate operator class (`vector_cosine_ops` for `\u003c=>` cosine distance) enables index-accelerated vector search.\n\n**Other choice:** Standard B-tree indexes cannot index high-dimensional vector similarity operations.\n\n**Other choice:** Range partitioning on `id` does not replace the need for vector indexes.\n\n**Other choice:** Unbounded `VECTOR` columns do not provide performance optimizations.","domain":"data","source":"https://github.com/pgvector/pgvector","topic":"postgresql-pgvector","type":"single","options":["Create an approximate nearest-neighbor index on the embedding column, e.g., CREATE INDEX ON chunks USING hnsw (embedding vector_cosine_ops); (or ivfflat with an appropriate lists parameter), so the planner can use an index scan instead of a full sequential scan with exact distance computation on every row.","Add a B-tree index on embedding: CREATE INDEX ON chunks USING btree (embedding);.","Partition the table by id range into 10 partitions; pgvector automatically parallelizes similarity search across partitions with no index needed.","Change VECTOR(1536) to VECTOR (unbounded dimension) to allow the planner to use a more efficient generic comparison operator."],"answer":0,"setId":"suralmk:ai200-practice-set","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/ai200-practice-set.json","reviewDate":"2026-10-11"},{"id":"suralmk:practice-042","prompt":"You choose between hnsw and ivfflat index types for a pgvector table with 5 million embeddings that receives frequent new inserts throughout the day:\n```sql\nCREATE INDEX ON chunks USING ivfflat (embedding vector_l2_ops) WITH (lists = 100);\n```\nAfter a large batch insert of 500,000 new rows, query recall noticeably degrades until the index is manually rebuilt with REINDEX. Which statement best explains this and the recommended fix?","explanation":"**Correct choice:** `ivfflat` uses static cluster centroids computed during `CREATE INDEX`. As data shifts with heavy inserts, recall degrades until centroids are recomputed via `REINDEX`. `hnsw` is a graph index that updates incrementally on inserts without requiring routine `REINDEX` to maintain recall.\n\n**Other choice:** `hnsw` indexes do not suffer from static centroid drift.\n\n**Other choice:** Setting `lists` to 100,000 degrades search performance and doesn't make static centroids dynamic.\n\n**Other choice:** B-tree indexes do not support high-dimensional vector search.","domain":"data","source":"https://github.com/pgvector/pgvector","topic":"postgresql-pgvector","type":"single","options":["ivfflat indexes cluster vectors into a fixed number of lists (partitions) determined at index build time; as new data is inserted, the cluster centroids no longer represent the updated data distribution well, degrading recall until a REINDEX. Switching to an hnsw index avoids this issue because HNSW graphs are incrementally updated with each insert and don't require periodic rebuilding to maintain recall.","This is expected and unavoidable with pgvector regardless of index type; all pgvector indexes require nightly REINDEX for correctness.","The fix is to increase lists to 100,000 so every future insert gets its own cluster, eliminating the need for REINDEX permanently.","Switching to a B-tree index resolves the recall degradation since B-tree indexes update incrementally with every insert by design."],"answer":0,"setId":"suralmk:ai200-practice-set","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/ai200-practice-set.json","reviewDate":"2026-10-11"},{"id":"suralmk:practice-043","prompt":"You write a hybrid pgvector query finding the 5 nearest chunks to a query embedding, restricted to a specific document_id, and need it to use both the vector index and a filter efficiently:\n```sql\nSELECT id, text, embedding \u003c=> :query_vector AS distance\nFROM chunks\nWHERE document_id = :doc_id\nORDER BY embedding \u003c=> :query_vector\nLIMIT 5;\n```\nEXPLAIN ANALYZE shows the planner is performing a full sequential scan despite an hnsw index existing on embedding, even though document_id has very low selectivity (only a few rows match). What is the most likely explanation and fix?","explanation":"**Correct choice:** When an equality filter is highly selective, PostgreSQL's planner frequently calculates that filtering rows via a B-tree index on `document_id` and computing exact vector distances on the tiny matching subset is faster than probing the `hnsw` vector index. Creating a B-tree index on `document_id` and running `ANALYZE` enables optimal execution.\n\n**Other choice:** A partial index on `document_id IS NOT NULL` does not solve general filtering selectivity.\n\n**Other choice:** pgvector supports combining SQL `WHERE` clauses with vector `ORDER BY`.\n\n**Other choice:** `OFFSET 0` has no effect on index selection.","domain":"data","source":"https://github.com/pgvector/pgvector","topic":"postgresql-pgvector","type":"single","options":["PostgreSQL's hnsw vector index scan does not natively support arbitrary pre-filtering by another column; when the filter is highly selective, the planner may reasonably choose a sequential scan (filter first, then compute exact distances on the small remaining set) over probing the vector index and filtering afterward — adding a supporting B-tree index on document_id and analyzing table statistics can help the planner choose a better combined plan.","The hnsw index must be dropped and recreated with a WHERE document_id IS NOT NULL clause to support filtered queries.","pgvector does not support any form of filtered vector search; filtering and vector search must always be run as two entirely separate queries.","Change LIMIT 5 to LIMIT 5 OFFSET 0 to force index usage."],"answer":0,"setId":"suralmk:ai200-practice-set","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/ai200-practice-set.json","reviewDate":"2026-10-11"},{"id":"suralmk:practice-044","prompt":"Your team is choosing among pgvector, Cosmos DB Vector Search, and Redis Vector Search for a new RAG platform. Which comparison statement is the most accurate representation of their core trade-offs?","explanation":"**Correct choice:** This accurately states the architectural trade-offs: `pgvector` co-locates vectors with relational SQL/ACID data; `Cosmos DB Vector Search` provides distributed NoSQL scale and global multi-region replication; `Redis Vector Search` delivers sub-millisecond in-memory performance for fast retrieval/caching.\n\n**Other choice:** The three platforms differ fundamentally in data model, latency, and scaling.\n\n**Other choice:** All three platforms support approximate nearest-neighbor search (`HNSW`, `ivfflat`, etc.).\n\n**Other choice:** All three platforms support metadata filtering combined with vector search.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/cosmos-db/nosql/","topic":"cosmos-db-nosql","type":"single","options":["pgvector is ideal when the application already relies on PostgreSQL for relational/transactional data and wants vector search co-located with existing relational queries and ACID transactions; Cosmos DB Vector Search suits globally distributed, elastically scalable NoSQL workloads with native multi-region replication and tunable consistency; Redis Vector Search excels at ultra-low-latency in-memory retrieval, often as a caching/retrieval layer in front of a primary store, at the cost of memory being the primary cost/scale constraint.","All three provide identical consistency, latency, and scaling characteristics; the choice is purely about licensing cost.","Only Cosmos DB supports approximate nearest-neighbor search; pgvector and Redis only support brute-force exact search.","Redis Vector Search is the only option of the three that supports metadata filtering combined with vector search."],"answer":0,"setId":"suralmk:ai200-practice-set","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/ai200-practice-set.json","reviewDate":"2026-10-11"},{"id":"suralmk:practice-045","prompt":"A Python v2 HTTP Function returns success and sets its Storage Queue output binding. No messages appear in the queue account you inspected. Which evidence should you check first?","explanation":"A target mismatch is a diagnostic hypothesis. Check the configured connection, output parameter and runtime logs. Output bindings can create a missing queue, so absence of a precreated queue alone is not the claimed cause.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/azure-functions/functions-bindings-storage-queue-output","topic":"azure-functions","type":"single","options":["Confirm the binding setting resolves to that account and queue, then inspect host/binding logs","Assume missing queues can never be created by output bindings","Conclude HTTP 200 proves every binding targets the inspected account","Disable authentication on all storage accounts"],"answer":0,"setId":"suralmk:ai200-practice-set","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/ai200-practice-set.json","reviewDate":"2026-10-11","reviewNote":"Replaced an unsupported definitive diagnosis with evidence-based troubleshooting."},{"id":"suralmk:practice-046","prompt":"You configure a Service Bus-triggered function that must process messages with limited concurrency to avoid overwhelming a downstream API, and dead-letter messages that fail repeatedly:\n```json\n// host.json\n{\n  \"version\": \"2.0\",\n  \"extensions\": {\n    \"serviceBus\": {\n      \"maxConcurrentCalls\": 1,\n      \"maxAutoLockRenewalDuration\": \"00:05:00\"\n    }\n  }\n}\n```\n```python\n@app.function_name(name=\"ProcessOrder\")\n@app.service_bus_queue_trigger(\n    arg_name=\"msg\",\n    queue_name=\"orders\",\n    connection=\"ServiceBusConnection\"\n)\ndef process_order(msg: func.ServiceBusMessage):\n    body = msg.get_body().decode(\"utf-8\")\n    call_downstream_api(body)\n```\nMessages that repeatedly fail are being reprocessed indefinitely rather than being dead-lettered after a reasonable number of attempts. What must be configured to achieve automatic dead-lettering after repeated failures?","explanation":"**Correct choice:** Dead-lettering after repeated failed processing attempts is controlled by `MaxDeliveryCount` on the Azure Service Bus queue resource itself, not in `host.json`. When delivery count exceeds this threshold, Service Bus moves the message to the dead-letter queue.\n\n**Other choice:** `maxConcurrentCalls` controls invocation concurrency, not dead-lettering.\n\n**Other choice:** `deadLetteringOnMessageExpiration` is a queue property for expired messages.\n\n**Other choice:** Service Bus handles automatic dead-lettering on `MaxDeliveryCount` exceeded without requiring explicit code.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/service-bus-messaging/service-bus-messaging-overview","topic":"service-bus","type":"single","options":["maxConcurrentCalls must be increased, since a value of 1 disables dead-lettering entirely.","Dead-lettering after repeated delivery failures is governed by the Service Bus queue's own MaxDeliveryCount setting (configured on the Service Bus namespace/queue itself, e.g., via Azure CLI az servicebus queue update --max-delivery-count 5), not by host.json.","Add \"deadLetteringOnMessageExpiration\": true to host.json's serviceBus extension section.","The function code must explicitly catch exceptions and call msg.dead_letter() for every failure."],"answer":1,"setId":"suralmk:ai200-practice-set","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/ai200-practice-set.json","reviewDate":"2026-10-11"},{"id":"suralmk:practice-047","prompt":"You implement a Durable Functions fan-out/fan-in pattern to process a batch of files in parallel and aggregate results:\n```python\nimport azure.durable_functions as df\n\napp = df.DFApp()\n\n@app.orchestration_trigger(context_name=\"context\")\ndef orchestrator(context: df.DurableOrchestrationContext):\n    files = context.get_input()\n    tasks = []\n    for file in files:\n        tasks.append(context.call_activity(\"process_file\", file))\n    results = yield tasks\n    total = sum(results)\n    return total\n\n@app.activity_trigger(input_name=\"file\")\ndef process_file(file: str) -> int:\n    return len(file)\n```\nThe orchestrator raises a non-deterministic workflow warning/error during replay. What is the bug?","explanation":"**Correct choice:** In Durable Functions Python SDK, awaiting a fan-out collection requires `yield context.task_all(tasks)`. Yielding a raw Python `list` is non-durable and causes replay errors.\n\n**Other choice:** `process_file` is an activity function, correctly decorated with `@app.activity_trigger`.\n\n**Other choice:** `for` loops appending `context.call_activity` tasks are standard fan-out pattern.\n\n**Other choice:** `context.get_input()` is deterministic and safe.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/azure-functions/functions-overview","topic":"azure-functions","type":"single","options":["yield tasks should be yield context.task_all(tasks) — awaiting a raw Python list of durable task objects directly is not the documented fan-in pattern; context.task_all() is required to properly await all parallel activity tasks and yield their results as a list.","process_file should be marked with @app.orchestration_trigger instead of @app.activity_trigger.","The orchestrator function must not use a for loop; fan-out requires context.map() exclusively.","context.get_input() is non-deterministic and must be replaced with a hardcoded file list."],"answer":0,"setId":"suralmk:ai200-practice-set","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/ai200-practice-set.json","reviewDate":"2026-10-11"},{"id":"suralmk:practice-048","prompt":"You configure a Cosmos DB trigger function to process change feed events, and need it to use Managed Identity instead of a connection string:\n```json\n// function.json (or equivalent binding in Python v2 model)\n{\n  \"type\": \"cosmosDBTrigger\",\n  \"connectionStringSetting\": \"CosmosDBConnection\",\n  \"databaseName\": \"ragdb\",\n  \"collectionName\": \"chunks\",\n  \"leaseCollectionName\": \"leases\"\n}\n```\nTo use Managed Identity authentication instead of a connection string, which changes are required?","explanation":"**Correct choice:** Azure Functions identity-based connections use the `connection` property pointing to an app setting prefix (e.g. `CosmosDBConnection`). Setting `\u003cprefix>__accountEndpoint` to the account URI and assigning the managed identity Cosmos DB RBAC permissions enables identity-based trigger execution without keys.\n\n**Other choice:** Managed Identity is fully supported for Cosmos DB trigger bindings.\n\n**Other choice:** `authType` is not a valid binding property.\n\n**Other choice:** Authentication inside function code does not authenticate the trigger listener runtime.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/azure-functions/functions-overview","topic":"azure-functions","type":"single","options":["Replace connectionStringSetting with a connection property pointing to an app setting prefix (e.g., \"connection\": \"CosmosDBConnection\") where CosmosDBConnection__accountEndpoint is set to the Cosmos DB account URI (no key), and assign the Function App's managed identity the appropriate Cosmos DB RBAC role (e.g., Cosmos DB Built-in Data Contributor) on the account.","Managed Identity is not supported for Cosmos DB trigger bindings; a connection string is always required.","Add \"authType\": \"ManagedIdentity\" directly to the binding JSON; no app settings changes are needed.","Use DefaultAzureCredential inside the function body to authenticate; the binding's connectionStringSetting can remain a placeholder value."],"answer":0,"setId":"suralmk:ai200-practice-set","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/ai200-practice-set.json","reviewDate":"2026-10-11"},{"id":"suralmk:practice-049","prompt":"A Python HTTP Function decorates its handler with app.retry. Will that make the Functions runtime retry failed HTTP requests?","explanation":"Function-level retry policies support specific trigger types. HTTP does not use that policy. Service Bus and Storage Queue retry behavior is configured through their extensions/broker rather than that same decorator. Consult the trigger-specific retry table.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/azure-functions/functions-bindings-error-pages","topic":"service-bus","type":"single","options":["No; implement bounded retries for the downstream call or use an asynchronous workflow","Yes; every Functions trigger uses the same function-level policy","Yes; the HTTP client is automatically reconnected after every error","Only if maxDequeueCount is set on the HTTP trigger"],"answer":0,"setId":"suralmk:ai200-practice-set","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/ai200-practice-set.json","reviewDate":"2026-10-11","reviewNote":"Corrected the list of function-level retry-policy triggers."},{"id":"suralmk:practice-050","prompt":"You inject a shared httpx.AsyncClient into multiple Azure Functions using dependency injection patterns in the Python v2 model to avoid creating a new HTTP client per invocation:\n```python\nimport azure.functions as func\nimport httpx\n\napp = func.FunctionApp()\n_client = None\n\ndef get_client() -> httpx.AsyncClient:\n    global _client\n    if _client is None:\n        _client = httpx.AsyncClient()\n    return _client\n\n@app.route(route=\"fetch\")\nasync def fetch_data(req: func.HttpRequest) -> func.HttpResponse:\n    client = get_client()\n    resp = await client.get(\"https://api.example.com/data\")\n    return func.HttpResponse(resp.text)\n```\nUnder sustained load, the function app eventually starts throwing connection pool exhaustion errors. What is the most likely architectural issue?","explanation":"**Correct choice:** Module-level singletons reuse client connections within a process. However, high concurrency per process can exhaust default connection limits if `httpx.Limits(max_connections=..., max_keepalive_connections=...)` is untuned.\n\n**Other choice:** `httpx.AsyncClient` supports connection pooling natively via `httpx.Limits`.\n\n**Other choice:** `global` is standard Python and functions correctly.\n\n**Other choice:** Client connection pool exhaustion occurs locally before reaching the remote server.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/azure-functions/functions-overview","topic":"azure-functions","type":"single","options":["The module-level singleton pattern shown is reasonable for reusing a client across invocations within a single worker process, but Azure Functions can scale out to multiple worker processes/instances; under high concurrency, either the per-instance pool's default connection limits are being exceeded (requiring explicit httpx.Limits tuning), or the client is never properly closed across the app lifecycle.","httpx.AsyncClient() does not support connection pooling; it must be replaced with requests.Session().","The global keyword is invalid in Azure Functions Python apps.","Connection pool exhaustion is caused exclusively by the external API's rate limiting."],"answer":0,"setId":"suralmk:ai200-practice-set","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/ai200-practice-set.json","reviewDate":"2026-10-11"},{"id":"suralmk:practice-051","prompt":"You use an Event Grid-triggered function to react to blob creation events and need to filter for only .pdf files above a certain size, minimizing unnecessary invocations:\n```json\n{\n  \"type\": \"Microsoft.EventGrid/eventSubscriptions\",\n  \"properties\": {\n    \"destination\": {\n      \"endpointType\": \"AzureFunction\",\n      \"properties\": {\n        \"resourceId\": \"/subscriptions/.../functions/ProcessBlob\"\n      }\n    },\n    \"filter\": {\n      \"subjectBeginsWith\": \"/blobServices/default/containers/uploads/\",\n      \"subjectEndsWith\": \".pdf\"\n    }\n  }\n}\n```\n```python\n@app.event_grid_trigger(arg_name=\"event\")\ndef process_blob(event: func.EventGridEvent):\n    data = event.get_json()\n    size = data.get(\"contentLength\", 0)\n    if size \u003c 1024 * 1024:\n        return # skip small files\n    process_pdf(data[\"url\"])\n```\nThe team wants to reduce cost by never invoking the function at all for files under 1 MB, rather than invoking it and returning early. What change accomplishes this at the Event Grid subscription level?","explanation":"**Correct choice:** Event Grid `advancedFilters` allow filtering on payload fields like `data.contentLength` using `NumberGreaterThanOrEquals`. Events are dropped server-side at Event Grid before invoking the Function App, avoiding execution costs.\n\n**Other choice:** Event Grid explicitly supports `advancedFilters` on payload data fields.\n\n**Other choice:** Adding a Logic App adds unnecessary cost and latency.\n\n**Other choice:** `maxDeliveryAttempts` controls failure retries, not initial event filtering.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/event-grid/overview","topic":"event-grid","type":"single","options":["Add an advancedFilter to the subscription's filter block matching on the event data's contentLength property with a NumberGreaterThanOrEquals operator (data.contentLength >= 1048576) — this filters events server-side at Event Grid before delivery, avoiding function invocation entirely.","This isn't possible; Event Grid subscription filters only support subject-based string filtering.","Change contentLength filtering to happen in a Logic App placed in front of the function.","Reduce maxDeliveryAttempts to 1 so undersized events aren't retried."],"answer":0,"setId":"suralmk:ai200-practice-set","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/ai200-practice-set.json","reviewDate":"2026-10-11"},{"id":"suralmk:practice-052","prompt":"An Event Hubs-triggered Function uses extension 5.x or later. Which host.json property sets the maximum number of events passed to one batch invocation?","explanation":"Current extensions use maxEventBatchSize. Older samples used eventProcessorOptions.maxBatchSize. Batch checkpoint frequency is a separate trade-off: fewer checkpoints can increase replay after failure. Match settings to the installed extension.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/azure-functions/functions-bindings-event-hubs","topic":"opentelemetry","type":"single","options":["extensions.eventHubs.maxEventBatchSize","extensions.eventHubs.eventProcessorOptions.maxBatchSize","extensions.serviceBus.maxDeliveryCount","extensions.eventHubs.connectionLimit"],"answer":0,"setId":"suralmk:ai200-practice-set","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/ai200-practice-set.json","reviewDate":"2026-10-11","reviewNote":"Updated the version-dependent Event Hubs batching schema."},{"id":"suralmk:practice-053","prompt":"You retrieve a secret from Key Vault using DefaultAzureCredential in code that must work identically both locally (developer signed in via Azure CLI) and in production (running in a Container App with a user-assigned managed identity), without any code branching:\n```python\nfrom azure.identity import DefaultAzureCredential\nfrom azure.keyvault.secrets import SecretClient\n\ncredential = DefaultAzureCredential()\nclient = SecretClient(vault_url=\"https://myvault.vault.azure.net/\", credential=credential)\nsecret = client.get_secret(\"db-password\")\n```\nIn production, this throws a credential authentication failure, while locally (via az login) it works fine. The Container App has a user-assigned managed identity configured. What's missing?","explanation":"**Correct choice:** User-assigned managed identities require specifying the client ID (`managed_identity_client_id` parameter or `AZURE_CLIENT_ID` env var) so `DefaultAzureCredential` knows which identity to request tokens for. Locally, it falls back to Azure CLI without issue.\n\n**Other choice:** `DefaultAzureCredential` is designed for both local and production environments.\n\n**Other choice:** User-assigned managed identities are fully supported by `DefaultAzureCredential`.\n\n**Other choice:** `SecretClient` does not require explicit `api_version` for managed identities.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/key-vault/general/overview","topic":"key-vault","type":"single","options":["DefaultAzureCredential must be explicitly told which managed identity to use via managed_identity_client_id (or AZURE_CLIENT_ID environment variable), because when multiple identity sources could apply (and specifically with user-assigned managed identities) DefaultAzureCredential's ManagedIdentityCredential step needs the specific client ID to select the correct identity.","DefaultAzureCredential only works in local development; production code must always use ManagedIdentityCredential explicitly.","The Container App's managed identity must be system-assigned; user-assigned identities are not supported by DefaultAzureCredential.","SecretClient requires an explicit api_version parameter when used with managed identity credentials."],"answer":0,"setId":"suralmk:ai200-practice-set","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/ai200-practice-set.json","reviewDate":"2026-10-11"},{"id":"suralmk:practice-054","prompt":"A Python app uses azure-appconfiguration-provider to load a Key Vault reference. How can it supply the identity used to resolve that reference?","explanation":"The Python provider exposes keyvault_credential and per-vault/resolver options. It does not use the displayed AzureAppConfigurationKeyVaultOptions API. The client identity needs access to both services as appropriate.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/azure-app-configuration/reference-python-provider","topic":"app-configuration","type":"single","options":["Pass keyvault_credential=DefaultAzureCredential() to load and authorize that identity to read the secret","Pass key_vault_options=AzureAppConfigurationKeyVaultOptions(...) from a different language SDK","Grant App Configuration itself the secret and assume the provider needs no identity","Store the actual secret in the reference URI"],"answer":0,"setId":"suralmk:ai200-practice-set","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/ai200-practice-set.json","reviewDate":"2026-10-11","reviewNote":"Replaced a nonexistent Python provider API."},{"id":"suralmk:practice-055","prompt":"You implement secret rotation awareness so your application always uses the latest version of a Key Vault secret without redeploying, and without a long-lived cache serving a stale/revoked version indefinitely:\n```python\nfrom azure.keyvault.secrets import SecretClient\nfrom azure.identity import DefaultAzureCredential\nimport time\n\nclient = SecretClient(vault_url=vault_url, credential=DefaultAzureCredential())\n_cache = {}\n\ndef get_db_password():\n    if \"db-password\" not in _cache:\n        secret = client.get_secret(\"db-password\") # version-less request\n        _cache[\"db-password\"] = {\"value\": secret.value, \"cachedAt\": time.time()}\n    return _cache[\"db-password\"][\"value\"]\n```\nThis caches the secret indefinitely after first retrieval, meaning a rotated secret is never picked up until the process restarts. What is the best fix that balances reducing Key Vault call volume with staying reasonably current after rotation?","explanation":"**Correct choice:** Adding a Time-To-Live (TTL) check balances Key Vault call volume reduction with secret rotation freshness. Periodically re-fetching the secret (e.g. hourly) allows version-less secret rotation to take effect automatically without requiring process restarts or excessive API calls.\n\n**Other choice:** Fetching from Key Vault on every single request introduces severe latency and causes API throttling.\n\n**Other choice:** Requesting a pinned version prevents picking up newly rotated secret versions.\n\n**Other choice:** Azure Key Vault does not push real-time updates directly into application memory.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/key-vault/general/overview","topic":"key-vault","type":"single","options":["Remove caching entirely and call get_secret(\"db-password\") on every single use of the password, regardless of call frequency.","Add a TTL check (e.g., re-fetch if time.time() - cachedAt > 3600) so the cached value is refreshed periodically (e.g., hourly) rather than only once at startup — balancing reduced Key Vault call volume against staying reasonably current within the TTL window after a rotation event.","Request a specific pinned secret version (e.g., client.get_secret(\"db-password\", version=\"abc123\")) so the cache is always guaranteed correct.","Rely on Key Vault's server-side push notifications to automatically update the local _cache dictionary in real time; no TTL logic is needed."],"answer":1,"setId":"suralmk:ai200-practice-set","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/ai200-practice-set.json","reviewDate":"2026-10-11"},{"id":"suralmk:practice-056","prompt":"An OpenTelemetry parent span exists in one Python thread, but work submitted to a new ThreadPoolExecutor worker starts an unrelated root span. What should you investigate?","explanation":"Python contextvars normally propagate across standard asyncio task/context boundaries. New threads may require explicit context propagation or supported instrumentation. A nested synchronous example alone does not prove missing context.","domain":"operations","source":"https://opentelemetry.io/docs/languages/python/propagation/","topic":"opentelemetry","type":"single","options":["Propagate the context into the worker thread, for example with a context copy or thread instrumentation","Assume every ordinary await automatically loses contextvars","Set a new random trace ID for every nested call","Remove all parent spans"],"answer":0,"setId":"suralmk:ai200-practice-set","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/ai200-practice-set.json","reviewDate":"2026-10-11","reviewNote":"Corrected the claim that ordinary await necessarily loses trace context."},{"id":"suralmk:practice-057","prompt":"You add custom baggage to propagate a tenantId across service boundaries in a distributed trace using OpenTelemetry:\n\nSender:\n```python\nfrom opentelemetry import baggage, context\nfrom opentelemetry.propagate import inject\n\nctx = baggage.set_baggage(\"tenantId\", \"tenant-42\")\nheaders = {}\ninject(headers, context=ctx)\nresponse = requests.post(\"https://inventory-service/api/check\", headers=headers)\n```\nReceiver:\n```python\ntenant_id = baggage.get_baggage(\"tenantId\")\n```\nOn the receiving service, code attempts to read the baggage value but gets None. What is missing on the receiving side?","explanation":"**Correct choice:** Baggage received over HTTP headers must be extracted on the receiver side via `opentelemetry.propagate.extract(headers)` and attached to the execution context (`context.attach(extracted_ctx)`). Without extraction and attachment, `baggage.get_baggage()` queries an empty active context.\n\n**Other choice:** `baggage.set_baggage` does not have a `persist` parameter.\n\n**Other choice:** OpenTelemetry Baggage is explicitly designed for cross-service context propagation.\n\n**Other choice:** `inject(headers)` populates standard W3C baggage headers into Python dicts.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/azure-monitor/app/opentelemetry-overview","topic":"opentelemetry","type":"single","options":["The receiving service must extract the incoming context from the request headers using opentelemetry.propagate.extract(headers) and activate it (e.g., via context.attach(extracted_ctx)) before calling baggage.get_baggage(), which by default reads from the current active context.","baggage.set_baggage on the sender must be called with persist=True for the value to survive HTTP transport.","Baggage cannot be propagated over HTTP; it only works within a single process's contextvars.","The header format used by inject() is incompatible with requests; a raw dict cannot be used as the headers argument."],"answer":0,"setId":"suralmk:ai200-practice-set","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/ai200-practice-set.json","reviewDate":"2026-10-11"},{"id":"suralmk:practice-058","prompt":"You write a KQL query against Application Insights to find, per API endpoint, the 95th-percentile response time over the last 24 hours, along with the count of requests, grouped into 1-hour buckets for a trend chart:\n```kql\nrequests\n| where timestamp > ago(24h)\n| ???\n```\nWhich completion correctly produces per-endpoint, per-hour p95 latency and request count?","explanation":"**Correct choice:** `percentile(duration, 95)` computes the 95th percentile duration within each summarized group. Grouping by `name, bin(timestamp, 1h)` aggregates results per endpoint and 1-hour time window.\n\n**Other choice:** `avg(duration) * 0.95` computes 95% of average duration, not the 95th percentile.\n\n**Other choice:** `percentile()` is an aggregation function and cannot be used inside `extend`.\n\n**Other choice:** Grouping by raw `timestamp` creates a group per individual log event instead of hourly buckets.","domain":"operations","source":"https://learn.microsoft.com/en-us/kusto/query/","topic":"kql","type":"single","options":["| summarize p95 = percentile(duration, 95), count() by name, bin(timestamp, 1h)","| summarize p95 = avg(duration) * 0.95, count() by name, bin(timestamp, 1h)","| extend p95 = percentile(duration, 95) | summarize count() by name, bin(timestamp, 1h)","| summarize p95 = percentile(duration, 95), count() by name, timestamp"],"answer":0,"setId":"suralmk:ai200-practice-set","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/ai200-practice-set.json","reviewDate":"2026-10-11"},{"id":"suralmk:practice-059","prompt":"You write a KQL query to find, for each cloud_RoleInstance, only the most recent exception event, using arg_max():\n```kql\nexceptions\n| where timestamp > ago(7d)\n| ???\n```\nWhich completion correctly returns one row per cloud_RoleInstance representing its most recent exception, including all columns of that specific event?","explanation":"**Correct choice:** `arg_max(timestamp, *) by cloud_RoleInstance` is KQL's standard aggregator for returning the full row (`*`) corresponding to the maximum timestamp per group (`cloud_RoleInstance`).\n\n**Other choice:** `max(timestamp)` returns only the timestamp scalar column, omitting exception message/details.\n\n**Other choice:** `top 1 by timestamp desc` returns a single row overall across the entire dataset.\n\n**Other choice:** `arg_max(timestamp)` without `*` returns only the timestamp value.","domain":"operations","source":"https://learn.microsoft.com/en-us/kusto/query/","topic":"kql","type":"single","options":["| summarize arg_max(timestamp, *) by cloud_RoleInstance","| summarize max(timestamp) by cloud_RoleInstance","| top 1 by timestamp desc","| summarize arg_max(timestamp) by cloud_RoleInstance"],"answer":0,"setId":"suralmk:ai200-practice-set","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/ai200-practice-set.json","reviewDate":"2026-10-11"},{"id":"suralmk:practice-060","prompt":"A head sampler keeps 10% of traces. The team now wants to retain every trace that ends in an error. Which design issue must be addressed?","explanation":"Trace sampling and metric aggregation are different. Head-sampled-away spans cannot be recovered at ingestion. Tail sampling evaluates completed trace information but needs suitable buffering, export support and an unsampled input pipeline; validate the chosen backend integration.","domain":"operations","source":"https://opentelemetry.io/docs/concepts/sampling/","topic":"opentelemetry","type":"single","options":["A head decision cannot know the final outcome; use a supported tail-sampling pipeline receiving unsampled spans if outcome-based retention is required","Set sampling_ratio=0.1 and assume errors bypass it","Apply an ingestion filter to recover spans that the SDK already discarded","Sample metrics and assume that preserves every failed trace"],"answer":0,"setId":"suralmk:ai200-practice-set","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/ai200-practice-set.json","reviewDate":"2026-10-11","reviewNote":"Removed the suggestion that a head or ingestion policy can recover discarded failed traces."},{"id":"suralmk:svc-101","prompt":"Which Azure service should you use to reliably queue back-end processing tasks (such as document embedding jobs) with guaranteed delivery and support for dead-letter handling?","explanation":"Azure Service Bus is a fully managed enterprise message broker supporting queues and topics/subscriptions with dead-letter queues, ideal for reliable back-end task processing. Event Grid is optimized for lightweight, reactive event notifications rather than durable task queuing, Blob Storage is object storage without native queuing semantics, and CDN accelerates content delivery, unrelated to messaging.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/service-bus-messaging/service-bus-messaging-overview","topic":"service-bus","type":"single","options":["Azure Service Bus","Azure Event Grid","Azure Blob Storage","Azure CDN delivery"],"answer":0,"setId":"suralmk:azure-services-160","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/azure-services-160.json","reviewDate":"2026-10-11"},{"id":"suralmk:svc-102","prompt":"Messages in an Azure Service Bus queue that repeatedly fail processing (e.g., due to malformed embedding requests) should be automatically moved aside after a maximum delivery count is reached. What handles this?","explanation":"Service Bus automatically moves a message to its associated dead-letter sub-queue once MaxDeliveryCount is exceeded (or on explicit dead-lettering), allowing failed messages to be inspected without blocking the main queue. Manual hourly polling is unreliable and delayed, Event Grid's retry policy applies to Event Grid delivery (not Service Bus queues), and increasing TTL just delays expiration without addressing repeated failures.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/service-bus-messaging/service-bus-messaging-overview","topic":"service-bus","type":"single","options":["Dead-letter queue after MaxDeliveryCount","Hourly script that deletes failed messages","Event Grid retry policy on the publisher","Indefinitely raised message TTL on the queue"],"answer":0,"setId":"suralmk:azure-services-160","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/azure-services-160.json","reviewDate":"2026-10-11"},{"id":"suralmk:svc-103","prompt":"You need multiple independent downstream systems (an indexing service, an audit service, and a notification service) to each receive a copy of every 'document uploaded' message. Which Service Bus entity type should you use?","explanation":"Topics implement publish/subscribe: each subscription attached to the topic receives its own copy of every matching message, exactly matching the requirement for three independent consumers. A single shared queue only delivers each message to one consumer (competing consumers pattern), round-robin distribution across a queue also delivers each message once, and sessions relate to ordered/grouped processing, not fan-out to multiple independent consumers.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/service-bus-messaging/service-bus-messaging-overview","topic":"service-bus","type":"single","options":["Topic with multiple subscriptions","Single queue shared by all consumers","One queue per message with round-robin","Session-enabled queue without any topic"],"answer":0,"setId":"suralmk:azure-services-160","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/azure-services-160.json","reviewDate":"2026-10-11"},{"id":"suralmk:svc-104","prompt":"An AI pipeline uses Service Bus topics with subscriptions filtered by message properties (e.g., only 'priority=high' messages go to an urgent-processing subscription). Which subscription feature enables this?","explanation":"Subscription filters — SQL filters (property-based boolean expressions) or correlation filters (matching specific property values) — determine which messages published to a topic are delivered to a given subscription, enabling selective routing like priority-based filtering. Dead-letter queues handle failed messages (not routing logic), namespace partitioning affects storage/throughput distribution, and lock duration governs how long a message is invisible to other receivers during processing.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/service-bus-messaging/service-bus-messaging-overview","topic":"service-bus","type":"single","options":["SQL or correlation filter on the subscription","Dead-letter queue attached to the topic root","Partitioning enabled on the Service Bus namespace","Longer lock duration on the subscription entity"],"answer":0,"setId":"suralmk:azure-services-160","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/azure-services-160.json","reviewDate":"2026-10-11"},{"id":"suralmk:svc-105","prompt":"Which Azure service is best suited for reacting to lightweight, discrete system events — such as a new blob being created — by triggering downstream workflows with built-in retry and filtering?","explanation":"Event Grid is a highly scalable, low-latency event routing service purpose-built for reactive event-driven architectures (e.g., BlobCreated events), with native support for event filtering and configurable retry policies. Service Bus queues are better suited to durable task processing rather than lightweight system event notification, Data Factory targets ETL orchestration, and Azure Files is a file share service with no event routing capability of its own.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/service-bus-messaging/service-bus-messaging-overview","topic":"service-bus","type":"single","options":["Azure Event Grid","Azure Service Bus","Azure Data Factory","Azure Files shares"],"answer":0,"setId":"suralmk:azure-services-160","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/azure-services-160.json","reviewDate":"2026-10-11"},{"id":"suralmk:svc-106","prompt":"You want an Event Grid subscription to only trigger your Azure Function for blob creation events under a specific folder path ending in '.pdf', ignoring all other blob events. What should you configure?","explanation":"Event Grid event subscriptions support subject filters (subjectBeginsWith for path prefix, subjectEndsWith for suffix like '.pdf') to narrow which events are delivered to a given handler, exactly matching this filtering requirement. Correlation filters are a Service Bus topic feature, not Event Grid, there's no such generic Function app setting for event filtering, and lifecycle management rules control blob tiering/deletion, unrelated to event delivery.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/service-bus-messaging/service-bus-messaging-overview","topic":"service-bus","type":"single","options":["Subject begins/endsWith filters on the subscription","Service Bus correlation filter on a topic entity","Function app setting named FilterPath for paths","Storage lifecycle rule controlling blob tiering"],"answer":0,"setId":"suralmk:azure-services-160","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/azure-services-160.json","reviewDate":"2026-10-11"},{"id":"suralmk:svc-107","prompt":"An Event Grid-triggered downstream service occasionally goes offline briefly, causing event delivery failures. You need failed events to be retried with exponential backoff and eventually captured for manual review rather than silently dropped. What should you configure?","explanation":"Event Grid event subscriptions support configurable retry policies (exponential backoff automatically applied, with max delivery attempts and event TTL) plus an optional dead-letter destination, so persistently failing events are retried appropriately and then preserved for review rather than lost. Disabling retries increases the chance of permanent data loss on transient outages, bypassing Event Grid removes its delivery guarantees entirely, and manual daily resends aren't a scalable or reliable event delivery mechanism.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/event-grid/overview","topic":"event-grid","type":"single","options":["Retry policy plus dead-letter Storage destination","Disable retries to avoid any duplicate deliveries","Fire-and-forget HTTP with no Event Grid sub","Publisher manually resends all events each day"],"answer":0,"setId":"suralmk:azure-services-160","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/azure-services-160.json","reviewDate":"2026-10-11"},{"id":"suralmk:svc-108","prompt":"Which Azure Functions trigger type causes a function to execute automatically whenever a new message arrives in a Service Bus queue?","explanation":"The Service Bus trigger binds a function to a queue or topic subscription and invokes the function automatically as new messages arrive, handling completion/abandon semantics for you. HTTP triggers respond to inbound web requests, Timer triggers run on a defined schedule (CRON), and Blob triggers fire on blob storage changes — none react to Service Bus messages directly.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/service-bus-messaging/service-bus-messaging-overview","topic":"service-bus","type":"single","options":["Service Bus trigger","HTTP request trigger","Timer schedule trigger","Blob storage trigger"],"answer":0,"setId":"suralmk:azure-services-160","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/azure-services-160.json","reviewDate":"2026-10-11"},{"id":"suralmk:svc-109","prompt":"An HTTP-triggered Python Function needs centrally managed configuration at startup. How should its application code load Azure App Configuration values?","explanation":"Load configuration with the App Configuration Python provider and appropriate credentials. This populates an application configuration object; it does not create a native App Configuration input-binding parameter.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/azure-app-configuration/reference-python-provider","topic":"app-configuration","type":"single","options":["App Configuration provider wired in function startup","Hardcoded configuration value inside function.json","Local-only environment variable on a laptop","Blob trigger reading a config file from storage"],"answer":0,"setId":"suralmk:azure-services-160","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/azure-services-160.json","reviewDate":"2026-10-11","reviewNote":"App Configuration providers are not native Functions input bindings."},{"id":"suralmk:svc-110","prompt":"An Azure Function with an HTTP trigger calls Azure OpenAI to generate embeddings, but occasionally times out under high load because the default HTTP trigger timeout is exceeded. What is the most appropriate architectural fix?","explanation":"For long-running operations that can exceed HTTP trigger limits, the standard pattern is asynchronous processing — accept and queue the request, process it out-of-band, and let clients poll a status endpoint or receive a webhook/callback, which sidesteps synchronous timeout constraints entirely. The Consumption plan has a hard timeout ceiling that cannot be set to unlimited, tightening a synchronous retry loop doesn't solve the fundamental timeout constraint, and simply changing languages doesn't address the architectural timeout issue.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/azure-functions/functions-overview","topic":"azure-functions","type":"single","options":["Queue the work; process async; client polls status","Set unlimited HTTP timeout on the Consumption plan","Tighten sync OpenAI retries without changing pattern","Change function language from Python to C# only"],"answer":0,"setId":"suralmk:azure-services-160","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/azure-services-160.json","reviewDate":"2026-10-11"},{"id":"suralmk:svc-111","prompt":"Which Azure Functions binding type allows a function to write output directly to a Cosmos DB container without manually instantiating a CosmosClient?","explanation":"Azure Functions' Cosmos DB output binding lets the runtime handle writing the function's return value (or bound object) directly to a specified container, abstracting away explicit SDK client management. Manually issuing REST calls or using unrelated bindings (queue trigger, App Configuration) doesn't provide this declarative Cosmos DB write integration.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/azure-app-configuration/overview","topic":"app-configuration","type":"single","options":["Cosmos DB output binding in function.json/attributes","HTTP trigger with a hand-written REST Cosmos call","Queue trigger configured with no Cosmos binding","App Configuration binding writing to Cosmos DB"],"answer":0,"setId":"suralmk:azure-services-160","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/azure-services-160.json","reviewDate":"2026-10-11"},{"id":"suralmk:svc-112","prompt":"Which Azure Functions Core Tools command publishes local code to an existing Function App?","explanation":"func azure functionapp publish belongs to Azure Functions Core Tools. The az command family belongs to Azure CLI.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/azure-functions/functions-run-local","topic":"azure-functions","type":"single","options":["func azure functionapp publish myFunctionApp","az functionapp create --name myFunctionApp","az webapp deploy --name myFunctionApp --type zip","docker push myFunctionApp:latest to a registry"],"answer":0,"setId":"suralmk:azure-services-160","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/azure-services-160.json","reviewDate":"2026-10-11","reviewNote":"Distinguished Functions Core Tools from Azure CLI."},{"id":"suralmk:svc-113","prompt":"A Service Bus-triggered Azure Function processing embedding jobs must guarantee that messages are only removed from the queue after processing succeeds, so a function crash mid-processing causes automatic redelivery. What behavior achieves this?","explanation":"With PeekLock (the Functions runtime default), a message is only marked complete after the function finishes successfully; if the function crashes, the lock expires and the message becomes visible again for redelivery, giving at-least-once processing guarantees. ReceiveAndDelete removes the message immediately on receipt regardless of processing outcome, risking message loss on failure; disabling retries removes the safety net entirely; and a zero TTL would cause messages to expire immediately, unrelated to delivery guarantees.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/service-bus-messaging/service-bus-messaging-overview","topic":"service-bus","type":"single","options":["PeekLock complete-after-success (Functions default)","ReceiveAndDelete removing messages on first receive","Retries disabled at the Service Bus namespace level","Message TTL set to zero so items expire instantly"],"answer":0,"setId":"suralmk:azure-services-160","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/azure-services-160.json","reviewDate":"2026-10-11"},{"id":"suralmk:svc-114","prompt":"You need an Event Grid custom topic to publish events from a custom application (not a built-in Azure resource) whenever a new AI model version is registered. What must you create and use to publish events?","explanation":"Custom applications publish domain-specific events by creating an Event Grid custom topic and using the EventGridPublisherClient (or equivalent REST calls) authenticated via key or Entra ID to send events to that topic's endpoint, which then fans out to any subscribed handlers. A Service Bus queue or Storage queue could carry messages but wouldn't provide Event Grid's native filtering/fan-out subscription model being asked about, and an App Configuration key is unrelated to event publishing.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/azure-app-configuration/overview","topic":"app-configuration","type":"single","options":["Custom topic; publish via EventGridPublisherClient","Service Bus queue named events for fan-out only","Storage queue with subscribers polling manually","App Configuration key named CustomEvents publish"],"answer":0,"setId":"suralmk:azure-services-160","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/azure-services-160.json","reviewDate":"2026-10-11"},{"id":"suralmk:svc-115","prompt":"Your Azure Function needs to both trigger on new blobs and write processed results back to a different container, entirely through declarative bindings rather than manual SDK calls. Which binding types should you use together?","explanation":"Pairing a Blob trigger (fires on new/updated blobs in the source container) with a Blob output binding (writes the result to a target container) lets Functions handle both input and output declaratively without manual BlobServiceClient calls. HTTP+Timer triggers don't react to blob events at all, Cosmos DB triggers react to change feed (not blob creation) and Event Grid isn't an output binding type, and using only a Service Bus trigger with no output mechanism wouldn't write results anywhere.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/service-bus-messaging/service-bus-messaging-overview","topic":"service-bus","type":"single","options":["Blob trigger for input and Blob output for results","HTTP trigger for input and Timer binding for output","Cosmos trigger for input and Event Grid for output","Service Bus trigger alone with no output binding"],"answer":0,"setId":"suralmk:azure-services-160","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/azure-services-160.json","reviewDate":"2026-10-11"},{"id":"suralmk:svc-116","prompt":"A high-throughput AI ingestion pipeline needs ordered processing of events per customer, guaranteeing that events for the same customer are always processed in the order they were sent, while different customers can be processed in parallel. Which Service Bus feature should you use?","explanation":"Service Bus sessions group related messages (using a shared SessionId, e.g., customer ID) and guarantee in-order, exclusive processing within that session while different sessions can be processed concurrently by different receivers — precisely matching per-customer ordering with cross-customer parallelism. A default queue doesn't guarantee this per-key ordering under concurrent consumers, unfiltered topics don't address ordering at all, and merely sharing a partition key without enabling sessions doesn't provide the exclusive in-order locking sessions offer.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/service-bus-messaging/service-bus-messaging-overview","topic":"service-bus","type":"single","options":["Sessions using customer ID as the SessionId","Single unsharded queue with default global FIFO","Topics with no subscription filters configured","Shared partition key without enabling sessions"],"answer":0,"setId":"suralmk:azure-services-160","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/azure-services-160.json","reviewDate":"2026-10-11"},{"id":"suralmk:svc-117","prompt":"Which Azure Functions hosting plan should you choose for an AI workload that must avoid cold starts entirely and needs predictable, dedicated compute with support for longer execution times?","explanation":"The Premium plan keeps a configurable number of pre-warmed instances always ready (eliminating cold starts), offers longer execution durations than Consumption, and provides more predictable performance for latency-sensitive AI workloads. The Consumption plan can experience cold starts and has a default hard timeout, Static Web Apps doesn't host general-purpose Functions workloads of this kind, and a hosting plan is always required to run Azure Functions.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/azure-functions/functions-overview","topic":"azure-functions","type":"single","options":["Premium or Dedicated App Service plan","Consumption plan with possible cold starts","Static Web Apps free tier hosting only","No hosting plan required for Functions"],"answer":0,"setId":"suralmk:azure-services-160","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/azure-services-160.json","reviewDate":"2026-10-11"},{"id":"suralmk:svc-118","prompt":"Which Azure service acts as a centralized store for application feature flags and configuration values that can be shared across multiple microservices?","explanation":"Azure App Configuration is purpose-built for centralized management of application settings and feature flags across distributed services, with dynamic refresh support. Key Vault is designed for secrets/keys/certificates (not general config or feature flags), Monitor is for observability data, and Container Registry stores container images, unrelated to configuration management.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/azure-app-configuration/overview","topic":"app-configuration","type":"single","options":["Azure App Configuration","Azure Key Vault secrets","Azure Monitor metrics","Azure Container Registry"],"answer":0,"setId":"suralmk:azure-services-160","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/azure-services-160.json","reviewDate":"2026-10-11"},{"id":"suralmk:svc-119","prompt":"Your team wants Azure App Configuration to serve different configuration values to a 'canary' subset of AI service instances versus the general population, without redeploying code. What feature should you use?","explanation":"App Configuration's feature management supports targeting filters that can route a percentage of traffic or specific users/groups to different flag states, enabling canary-style configuration rollout without redeployment. Maintaining separate stores manually is operationally heavy and error-prone, hardcoded hostname logic requires code changes/redeploys (defeating the goal), and Key Vault secret versioning manages secret values, not feature targeting logic.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/azure-app-configuration/overview","topic":"app-configuration","type":"single","options":["Feature flags with percentage or group targeting","Separate App Configuration store per instance","Hardcoded if/else based on machine hostname","Key Vault secret versioning for feature routing"],"answer":0,"setId":"suralmk:azure-services-160","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/azure-services-160.json","reviewDate":"2026-10-11"},{"id":"suralmk:svc-120","prompt":"You need Service Bus, Event Grid, and Azure Functions to authenticate to each other and to downstream Azure resources without any connection strings or keys stored in application settings. What is the recommended architecture?","explanation":"Assigning managed identities to each compute resource and granting them fine-grained Azure RBAC roles (like Azure Service Bus Data Sender/Receiver) is the Microsoft-recommended, keyless authentication pattern that eliminates secret sprawl entirely. Plain environment variable connection strings and hardcoded long-lived SAS keys both create secret-management and rotation risk, and disabling authentication is a severe security anti-pattern regardless of workload sensitivity.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/service-bus-messaging/service-bus-messaging-overview","topic":"service-bus","type":"single","options":["Managed identities with RBAC roles on each resource","Plain connection strings in Function App settings","One shared SAS key hardcoded across all services","Authentication disabled between all internal apps"],"answer":0,"setId":"suralmk:azure-services-160","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/azure-services-160.json","reviewDate":"2026-10-11"},{"id":"suralmk:svc-121","prompt":"Which Azure Functions binding direction should be used if a function needs to send a new message onto a Service Bus queue as part of its execution, without manually creating a ServiceBusClient?","explanation":"An output binding lets the Functions runtime handle sending a message to the specified Service Bus queue/topic when the function returns or sets the bound value, avoiding manual SDK client setup. An input binding retrieves data (not sends), triggers define what invokes the function (not a generic output mechanism), and while the SDK client is a valid alternative, it isn't required — the output binding is the simpler declarative option being asked about.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/service-bus-messaging/service-bus-messaging-overview","topic":"service-bus","type":"single","options":["Output binding targeting the Service Bus queue","Input binding on the same queue as the trigger","Trigger binding with direction incorrectly set out","No binding; always require a manual SDK client"],"answer":0,"setId":"suralmk:azure-services-160","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/azure-services-160.json","reviewDate":"2026-10-11"},{"id":"suralmk:svc-122","prompt":"An AI orchestration workflow spans multiple Azure Functions with fan-out/fan-in patterns (calling several activities in parallel, then aggregating results) and needs reliable state management across long-running executions. What should you use?","explanation":"Durable Functions extends Azure Functions with stateful orchestration, natively supporting fan-out/fan-in, chaining, and long-running workflows while automatically checkpointing progress for reliability. Plain stateless functions calling each other synchronously don't provide durable state or automatic retry/checkpointing, a single monolithic function loses the parallelism and modularity fan-out/fan-in requires, and Event Grid alone doesn't provide the stateful coordination an orchestrator does.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/event-grid/overview","topic":"event-grid","type":"single","options":["Durable Functions orchestrator for fan-out/fan-in","Stateless HTTP functions calling each other sync","Single monolithic function running all steps serially","Event Grid alone without any orchestration layer"],"answer":0,"setId":"suralmk:azure-services-160","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/azure-services-160.json","reviewDate":"2026-10-11"},{"id":"suralmk:svc-123","prompt":"You need to configure an Event Grid subscription so failed events are ultimately stored for later analysis rather than discarded after retries are exhausted. Where should this be configured?","explanation":"Event Grid event subscriptions include a dedicated dead-letter destination setting (commonly a Blob Storage container) where events that exhaust retries are automatically written for later inspection. Access keys govern authentication (not dead-lettering), CORS settings control cross-origin browser requests (irrelevant here), and resource-group-level diagnostic settings capture platform logs, not per-subscription dead-lettered events.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/event-grid/overview","topic":"event-grid","type":"single","options":["Dead letter destination on the event subscription","Access keys section of the Event Grid topic","CORS settings on the subscriber Function App","Diagnostic settings at the resource group scope"],"answer":0,"setId":"suralmk:azure-services-160","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/azure-services-160.json","reviewDate":"2026-10-11"},{"id":"suralmk:svc-124","prompt":"Which of the following is the correct Azure CLI command to create a new Service Bus namespace in the 'Standard' pricing tier?","explanation":"az servicebus namespace create with --sku Standard provisions a new Service Bus namespace at the Standard tier (which adds topics/subscriptions over Basic). 'az servicebus create' isn't a valid subcommand, 'az servicebus queue create' creates a queue within an existing namespace (not the namespace itself), and 'az sb namespace new' isn't valid Azure CLI syntax.\n\n```bash\naz servicebus namespace create --name myNamespace --resource-group myRG --sku Standard --location eastus\n```","domain":"services","source":"https://learn.microsoft.com/en-us/azure/service-bus-messaging/service-bus-messaging-overview","topic":"service-bus","type":"single","options":["az servicebus namespace create --name myNamespace --resource-group myRG --sku Standard","az servicebus create --name myNamespace --resource-group myRG --tier Standard","az servicebus queue create --namespace myNamespace --name q1 --sku Standard","az sb namespace new --name myNamespace --resource-group myRG --sku Standard"],"answer":0,"setId":"suralmk:azure-services-160","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/azure-services-160.json","reviewDate":"2026-10-11"},{"id":"suralmk:svc-001","prompt":"A Python Azure Function must process a large blob in chunks without loading the entire payload into memory. Which approach provides explicit chunked reads?","explanation":"BlobClient provides a StorageStreamDownloader with chunks(). dataType: stream is not a valid generic Python blob binding setting. Select the supported SDK binding/runtime or construct the storage client explicitly.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/azure-functions/functions-bindings-storage-blob-trigger","topic":"azure-functions","type":"single","options":["Use BlobClient.download_blob().chunks(), with SDK-type binding support or a BlobClient created in code","Set dataType to stream in function.json","Call readall() before processing","Convert the whole blob to a base64 string"],"answer":0,"setId":"suralmk:azure-services","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/azure-services.json","reviewDate":"2026-10-11","reviewNote":"Replaced a nonexistent Python binding setting."},{"id":"suralmk:svc-002","prompt":"You are developing an AI solution that uses Azure Event Grid to route customer feedback. You want to filter events so only those with a subject ending in .json are sent to a specific Azure Function. Which property of the Event Subscription must you configure?","explanation":"Event Grid subscriptions support subject filters such as `subjectBeginsWith` and **subjectEndsWith** to route matching subjects to an endpoint.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/event-grid/overview","topic":"event-grid","type":"single","options":["subjectEndsWith","subjectBeginsWith","subjectContains","dataVersionMatch"],"answer":0,"setId":"suralmk:azure-services","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/azure-services.json","reviewDate":"2026-10-11"},{"id":"suralmk:svc-003","prompt":"In the Azure Service Bus Python SDK, you want to ensure that a message is not processed by other workers while your current worker is handling it, but can be abandoned if processing fails. Which mode should you use when receiving the message?","explanation":"In **PEEK_LOCK** mode the receiver locks the message. Call `complete_message()` on success or `abandon_message()` on failure so another worker can retry.\n\n```python\nfrom azure.servicebus import ServiceBusClient\n\nservicebus_client = ServiceBusClient.from_connection_string(CONN_STR)\nwith servicebus_client:\n    receiver = servicebus_client.get_queue_receiver(\n        queue_name=QUEUE_NAME, receive_mode=\"peek_lock\"\n    )\n    with receiver:\n        for msg in receiver:\n            # Process message\n            receiver.complete_message(msg)\n```","domain":"services","source":"https://learn.microsoft.com/en-us/azure/service-bus-messaging/service-bus-messaging-overview","topic":"service-bus","type":"single","options":["PEEK_LOCK receive mode","RECEIVE_AND_DELETE mode","AT_MOST_ONCE delivery mode","EXACTLY_ONCE delivery mode"],"answer":0,"setId":"suralmk:azure-services","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/azure-services.json","reviewDate":"2026-10-11"},{"id":"suralmk:svc-004","prompt":"An AI solution uses Azure Service Bus to decouple a web front-end from a slow AI processing backend. If a message fails processing repeatedly beyond maxDeliveryCount, where does Service Bus automatically move the message?","explanation":"When delivery attempts exceed **MaxDeliveryCount**, Service Bus moves the message to the **dead-letter queue (DLQ)** for inspection and remediation.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/service-bus-messaging/service-bus-messaging-overview","topic":"service-bus","type":"single","options":["Dead-letter queue","Transfer dead-letter","Scheduled messages","Deferred messages"],"answer":0,"setId":"suralmk:azure-services","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/azure-services.json","reviewDate":"2026-10-11"},{"id":"suralmk:svc-005","prompt":"You are implementing an Azure Function that needs to store and retrieve high-frequency AI model state. Which trigger/binding combination provides direct, low-latency integration with Redis?","explanation":"Azure Functions supports official **Redis input/output bindings**, so you can read and write Redis data without manually managing client connection pools.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/azure-functions/functions-overview","topic":"azure-functions","type":"single","options":["Redis input/output bindings","HTTP trigger to Redis REST","Blob binding proxy to Redis","Event Hubs Redis extension"],"answer":0,"setId":"suralmk:azure-services","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/azure-services.json","reviewDate":"2026-10-11"},{"id":"suralmk:svc-006","prompt":"You are implementing an event-driven AI workflow. You want to use Azure Event Grid to handle events published from an external custom microservice. Which Event Grid resource must you create first?","explanation":"Custom apps publish to an Event Grid **Custom Topic**, which exposes an HTTP endpoint for your event payloads. System topics are for Azure resource events.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/event-grid/overview","topic":"event-grid","type":"single","options":["Custom Topic","System Topic","Event Domain","Partner Topic"],"answer":0,"setId":"suralmk:azure-services","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/azure-services.json","reviewDate":"2026-10-11"},{"id":"suralmk:svc-007","prompt":"An Azure Service Bus subscription is configured with a filter to only receive messages where Region = 'EastUS'. If a message arrives with Region = 'WestUS', what happens to the message relative to that subscription?","explanation":"Subscription filters decide which topic messages are copied into that subscription. Messages that do not match are simply skipped for that subscription — no error and no DLQ.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/service-bus-messaging/service-bus-messaging-overview","topic":"service-bus","type":"single","options":["Ignored by this subscription's filter","Dead-lettered immediately by subscription","Rejected with an error to topic sender","Deferred for a later subscription pull"],"answer":0,"setId":"suralmk:azure-services","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/azure-services.json","reviewDate":"2026-10-11"},{"id":"suralmk:svc-008","prompt":"In an Azure Functions app using Python, which file defines the triggers, bindings, and function entry point when using the V2 programming model?","explanation":"The Python **V2** model uses decorators in **function_app.py** instead of the legacy `function.json` files.\n\n```python\nimport azure.functions as func\n\napp = func.FunctionApp()\n\n@app.service_bus_queue_trigger(\n    arg_name=\"msg\",\n    queue_name=\"inputqueue\",\n    connection=\"ServiceBusConnectionString\",\n)\ndef main(msg: func.ServiceBusMessage):\n    print(msg.get_body().decode(\"utf-8\"))\n```","domain":"services","source":"https://learn.microsoft.com/en-us/azure/service-bus-messaging/service-bus-messaging-overview","topic":"service-bus","type":"single","options":["function_app.py (V2 model)","function.json (V1 model)","host.json runtime config","requirements.txt packages"],"answer":0,"setId":"suralmk:azure-services","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/azure-services.json","reviewDate":"2026-10-11"},{"id":"suralmk:svc-009","prompt":"You are configuring an Event Grid event subscription to retry failed deliveries to a handler. What is the default maximum number of delivery attempts made by Event Grid before dropping or dead-lettering the event?","explanation":"Event Grid retries delivery up to **30** times (or until event TTL expires, default 1440 minutes) with exponential backoff before dead-lettering if configured.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/event-grid/overview","topic":"event-grid","type":"single","options":["30 delivery attempts","10 delivery attempts","5 delivery attempts","100 delivery attempts"],"answer":0,"setId":"suralmk:azure-services","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/azure-services.json","reviewDate":"2026-10-11"},{"id":"suralmk:svc-010","prompt":"A Service Bus message exceeds the Standard tier 256 KB limit. Which tier supports a configurable larger single-message limit over AMQP?","explanation":"Standard supports messages up to 256 KB. Premium supports configurable single-message sizes up to 100 MB over AMQP; the entity default is 1 MB. Batch and protocol limits differ. A claim-check pattern using Blob Storage is another design when appropriate.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/service-bus-messaging/service-bus-quotas","topic":"service-bus","type":"single","options":["Upgrade to Service Bus Premium tier","Stay on Service Bus Basic messaging","Use Service Bus Standard compression","Store payload only in topic metadata"],"answer":0,"setId":"suralmk:azure-services","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/azure-services.json","reviewDate":"2026-10-11","reviewNote":"Corrected Standard message size and Premium protocol/entity limits."},{"id":"suralmk:cont-101","prompt":"Your team needs a private registry to store and version container images for an AI inference service before deploying to Azure Container Apps. Which service should you provision?","explanation":"Azure Container Registry (ACR) is the managed private registry for building, storing, and versioning container images inside Azure, with tight IAM and Container Apps/AKS integration. Azure Artifacts targets NuGet/npm packages, Docker Hub is a public third-party registry lacking native Azure RBAC integration, and Blob Storage is unstructured object storage, not an OCI image registry.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/container-apps/scale-app","topic":"container-apps-keda","type":"single","options":["Azure Container Registry","Azure Artifacts package feed","Docker Hub public registry","Azure Blob object storage"],"answer":0,"setId":"suralmk:containers-160","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/containers-160.json","reviewDate":"2026-10-11"},{"id":"suralmk:cont-102","prompt":"You want to build a container image in the cloud without maintaining local Docker tooling, and have the resulting image pushed automatically to your registry. Which ACR feature should you use?","explanation":"ACR Tasks (az acr build / az acr task create) performs cloud-based image builds and can push directly to the registry, including automated builds triggered by source commits or base-image updates. Repositories only store existing images, Webhooks notify external systems of registry events, and Content Trust handles image signing, not building.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/container-registry/container-registry-intro","topic":"acr","type":"single","options":["ACR Tasks cloud builds","ACR Repositories storage","ACR Webhooks event notify","ACR Content Trust signing"],"answer":0,"setId":"suralmk:containers-160","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/containers-160.json","reviewDate":"2026-10-11"},{"id":"suralmk:cont-103","prompt":"A development team wants an ACR Task that automatically rebuilds and pushes an image whenever the base image (e.g., a Python runtime image) receives a security patch. What should they configure?","explanation":"ACR Tasks support base image update triggers, which automatically detect when a referenced base image changes in the registry (or in a public registry it tracks) and rebuild dependent images. Manual scheduled builds don't react to base image changes, Blob Storage events are unrelated, and Container Apps revision rules govern traffic splitting, not image builds.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/container-apps/scale-app","topic":"container-apps-keda","type":"single","options":["Base image update trigger on an ACR Task","Manual az acr build on a fixed schedule","Event Grid subscription to Blob Storage","Container Apps revision traffic weights"],"answer":0,"setId":"suralmk:containers-160","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/containers-160.json","reviewDate":"2026-10-11"},{"id":"suralmk:cont-104","prompt":"You are deploying a containerized AI model-serving API to Azure App Service. The image requires an OPENAI_API_KEY at runtime that should not be stored in source control. What is the recommended approach?","explanation":"App Service application settings support Key Vault references (@Microsoft.KeyVault(...)), which inject secrets as environment variables at runtime without exposing them in the image or source. Baking secrets into the Dockerfile embeds them permanently in image layers, and the Gist/requirements.txt options expose the secret publicly or are not designed for runtime configuration.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/key-vault/general/overview","topic":"key-vault","type":"single","options":["App setting with Key Vault reference","Dockerfile ENV with the secret baked","Public GitHub Gist fetched at startup","Hardcoded key in requirements.txt file"],"answer":0,"setId":"suralmk:containers-160","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/containers-160.json","reviewDate":"2026-10-11"},{"id":"suralmk:cont-105","prompt":"Your organization requires that container images deployed to App Service can only be pulled using a managed identity rather than admin credentials stored on the registry. Which configuration satisfies this?\nAssume the registry uses classic RBAC permissions, not RBAC + ABAC repository permissions.","explanation":"Grant AcrPull to the web app identity on a classic RBAC registry and enable managed-identity registry authentication in App Service. ABAC-enabled registries require repository roles such as Container Registry Repository Reader.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/container-registry/container-registry-rbac-built-in-roles-overview","topic":"app-service-containers","type":"single","options":["Enable ACR admin user in App settings","Grant AcrPull to App Service identity","Give Owner rights to a service principal","Store ACR password in Actions secrets"],"answer":1,"setId":"suralmk:containers-160","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/containers-160.json","reviewDate":"2026-10-11","reviewNote":"Scoped AcrPull to classic registry RBAC."},{"id":"suralmk:cont-106","prompt":"Which Azure service lets you run containerized microservices with built-in autoscaling and traffic splitting between revisions, without managing the underlying Kubernetes cluster?","explanation":"Azure Container Apps is a fully managed serverless container platform built on Kubernetes and KEDA that abstracts cluster management while providing revisions and traffic splitting. AKS requires you to manage the cluster, VM Scale Sets manage VMs (not containers directly), and Batch targets large-scale parallel/batch compute jobs.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/container-apps/scale-app","topic":"container-apps-keda","type":"single","options":["Azure Container Apps","Azure Kubernetes Service","Virtual Machine Scale Sets","Azure Batch compute jobs"],"answer":0,"setId":"suralmk:containers-160","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/containers-160.json","reviewDate":"2026-10-11"},{"id":"suralmk:cont-107","prompt":"You need an AI inference container in Azure Container Apps to scale out based on the depth of an Azure Service Bus queue rather than CPU usage. What should you configure?","explanation":"Container Apps uses KEDA under the hood; configuring a custom scale rule of type azure-servicebus lets replicas scale based on queue message count. HTTP scale rules react to request concurrency, not queue depth; manual fixed scaling wastes resources or under-provisions; and CPU-based autoscale doesn't reflect the actual event-driven workload.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/service-bus-messaging/service-bus-messaging-overview","topic":"service-bus","type":"single","options":["KEDA azure-servicebus scale rule","HTTP scale rule on request count","Manual scale fixed at max replicas","Monitor autoscale on CPU percent"],"answer":0,"setId":"suralmk:containers-160","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/containers-160.json","reviewDate":"2026-10-11"},{"id":"suralmk:cont-108","prompt":"You deployed a new version of a container image to Azure Container Apps and want to gradually shift 10% of production traffic to it while keeping 90% on the stable version. What should you configure?","explanation":"Container Apps supports multiple active revisions with configurable traffic weights, letting you route a percentage of traffic to a new revision for canary-style rollouts within a single app. A separate app or Front Door origin group adds unnecessary infrastructure, and AKS Ingress is a different orchestration platform entirely.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/container-apps/scale-app","topic":"container-apps-keda","type":"single","options":["Revisions with weighted traffic split","Separate app with its own custom domain","Front Door origin with 90/10 priority","Two AKS deployments behind an Ingress"],"answer":0,"setId":"suralmk:containers-160","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/containers-160.json","reviewDate":"2026-10-11"},{"id":"suralmk:cont-109","prompt":"An AKS-hosted RAG (retrieval-augmented generation) API intermittently fails to reach Azure Cosmos DB. You need to diagnose whether the issue is DNS resolution, network policy, or application-level, using data already available in the cluster. What is the best first step?","explanation":"Structured troubleshooting starts with kubectl logs to check application-level errors, then kubectl exec into the pod to test DNS (nslookup) and connectivity (curl/telnet) to isolate whether the failure is network, DNS, or app-level before escalating. Recreating the cluster or scaling replicas doesn't diagnose root cause and risks masking the real issue.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/cosmos-db/nosql/","topic":"cosmos-db-nosql","type":"single","options":["Check pod logs then test DNS in-pod","Delete and recreate the whole AKS cluster","Open a support ticket with no diagnostics","Increase replicas hoping the issue clears"],"answer":0,"setId":"suralmk:containers-160","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/containers-160.json","reviewDate":"2026-10-11"},{"id":"suralmk:cont-110","prompt":"You need to deploy a set of Kubernetes resources (Deployment, Service, ConfigMap) to an AKS cluster from files checked into source control. Which command applies them?","explanation":"kubectl apply -f applies one or more manifest files (or a directory of them) declaratively to the cluster, creating or updating resources to match the desired state. az aks create provisions the cluster itself (not workloads), az acr import copies images between registries, and 'kubectl create cluster' is not a valid kubectl subcommand.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/aks/concepts-clusters-workloads","topic":"aks","type":"single","options":["kubectl apply -f manifests/","az aks create --manifest path","az acr import --manifest path","kubectl create cluster -f path"],"answer":0,"setId":"suralmk:containers-160","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/containers-160.json","reviewDate":"2026-10-11"},{"id":"suralmk:cont-111","prompt":"Your AKS-hosted AI service needs to autoscale pods based on GPU utilization metrics that aren't exposed by the default Kubernetes Metrics Server. What should you implement?","explanation":"HPA scales on CPU/memory by default; to scale on custom metrics like GPU utilization, you need a custom metrics adapter (e.g., Prometheus Adapter or KEDA) exposing that metric to the HPA. Vertical Pod Autoscaler adjusts resource requests rather than replica count, Cluster Autoscaler only adds/removes nodes (not pods) and doesn't address pod-level GPU scaling, and cron-based restarts don't scale capacity at all.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/container-apps/scale-app","topic":"container-apps-keda","type":"single","options":["Custom metrics adapter feeding the HPA","Vertical Pod Autoscaler for CPU only","Cluster Autoscaler without any HPA","CronJob that restarts pods every five"],"answer":0,"setId":"suralmk:containers-160","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/containers-160.json","reviewDate":"2026-10-11"},{"id":"suralmk:cont-112","prompt":"You need to verify end-to-end connectivity between an Azure Container Apps environment and a private Azure Database for PostgreSQL instance that has public access disabled. What should you check first?","explanation":"When public network access is disabled on PostgreSQL, connectivity requires the Container Apps environment to be VNet-integrated and able to route to the database's private endpoint (or delegated subnet with private access). Image tagging, Content Trust, and replica count have no bearing on network-layer reachability.","domain":"containers","source":"https://github.com/pgvector/pgvector","topic":"postgresql-pgvector","type":"single","options":["VNet path to private PostgreSQL endpoint","Image tag set to latest on the revision","ACR Content Trust signing for the image","Replica count greater than one on the app"],"answer":0,"setId":"suralmk:containers-160","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/containers-160.json","reviewDate":"2026-10-11"},{"id":"suralmk:cont-113","prompt":"Which command builds a container image using ACR's cloud build compute and pushes it directly to the registry, without requiring a local Docker daemon?","explanation":"az acr build submits the build context to ACR Tasks, which builds the image in Azure and pushes it to the specified registry — no local Docker engine required. docker build runs locally, az acr login only authenticates the local Docker CLI, and az acr repository list just lists existing repositories.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/container-registry/container-registry-intro","topic":"acr","type":"single","options":["az acr build --registry myregistry --image myapp:v1 .","docker build -t myregistry.azurecr.io/myapp:v1 .","az acr login --name myregistry --expose-token","az acr repository list --name myregistry -o tsv"],"answer":0,"setId":"suralmk:containers-160","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/containers-160.json","reviewDate":"2026-10-11"},{"id":"suralmk:cont-114","prompt":"An AI batch-scoring workload runs as a scheduled job rather than a long-running service. Which Container Apps feature best fits this pattern?","explanation":"Container Apps Jobs are purpose-built for finite, run-to-completion or scheduled workloads (manual, scheduled via cron, or event-driven), unlike the always-on revision model used for services. Ingress/sticky sessions serve long-running HTTP apps, Dapr bindings integrate with external systems but don't define job execution, and revision labels just tag stable revision endpoints.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/container-apps/scale-app","topic":"container-apps-keda","type":"single","options":["Container Apps Jobs for finite work","Ingress sticky sessions for HTTP apps","Dapr binding component for external IO","Revision label for stable endpoints"],"answer":0,"setId":"suralmk:containers-160","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/containers-160.json","reviewDate":"2026-10-11"},{"id":"suralmk:cont-115","prompt":"You must ensure that an Azure Container Apps environment used for a healthcare AI application has no public inbound access and all outbound traffic is routed through a network virtual appliance for inspection. What deployment model should you choose?","explanation":"A custom VNet alone is insufficient. Use an internal environment/no public ingress, supported workload-profile routing, DNS and required platform dependencies, with UDRs and firewall/NVA policy for egress.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/container-apps/networking","topic":"container-apps-keda","type":"single","options":["Use an internal workload-profiles environment in a custom VNet with supported UDRs routing egress through the NVA","Default Consumption environment without a VNet","Public FQDN environment with IP allowlists only","AKS cluster deployed with no network policies"],"answer":0,"setId":"suralmk:containers-160","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/containers-160.json","reviewDate":"2026-10-11","reviewNote":"Explicitly included internal ingress, routing and DNS in the network design."},{"id":"suralmk:cont-116","prompt":"Which command retrieves the credentials needed for kubectl to communicate with an AKS cluster?","explanation":"az aks get-credentials merges the cluster's kubeconfig into your local kubectl config so subsequent kubectl commands target that cluster. az aks show only displays cluster properties, kubectl config get-contexts lists contexts already configured (doesn't fetch new ones), and az acr credential show retrieves registry admin credentials, unrelated to AKS auth.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/aks/concepts-clusters-workloads","topic":"aks","type":"single","options":["az aks get-credentials --resource-group myRG --name myCluster","az aks show --resource-group myRG --name myCluster --output json","kubectl config get-contexts --output name for all contexts","az acr credential show --name myregistry --resource-group myRG"],"answer":0,"setId":"suralmk:containers-160","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/containers-160.json","reviewDate":"2026-10-11"},{"id":"suralmk:cont-117","prompt":"Your Container Apps-hosted AI service logs show intermittent 502 errors correlating with new revision deployments. You suspect the new revision isn't passing its readiness probe before receiving traffic. What should you configure to prevent this?","explanation":"A properly tuned readiness probe ensures Container Apps only routes traffic to replicas that report ready, preventing 502s during cold start; combined with adequate warm-up this smooths deployments. Increasing max replicas doesn't address readiness timing, disabling multiple revisions removes the ability to do safe rollouts, and reducing CPU would likely worsen startup latency.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/container-apps/scale-app","topic":"container-apps-keda","type":"single","options":["Readiness probe plus warm-up before traffic","Raise the max replica count for the app","Disable multi-revision mode entirely now","Lower the container CPU allocation value"],"answer":0,"setId":"suralmk:containers-160","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/containers-160.json","reviewDate":"2026-10-11"},{"id":"suralmk:cont-118","prompt":"What is the primary purpose of Azure Container Registry Tasks (ACR Tasks) in an AI development workflow?","explanation":"ACR Tasks automates the build-test-push pipeline for container images, often triggered by Git commits or base image updates, which is central to CI/CD for containerized AI services. Batch inference is better suited to Azure Batch or Container Apps Jobs, vector embeddings belong in Cosmos DB/PostgreSQL/AI Search, and secrets management is Key Vault's role.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/key-vault/general/overview","topic":"key-vault","type":"single","options":["Automate image build, test, and push triggers","Run scheduled batch inference jobs at scale","Store vector embeddings for semantic search","Manage secrets for containerized applications"],"answer":0,"setId":"suralmk:containers-160","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/containers-160.json","reviewDate":"2026-10-11"},{"id":"suralmk:cont-119","prompt":"You want App Service to automatically restart and pull the newest image tag whenever a new image is pushed to ACR, without manual redeployment. What should you enable?","explanation":"Enabling continuous deployment for App Service's container configuration creates a webhook in ACR that notifies App Service whenever the tracked tag is updated, triggering an automatic pull and restart. A pinned static tag with no webhook won't auto-update, geo-replication only copies images across regions, and 'Always On' just prevents idle unloading, unrelated to deployment triggers.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/app-service/configure-custom-container","topic":"app-service-containers","type":"single","options":["Continuous deploy webhook from ACR to App Service","Static image tag pinned with no update webhook","ACR geo-replication across paired Azure regions","App Service Always On without deploy triggers"],"answer":0,"setId":"suralmk:containers-160","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/containers-160.json","reviewDate":"2026-10-11"},{"id":"suralmk:cont-120","prompt":"A team runs both an AKS cluster and Container Apps environment for different AI microservices and needs a single command-line-driven way to confirm end-to-end connectivity, DNS resolution, and recent error events across both platforms during an incident. Which combination of steps is correct?","explanation":"Effective cross-platform troubleshooting combines platform-native diagnostics (kubectl logs/describe for AKS, az containerapp logs show for Container Apps) with centralized KQL queries in Log Analytics to correlate timelines and root cause across services. The Activity Log only captures control-plane operations, blind restarts don't diagnose anything, and ACR logs only cover registry operations, not application errors.","domain":"containers","source":"https://learn.microsoft.com/en-us/kusto/query/","topic":"kql","type":"single","options":["kubectl/az logs plus Log Analytics KQL correlation","Check only Azure portal Activity Log entries now","Restart both platforms at the same time together","Rely only on ACR repository operation log entries"],"answer":0,"setId":"suralmk:containers-160","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/containers-160.json","reviewDate":"2026-10-11"},{"id":"suralmk:cont-121","prompt":"A new ACR-based delivery pipeline must sign images and verify trust before deployment. Which current approach should it adopt?","explanation":"Docker Content Trust is deprecated and cannot be newly enabled on registries after May 31, 2026. Use Notation and an actual enforcement point; ACR storage alone does not prevent deployment of unsigned images.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/container-registry/container-registry-content-trust-deprecation","topic":"container-apps-keda","type":"single","options":["Use Notary Project/Notation signing and enforce verification in the pipeline or a supported admission controller","Enable Docker Content Trust on every new registry","Assume tags are cryptographic signatures","Rely on AcrPull to validate the publisher signature"],"answer":0,"setId":"suralmk:containers-160","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/containers-160.json","reviewDate":"2026-10-11","reviewNote":"Replaced deprecated Content Trust guidance."},{"id":"suralmk:cont-122","prompt":"A Container Apps-hosted inference API needs to scale to zero when idle to reduce cost, then scale up on the first incoming HTTP request. Which configuration supports this?","explanation":"Container Apps supports scale-to-zero when minReplicas is set to 0; an HTTP scale rule then triggers cold-start scale-up on incoming requests, which AKS's Cluster Autoscaler (node-level, not pod-level scale-to-zero for HTTP) does not natively provide as simply. minReplicas of 1 keeps a replica always running, incurring idle cost, and disabling autoscaling removes elasticity altogether.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/container-apps/scale-app","topic":"container-apps-keda","type":"single","options":["minReplicas 0 with an HTTP scale rule","minReplicas 1 with a CPU scale rule","Disable autoscaling on the Container App","AKS Cluster Autoscaler without KEDA rules"],"answer":0,"setId":"suralmk:containers-160","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/containers-160.json","reviewDate":"2026-10-11"},{"id":"suralmk:cont-001","prompt":"An Azure Container App worker must scale from zero using Service Bus queue depth. Which custom scale-rule type should it use?","explanation":"The KEDA Service Bus scaler type is azure-servicebus. Configure queue metadata, authentication, and minReplicas=0. A hyphen between service and bus is not the scaler name.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/container-apps/scale-app","topic":"service-bus","type":"single","options":["azure-servicebus","azure-service-bus","azure-queue-storage","azure-blob"],"answer":0,"setId":"suralmk:containers","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/containers.json","reviewDate":"2026-10-11","reviewNote":"Corrected the invalid scaler identifier."},{"id":"suralmk:cont-002","prompt":"You are automating the build process for a containerized AI model. You want to trigger a build in Azure Container Registry (ACR) every time a base image is updated. Which ACR feature should you use?","explanation":"**ACR Tasks** provides cloud-based container image building and automated triggers. It can run builds on source commits, base image updates, or a schedule.\n\n```bash\naz acr task create \\\n  --registry myregistry \\\n  --name baseImageAutoBuild \\\n  --image aimodel:latest \\\n  --context https://github.com/myorg/aimodel.git#main \\\n  --file Dockerfile\n```","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/container-registry/container-registry-intro","topic":"acr","type":"single","options":["ACR Tasks","ACR Webhooks","ACR Replicas","ACR Cache"],"answer":0,"setId":"suralmk:containers","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/containers.json","reviewDate":"2026-10-11"},{"id":"suralmk:cont-003","prompt":"An AKS pod needs one NVIDIA GPU device. Which manifest area declares the device resource?","explanation":"With the NVIDIA device plugin installed, request GPUs as extended resources in limits. Requests may be omitted or must equal limits. GPU VRAM is a hardware/property choice, not ordinary resources.requests.memory.","domain":"containers","source":"https://kubernetes.io/docs/tasks/manage-gpus/scheduling-gpus/","topic":"aks","type":"single","options":["spec.nodeSelector targeting GPU node SKUs","resources.limits with nvidia.com/gpu: 1 (requests, if specified, must match)","spec.affinity rules for GPU node placement","spec.tolerations allowing GPU node taints"],"answer":1,"setId":"suralmk:containers","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/containers.json","reviewDate":"2026-10-11","reviewNote":"GPU requests count devices rather than directly reserving GPU VRAM."},{"id":"suralmk:cont-004","prompt":"You are troubleshooting an Azure Container App that is failing to start. You need to view the logs generated during the container's startup phase. Which CLI command provides access to these logs?","explanation":"az containerapp logs show retrieves container console or platform system log streams; choose --type and replica/container as appropriate. Query historical workspace data separately with Log Analytics/KQL.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/container-apps/log-streaming","topic":"opentelemetry","type":"single","options":["az containerapp logs show","az containerapp revision list","az containerapp replica list","az containerapp env show"],"answer":0,"setId":"suralmk:containers","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/containers.json","reviewDate":"2026-10-11","reviewNote":"Distinguished live log streams from historical Log Analytics queries."},{"id":"suralmk:cont-005","prompt":"An AKS Deployment container remains running but its health endpoint fails because the process is deadlocked. Which probe should trigger a restart after repeated failures?","explanation":"A liveness probe detects unhealthy running containers. A normal process crash is handled by the Pod restart policy; liveness is not required merely to restart an exited Deployment container.","domain":"containers","source":"https://kubernetes.io/docs/concepts/workloads/pods/pod-lifecycle/","topic":"aks","type":"single","options":["livenessProbe","readinessProbe","startupProbe","lifecycleProbe"],"answer":0,"setId":"suralmk:containers","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/containers.json","reviewDate":"2026-10-11","reviewNote":"A process exit is handled by restartPolicy; liveness probes detect an unresponsive running process."},{"id":"suralmk:cont-006","prompt":"When deploying to Azure Container Apps, you want to test a new version of your AI model with 10% of the live traffic before a full rollout. Which feature should you use?","explanation":"Azure Container Apps supports **revision traffic splitting** natively. With multiple active revisions, assign percentage weights to route traffic across revisions (for example 90/10 canary).\n\n```bash\naz containerapp ingress traffic set \\\n  --name order-api \\\n  --resource-group rg-ecommerce \\\n  --revision-weight order-api--v1=90 order-api--v2=10\n```","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/container-apps/scale-app","topic":"container-apps-keda","type":"single","options":["Revision traffic splitting","Application Gateway routing","Front Door origin weighting","App Service slot percentage"],"answer":0,"setId":"suralmk:containers","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/containers.json","reviewDate":"2026-10-11"},{"id":"suralmk:cont-007","prompt":"You are using ACR Tasks to build a container image. Which file name does ACR Tasks look for by default if no file is specified in the build command?","explanation":"By default, `az acr build` and ACR Tasks look for a file named **Dockerfile** in the root of the build context unless you override it with `--file` / `-f`.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/container-registry/container-registry-intro","topic":"acr","type":"single","options":["Dockerfile (default name)","Containerfile (Podman name)","build.yaml (custom task)","Taskfile (task runner)"],"answer":0,"setId":"suralmk:containers","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/containers.json","reviewDate":"2026-10-11"},{"id":"suralmk:cont-008","prompt":"In a KEDA ScaledObject on AKS, which HPA behavior setting reduces scale-down flapping?","explanation":"The HPA scale-down stabilization window considers recent recommendations. Do not assume arbitrary ScaledObject/HPA fields can be pasted into an Azure Container Apps custom scaler.","domain":"containers","source":"https://keda.sh/docs/2.18/reference/scaledobject-spec/","topic":"container-apps-keda","type":"single","options":["advanced.horizontalPodAutoscalerConfig.behavior.scaleDown.stabilizationWindowSeconds","metadata.queueName","spec.pollingInterval as a CPU averaging window","resources.requests.cpu as a time interval"],"answer":0,"setId":"suralmk:containers","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/containers.json","reviewDate":"2026-10-11","reviewNote":"Scoped the HPA setting to KEDA on AKS rather than an unsupported Container Apps field."},{"id":"suralmk:cont-009","prompt":"An App Service container needs centrally managed, non-secret key-value settings and feature flags that can refresh without rebuilding the image. Which service fits?","explanation":"Use Azure App Configuration with a provider and explicit refresh integration. Store large configuration files in appropriate object/file storage; an App Configuration key-value has a size limit.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/azure-app-configuration/overview","topic":"app-configuration","type":"single","options":["Azure App Configuration store","Azure Key Vault secret values","Azure Files volume mount path","Hard-coded container env vars"],"answer":0,"setId":"suralmk:containers","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/containers.json","reviewDate":"2026-10-11","reviewNote":"App Configuration is a key-value store, not an arbitrary large-file mount."},{"id":"suralmk:cont-010","prompt":"You are using ACR Tasks to build an image from a GitHub repository. You want the build to happen automatically every time you push code to the main branch. What is this called in ACR Tasks?","explanation":"**Source triggers** in ACR Tasks watch a source repository (GitHub or Azure Repos) and run a build when new commits are pushed. **Image triggers** react to base image updates instead.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/container-registry/container-registry-intro","topic":"acr","type":"single","options":["Source trigger","Image trigger","Timer trigger","Webhook sync"],"answer":0,"setId":"suralmk:containers","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/containers.json","reviewDate":"2026-10-11"},{"id":"suralmk:cont-011","prompt":"You want to deploy an AI model to Azure App Service for Containers and supply sensitive environment variables (like API keys). How should you supply these secrets securely?","explanation":"Reference Key Vault secrets in App Service Application Settings with `@Microsoft.KeyVault(...)` and resolve them via **Managed Identity**. That keeps credentials out of Docker layers and source control.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/key-vault/general/overview","topic":"key-vault","type":"single","options":["Key Vault refs in App Settings via managed identity","Plaintext API keys set in Dockerfile ENV instructions","Secrets baked into image layers during container build","Secrets passed as CLI args in the container start cmd"],"answer":0,"setId":"suralmk:containers","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/containers.json","reviewDate":"2026-10-11"},{"id":"suralmk:cont-012","prompt":"You need to inspect real-time logs from an Azure Container Apps instance. Which command enables live streaming of application console logs?","explanation":"Add `--follow` (or `-f`) to `az containerapp logs show` to stream stdout/stderr from the container app in real time.\n\n```bash\naz containerapp logs show \\\n  --name my-app \\\n  --resource-group rg-ai200 \\\n  --follow\n```","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/container-apps/scale-app","topic":"container-apps-keda","type":"single","options":["az containerapp logs show --follow","az containerapp logs show --watch","az containerapp logs show --stream","az containerapp logs show --tail"],"answer":0,"setId":"suralmk:containers","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/containers.json","reviewDate":"2026-10-11"},{"id":"suralmk:cont-013","prompt":"Which Kubernetes resource allows you to define declarative rules for routing external HTTP/HTTPS traffic to services inside an Azure Kubernetes Service (AKS) cluster?","explanation":"An **Ingress** (with an Ingress controller) manages external HTTP/HTTPS access to cluster services, including path/host routing and TLS termination. NetworkPolicy controls pod-to-pod traffic, not public HTTP routing.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/aks/concepts-clusters-workloads","topic":"aks","type":"single","options":["Ingress","Service","Endpoint","Gateway"],"answer":0,"setId":"suralmk:containers","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/containers.json","reviewDate":"2026-10-11"},{"id":"suralmk:data-101","prompt":"Which Azure Cosmos DB API is purpose-built for flexible, schema-less JSON document storage commonly used to persist chat history and embeddings in AI applications?","explanation":"The NoSQL (formerly SQL) API is the native, most feature-complete Cosmos DB API, offering JSON documents, SQL-like querying, and first-class vector search support widely used in RAG applications. Table API mimics key-value storage, Cassandra API targets wide-column workloads migrating from Cassandra, and Gremlin targets graph data — none are the primary recommended choice for flexible AI document + vector storage.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/cosmos-db/nosql/","topic":"cosmos-db-nosql","type":"single","options":["Azure Cosmos DB for NoSQL","Azure Cosmos DB for Table","Azure Cosmos DB for Cassandra","Azure Cosmos DB for Gremlin"],"answer":0,"setId":"suralmk:data-management-160","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/data-management-160.json","reviewDate":"2026-10-11"},{"id":"suralmk:data-102","prompt":"Your Python application must connect to Azure Cosmos DB for NoSQL using Microsoft Entra ID rather than a primary key. Which SDK construct should you use?","explanation":"Passing a DefaultAzureCredential (or another TokenCredential) as the credential parameter enables Entra ID / managed identity authentication instead of key-based auth, which is the Microsoft-recommended, more secure pattern. The other options rely on static keys or raw HTTP calls that bypass RBAC entirely.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/cosmos-db/nosql/","topic":"cosmos-db-nosql","type":"single","options":["CosmosClient(url, credential=DefaultAzureCredential())","CosmosClient(url, credential=primary_key_string)","requests.get(url, headers={\"key\": primary_key})","CosmosClient.from_connection_string(conn_str)"],"answer":0,"setId":"suralmk:data-management-160","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/data-management-160.json","reviewDate":"2026-10-11"},{"id":"suralmk:data-103","prompt":"Cosmos DB writes are expensive because the default indexing policy indexes a large payload that no query uses. Which change can reduce index-maintenance RU cost?","explanation":"Unused indexes increase write work. Point reads use id and partition key and do not query the index; an indexing policy is not the explanation for expensive point reads.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/cosmos-db/optimize-cost-reads-writes","topic":"cosmos-db-nosql","type":"single","options":["Exclude unused properties from scalar indexing","Add more unused indexed paths","Use cross-partition scans instead of point reads","Raise the consistency level to strong"],"answer":0,"setId":"suralmk:data-management-160","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/data-management-160.json","reviewDate":"2026-10-11","reviewNote":"Corrected the claim that unused indexes drive point-read RU cost."},{"id":"suralmk:data-104","prompt":"You are designing a RAG system storing 1536-dimension embeddings in Cosmos DB for NoSQL. Query latency for vector similarity search is too high at scale. What should you configure to improve it?","explanation":"Cosmos DB for NoSQL requires an explicit vector index type (flat, quantizedFlat, or diskANN) configured in the vectorIndexes section of the indexing policy to efficiently perform vector similarity search at scale — without it, queries fall back to brute-force scans. Composite indexes address multi-property sort/filter queries, not vector search; higher consistency increases latency rather than improving vector search speed; and hierarchical partition keys alone don't accelerate similarity search without a vector index.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/cosmos-db/nosql/","topic":"cosmos-db-nosql","type":"single","options":["Vector index (quantizedFlat/diskANN) on embeddings","Composite index on every string property path","Strong consistency to speed similarity search","Hierarchical keys alone without a vector index"],"answer":0,"setId":"suralmk:data-management-160","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/data-management-160.json","reviewDate":"2026-10-11"},{"id":"suralmk:data-105","prompt":"You need your application to react in near-real time whenever new documents (containing chatbot transcripts) are inserted into a Cosmos DB for NoSQL container, so they can be embedded and indexed for search. What should you implement?","explanation":"The change feed processor provides a persistent, low-latency feed of inserts and updates in a container, ideal for driving downstream embedding/indexing pipelines in near real time. Nightly batch jobs and hourly polling introduce unacceptable latency for near-real-time requirements, and manually triggered stored procedures aren't an event-driven mechanism.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/cosmos-db/nosql/","topic":"cosmos-db-nosql","type":"single","options":["Change feed processor on the container","Nightly scheduled batch export job run","Hourly polling loop querying the container","Manually triggered Cosmos stored procedure"],"answer":0,"setId":"suralmk:data-management-160","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/data-management-160.json","reviewDate":"2026-10-11"},{"id":"suralmk:data-106","prompt":"A Cosmos DB application accepts stale reads and requires no read-your-own-writes or ordering guarantees. Which weakest consistency level meets that requirement?","explanation":"Eventual is the weakest consistency model. Session adds session-token guarantees. Read latency and availability depend on topology and workload; choosing a weaker level is not an unconditional latency guarantee.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/cosmos-db/consistency-levels","topic":"cosmos-db-nosql","type":"single","options":["Eventual consistency","Strong consistency across all regions","Bounded Staleness with zero staleness","No latency trade-off exists in Cosmos DB"],"answer":0,"setId":"suralmk:data-management-160","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/data-management-160.json","reviewDate":"2026-10-11","reviewNote":"Specified the weakest consistency guarantee instead of conflating eventual and session."},{"id":"suralmk:data-107","prompt":"Which Python package provides the client library to connect to Azure Database for PostgreSQL from application code?","explanation":"psycopg/psycopg2 is the standard PostgreSQL driver for Python, and pairing it with azure-identity allows acquiring Entra ID access tokens for passwordless authentication to Azure Database for PostgreSQL. azure-storage-blob targets Blob Storage, pymongo targets MongoDB, and azure-cosmos targets Cosmos DB — none connect to PostgreSQL.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/cosmos-db/nosql/","topic":"cosmos-db-nosql","type":"single","options":["psycopg with azure-identity for tokens","azure-storage-blob for object access","pymongo for MongoDB-style document use","azure-cosmos for Cosmos DB document use"],"answer":0,"setId":"suralmk:data-management-160","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/data-management-160.json","reviewDate":"2026-10-11"},{"id":"suralmk:data-108","prompt":"You are designing a table in Azure Database for PostgreSQL to store product embeddings for similarity search. Which extension must be enabled and which column type used?","explanation":"pgvector (CREATE EXTENSION vector) adds the vector(n) data type and similarity operators (\u003c->, \u003c=>, \u003c#>) needed for efficient embedding storage and similarity search in PostgreSQL. PostGIS targets geospatial data, pg_trgm targets fuzzy text matching, and plain numeric arrays lack the indexing and distance operators pgvector provides.","domain":"data","source":"https://github.com/pgvector/pgvector","topic":"postgresql-pgvector","type":"single","options":["CREATE EXTENSION vector; column vector(n)","CREATE EXTENSION postgis; column geometry","CREATE EXTENSION pg_trgm; column text type","No extension; use a plain numeric array"],"answer":0,"setId":"suralmk:data-management-160","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/data-management-160.json","reviewDate":"2026-10-11"},{"id":"suralmk:data-109","prompt":"A vector similarity search on a pgvector column in Azure Database for PostgreSQL is slow at scale (millions of rows) despite low compute overhead concerns. What is the most effective optimization?","explanation":"pgvector supports approximate nearest-neighbor indexes — HNSW (generally higher recall/query speed) or IVFFlat (faster to build, needs tuning of 'lists') — which dramatically speed up similarity search versus a sequential scan. B-tree indexes don't support vector distance operators, fill factor tuning affects update performance not search speed, and JSONB removes the ability to use vector operators or indexes entirely.","domain":"data","source":"https://github.com/pgvector/pgvector","topic":"postgresql-pgvector","type":"single","options":["HNSW or IVFFlat index on the vector column","B-tree index created on the vector column","Raise fill factor on the table to one hundred","Convert the vector column into JSONB storage"],"answer":0,"setId":"suralmk:data-management-160","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/data-management-160.json","reviewDate":"2026-10-11"},{"id":"suralmk:data-110","prompt":"Your RAG pipeline needs to retrieve the top-k most relevant document chunks from PostgreSQL, but only within documents belonging to the current user's tenant. What is the recommended pattern?","explanation":"Combining vector similarity search with metadata filtering (WHERE tenant_id = ...) in a single SQL query, backed by an index on tenant_id, implements RAG with metadata filtering efficiently and correctly scopes retrieval. Filtering in application code after full retrieval wastes compute and risks leaking cross-tenant data if a limit is hit early; per-tenant databases add operational overhead unnecessarily for this use case; and embedding tenant_id into the vector corrupts the semantic embedding.","domain":"data","source":"https://github.com/pgvector/pgvector","topic":"postgresql-pgvector","type":"single","options":["Vector query plus WHERE tenant_id filter","Fetch all rows then filter tenant in app","Query separate databases per tenant in turn","Encode tenant_id inside the embedding vector"],"answer":0,"setId":"suralmk:data-management-160","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/data-management-160.json","reviewDate":"2026-10-11"},{"id":"suralmk:data-111","prompt":"Your Azure Database for PostgreSQL instance is under heavy connection churn from a serverless AI application that opens many short-lived connections, causing latency spikes and occasional connection refusals. What should you implement to improve throughput?","explanation":"Connection pooling (e.g., PgBouncer in transaction pooling mode, or Azure's built-in pooler) reuses a smaller set of backend connections across many short-lived client connections, which is the standard, Microsoft-recommended fix for connection churn in serverless/high-concurrency scenarios. Simply raising max_connections increases memory/CPU overhead per connection without solving churn, creating new databases is irrelevant and harmful, and disabling SSL trades security for a negligible performance gain while not addressing the actual bottleneck.","domain":"data","source":"https://github.com/pgvector/pgvector","topic":"postgresql-pgvector","type":"single","options":["PgBouncer or Azure pooler in transaction mode","Raise max_connections high with no pooler","Open a new database on every app connect","Disable SSL to cut connection handshake cost"],"answer":0,"setId":"suralmk:data-management-160","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/data-management-160.json","reviewDate":"2026-10-11"},{"id":"suralmk:data-112","prompt":"When modeling a schema in Azure Database for PostgreSQL for a document-chunking pipeline, which data type is most appropriate for storing large blocks of extracted text alongside metadata columns?","explanation":"Storing chunk text in a text/varchar column and metadata (source, page number, tenant, timestamps) in dedicated structured columns keeps queries efficient and indexable, following standard relational schema design. Merging everything into JSONB sacrifices type safety and indexing efficiency for structured fields, bytea is for binary data (not searchable text), and vector columns are reserved for embeddings, not raw text.","domain":"data","source":"https://github.com/pgvector/pgvector","topic":"postgresql-pgvector","type":"single","options":["text/varchar for chunks; typed metadata columns","Single JSONB blob merging text and metadata","bytea binary type for searchable chunk text","vector column used to store raw chunk text"],"answer":0,"setId":"suralmk:data-management-160","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/data-management-160.json","reviewDate":"2026-10-11"},{"id":"suralmk:data-113","prompt":"Which Azure service provides an in-memory data store commonly used to cache frequent AI application queries and reduce latency?","explanation":"Azure Managed Redis is the managed in-memory key-value store designed for caching, session state, and now vector search, ideal for reducing latency on repeated AI queries. Data Lake Storage and Azure Files are file/object storage systems (not in-memory caches), and PostgreSQL is a relational database better suited to durable structured storage than sub-millisecond caching.","domain":"data","source":"https://github.com/pgvector/pgvector","topic":"postgresql-pgvector","type":"single","options":["Azure Managed Redis cache","Azure Data Lake Storage Gen2","Azure Database for PostgreSQL","Azure Files network shares"],"answer":0,"setId":"suralmk:data-management-160","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/data-management-160.json","reviewDate":"2026-10-11"},{"id":"suralmk:data-114","prompt":"You want cached AI-generated responses in Azure Managed Redis to automatically expire after 15 minutes so stale answers aren't served. What should you configure?","explanation":"Setting a TTL via SETEX (or SET with EX) or the EXPIRE command causes Redis to automatically evict the key after the specified duration, which is the built-in, efficient mechanism for cache expiration. Keyspace notifications only announce events, they don't cause expiration; a manual scan-and-delete cron job is inefficient and error-prone compared to native TTL; and RDB persistence is about durability/snapshotting, not expiration.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/redis/","topic":"azure-managed-redis","type":"single","options":["TTL of 900 seconds via EXPIRE or SETEX","Keyspace notification with no expiration","Cron job scanning and deleting every 15m","RDB snapshots scheduled every 15 minutes"],"answer":0,"setId":"suralmk:data-management-160","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/data-management-160.json","reviewDate":"2026-10-11"},{"id":"suralmk:data-115","prompt":"Your team wants to use Azure Managed Redis for both caching and low-latency vector similarity search of embeddings within the same cache tier. Which capability should you enable and use?","explanation":"Azure Managed Redis supports the search module enabling vector indexing (HNSW/flat) over hash or JSON documents, letting you run KNN/vector similarity queries directly against cached data. Sorted sets by insertion order don't support similarity search, Pub/Sub is a messaging pattern (not storage/search), and Streams without an index provide no similarity query capability.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/redis/","topic":"azure-managed-redis","type":"single","options":["RediSearch vector index (HNSW) on embeddings","Sorted sets scored only by insertion order","Pub/Sub channels broadcasting embedding data","Streams holding vectors without any index"],"answer":0,"setId":"suralmk:data-management-160","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/data-management-160.json","reviewDate":"2026-10-11"},{"id":"suralmk:data-116","prompt":"An application caches user session state in Azure Managed Redis and needs to invalidate a specific cached entry immediately when the underlying source record changes. What is the correct approach?","explanation":"Explicit invalidation (DEL/UNLINK) at the moment of the source update is the standard cache-invalidation pattern for immediate consistency, rather than waiting on a long TTL. Waiting for TTL expiry leaves stale data served in the interim, restarting the instance is a heavy-handed operation that clears unrelated cached data too, and eviction policies (like LRU) only trigger under memory pressure, not on data changes.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/redis/","topic":"azure-managed-redis","type":"single","options":["DEL or UNLINK the key when source updates","Wait for a multi-hour TTL to expire alone","Restart Redis to clear every cache entry","Rely on LRU eviction under memory pressure"],"answer":0,"setId":"suralmk:data-management-160","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/data-management-160.json","reviewDate":"2026-10-11"},{"id":"suralmk:data-117","prompt":"You need to implement retrieval-augmented generation where document chunks are filtered by both semantic similarity and a numeric 'publish_date' metadata range in Azure Database for PostgreSQL. Which query pattern is correct?","explanation":"Combining the pgvector distance operator (e.g., \u003c=> for cosine distance) with a standard WHERE range filter in one SQL statement lets PostgreSQL's planner apply both the metadata filter and vector ranking efficiently in a single pass. Unrelated unioned queries don't correctly combine the two filter criteria, ignoring the embedding defeats the purpose of RAG, and text-based LIKE matching on dates is unreliable and can't express numeric range logic correctly.","domain":"data","source":"https://github.com/pgvector/pgvector","topic":"postgresql-pgvector","type":"single","options":["ORDER BY embedding \u003c=> vector with date WHERE","Union two unrelated queries with no join key","Full scan sorted by publish_date only, no vector","Store dates as text and LIKE for range filters"],"answer":0,"setId":"suralmk:data-management-160","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/data-management-160.json","reviewDate":"2026-10-11"},{"id":"suralmk:data-118","prompt":"Which Cosmos DB for NoSQL SDK method is used to execute a parameterized SQL query against a container from Python?","explanation":"query_items executes a SQL-like query (optionally parameterized) against the container and returns an iterable of matching items. upsert_item creates or replaces a single item, read_item fetches a single known item by id/partition key, and delete_item removes a single item — none of these run arbitrary queries.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/cosmos-db/nosql/","topic":"cosmos-db-nosql","type":"single","options":["container.query_items(query=..., parameters=[...])","container.upsert_item(body=document_payload)","container.read_item(item=..., partition_key=...)","container.delete_item(item=..., partition_key=...)"],"answer":0,"setId":"suralmk:data-management-160","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/data-management-160.json","reviewDate":"2026-10-11"},{"id":"suralmk:data-119","prompt":"A Cosmos DB for NoSQL change feed processor for an AI indexing pipeline occasionally reprocesses the same documents after a host restart. What is the most likely cause and fix?","explanation":"A crash between processing and checkpoint persistence can replay changes. Use idempotent writes or deduplication and checkpoint after success. Tuning checkpoint frequency changes replay volume but cannot guarantee exactly-once execution.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/cosmos-db/nosql/change-feed-processor","topic":"cosmos-db-nosql","type":"single","options":["Make processing idempotent and persist checkpoints only after successful work","Change feed is at-most-once; Cosmos has a bug","Partition key design alone caused reprocessing","Lower consistency to Eventual to stop duplicates"],"answer":0,"setId":"suralmk:data-management-160","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/data-management-160.json","reviewDate":"2026-10-11","reviewNote":"Reprocessing is normal under at-least-once delivery; checkpoint tuning alone is not a correctness fix."},{"id":"suralmk:data-120","prompt":"Your application performs frequent single-item lookups by a known 'userId' in Cosmos DB for NoSQL. To minimize RU cost, what should the partition key be?","explanation":"Choosing userId as the partition key aligns the physical partitioning with the dominant access pattern (point reads by user), enabling efficient single-partition point reads at minimal RU cost. A constant partition key creates a hot partition and defeats horizontal scaling, an unrelated random GUID doesn't match query patterns and forces cross-partition fan-out, and partitioning solely by creation date doesn't align with the userId lookup pattern described.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/cosmos-db/nosql/","topic":"cosmos-db-nosql","type":"single","options":["userId matching the dominant lookup pattern","Constant fixed value shared by every document","Random GUID unrelated to any query pattern","Creation date alone as the sole partition key"],"answer":0,"setId":"suralmk:data-management-160","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/data-management-160.json","reviewDate":"2026-10-11"},{"id":"suralmk:data-121","prompt":"You must reduce pgvector compute overhead for a write-heavy PostgreSQL table where embeddings are inserted in large nightly batches, but query latency during the day is not critical. What indexing strategy minimizes overhead?","explanation":"IVFFlat has a cheaper build cost than HNSW and is well suited to batch-oriented workloads where you can rebuild the index after loads to keep clustering accurate, trading some query recall for lower compute/maintenance overhead — appropriate given daytime latency isn't critical. Maximizing HNSW parameters increases build cost unnecessarily for this scenario, skipping indexing entirely causes slow scans on every query, and irrelevant B-tree indexes add overhead without helping vector search.","domain":"data","source":"https://github.com/pgvector/pgvector","topic":"postgresql-pgvector","type":"single","options":["IVFFlat with modest lists; REINDEX after batches","HNSW at max ef_construction and m regardless","Skip vector indexes; always full sequential scans","Separate B-tree indexes on every table column"],"answer":0,"setId":"suralmk:data-management-160","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/data-management-160.json","reviewDate":"2026-10-11"},{"id":"suralmk:data-122","prompt":"Which statement about Request Units (RUs) in Azure Cosmos DB for NoSQL is correct?","explanation":"RU cost is influenced by multiple factors together: the size of items read/written, how many properties are indexed, query complexity (e.g., cross-partition, ORDER BY, aggregates), and the chosen consistency level. RUs apply to both reads and writes, are not fixed regardless of workload characteristics, and apply across all Cosmos DB APIs, not just Table.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/cosmos-db/nosql/","topic":"cosmos-db-nosql","type":"single","options":["RU cost varies with size, indexing, query, consistency","RU cost is fixed regardless of size or complexity","RUs apply only to writes and never to any reads","RUs matter only when using the Table API alone"],"answer":0,"setId":"suralmk:data-management-160","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/data-management-160.json","reviewDate":"2026-10-11"},{"id":"suralmk:data-123","prompt":"An AI application must guarantee that within a single client session, a user always sees their own writes to Cosmos DB for NoSQL immediately, while allowing other users to see slightly stale data for lower latency. Which consistency level fits best?","explanation":"Session consistency guarantees read-your-own-writes and monotonic reads within the same session token/client, while still allowing lower latency and higher availability than Strong for other sessions — matching the described requirement precisely. Eventual consistency doesn't guarantee a user sees their own writes immediately, Strong consistency applies the strictest guarantee to every client (higher latency, unnecessary here), and Consistent Prefix only guarantees ordering without the read-your-own-writes guarantee needed.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/cosmos-db/nosql/","topic":"cosmos-db-nosql","type":"single","options":["Session consistency","Eventual consistency","Strong consistency","Consistent Prefix"],"answer":0,"setId":"suralmk:data-management-160","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/data-management-160.json","reviewDate":"2026-10-11"},{"id":"suralmk:data-124","prompt":"You are creating a Cosmos DB container for indexed similarity search over embeddings. Which vector configuration should you define?","explanation":"Define a vectorEmbeddingPolicy with path, dimensions, type and metric, plus an appropriate vectorIndexes entry. JSON arrays can be stored without a vector index, but efficient indexed vector retrieval needs the correct policies. Supported changes to existing policies depend on current service capabilities.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/cosmos-db/nosql/vector-search","topic":"azure-functions","type":"single","options":["vectorEmbeddingPolicy plus matching vector index","Unique key constraint on the embedding property","JS stored procedure computing cosine each query","No setup; any array property is vector-searchable"],"answer":0,"setId":"suralmk:data-management-160","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/data-management-160.json","reviewDate":"2026-10-11","reviewNote":"Clarified policy plus indexed retrieval rather than forbidding storage before an index exists."},{"id":"suralmk:data-125","prompt":"Your application connects to Azure Database for PostgreSQL and experiences elevated latency due to establishing a new TCP+SSL handshake for every short-lived query. Besides pooling, what connection-level optimization helps?","explanation":"Reusing persistent (or pooled) connections avoids the repeated overhead of TCP and SSL/TLS handshakes on every query, directly improving throughput and reducing latency. Disabling keepalives can lead to connections being dropped unexpectedly, forcing renegotiation increases overhead rather than reducing it, and disabling SSL removes encryption in transit, a security regression not aligned with best practice.","domain":"data","source":"https://github.com/pgvector/pgvector","topic":"postgresql-pgvector","type":"single","options":["Reuse persistent or pooled connections across requests","Disable TCP keepalives on every database connection","Force SSL renegotiation on each individual query","Use SSL mode disable for all application traffic"],"answer":0,"setId":"suralmk:data-management-160","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/data-management-160.json","reviewDate":"2026-10-11"},{"id":"suralmk:data-126","prompt":"In Azure Cosmos DB for NoSQL, what mechanism allows an application to detect and react to newly inserted or updated items in near real time?","explanation":"The change feed is Cosmos DB's built-in, ordered log of inserts and updates per partition key range, designed specifically for building event-driven downstream processing. TTL controls automatic item expiration (not change detection), partition key ranges define physical data distribution, and the indexing policy governs which properties are indexed for queries.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/cosmos-db/nosql/","topic":"cosmos-db-nosql","type":"single","options":["Change feed stream","Time to Live (TTL)","Partition key range","Indexing policy set"],"answer":0,"setId":"suralmk:data-management-160","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/data-management-160.json","reviewDate":"2026-10-11"},{"id":"suralmk:data-127","prompt":"Your team must choose between Cosmos DB for NoSQL and Azure Database for PostgreSQL with pgvector for a new RAG application requiring complex relational joins across normalized tables in addition to vector search. Which is the better fit, and why?","explanation":"When a workload requires genuine multi-table relational joins and ACID transactions across normalized schemas in addition to vector similarity search, PostgreSQL with pgvector is the better architectural fit since Cosmos DB's document model doesn't support cross-container joins natively. Cosmos DB isn't universally faster for every workload (especially relational join-heavy ones), both Cosmos DB and PostgreSQL do support native vector search as described in the exam objectives, and Redis is an in-memory cache/vector store, not a durable relational system for joins.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/cosmos-db/nosql/","topic":"cosmos-db-nosql","type":"single","options":["PostgreSQL with pgvector for joins plus vectors","Cosmos DB NoSQL because it is always fastest","Neither supports vectors; use a third-party DB","Managed Redis alone for joins and durable store"],"answer":0,"setId":"suralmk:data-management-160","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/data-management-160.json","reviewDate":"2026-10-11"},{"id":"suralmk:data-001","prompt":"You are using the Azure Cosmos DB Python SDK to perform a vector similarity search. Which method/clause is required to execute a vector query against stored embeddings?","explanation":"In Azure Cosmos DB for NoSQL, vector similarity queries use the `VectorDistance()` system function inside an `ORDER BY` clause to rank documents by similarity to a target vector.\n\n```sql\nSELECT TOP 5 c.id, c.text,\n  VectorDistance(c.vector, [0.1, 0.2, 0.3]) AS SimilarityScore\nFROM c\nORDER BY VectorDistance(c.vector, [0.1, 0.2, 0.3])\n```","domain":"data","source":"https://learn.microsoft.com/en-us/azure/azure-functions/functions-overview","topic":"azure-functions","type":"single","options":["ORDER BY VectorDistance()","WHERE VectorDistance() ASC","SELECT TOP VectorDistance()","GROUP BY VectorDistance()"],"answer":0,"setId":"suralmk:data-management","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/data-management.json","reviewDate":"2026-10-11"},{"id":"suralmk:data-002","prompt":"An AI solution requires high-performance vector retrieval with sub-millisecond latency using Azure Managed Redis. Which command is used to create an index for vectors stored as Hashes?","explanation":"RediSearch commands power vector search in Azure Managed Redis. **FT.CREATE** builds search indexes over hashes or JSON documents that contain vector fields.\n\n```bash\nFT.CREATE vector_idx ON HASH PREFIX 1 doc: SCHEMA vec VECTOR HNSW 6 TYPE FLOAT32 DIM 1536 DISTANCE_METRIC COSINE\n```","domain":"data","source":"https://learn.microsoft.com/en-us/azure/redis/","topic":"azure-managed-redis","type":"single","options":["FT.CREATE","FT.SEARCH","FT.ALTER","FT.INFO"],"answer":0,"setId":"suralmk:data-management","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/data-management.json","reviewDate":"2026-10-11"},{"id":"suralmk:data-003","prompt":"In a Retrieval-Augmented Generation (RAG) pattern using Azure Database for PostgreSQL, which SQL operator calculates cosine distance between vectors in pgvector?","explanation":"In pgvector:\n- `\u003c=>` = Cosine distance\n- `\u003c->` = L2 (Euclidean) distance\n- `\u003c#>` = Negative inner product\n\n```sql\nSELECT id, content FROM documents\nORDER BY embedding \u003c=> '[0.01, 0.02, ...]' LIMIT 5;\n```","domain":"data","source":"https://github.com/pgvector/pgvector","topic":"postgresql-pgvector","type":"single","options":["\u003c=>","\u003c->","\u003c#>","\u003c~>"],"answer":0,"setId":"suralmk:data-management","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/data-management.json","reviewDate":"2026-10-11"},{"id":"suralmk:data-004","prompt":"You are implementing vector search in Azure Database for PostgreSQL. Which index type is best suited for approximate nearest neighbor (ANN) search on large datasets where low memory footprint during indexing is required?","explanation":"**ivfflat** (Inverted File Flat) partitions vectors into lists and searches a subset. It builds faster and uses less memory than HNSW. HNSW usually offers better query performance/recall but needs more memory during indexing.","domain":"data","source":"https://github.com/pgvector/pgvector","topic":"postgresql-pgvector","type":"single","options":["ivfflat vector index","hnsw vector index","btree scalar index","gist spatial index"],"answer":0,"setId":"suralmk:data-management","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/data-management.json","reviewDate":"2026-10-11"},{"id":"suralmk:data-005","prompt":"You are using the Azure Cosmos DB Change Feed Processor to update a vector index in Azure AI Search. What is the role of the 'Lease Container' in this architecture?","explanation":"The lease container records ownership and checkpoints for change feed processor instances. Coordination divides work across instances, but delivery is at least once and failures can replay already processed changes. Make handlers idempotent.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/cosmos-db/nosql/change-feed-processor","topic":"cosmos-db-nosql","type":"single","options":["Coordinate checkpoints and worker lease ownership","Persist completed vector search result document sets","Cache inbound user search request payload documents","Store backup copies of embedding vector field values"],"answer":0,"setId":"suralmk:data-management","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/data-management.json","reviewDate":"2026-10-11","reviewNote":"Lease coordination does not eliminate replay."},{"id":"suralmk:data-006","prompt":"A Cosmos DB container indexes a large raw payload that the application never filters or sorts on. How can write RU cost and index size be reduced?","explanation":"Index maintenance affects writes. Exclude unused scalar paths while retaining paths needed by queries; vector policy/index configuration is separate. Measure query RU and recall instead of assuming every exclusion improves vector query cost.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/cosmos-db/index-policy","topic":"cosmos-db-nosql","type":"single","options":["Exclude unused payload paths while keeping scalar filter/sort indexes and a suitable separate vector index","Remove every index used by filters","Index only vectors and remove all metadata indexes regardless of queries","Set strong consistency to disable index maintenance"],"answer":0,"setId":"suralmk:data-management","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/data-management.json","reviewDate":"2026-10-11","reviewNote":"Changed a write-cost optimization that was incorrectly presented as a vector-query guarantee."},{"id":"suralmk:data-007","prompt":"A cached string should expire after 30 minutes without a read. Which read operation implements sliding expiration atomically?","explanation":"An ordinary GET does not reset the TTL. GETEX reads a string and renews its expiry in one operation. Absolute expiration and sliding expiration are different.","domain":"data","source":"https://redis.io/docs/latest/commands/getex/","topic":"azure-managed-redis","type":"single","options":["GETEX cache:key EX 1800","GET cache:key with an unchanged TTL","SET cache:key value without an expiry","PERSIST cache:key"],"answer":0,"setId":"suralmk:data-management","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/data-management.json","reviewDate":"2026-10-11","reviewNote":"Corrected TTL versus sliding-expiration semantics."},{"id":"suralmk:data-008","prompt":"You are designing a schema for a vector database in Azure Database for PostgreSQL. Which data type provided by the pgvector extension should you use to store embeddings?","explanation":"The pgvector extension adds the native **vector** type, which supports distance operators and specialized vector indexes.\n\n```sql\nCREATE EXTENSION IF NOT EXISTS vector;\nCREATE TABLE items (\n  id serial PRIMARY KEY,\n  embedding vector(1536)\n);\n```","domain":"data","source":"https://github.com/pgvector/pgvector","topic":"postgresql-pgvector","type":"single","options":["vector","float8","bytea","jsonb"],"answer":0,"setId":"suralmk:data-management","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/data-management.json","reviewDate":"2026-10-11"},{"id":"suralmk:data-009","prompt":"To optimize performance of a vector similarity search in Azure Cosmos DB NoSQL using disk-optimized indexing, which vector index type option is available?","explanation":"Azure Cosmos DB for NoSQL supports **DiskANN** (plus options like quantized flat) for efficient large-scale, cost-effective vector indexing.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/cosmos-db/nosql/","topic":"cosmos-db-nosql","type":"single","options":["DiskANN vector index","HNSW vector index","IVFFlat vector index","Annoy vector index"],"answer":0,"setId":"suralmk:data-management","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/data-management.json","reviewDate":"2026-10-11"},{"id":"suralmk:data-010","prompt":"In Azure Database for PostgreSQL, you are seeing high query latency under heavy concurrency during vector search operations. You want to enable connection pooling to minimize connection overhead. Which built-in component should you use?","explanation":"Azure Database for PostgreSQL Flexible Server includes built-in **PgBouncer**, which pools database connections and reduces connection setup cost under concurrency.","domain":"data","source":"https://github.com/pgvector/pgvector","topic":"postgresql-pgvector","type":"single","options":["PgBouncer connection pooler","PostgreSQL Foreign Data Wrapper","Azure Traffic Manager endpoint","Azure Front Door backend pool"],"answer":0,"setId":"suralmk:data-management","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/data-management.json","reviewDate":"2026-10-11"},{"id":"suralmk:data-011","prompt":"Using the Python SDK for Azure Managed Redis, you want to perform a vector search over millions of items where high throughput and recall accuracy are critical. Which search index algorithm is most suitable?","explanation":"**HNSW** in Redis delivers strong query performance and recall on large datasets. It uses more memory than FLAT during index construction, which is the usual trade-off for accuracy and speed.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/redis/","topic":"azure-managed-redis","type":"single","options":["HNSW","FLAT","IVF","LSH"],"answer":0,"setId":"suralmk:data-management","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/data-management.json","reviewDate":"2026-10-11"},{"id":"suralmk:data-012","prompt":"You have a large set of image embeddings in Azure Cosmos DB NoSQL. You want to retrieve the top 5 most similar images to a target vector. Which SQL statement shows the correct syntax?","explanation":"Cosmos DB returns nearest neighbors with `ORDER BY VectorDistance(...)` combined with `TOP N`.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/cosmos-db/nosql/","topic":"cosmos-db-nosql","type":"single","options":["SELECT TOP 5 c.id FROM c ORDER BY VectorDistance(c.vector, @v)","SELECT TOP 5 c.id FROM c WHERE VectorDistance(c.vector, @v) \u003c 1","SELECT TOP 5 c.id FROM c FILTER BY VectorSearch(c.vector, @v)","SELECT TOP 5 c.id FROM c SIMILAR TO VectorMatch(c.vector, @v)"],"answer":0,"setId":"suralmk:data-management","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/data-management.json","reviewDate":"2026-10-11"},{"id":"suralmk:data-013","prompt":"You are optimizing an Azure Database for PostgreSQL Flexible Server for a vector workload indexing step. You need to increase memory allocated for index creation (such as building ivfflat indexes). Which server parameter should you adjust?","explanation":"**maintenance_work_mem** controls memory available for maintenance operations including `CREATE INDEX`. Raising it speeds up building vector indexes such as ivfflat.","domain":"data","source":"https://github.com/pgvector/pgvector","topic":"postgresql-pgvector","type":"single","options":["maintenance_work_mem","max_parallel_workers","shared_buffers_size","effective_cache_size"],"answer":0,"setId":"suralmk:data-management","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/data-management.json","reviewDate":"2026-10-11"},{"id":"suralmk:data-014","prompt":"With continuous backup enabled and a supported client/API, which Cosmos DB change feed mode includes intermediate versions and deletes within the available backup retention window?","explanation":"All versions and deletes mode includes changes within the continuous-backup retention window. It is not unlimited history. Verify feature availability and the supported client/SDK version, rather than assuming every Python change-feed API supports it.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/cosmos-db/nosql/change-feed-modes","topic":"cosmos-db-nosql","type":"single","options":["All versions and deletes","Latest version only mode","Full fidelity change mode","Incremental snapshot mode"],"answer":0,"setId":"suralmk:data-management","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/data-management.json","reviewDate":"2026-10-11","reviewNote":"Limited all-versions change feed history to supported retention and SDK capability."},{"id":"suralmk:data-015","prompt":"When implementing a RAG pattern with Azure Database for PostgreSQL, you want to filter results based on a user's ID to ensure they only search their own embeddings. Where should this filter be applied for maximum performance?","explanation":"Put metadata filters in the SQL `WHERE` clause with the vector distance predicate so PostgreSQL can apply filtering and indexing at the engine layer instead of post-filtering in application code.","domain":"data","source":"https://github.com/pgvector/pgvector","topic":"postgresql-pgvector","type":"single","options":["WHERE clause with the vector distance predicate","App code after fetching all global ANN match rows","Staging table loaded before running vector search","Export embeddings to files then filter them offline"],"answer":0,"setId":"suralmk:data-management","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/data-management.json","reviewDate":"2026-10-11"},{"id":"suralmk:sdk-001","prompt":"Which Azure CLI command creates a new resource group?","explanation":"az group create is the correct command to create a resource group, requiring --name and --location. az resource create manages generic individual resources (not groups), 'az rg new' isn't valid syntax, and az account create doesn't exist as a resource-group operation.\n\n```bash\naz group create --name myRG --location eastus\n```","domain":"operations","source":"https://learn.microsoft.com/en-us/cli/azure/reference-index","topic":"azure-cli","type":"single","options":["az group create --name myRG --location eastus --tags env=dev project=ai","az group deployment create --name d1 --resource-group myRG --template-file main.json","az resource create --name myRes --resource-group myRG --location eastus --properties {}","az account management-group create --name myMG --display-name ContosoRootMG"],"answer":0,"setId":"suralmk:sdk-cli-part1","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/sdk-cli-part1.json","reviewDate":"2026-10-11"},{"id":"suralmk:sdk-002","prompt":"Which command creates a new Azure Storage Account?","explanation":"az storage account create provisions the storage account itself with required --sku and --location. 'az storage create' isn't valid, az storage container create makes a blob container inside an existing account (not the account itself), and 'az blob account create' isn't a real command.\n\n```bash\naz storage account create --name mystorageacct123 --resource-group myRG --location eastus --sku Standard_LRS\n```","domain":"operations","source":"https://learn.microsoft.com/en-us/cli/azure/reference-index","topic":"azure-cli","type":"single","options":["az storage account create --name mystorageacct --resource-group myRG --location eastus --sku Standard_LRS","az storage container create --name mystorageacct --account-name myacct --resource-group myRG --public-access off","az storage share create --name mystorageacct --account-name myacct --quota 100 --resource-group myRG","az storage blob service-properties update --account-name mystorageacct --static-website --index-document index.html"],"answer":0,"setId":"suralmk:sdk-cli-part1","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/sdk-cli-part1.json","reviewDate":"2026-10-11"},{"id":"suralmk:sdk-003","prompt":"Which command creates an Azure Key Vault?","explanation":"az keyvault create provisions a new vault instance. 'az kv new' is not valid CLI syntax, az keyvault secret create operates on secrets within an existing vault (not the vault itself), and 'az security keyvault create' is not a real command group.\n\n```bash\naz keyvault create --name myVault --resource-group myRG --location eastus\n```","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/key-vault/general/overview","topic":"key-vault","type":"single","options":["az keyvault create --name myVault --resource-group myRG --location eastus","az keyvault secret set --vault-name myVault --name mySecret --value secret","az keyvault key create --vault-name myVault --name myKey --protection software","az keyvault certificate create --vault-name myVault --name myCert --policy @p.json"],"answer":0,"setId":"suralmk:sdk-cli-part1","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/sdk-cli-part1.json","reviewDate":"2026-10-11"},{"id":"suralmk:sdk-004","prompt":"Which command deploys a container image to a new Azure Container App?","explanation":"az containerapp create provisions and deploys a new Container App from the specified image within a Container Apps environment. az container create targets Azure Container Instances (a different service), 'az app deploy' isn't valid syntax, and az acr deploy doesn't exist — ACR only manages images, not app deployment.\n\n```bash\naz containerapp create --name myApp --resource-group myRG --image myregistry.azurecr.io/myapp:v1 --environment myEnv\n```","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/container-apps/scale-app","topic":"container-apps-keda","type":"single","options":["az containerapp create --name myApp --resource-group myRG --image myregistry.azurecr.io/myapp:v1 --environment myEnv","az container create --name myApp --resource-group myRG --image myregistry.azurecr.io/myapp:v1 --cpu 1 --memory 1.5","az webapp create --name myApp --resource-group myRG --plan myPlan --deployment-container-image-name myapp:v1","az acr build --registry myregistry --image myapp:v1 --file Dockerfile --resource-group myRG ."],"answer":0,"setId":"suralmk:sdk-cli-part1","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/sdk-cli-part1.json","reviewDate":"2026-10-11"},{"id":"suralmk:sdk-005","prompt":"Which command uploads a local file as a blob to an Azure Storage container?","explanation":"az storage blob upload sends a specified local file to a named blob within a container. az storage account upload isn't valid (accounts don't take file uploads directly), az storage container upload isn't a real subcommand, and 'az blob push' doesn't exist in the Azure CLI.\n\n```bash\naz storage blob upload --account-name myacct --container-name mycontainer --name myblob --file ./localfile.txt --auth-mode login\n```","domain":"operations","source":"https://learn.microsoft.com/en-us/cli/azure/reference-index","topic":"azure-cli","type":"single","options":["az storage blob upload --account-name myacct --container-name mycontainer --name myblob --file ./localfile.txt","az storage file upload --account-name myacct --share-name myshare --path myfile --source ./localfile.txt","az storage container create --account-name myacct --name mycontainer --public-access blob --fail-on-exist","az storage account update --name myacct --resource-group myRG --access-tier Hot --https-only true"],"answer":0,"setId":"suralmk:sdk-cli-part1","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/sdk-cli-part1.json","reviewDate":"2026-10-11"},{"id":"suralmk:sdk-006","prompt":"Which command creates an Event Grid subscription that sends events to a webhook endpoint?","explanation":"az eventgrid event-subscription create creates a subscription against a given source resource, pointing to a webhook or other endpoint type. az eventgrid topic create only creates a custom topic (not a subscription), 'az eventgrid subscribe' isn't valid syntax, and 'az event create' isn't a real command.\n\n```bash\naz eventgrid event-subscription create --name mySub --source-resource-id /subscriptions/.../storageAccounts/myacct --endpoint https://myfunction.azurewebsites.net/api/handler\n```","domain":"services","source":"https://learn.microsoft.com/en-us/azure/event-grid/overview","topic":"event-grid","type":"single","options":["az eventgrid event-subscription create --name mySub --source-resource-id \u003cresourceId> --endpoint \u003curl>","az eventgrid topic create --name mySub --resource-group myRG --location eastus --input-schema EventGridSchema","az eventgrid system-topic create --name mySub --resource-group myRG --topic-type Microsoft.Storage.StorageAccounts","az eventgrid domain create --name mySub --resource-group myRG --location eastus --input-schema EventGridSchema"],"answer":0,"setId":"suralmk:sdk-cli-part1","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/sdk-cli-part1.json","reviewDate":"2026-10-11"},{"id":"suralmk:sdk-007","prompt":"Which command creates a new Azure Cosmos DB account using the NoSQL (Core SQL) API?","explanation":"az cosmosdb create provisions the Cosmos DB account itself; --kind GlobalDocumentDB corresponds to the NoSQL/Core SQL API. 'az cosmosdb account new' is invalid syntax, 'az cosmos create' is not a valid command group, and az cosmosdb database create only creates a database inside an already-existing account.\n\n```bash\naz cosmosdb create --name myaccount --resource-group myRG --kind GlobalDocumentDB --locations regionName=eastus\n```","domain":"data","source":"https://learn.microsoft.com/en-us/azure/cosmos-db/nosql/","topic":"cosmos-db-nosql","type":"single","options":["az cosmosdb create --name myaccount --resource-group myRG --kind GlobalDocumentDB","az cosmosdb sql database create --account-name myaccount --name mydb --throughput 400","az cosmosdb gremlin database create --account-name myaccount --name mydb --throughput 400","az cosmosdb mongodb database create --account-name myaccount --name mydb --throughput 400"],"answer":0,"setId":"suralmk:sdk-cli-part1","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/sdk-cli-part1.json","reviewDate":"2026-10-11"},{"id":"suralmk:sdk-008","prompt":"Which command creates a new Service Bus namespace?","explanation":"az servicebus namespace create provisions the namespace container that will hold queues/topics, with --sku controlling tier. 'az servicebus create' and 'az sb create' are not valid command forms, and az servicebus topic create makes a topic inside an already-existing namespace, not the namespace itself.\n\n```bash\naz servicebus namespace create --name myNamespace --resource-group myRG --location eastus --sku Standard\n```","domain":"services","source":"https://learn.microsoft.com/en-us/azure/service-bus-messaging/service-bus-messaging-overview","topic":"service-bus","type":"single","options":["az servicebus namespace create --name myNamespace --resource-group myRG --location eastus --sku Standard","az servicebus queue create --name myQueue --namespace-name myNamespace --resource-group myRG --max-size 1024","az servicebus topic create --name myTopic --namespace-name myNamespace --resource-group myRG --max-size 1024","az servicebus georecovery-alias create --alias myAlias --namespace-name myNamespace --resource-group myRG"],"answer":0,"setId":"suralmk:sdk-cli-part1","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/sdk-cli-part1.json","reviewDate":"2026-10-11"},{"id":"suralmk:sdk-009","prompt":"Which command creates an AKS cluster with 3 nodes?","explanation":"az aks create provisions a new AKS cluster, with --node-count specifying the initial node pool size and --generate-ssh-keys auto-generating SSH keys if needed. 'az aks new' and 'az kubernetes create' aren't valid command names, and 'az acs create' refers to the deprecated Azure Container Service, not AKS.\n\n```bash\naz aks create --name myCluster --resource-group myRG --node-count 3 --generate-ssh-keys\n```","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/aks/concepts-clusters-workloads","topic":"aks","type":"single","options":["az aks create --name myCluster --resource-group myRG --node-count 3 --generate-ssh-keys","az aks nodepool add --cluster-name myCluster --resource-group myRG --name np2 --node-count 3","az aks scale --name myCluster --resource-group myRG --node-count 3 --nodepool-name nodepool1","az aks update --name myCluster --resource-group myRG --enable-cluster-autoscaler --min-count 1 --max-count 3"],"answer":0,"setId":"suralmk:sdk-cli-part1","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/sdk-cli-part1.json","reviewDate":"2026-10-11"},{"id":"suralmk:sdk-010","prompt":"Which Python SDK class is used to upload and download blobs from Azure Blob Storage?","explanation":"BlobClient represents one blob and exposes upload_blob/download_blob. BlobServiceClient manages the account-level service and creates container/blob clients.","domain":"operations","source":"https://learn.microsoft.com/en-us/python/api/azure-storage-blob/azure.storage.blob.blobclient?view=azure-python","topic":"key-vault","type":"single","options":["BlobClient from azure-storage-blob; obtain it directly or with BlobServiceClient.get_blob_client()","QueueClient from azure-storage-queue for enqueue and dequeue messages","ShareClient from azure-storage-file-share for upload_file/download_file","DataLakeServiceClient from azure-storage-file-datalake for filesystem ops"],"answer":0,"setId":"suralmk:sdk-cli-part1","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/sdk-cli-part1.json","reviewDate":"2026-10-11","reviewNote":"Corrected the SDK object that owns upload_blob/download_blob."},{"id":"suralmk:sdk-011","prompt":"Which Python SDK class retrieves secrets from Azure Key Vault?","explanation":"SecretClient from azure-keyvault-secrets exposes methods like get_secret and set_secret for managing Key Vault secrets specifically. KeyClient manages cryptographic keys (not secrets), CertificateClient manages certificates, and BlobServiceClient is unrelated to Key Vault entirely.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/key-vault/general/overview","topic":"key-vault","type":"single","options":["SecretClient from azure-keyvault-secrets for get_secret/set_secret","KeyClient from azure-keyvault-keys for create_key and get_key ops","CertificateClient from azure-keyvault-certificates for cert lifecycle","BlobServiceClient from azure-storage-blob for blob upload/download"],"answer":0,"setId":"suralmk:sdk-cli-part1","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/sdk-cli-part1.json","reviewDate":"2026-10-11"},{"id":"suralmk:sdk-012","prompt":"Which Python SDK class sends messages to an Azure Service Bus queue or topic?","explanation":"ServiceBusClient creates a ServiceBusSender (via get_queue_sender/get_topic_sender) used to send messages to Service Bus entities. EventGridPublisherClient targets Event Grid (a different pub/sub service), azure-storage-queue's QueueClient targets Storage Queues (a simpler, different queuing service), and CosmosClient is unrelated to messaging.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/service-bus-messaging/service-bus-messaging-overview","topic":"service-bus","type":"single","options":["ServiceBusClient with get_queue_sender/get_topic_sender (ServiceBusSender)","EventGridPublisherClient from azure-eventgrid for topic event publish","QueueClient from azure-storage-queue for send_message on storage queues","EventHubProducerClient from azure-eventhub for send_batch to Event Hubs"],"answer":0,"setId":"suralmk:sdk-cli-part1","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/sdk-cli-part1.json","reviewDate":"2026-10-11"},{"id":"suralmk:sdk-013","prompt":"Which Python SDK class publishes custom events to an Azure Event Grid topic?","explanation":"EventGridPublisherClient from the azure-eventgrid package is specifically designed to send events to an Event Grid topic endpoint. ServiceBusSender sends Service Bus messages (a different messaging paradigm), BlobServiceClient handles blob storage, and SecretClient handles Key Vault secrets — none publish Event Grid events.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/key-vault/general/overview","topic":"key-vault","type":"single","options":["EventGridPublisherClient from azure-eventgrid for send to topic endpoint","ServiceBusSender from azure-servicebus for send_messages to a queue/topic","EventHubProducerClient from azure-eventhub for send_batch of EventData","NotificationHubsClient from azure-notificationhubs for push notifications"],"answer":0,"setId":"suralmk:sdk-cli-part1","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/sdk-cli-part1.json","reviewDate":"2026-10-11"},{"id":"suralmk:sdk-014","prompt":"Which Azure OpenAI Python SDK call generates text embeddings for a given input string?","explanation":"The embeddings.create method (via the OpenAI Python SDK configured for Azure OpenAI) returns a vector embedding for the given input text, used for semantic search/RAG. chat.completions.create generates conversational text responses (not embeddings), images.generate creates images from a prompt, and files.create uploads files for fine-tuning/assistants, none of which produce embeddings.","domain":"operations","source":"https://learn.microsoft.com/en-us/cli/azure/reference-index","topic":"azure-cli","type":"single","options":["client.embeddings.create(model=\u003cdeployment_name>, input=\u003ctext>)","client.chat.completions.create(model=\u003cdeployment_name>, messages=[...])","client.images.generate(model=\u003cdeployment_name>, prompt=\u003ctext>)","client.audio.transcriptions.create(model=\u003cdeployment_name>, file=\u003cf>)"],"answer":0,"setId":"suralmk:sdk-cli-part1","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/sdk-cli-part1.json","reviewDate":"2026-10-11"},{"id":"suralmk:sdk-015","prompt":"Which Python SDK class performs vector similarity search against an Azure AI Search index containing embeddings?","explanation":"SearchClient (azure-search-documents) exposes a search() method that accepts a VectorizedQuery (or vector_queries parameter) to perform vector similarity search, optionally combined with traditional keyword filters for hybrid search. The other three classes/methods target blob download, Cosmos DB database creation, and Key Vault secret retrieval respectively — none perform search operations.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/key-vault/general/overview","topic":"key-vault","type":"single","options":["SearchClient.search() with VectorizedQuery (azure-search-documents)","BlobServiceClient.download_blob() streaming bytes from Azure Blob Storage","CosmosClient.create_database_if_not_exists() provisioning a Cosmos database","SecretClient.get_secret() retrieving a named secret from Azure Key Vault"],"answer":0,"setId":"suralmk:sdk-cli-part1","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/sdk-cli-part1.json","reviewDate":"2026-10-11"},{"id":"suralmk:sdk-016","prompt":"Which method on a Cosmos DB Python SDK container object inserts a new item or replaces it if it already exists (by id)?","explanation":"upsert_item creates the item if it doesn't exist or replaces it if an item with the same id/partition key already exists, which is the standard idempotent write pattern. create_item raises a conflict error if the item already exists (not idempotent), read_item only retrieves a single known item, and query_items executes read queries rather than performing writes.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/cosmos-db/nosql/","topic":"cosmos-db-nosql","type":"single","options":["container.upsert_item(body=item) creating or replacing by id/partition key","container.create_item(body=item) which fails with conflict if item exists","container.replace_item(item=item_id, body=item) requiring the item exist","container.patch_item(item=item_id, partition_key=pk, patch_operations=[...])"],"answer":0,"setId":"suralmk:sdk-cli-part1","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/sdk-cli-part1.json","reviewDate":"2026-10-11"},{"id":"suralmk:sdk-017","prompt":"Which Azure CLI command sets an application setting (environment variable) on an App Service?","explanation":"az webapp config appsettings set adds or updates key-value application settings on an existing App Service (surfaced to the app as environment variables). az webapp create only provisions a new app (doesn't manage settings on existing ones this way), az appservice env create provisions an App Service Environment (a different, isolated hosting resource), and az webapp restart just restarts the app with no settings parameter.\n\n```bash\naz webapp config appsettings set --name myApp --resource-group myRG --settings OPENAI_API_KEY=@Microsoft.KeyVault(SecretUri=https://myvault.vault.azure.net/secrets/openai-key/)\n```","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/key-vault/general/overview","topic":"key-vault","type":"single","options":["az webapp config appsettings set --name myApp --resource-group myRG --settings KEY=VALUE","az webapp config connection-string set --name myApp --resource-group myRG --settings KEY=VALUE","az webapp config storage-account add --name myApp --resource-group myRG --custom-id KEY","az webapp config access-restriction add --name myApp --resource-group myRG --rule-name KEY"],"answer":0,"setId":"suralmk:sdk-cli-part1","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/sdk-cli-part1.json","reviewDate":"2026-10-11"},{"id":"suralmk:sdk-018","prompt":"Which command sequence authenticates Docker and pushes an already tagged image to a classic ACR login server?","explanation":"az acr login authenticates the local Docker client, then docker push uploads the image. Use the registry loginServer property rather than assuming its DNS name.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/container-registry/container-registry-get-started-docker-cli","topic":"acr","type":"single","options":["az acr login --name myregistry, then docker push myregistry.azurecr.io/myapp:v1","az acr build --registry myregistry --image myapp:v1 --file Dockerfile --no-push .","az acr import --name myregistry --source docker.io/library/myapp:v1 --image myapp:v1","az acr repository update --name myregistry --image myapp:v1 --write-enabled false"],"answer":0,"setId":"suralmk:sdk-cli-part1","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/sdk-cli-part1.json","reviewDate":"2026-10-11","reviewNote":"Distinguished Azure CLI authentication from the Docker push command."},{"id":"suralmk:sdk-019","prompt":"Which Azure CLI command enables a system-assigned managed identity on an existing App Service?","explanation":"az webapp identity assign enables (and returns the principal ID for) a system-assigned managed identity on an existing App Service. az webapp create doesn't have an '--identity system' flag for this purpose, az ad sp create manually creates a service principal (a different, less integrated identity mechanism), and az role assignment create only assigns roles — it doesn't create the identity itself.\n\n```bash\naz webapp identity assign --name myApp --resource-group myRG\n```","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/app-service/configure-custom-container","topic":"app-service-containers","type":"single","options":["az webapp identity assign --name myApp --resource-group myRG --identities [system]","az webapp identity remove --name myApp --resource-group myRG --identities [system]","az identity create --name myAppIdentity --resource-group myRG --location eastus","az ad sp create-for-rbac --name myAppSp --role Contributor --scopes /subscriptions/x"],"answer":0,"setId":"suralmk:sdk-cli-part1","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/sdk-cli-part1.json","reviewDate":"2026-10-11"},{"id":"suralmk:sdk-020","prompt":"Which Azure CLI command grants a managed identity the 'Key Vault Secrets User' role on a specific Key Vault, scoped only to that vault?","explanation":"az role assignment create with --role \"Key Vault Secrets User\" and --scope set to the specific vault's resource ID grants exactly the least-privilege, RBAC-based access described. az keyvault set-policy uses the legacy access-policy model (not RBAC) and 'all' permissions violates least privilege, assigning Owner at the subscription scope is drastically over-privileged, and enabling RBAC authorization alone doesn't grant any specific role assignment.\n\n```bash\naz role assignment create --assignee \u003cprincipalId> --role \"Key Vault Secrets User\" --scope /subscriptions/\u003csubId>/resourceGroups/myRG/providers/Microsoft.KeyVault/vaults/myVault\n```","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/key-vault/general/overview","topic":"key-vault","type":"single","options":["az role assignment create --assignee \u003cprincipalId> --role \"Key Vault Secrets User\" --scope \u003ckeyVaultResourceId>","az keyvault set-policy --name myVault --object-id \u003cprincipalId> --secret-permissions get list","az role assignment create --assignee \u003cprincipalId> --role Owner --scope /subscriptions/\u003csubId>","az keyvault update --name myVault --resource-group myRG --enable-rbac-authorization true"],"answer":0,"setId":"suralmk:sdk-cli-part1","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/sdk-cli-part1.json","reviewDate":"2026-10-11"},{"id":"suralmk:sdk-021","prompt":"Which Azure CLI command deploys a ZIP-packaged application to an existing Azure App Service?","explanation":"az webapp deploy with --type zip pushes and deploys a zipped app package to an existing App Service. az webapp create only provisions the app resource (no zip option for code deployment), storage blob upload merely stores the zip file without deploying it, and az acr build builds container images, unrelated to App Service zip deployment.\n\n```bash\naz webapp deploy --resource-group myRG --name myApp --src-path ./app.zip --type zip\n```","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/app-service/configure-custom-container","topic":"app-service-containers","type":"single","options":["az webapp deploy --resource-group myRG --name myApp --src-path ./app.zip --type zip","az webapp deployment source config-zip --resource-group myRG --name myApp --src ./app.zip","az webapp config container set --resource-group myRG --name myApp --docker-custom-image-name app:v1","az storage blob upload --account-name myacct --container-name deploy --file ./app.zip --name app.zip"],"answer":0,"setId":"suralmk:sdk-cli-part1","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/sdk-cli-part1.json","reviewDate":"2026-10-11"},{"id":"suralmk:sdk-022","prompt":"Which command returns the declared configuration of an existing Container App, including its configured container template?","explanation":"az containerapp show returns the resource configuration. Use revision/replica list commands to enumerate runtime instances; a template entry is not proof a container is running.","domain":"containers","source":"https://learn.microsoft.com/en-us/cli/azure/containerapp?view=azure-cli-latest#az-containerapp-show","topic":"container-apps-keda","type":"single","options":["az containerapp show --name myApp --resource-group myRG","az container list --resource-group myRG --query \"[].name\" -o table","az aks get-credentials --name myCluster --resource-group myRG","az acr repository list --name myregistry --output table"],"answer":0,"setId":"suralmk:sdk-cli-part1","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/sdk-cli-part1.json","reviewDate":"2026-10-11","reviewNote":"App configuration does not list running replicas."},{"id":"suralmk:sdk-023","prompt":"For an App Service-hosted Function App with supported log streaming and filesystem application logging enabled, which Azure CLI command tails the live log stream?","explanation":"az webapp log tail can stream supported App Service logs. This is not a universal history API for all Function hosting plans; use Application Insights/Log Analytics for retained execution telemetry.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/azure-functions/streaming-logs","topic":"opentelemetry","type":"single","options":["az webapp log tail --name myFunctionApp --resource-group myRG","az functionapp show --name myFunctionApp --resource-group myRG -o json","az monitor activity-log list --resource-group myRG --max-events 50","az webapp restart --name myFunctionApp --resource-group myRG"],"answer":0,"setId":"suralmk:sdk-cli-part1","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/sdk-cli-part1.json","reviewDate":"2026-10-11","reviewNote":"Restricted log tail to supported hosting and enabled logs."},{"id":"suralmk:sdk-024","prompt":"Which Azure CLI command lists the access keys/connection strings for a Service Bus namespace's default authorization rule?","explanation":"az servicebus namespace authorization-rule keys list retrieves the primary/secondary connection strings for the named authorization rule (commonly RootManageSharedAccessKey). az servicebus namespace show only returns namespace metadata (no keys), az servicebus namespace create provisions a new namespace, and az keyvault secret show is unrelated unless the key happens to be separately stored there.\n\n```bash\naz servicebus namespace authorization-rule keys list --name RootManageSharedAccessKey --namespace-name myNamespace --resource-group myRG\n```","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/key-vault/general/overview","topic":"key-vault","type":"single","options":["az servicebus namespace authorization-rule keys list --name RootManageSharedAccessKey --namespace-name myNamespace --resource-group myRG","az servicebus namespace show --name myNamespace --resource-group myRG --query \"{sku:sku,status:status,location:location}\" -o json","az servicebus namespace create --name myNamespace --resource-group myRG --location eastus --sku Standard --tags env=prod","az servicebus queue authorization-rule keys list --name RootManageSharedAccessKey --namespace-name myNamespace --queue-name q --resource-group myRG"],"answer":0,"setId":"suralmk:sdk-cli-part1","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/sdk-cli-part1.json","reviewDate":"2026-10-11"},{"id":"suralmk:sdk-025","prompt":"Which Azure CLI command enables diagnostic settings on an AKS cluster to forward logs to a Log Analytics workspace?","explanation":"az monitor diagnostic-settings create is the generic command that wires any resource's diagnostic logs/metrics to a destination like a Log Analytics workspace, letting you specify exactly which log categories (like kube-audit) to forward. Enabling the monitoring add-on without specifying a workspace doesn't establish the diagnostic settings pipeline needed here, creating a new workspace alone doesn't connect it to AKS, and enabling managed identity on AKS is an unrelated identity configuration.\n\n```bash\naz monitor diagnostic-settings create --resource \u003caksResourceId> --workspace \u003cworkspaceId> --name aksDiagnostics --logs '[{\"category\":\"kube-audit\",\"enabled\":true}]'\n```","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/azure-monitor/app/opentelemetry-overview","topic":"opentelemetry","type":"single","options":["az monitor diagnostic-settings create --resource \u003caksId> --workspace \u003cwsId> --name aksDiag --logs '[{\"category\":\"kube-audit\",\"enabled\":true}]'","az aks enable-addons --addons monitoring --name myCluster --resource-group myRG --workspace-resource-id \u003cwsId> --no-wait","az monitor log-analytics workspace create --resource-group myRG --workspace-name aksLogsWS --location eastus --sku PerGB2018","az aks update --name myCluster --resource-group myRG --enable-managed-identity --enable-addons monitoring --no-wait"],"answer":0,"setId":"suralmk:sdk-cli-part1","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/sdk-cli-part1.json","reviewDate":"2026-10-11"},{"id":"suralmk:sdk-026","prompt":"Which Azure CLI command creates a Log Analytics workspace to serve as a central monitoring destination?","explanation":"az monitor log-analytics workspace create provisions the workspace resource itself. 'az monitor workspace new' and 'az loganalytics create' aren't valid command forms, and az monitor diagnostic-settings create wires an existing resource's logs to an existing workspace rather than creating the workspace.\n\n```bash\naz monitor log-analytics workspace create --resource-group myRG --workspace-name myWorkspace\n```","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/azure-monitor/app/opentelemetry-overview","topic":"opentelemetry","type":"single","options":["az monitor log-analytics workspace create --resource-group myRG --workspace-name myWorkspace --location eastus","az monitor app-insights component create --app myApp --resource-group myRG --location eastus --kind web","az monitor diagnostic-settings create --resource \u003cid> --workspace \u003cwsId> --name diagSettings --logs '[]'","az monitor metrics alert create --name myAlert --resource-group myRG --scopes \u003cid> --condition \"avg Percentage CPU > 80\""],"answer":0,"setId":"suralmk:sdk-cli-part1","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/sdk-cli-part1.json","reviewDate":"2026-10-11"},{"id":"suralmk:sdk-027","prompt":"Which credential class from azure-identity is generally recommended as the default choice for authenticating Azure SDK clients across both local development and Azure-hosted environments?","explanation":"DefaultAzureCredential chains together several credential types (managed identity, environment variables, Azure CLI, VS Code, etc.) and is Microsoft's recommended default for most application scenarios spanning local dev and production. UsernamePasswordCredential is discouraged for automated workloads and doesn't support MFA well, hardcoding a ClientSecretCredential embeds long-lived secrets in source control, and there's no 'AnonymousCredential' construct for authenticated Azure SDK calls.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/container-registry/container-registry-intro","topic":"acr","type":"single","options":["DefaultAzureCredential chaining managed identity, env vars, and Azure CLI","UsernamePasswordCredential using interactive username/password without MFA","ClientSecretCredential constructed with a hardcoded client secret in source","InteractiveBrowserCredential requiring a browser login on every application start"],"answer":0,"setId":"suralmk:sdk-cli-part1","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/sdk-cli-part1.json","reviewDate":"2026-10-11"},{"id":"suralmk:sdk-028","prompt":"Which Azure CLI command explicitly enables a user-assigned managed identity (already created) on an Azure Container App?","explanation":"az containerapp identity assign with --user-assigned attaches a pre-existing user-assigned managed identity to the Container App. az identity create only creates the identity resource itself (doesn't attach it to the app), Container Apps does support user-assigned identities (not only system-assigned as the distractor claims), and az role assignment create grants permissions but doesn't attach the identity to the app in the first place.\n\n```bash\naz containerapp identity assign --name myApp --resource-group myRG --user-assigned /subscriptions/\u003csubId>/resourcegroups/myRG/providers/Microsoft.ManagedIdentity/userAssignedIdentities/myIdentity\n```","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/container-apps/scale-app","topic":"container-apps-keda","type":"single","options":["az containerapp identity assign --name myApp --resource-group myRG --user-assigned \u003cidentityResourceId>","az identity create --name myIdentity --resource-group myRG --location eastus --tags app=myApp","az containerapp create --name myApp --resource-group myRG --system-assigned --environment myEnv","az role assignment create --assignee \u003cprincipalId> --role Contributor --scope \u003cresourceId>"],"answer":0,"setId":"suralmk:sdk-cli-part1","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/sdk-cli-part1.json","reviewDate":"2026-10-11"},{"id":"suralmk:sdk-029","prompt":"Which Azure CLI command creates a new revision-enabled update to an existing Container App with a new image tag?","explanation":"az containerapp update changes the app's configuration (including image) and, with multiple revision mode enabled, creates a new revision reflecting the change. az containerapp create is meant for initial creation (not idiomatic for updates), az containerapp revision list only lists existing revisions without creating one, and az containerapp env update modifies the shared environment, not an individual app's image.\n\n```bash\naz containerapp update --name myApp --resource-group myRG --image myregistry.azurecr.io/myapp:v2\n```","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/container-apps/scale-app","topic":"container-apps-keda","type":"single","options":["az containerapp update --name myApp --resource-group myRG --image myregistry.azurecr.io/myapp:v2","az containerapp create --name myApp --resource-group myRG --image myregistry.azurecr.io/myapp:v2 --environment myEnv","az containerapp revision list --name myApp --resource-group myRG --query \"[].name\" -o table","az containerapp env update --name myEnv --resource-group myRG --logs-destination log-analytics"],"answer":0,"setId":"suralmk:sdk-cli-part1","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/sdk-cli-part1.json","reviewDate":"2026-10-11"},{"id":"suralmk:sdk-030","prompt":"Which Python SDK method retrieves configuration values (including feature flags) from Azure App Configuration?","explanation":"AzureAppConfigurationClient (azure-appconfiguration) exposes get_configuration_setting to retrieve a named setting or feature flag from the store. SecretClient targets Key Vault secrets specifically, BlobClient downloads blob content, and CosmosClient.read_item retrieves Cosmos DB documents — none read from App Configuration.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/azure-app-configuration/overview","topic":"app-configuration","type":"single","options":["AzureAppConfigurationClient.get_configuration_setting(key=...) for flags/settings","SecretClient.get_secret(name=...) retrieving a secret value from Azure Key Vault","BlobClient.download_blob() reading blob content bytes from Azure Blob Storage","CosmosClient.get_database_client(...).read() fetching Cosmos database metadata"],"answer":0,"setId":"suralmk:sdk-cli-part1","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/sdk-cli-part1.json","reviewDate":"2026-10-11"},{"id":"suralmk:sdk-031","prompt":"Which Azure CLI command configures a KEDA-based custom scale rule (based on Service Bus queue length) on an existing Container App?","explanation":"For secret authentication, trigger parameter connection maps to a preconfigured Container Apps secret named sb-connection. Set the Service Bus queue/namespace metadata and messageCount target. For managed identity, use supported scale-rule identity configuration.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/container-apps/scale-app","topic":"opentelemetry","type":"single","options":["az containerapp update --name myApp --resource-group myRG --scale-rule-name queue-rule --scale-rule-type azure-servicebus --scale-rule-metadata queueName=myqueue namespace=mynamespace messageCount=5 --scale-rule-auth connection=sb-connection","az containerapp revision copy --name myApp --resource-group myRG --from-revision myApp--0001 --scale-min-replicas 1 --scale-max-replicas 5 --image myregistry.azurecr.io/myapp:v2","az monitor autoscale create --resource \u003cappResourceId> --name queueAutoscale --min-count 1 --max-count 5 --condition \"avg Percentage CPU > 70\" --resource-group myRG","az aks nodepool update --resource-group myRG --cluster-name myCluster --name nodepool1 --enable-cluster-autoscaler --min-count 1 --max-count 5 --update-cluster-autoscaler"],"answer":0,"setId":"suralmk:sdk-cli-part1","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/sdk-cli-part1.json","reviewDate":"2026-10-11","reviewNote":"Corrected the scaler auth parameter and included required metadata."},{"id":"suralmk:sdk-032","prompt":"Which Azure CLI command creates a new secret inside an existing Key Vault?","explanation":"az keyvault secret set both creates a new secret and updates an existing one (adding a new version), taking --value directly or --file for content. 'az keyvault secret create', 'az keyvault add-secret', and 'az keyvault secret new' are not valid Azure CLI command names.\n\n```bash\naz keyvault secret set --vault-name myVault --name dbConnectionString --value \"Server=...;\"\n```","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/key-vault/general/overview","topic":"key-vault","type":"single","options":["az keyvault secret set --vault-name myVault --name mySecret --value \"mySecretValue\"","az keyvault key create --vault-name myVault --name myKey --protection software","az keyvault certificate create --vault-name myVault --name myCert --policy @p.json","az keyvault secret backup --vault-name myVault --name mySecret --file secret.bak"],"answer":0,"setId":"suralmk:sdk-cli-part1","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/sdk-cli-part1.json","reviewDate":"2026-10-11"},{"id":"suralmk:sdk-033","prompt":"Which Azure CLI command retrieves the connection string for an Azure Cosmos DB account?","explanation":"az cosmosdb keys list with --type connection-strings returns the account's connection strings (primary/secondary, and read-only variants). az cosmosdb show returns account metadata but doesn't include a literal 'connectionString' property by default via that simple query, 'az cosmosdb connectionstring show' isn't a valid subcommand, and az keyvault secret show is unrelated unless the string happens to be stored there separately.\n\n```bash\naz cosmosdb keys list --name myaccount --resource-group myRG --type connection-strings\n```","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/key-vault/general/overview","topic":"key-vault","type":"single","options":["az cosmosdb keys list --name myaccount --resource-group myRG --type connection-strings","az cosmosdb show --name myaccount --resource-group myRG --query documentEndpoint","az cosmosdb list-keys --name myaccount --resource-group myRG --query primaryMasterKey","az cosmosdb sql database list --account-name myaccount --resource-group myRG -o table"],"answer":0,"setId":"suralmk:sdk-cli-part1","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/sdk-cli-part1.json","reviewDate":"2026-10-11"},{"id":"suralmk:sdk-034","prompt":"Which Azure CLI command enumerates current Key Vault secret names and enabled metadata, without returning values or every version?","explanation":"secret list returns secret metadata, not all versions. To enumerate versions of one secret, use az keyvault secret list-versions --vault-name myVault --name mySecret.","domain":"operations","source":"https://learn.microsoft.com/en-us/cli/azure/keyvault/secret?view=azure-cli-latest","topic":"key-vault","type":"single","options":["az keyvault secret list --vault-name myVault --query \"[].{name:name,enabled:attributes.enabled}\"","az keyvault secret show --vault-name myVault --name mySecret --version \"\" --query attributes","az keyvault secret restore --vault-name myVault --file secret.bak --encoding base64","az keyvault secret list-deleted --vault-name myVault --query \"[].{name:name,deletionDate:deletedDate}\""],"answer":0,"setId":"suralmk:sdk-cli-part2","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/sdk-cli-part2.json","reviewDate":"2026-10-11","reviewNote":"Listing secret names does not list their versions."},{"id":"suralmk:sdk-035","prompt":"Which command enables the App Service HTTPS-only setting, causing HTTP requests to be redirected to HTTPS?","explanation":"HTTPS-only redirects HTTP requests to HTTPS. Configure minimum TLS separately through site configuration. Do not confuse redirect behavior with an HTTP deny rule.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/app-service/configure-ssl-bindings","topic":"app-service-containers","type":"single","options":["az webapp update --name myApp --resource-group myRG --https-only true","az webapp config set --name myApp --resource-group myRG --http20-enabled true --ftps-state Disabled","az webapp config ssl bind --name myApp --resource-group myRG --certificate-thumbprint \u003ctp> --ssl-type SNI","az webapp config access-restriction add --name myApp --resource-group myRG --rule-name HttpsOnly --priority 100"],"answer":0,"setId":"suralmk:sdk-cli-part2","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/sdk-cli-part2.json","reviewDate":"2026-10-11","reviewNote":"HTTPS-only redirects HTTP traffic rather than guaranteeing rejection."},{"id":"suralmk:sdk-036","prompt":"Which command creates a private endpoint to a PostgreSQL flexible server that supports Private Link?","explanation":"The command creates the endpoint connection. Configure private DNS and approve the connection as needed. Separately disable public network access; endpoint creation alone does not disable it.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/postgresql/flexible-server/concepts-networking-private-link","topic":"postgresql-pgvector","type":"single","options":["az network private-endpoint create --name myPe --resource-group myRG --vnet-name myVnet --subnet mySubnet --private-connection-resource-id \u003cpgId> --group-id postgresqlServer --connection-name c1","az postgres flexible-server update --name myserver --resource-group myRG --public-access Disabled --tier GeneralPurpose --sku-name Standard_D2s_v3 --storage-size 128","az network private-link-service create --name myPls --resource-group myRG --vnet-name myVnet --subnet mySubnet --lb-frontend-ip-configs \u003cfrontendIpConfigId>","az postgres flexible-server firewall-rule create --name AllowAll --resource-group myRG --server-name myserver --start-ip-address 0.0.0.0 --end-ip-address 255.255.255.255"],"answer":0,"setId":"suralmk:sdk-cli-part2","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/sdk-cli-part2.json","reviewDate":"2026-10-11","reviewNote":"Creating a private endpoint does not disable public access."},{"id":"suralmk:sdk-037","prompt":"Which method call correctly performs a synchronous chat completion request against an Azure OpenAI deployment using the OpenAI Python SDK configured for Azure?","explanation":"chat.completions.create with a messages array is the current standard method for chat-style completions against Azure OpenAI chat models. The legacy completions.create/engine-based call targets older non-chat completion models and isn't the modern default, embeddings.create returns vector embeddings (not a chat response), and moderations.create checks content policy compliance rather than generating a completion.","domain":"operations","source":"https://learn.microsoft.com/en-us/cli/azure/reference-index","topic":"azure-cli","type":"single","options":["client.chat.completions.create(model=\"my-deployment\", messages=[{\"role\": \"user\", \"content\": \"Hello\"}])","client.completions.create(model=\"my-deployment\", prompt=\"Hello\", max_tokens=256, temperature=0.7)","client.embeddings.create(model=\"my-deployment\", input=\"Hello\", encoding_format=\"float\")","client.moderations.create(model=\"text-moderation-latest\", input=\"Hello world text\")"],"answer":0,"setId":"suralmk:sdk-cli-part2","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/sdk-cli-part2.json","reviewDate":"2026-10-11"},{"id":"suralmk:sdk-038","prompt":"Which Azure CLI command configures autoscaling on an AKS node pool to scale between 2 and 8 nodes based on cluster resource pressure?","explanation":"az aks nodepool update with --enable-cluster-autoscaler and --min-count/--max-count configures the Cluster Autoscaler to dynamically adjust node count within the specified bounds based on pending pod resource demand. az aks scale performs a one-time, fixed manual scale (not dynamic autoscaling), az vmss scale operates on the underlying scale set directly and bypasses AKS-aware autoscaling logic, and az monitor autoscale targets classic Azure Monitor autoscale, not AKS's built-in Cluster Autoscaler.\n\n```bash\naz aks nodepool update --resource-group myRG --cluster-name myCluster --name nodepool1 --enable-cluster-autoscaler --min-count 2 --max-count 8\n```","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/azure-monitor/app/opentelemetry-overview","topic":"opentelemetry","type":"single","options":["az aks nodepool update --cluster-name myCluster --resource-group myRG --name np1 --enable-cluster-autoscaler --min-count 2 --max-count 8","az aks scale --name myCluster --resource-group myRG --nodepool-name np1 --node-count 8 --no-wait false --yes","az vmss scale --name aks-np1-12345678-vmss --resource-group myRG --new-capacity 8 --no-wait false --yes","az monitor autoscale create --resource \u003cvmssId> --name aksAuto --min-count 2 --max-count 8 --condition \"avg Percentage CPU > 70\""],"answer":0,"setId":"suralmk:sdk-cli-part2","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/sdk-cli-part2.json","reviewDate":"2026-10-11"},{"id":"suralmk:sdk-039","prompt":"Which Azure CLI command retrieves the current deployment status of a Container App to troubleshoot a failed rollout?","explanation":"Inspect revision provisioning and health as well as active state. An active revision is not by itself evidence of a successful rollout.","domain":"containers","source":"https://learn.microsoft.com/en-us/cli/azure/containerapp/revision?view=azure-cli-latest","topic":"container-apps-keda","type":"single","options":["az containerapp revision list --name myApp --resource-group myRG --all --query \"[].{name:name,active:properties.active,health:properties.healthState,provisioning:properties.provisioningState}\" -o table","az containerapp show --name myApp --resource-group myRG --query properties.provisioningState -o tsv","az group deployment list --resource-group myRG --query \"[].{name:name,state:properties.provisioningState}\" -o table","az acr repository show-tags --name myregistry --repository myapp --orderby time_desc --top 20 -o table"],"answer":0,"setId":"suralmk:sdk-cli-part2","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/sdk-cli-part2.json","reviewDate":"2026-10-11","reviewNote":"The original projection omitted rollout health."},{"id":"suralmk:sdk-040","prompt":"Which Azure CLI command creates an Azure Function App backed by a Consumption (serverless) hosting plan?","explanation":"Python Function Apps run on Linux. This illustrates classic Consumption creation where supported. Check current region, runtime and hosting support; evaluate Flex Consumption for new serverless Python apps.","domain":"services","source":"https://learn.microsoft.com/en-us/cli/azure/functionapp?view=azure-cli-latest#az-functionapp-create","topic":"azure-functions","type":"single","options":["az functionapp create --name myFuncApp --resource-group myRG --consumption-plan-location eastus --runtime python --runtime-version 3.11 --os-type Linux --functions-version 4 --storage-account mystorage","az webapp create --name myFuncApp --resource-group myRG --plan myPlan --runtime \"python:3.11\" --deployment-local-git","az functionapp plan create --name myPlan --resource-group myRG --sku EP1 --is-linux --location eastus --min-instances 1","az functionapp deployment source config-zip --name myFuncApp --resource-group myRG --src ./app.zip --build-remote true"],"answer":0,"setId":"suralmk:sdk-cli-part2","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/sdk-cli-part2.json","reviewDate":"2026-10-11","reviewNote":"Python Functions require Linux hosting and a supported runtime."},{"id":"suralmk:sdk-041","prompt":"Which Azure CLI command configures environment variables (app settings) for an Azure Function App, such as an OpenAI endpoint URL?","explanation":"az functionapp config appsettings set adds/updates application settings (surfaced as environment variables) on an existing Function App, mirroring the App Service pattern. Re-running functionapp create against an existing app isn't the correct update path, 'az functionapp update' doesn't take a generic --env flag, and az keyvault secret set stores a Key Vault secret rather than configuring the Function App's environment directly (though it could be referenced from a setting).\n\n```bash\naz functionapp config appsettings set --name myFuncApp --resource-group myRG --settings OPENAI_ENDPOINT=https://myendpoint.openai.azure.com/\n```","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/key-vault/general/overview","topic":"key-vault","type":"single","options":["az functionapp config appsettings set --name myFuncApp --resource-group myRG --settings OPENAI_ENDPOINT=https://myendpoint.openai.azure.com/","az functionapp config hostname add --name myFuncApp --resource-group myRG --hostname api.contoso.com --slot production","az functionapp update --name myFuncApp --resource-group myRG --set siteConfig.alwaysOn=true siteConfig.http20Enabled=true","az keyvault secret set --vault-name myVault --name OPENAI_ENDPOINT --value https://myendpoint.openai.azure.com/ --description endpoint"],"answer":0,"setId":"suralmk:sdk-cli-part2","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/sdk-cli-part2.json","reviewDate":"2026-10-11"},{"id":"suralmk:sdk-042","prompt":"Which Azure CLI command creates a private DNS zone link required so resources in a VNet can resolve the private endpoint FQDN of an Azure service like Cosmos DB?","explanation":"az network private-dns link vnet create links a private DNS zone (e.g., privatelink.documents.azure.com for Cosmos DB) to a VNet, enabling name resolution of the private endpoint's FQDN from within that network — a required step for private endpoint DNS to function. A public DNS zone (az network dns zone create) doesn't handle private-link resolution, creating the VNet alone doesn't establish the DNS link, and creating a private-endpoint DNS zone group without first linking the zone to the VNet leaves resolution incomplete.\n\n```bash\naz network private-dns link vnet create --resource-group myRG --zone-name privatelink.documents.azure.com --name myLink --virtual-network myVnet --registration-enabled false\n```","domain":"services","source":"https://learn.microsoft.com/en-us/azure/azure-functions/functions-overview","topic":"azure-functions","type":"single","options":["az network private-dns link vnet create --resource-group myRG --zone-name privatelink.documents.azure.com --name myLink --virtual-network myVnet --registration-enabled false","az network dns zone create --resource-group myRG --name contoso.com --tags purpose=public-dns-resolution env=prod owner=platform team=netops","az network private-dns zone create --resource-group myRG --name privatelink.documents.azure.com --tags purpose=private-endpoint-dns env=prod","az network private-endpoint dns-zone-group add --resource-group myRG --endpoint-name myEndpoint --name myZoneGroup --private-dns-zone privatelink.documents.azure.com --zone-name cosmos"],"answer":0,"setId":"suralmk:sdk-cli-part2","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/sdk-cli-part2.json","reviewDate":"2026-10-11"},{"id":"suralmk:sdk-043","prompt":"For an App Service Plan whose metric definitions include CpuPercentage, which command reads that platform metric?","explanation":"Use az monitor metrics list with the plan resource ID and CpuPercentage. List the metric definitions first for another resource type; CPU metric names are not universal.","domain":"operations","source":"https://learn.microsoft.com/en-us/cli/azure/monitor/metrics?view=azure-cli-latest","topic":"opentelemetry","type":"single","options":["az monitor metrics list --resource \u003cresourceId> --metric \"CpuPercentage\" --interval PT1M","az monitor activity-log list --resource-group myRG --max-events 50 --offset 1h","az resource show --ids \u003cresourceId> --query properties.provisioningState -o tsv","az monitor log-analytics query --workspace \u003cid> --analytics-query \"AppRequests | take 20\""],"answer":0,"setId":"suralmk:sdk-cli-part2","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/sdk-cli-part2.json","reviewDate":"2026-10-11","reviewNote":"Metric names depend on resource type."},{"id":"suralmk:sdk-044","prompt":"Which Azure CLI command lists all role assignments currently granted to a specific managed identity, useful when troubleshooting an 'access denied' error?","explanation":"az role assignment list --assignee \u003cprincipalId> shows exactly which roles and scopes have been granted to that identity, which is the direct troubleshooting step for access-denied issues. az ad sp list searches for service principal objects by name (not role assignments), az role definition list only enumerates available role definitions (not what's actually assigned), and az keyvault show returns vault configuration, unrelated to identity role assignments.\n\n```bash\naz role assignment list --assignee \u003cprincipalId> --all -o table\n```","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/key-vault/general/overview","topic":"key-vault","type":"single","options":["az role assignment list --assignee \u003cprincipalId> --all -o table","az ad sp show --id \u003cprincipalId> --query \"{appId:appId,displayName:displayName}\"","az role definition list --custom-role-only false --query \"[].roleName\" -o tsv","az identity show --ids \u003cidentityResourceId> --query principalId -o tsv"],"answer":0,"setId":"suralmk:sdk-cli-part2","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/sdk-cli-part2.json","reviewDate":"2026-10-11"},{"id":"suralmk:sdk-045","prompt":"Which command restricts a Container App HTTP endpoint to callers within the same Container Apps environment?","explanation":"App ingress type internal restricts access to the same environment. To serve other reachable VNet clients privately, use an internal environment with app ingress external to the environment and appropriate DNS/routes.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/container-apps/ingress-overview","topic":"container-apps-keda","type":"single","options":["az containerapp ingress enable --name myApp --resource-group myRG --type internal --target-port 8080 --transport auto","az containerapp ingress enable --name myApp --resource-group myRG --type external --target-port 8080 --transport auto","az containerapp update --name myApp --resource-group myRG --set properties.configuration.ingress.allowInsecure=true","az network nsg rule create --resource-group myRG --nsg-name myNSG --name DenyInternet --priority 100 --access Deny --direction Inbound"],"answer":0,"setId":"suralmk:sdk-cli-part2","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/sdk-cli-part2.json","reviewDate":"2026-10-11","reviewNote":"Internal app ingress is scoped to the Container Apps environment, not the entire VNet."},{"id":"suralmk:sdk-046","prompt":"Which Azure CLI command shows the current status (running, failed, succeeded) of an ACR Task run, useful when a build appears stuck?","explanation":"az acr task list-runs returns the run history and current status for tasks executed against the registry, which is the direct way to check whether a build is running, succeeded, or failed. az acr task create defines a new task (doesn't show run status), az acr repository show returns repository metadata (not build/task run status), and az acr login only authenticates the local Docker client.\n\n```bash\naz acr task list-runs --registry myregistry --output table\n```","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/container-registry/container-registry-intro","topic":"acr","type":"single","options":["az acr task list-runs --registry myregistry --output table","az acr task show --registry myregistry --name buildTask -o json","az acr repository show --name myregistry --repository myapp -o json","az acr run --registry myregistry --cmd \"echo status\" /dev/null"],"answer":0,"setId":"suralmk:sdk-cli-part2","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/sdk-cli-part2.json","reviewDate":"2026-10-11"},{"id":"suralmk:sdk-047","prompt":"Which Azure CLI command retrieves logs for a specific Azure Function's recent executions, filtered to only error-level entries, via Log Analytics KQL?","explanation":"Filter the retained FunctionAppLogs table to the desired interval and level, then explicitly order by time. take 50 alone does not mean the most recent entries. Diagnostic settings must populate the table.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/azure-monitor/reference/tables/functionapplogs","topic":"kql","type":"single","options":["az monitor log-analytics query --workspace \u003cworkspaceId> --analytics-query \"FunctionAppLogs | where TimeGenerated > ago(1h) and Level == 'Error' | top 50 by TimeGenerated desc\"","az functionapp log deployment show --name myFuncApp --resource-group myRG --slot production -o table","az webapp log download --name myFuncApp --resource-group myRG --log-file ./logs.zip --slot production","az monitor activity-log list --resource-group myRG --status Failed --offset 24h --max-events 50 -o table"],"answer":0,"setId":"suralmk:sdk-cli-part2","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/sdk-cli-part2.json","reviewDate":"2026-10-11","reviewNote":"Added a time filter and deterministic recent-first ordering."},{"id":"suralmk:sdk-048","prompt":"Which Azure CLI command creates a resource group-scoped assignment giving a user the built-in 'Reader' role, for read-only troubleshooting access?","explanation":"az role assignment create with --role Reader and --resource-group scopes the assignment to read-only access on that resource group, matching least-privilege troubleshooting access. Assigning Owner grants far more than read access, az ad user create provisions a new user account (unrelated to role assignment), and az group create merely creates a resource group, not a role assignment.\n\n```bash\naz role assignment create --assignee user@contoso.com --role Reader --resource-group myRG\n```","domain":"operations","source":"https://learn.microsoft.com/en-us/cli/azure/reference-index","topic":"azure-cli","type":"single","options":["az role assignment create --assignee \u003cuserPrincipalNameOrId> --role Reader --resource-group myRG","az role assignment create --assignee \u003cuserId> --role Contributor --resource-group myRG","az role assignment create --assignee \u003cuserId> --role Owner --scope /subscriptions/\u003csubId>","az ad user update --id \u003cuserId> --display-name Reader --force-change-password-next-sign-in false"],"answer":0,"setId":"suralmk:sdk-cli-part2","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/sdk-cli-part2.json","reviewDate":"2026-10-11"},{"id":"suralmk:sdk-049","prompt":"Which Python SDK method call correctly performs a vector similarity search directly against a Cosmos DB for NoSQL container using the SDK's query capability?","explanation":"Use query_items with a parameterized vector query. enable_cross_partition_query=True explicitly permits cross-partition execution in SDK versions that expose the option. Provide partition_key for a scoped query, and check the documentation of the installed SDK.","domain":"services","source":"https://learn.microsoft.com/en-us/python/api/azure-cosmos/azure.cosmos.containerproxy?view=azure-python","topic":"azure-functions","type":"single","options":["container.query_items(query=\"SELECT TOP 5 c.id, VectorDistance(c.embedding,@v) AS s FROM c ORDER BY VectorDistance(c.embedding,@v)\", parameters=[{\"name\":\"@v\",\"value\":qv}], enable_cross_partition_query=True)","container.read_item(item=item_id, partition_key=pk); then locally rank embeddings by cosine similarity and return the top-k nearest neighbors","container.upsert_item(body={\"id\":\"q\",\"embedding\":qv}); then container.query_items(query=\"SELECT TOP 5 c.id, c.embedding FROM c WHERE c.id != 'q'\")","container.scripts.execute_stored_procedure(sproc=\"vectorSearch\", params=[qv, 5], partition_key=part_key, enable_script_logging=True)"],"answer":0,"setId":"suralmk:sdk-cli-part2","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/sdk-cli-part2.json","reviewDate":"2026-10-11","reviewNote":"Made cross-partition intent explicit without assuming identical defaults in every SDK version."},{"id":"suralmk:sdk-050","prompt":"An ACR image-push webhook is already configured to call the App Service deployment endpoint. Which command enables container continuous deployment on the App Service side?","explanation":"Enable CD on App Service and configure the registry webhook for the image/tag. The CLI switch alone is not the whole end-to-end notification setup.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/app-service/deploy-ci-cd-custom-container","topic":"app-service-containers","type":"single","options":["az webapp deployment container config --name myApp --resource-group myRG --enable-cd true","az webapp config container set --name myApp --resource-group myRG --docker-custom-image-name myimage:v1","az acr webhook create --name myHook --registry myregistry --actions push --uri https://myapp.azurewebsites.net/hook","Use az webapp deployment container config --enable-cd true (auto ACR webhook); verify with az acr webhook list"],"answer":0,"setId":"suralmk:sdk-cli-part2","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/sdk-cli-part2.json","reviewDate":"2026-10-11","reviewNote":"Enabling the App Service endpoint does not alone create the ACR webhook."},{"id":"suralmk:sdk-051","prompt":"Which Azure CLI command creates a Cosmos DB SQL (NoSQL) container with a specified partition key and throughput?","explanation":"az cosmosdb sql container create is the specific command for creating a container within an existing SQL/NoSQL API database, taking --partition-key-path and --throughput. az cosmosdb sql database create creates a database (a level above containers, not a container itself), 'az cosmosdb collection create' is not valid modern CLI syntax, and az cosmosdb create provisions the account, not an individual container.\n\n```bash\naz cosmosdb sql container create --account-name myaccount --database-name mydb --name mycontainer --partition-key-path /userId --throughput 400\n```","domain":"data","source":"https://learn.microsoft.com/en-us/cli/azure/cosmosdb/sql/container?view=azure-cli-latest","topic":"cosmos-db-nosql","type":"single","options":["az cosmosdb sql container create --resource-group myRG --account-name myaccount --database-name mydb --name mycontainer --partition-key-path /userId --throughput 400","az cosmosdb sql database create --account-name myaccount --resource-group myRG --name mydb --throughput 400","az cosmosdb sql container throughput update --account-name myaccount --database-name mydb --name mycontainer --throughput 400","az cosmosdb create --name myaccount --resource-group myRG --kind GlobalDocumentDB --locations regionName=eastus"],"answer":0,"setId":"suralmk:sdk-cli-part2","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/sdk-cli-part2.json","reviewDate":"2026-10-11","reviewNote":"Added the required resource-group context."},{"id":"suralmk:sdk-052","prompt":"Which Azure CLI command creates a new App Configuration store to centrally hold feature flags for an AI application?","explanation":"az appconfig create provisions a new App Configuration store resource, with --sku controlling the pricing tier (standard supports feature management at scale). 'az appconfig store new' and 'az config create' aren't valid command names, and az keyvault create provisions a Key Vault, a different secrets-focused service.\n\n```bash\naz appconfig create --name myAppConfig --resource-group myRG --location eastus --sku standard\n```","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/azure-app-configuration/overview","topic":"app-configuration","type":"single","options":["az appconfig create --name myAppConfig --resource-group myRG --location eastus --sku standard","az appconfig kv set --name myAppConfig --key FeatureFlags:Beta --value true --label prod","az appconfig feature set --name myAppConfig --feature Beta --description \"beta rollout flag\"","az keyvault create --name myAppConfig --resource-group myRG --location eastus --sku standard"],"answer":0,"setId":"suralmk:sdk-cli-part2","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/sdk-cli-part2.json","reviewDate":"2026-10-11"},{"id":"suralmk:sdk-053","prompt":"Which Azure CLI command retrieves the effective role assignments (including inherited ones from management group/subscription level) for a resource, to troubleshoot unexpected access?","explanation":"Including --include-inherited (alongside --scope) surfaces role assignments granted at higher scopes (subscription, management group) that also apply to the resource, which is essential when troubleshooting unexpected access that isn't explained by resource-level assignments alone. Omitting that flag only shows assignments made directly at that exact scope, resource show returns configuration (not access), and account show just displays the current subscription context.\n\n```bash\naz role assignment list --scope \u003cresourceId> --include-inherited -o table\n```","domain":"operations","source":"https://learn.microsoft.com/en-us/cli/azure/reference-index","topic":"azure-cli","type":"single","options":["az role assignment list --scope \u003cresourceId> --include-inherited -o table","az role assignment list --scope \u003cresourceId> --include-groups false -o table","az resource show --ids \u003cresourceId> --query \"identity.principalId\" -o tsv","az account management-group show --name myMg --query \"properties.displayName\""],"answer":0,"setId":"suralmk:sdk-cli-part2","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/sdk-cli-part2.json","reviewDate":"2026-10-11"},{"id":"suralmk:sdk-054","prompt":"Which Azure CLI command creates a new subscription (in the Service Bus sense) on an existing topic?","explanation":"az servicebus topic subscription create adds a new subscription under a specific existing topic within a namespace, which is exactly the entity needed for pub/sub fan-out. Creating a namespace or a queue doesn't create a topic subscription, and az servicebus topic create makes a new topic, not a subscription on an existing one.\n\n```bash\naz servicebus topic subscription create --resource-group myRG --namespace-name myNamespace --topic-name myTopic --name mySubscription\n```","domain":"services","source":"https://learn.microsoft.com/en-us/azure/service-bus-messaging/service-bus-messaging-overview","topic":"service-bus","type":"single","options":["az servicebus topic subscription create --resource-group myRG --namespace-name myNamespace --topic-name myTopic --name mySubscription","az servicebus namespace create --name myNamespace --resource-group myRG --location eastus --sku Standard","az servicebus queue create --resource-group myRG --namespace-name myNamespace --name mySubscription --max-size 1024","az servicebus topic create --resource-group myRG --namespace-name myNamespace --name myTopic --max-size 1024"],"answer":0,"setId":"suralmk:sdk-cli-part2","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/sdk-cli-part2.json","reviewDate":"2026-10-11"},{"id":"suralmk:sdk-055","prompt":"Which Azure CLI command retrieves the current outbound IP address set of an App Service?","explanation":"outboundIpAddresses gives the current set. possibleOutboundIpAddresses represents a broader possible set across scale/tier changes. Network integration, NAT and hosting choices can change egress behavior.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/app-service/overview-inbound-outbound-ips","topic":"postgresql-pgvector","type":"single","options":["az webapp show --name myApp --resource-group myRG --query outboundIpAddresses -o tsv","az webapp config show --name myApp --resource-group myRG --query linuxFxVersion -o tsv","az network public-ip list --resource-group myRG --query \"[].ipAddress\" -o tsv","az webapp list-runtimes --os linux --query \"[].{runtime:runtime}\" -o table"],"answer":0,"setId":"suralmk:sdk-cli-part2","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/sdk-cli-part2.json","reviewDate":"2026-10-11","reviewNote":"Distinguished current outbound addresses from possible future addresses."},{"id":"suralmk:sdk-056","prompt":"Assume a subnet has the Microsoft.Storage service endpoint enabled. Which commands allow that subnet and the documented trusted-services bypass, while denying other public data-plane traffic?","explanation":"Set both the VNet rule and default-action Deny; configure the specific AzureServices bypass intentionally. Trusted services still need authorization. This is public-endpoint network filtering, not Private Link.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/storage/common/storage-network-security","topic":"azure-cli","type":"single","options":["az storage account network-rule add --resource-group myRG --account-name mystorageacct --vnet-name myVnet --subnet mySubnet; az storage account update --resource-group myRG --name mystorageacct --default-action Deny --bypass AzureServices","az storage account update --resource-group myRG --name mystorageacct --default-action Allow --bypass AzureServices --public-network-access Enabled","az storage account update --resource-group myRG --name mystorageacct --public-network-access Enabled --sku Standard_LRS --access-tier Hot","az network nsg rule create --resource-group myRG --nsg-name myNSG --name AllowStorage --priority 200 --access Allow --direction Outbound --destination-port-ranges 443"],"answer":0,"setId":"suralmk:sdk-cli-part2","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/sdk-cli-part2.json","reviewDate":"2026-10-11","reviewNote":"Completed the storage update command and stated service-endpoint prerequisites."},{"id":"suralmk:sdk-057","prompt":"Which Azure CLI command lists the deployment history for an App Service, useful to identify when a bad deployment was introduced?","explanation":"The deployment log history is available under az webapp log deployment list. It reports deployments visible to that mechanism; platform-specific delivery methods can have additional logs.","domain":"containers","source":"https://learn.microsoft.com/en-us/cli/azure/webapp/log/deployment?view=azure-cli-latest","topic":"app-service-containers","type":"single","options":["az webapp log deployment list --name myApp --resource-group myRG -o table","az webapp show --name myApp --resource-group myRG --query state -o tsv","az webapp log deployment show --name myApp --resource-group myRG -o table","az group deployment list --resource-group myRG --query \"[].name\" -o tsv"],"answer":0,"setId":"suralmk:sdk-cli-part2","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/sdk-cli-part2.json","reviewDate":"2026-10-11","reviewNote":"Corrected the App Service deployment-log command family."},{"id":"suralmk:sdk-058","prompt":"Which Azure CLI command sequence correctly rotates a Storage Account access key without causing downtime for applications currently using the other key?","explanation":"The zero-downtime rotation pattern renews the key currently NOT in active use (e.g., key2) first, migrates applications to use that freshly rotated key, and only then rotates the original key (key1) they've since stopped using — preventing any window where the active key is invalidated out from under a running app. Renewing both keys simultaneously (or renewing the key actively in use) risks breaking active connections, deleting and recreating the account is drastic and destroys existing data/configuration, and changing the redundancy SKU has nothing to do with key rotation.\n\n```bash\naz storage account keys renew --resource-group myRG --account-name mystorageacct --key key2\n```","domain":"operations","source":"https://learn.microsoft.com/en-us/cli/azure/reference-index","topic":"azure-cli","type":"single","options":["az storage account keys renew --resource-group myRG --account-name mystorageacct --key key2; migrate apps to key2; later renew key1","az storage account keys renew --resource-group myRG --account-name mystorageacct --key key1 while apps still use key1 actively","az storage account keys list --resource-group myRG --account-name mystorageacct then delete both keys at once","az storage account update --resource-group myRG --name mystorageacct --sku Standard_GRS (redundancy change only)"],"answer":0,"setId":"suralmk:sdk-cli-part2","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/sdk-cli-part2.json","reviewDate":"2026-10-11"},{"id":"suralmk:sdk-059","prompt":"Which Azure CLI command creates an ACR Task that automatically rebuilds an image whenever the associated Git repository receives a new commit?","explanation":"az acr task create with a Git --context and access token establishes a persistent task that ACR monitors, automatically triggering rebuilds on new commits to the repository. az acr build performs a single, one-off manual build (not a persistent trigger), az acr task run manually invokes an already-defined task on demand (doesn't itself define the Git trigger), and az acr repository show only inspects existing repository metadata.\n\n```bash\naz acr task create --registry myregistry --name buildTask --image myapp:{{.Run.ID}} --context https://github.com/org/repo.git --file Dockerfile --git-access-token \u003ctoken>\n```","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/container-registry/container-registry-intro","topic":"acr","type":"single","options":["az acr task create --registry myregistry --name buildTask --image myapp:{{.Run.ID}} --context https://github.com/org/repo.git --file Dockerfile --git-access-token \u003ctoken>","az acr build --registry myregistry --image myapp:v1 --file Dockerfile --platform linux --timeout 3600 --context https://github.com/org/repo.git","az acr task run --registry myregistry --name buildTask --set myapp.tag=manual --context https://github.com/org/repo.git --file Dockerfile","az acr task update --registry myregistry --name buildTask --image myapp:latest --context https://github.com/org/repo.git --file Dockerfile --git-access-token \u003ctoken>"],"answer":0,"setId":"suralmk:sdk-cli-part2","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/sdk-cli-part2.json","reviewDate":"2026-10-11"},{"id":"suralmk:sdk-060","prompt":"Which Python SDK class and method combination correctly deletes a message from a Service Bus queue after successful processing (completing the message)?","explanation":"complete_message on a ServiceBusReceiver settles the message as successfully processed, removing it from the queue permanently. abandon_message releases the lock so the message becomes available for redelivery (used on failure, not success), dead_letter_message explicitly moves it to the dead-letter sub-queue, and send_messages is a sender-side operation for publishing new messages, not completing received ones.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/service-bus-messaging/service-bus-messaging-overview","topic":"service-bus","type":"single","options":["ServiceBusReceiver.complete_message(message) to settle and remove after success","ServiceBusReceiver.abandon_message(message) to release the lock for redelivery","ServiceBusReceiver.dead_letter_message(message) to move it to the dead-letter queue","ServiceBusSender.send_messages(message) to publish a new message onto the queue"],"answer":0,"setId":"suralmk:sdk-cli-part2","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/sdk-cli-part2.json","reviewDate":"2026-10-11"},{"id":"suralmk:sdk-061","prompt":"An AKS cluster already uses managed identities. Its ACR uses classic RBAC Registry Permissions. Which command grants the kubelet identity pull access?","explanation":"attach-acr grants AcrPull to the kubelet managed identity. It does not use the control-plane identity for image pulls. For RBAC + ABAC registries, assign repository reader permissions explicitly instead.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/aks/cluster-container-registry-integration","topic":"aks","type":"single","options":["az aks update --name myCluster --resource-group myRG --attach-acr myregistry","az aks update --name myCluster --resource-group myRG --api-server-authorized-ip-ranges 203.0.113.0/24","kubectl create secret docker-registry acr-secret --docker-server=myregistry.azurecr.io --docker-username=u --docker-password=p","az acr update --name myregistry --admin-enabled true; copy admin password into a K8s docker-registry secret"],"answer":0,"setId":"suralmk:sdk-cli-part2","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/sdk-cli-part2.json","reviewDate":"2026-10-11","reviewNote":"Identified the kubelet identity and excluded ABAC mode from attach-acr."},{"id":"suralmk:sdk-062","prompt":"Which Azure CLI command shows the current health/provisioning state of an Azure Database for PostgreSQL flexible server, useful when troubleshooting connectivity issues?","explanation":"az postgres flexible-server show with --query state returns the server's current provisioning/operational state, a direct first check when diagnosing connectivity problems. list-skus only shows available pricing tiers in a region (unrelated to a specific server's health), delete obviously doesn't diagnose anything, and listing private endpoints checks network configuration broadly rather than the server's own state directly.\n\n```bash\naz postgres flexible-server show --name myserver --resource-group myRG --query state -o tsv\n```","domain":"data","source":"https://github.com/pgvector/pgvector","topic":"postgresql-pgvector","type":"single","options":["az postgres flexible-server show --name myserver --resource-group myRG --query state -o tsv","az postgres flexible-server list-skus --location eastus --query \"[].{tier:tier,name:name}\"","az postgres flexible-server firewall-rule list --name myserver --resource-group myRG -o table","az network private-endpoint list --resource-group myRG --query \"[].{name:name,state:provisioningState}\""],"answer":0,"setId":"suralmk:sdk-cli-part2","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/sdk-cli-part2.json","reviewDate":"2026-10-11"},{"id":"suralmk:sdk-063","prompt":"Which Azure CLI command configures a minimum and maximum replica count for an Azure Container App (general replica scaling bounds, separate from a specific scale rule)?","explanation":"az containerapp update with --min-replicas and --max-replicas sets the elastic scaling bounds within which Container Apps' scale rules operate. Setting a fixed --replicas count on creation doesn't establish elastic min/max bounds, AKS nodepool scaling manages cluster nodes (not Container Apps replicas), and VMSS scaling targets a completely different compute resource (Virtual Machine Scale Sets).\n\n```bash\naz containerapp update --name myApp --resource-group myRG --min-replicas 1 --max-replicas 10\n```","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/container-apps/scale-app","topic":"container-apps-keda","type":"single","options":["az containerapp update --name myApp --resource-group myRG --min-replicas 1 --max-replicas 10","az containerapp create --name myApp --resource-group myRG --min-replicas 10 --max-replicas 10 --environment myEnv","az aks nodepool update --resource-group myRG --cluster-name myCluster --name np1 --min-count 1 --max-count 10","az monitor autoscale create --resource \u003cappId> --min-count 1 --max-count 10 --condition \"avg Percentage CPU > 70\""],"answer":0,"setId":"suralmk:sdk-cli-part2","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/sdk-cli-part2.json","reviewDate":"2026-10-11"},{"id":"suralmk:sec-101","prompt":"Which Azure service should be used to securely store and manage API keys, connection strings, and certificates used by an AI application?","explanation":"Key Vault is purpose-built for secrets, keys, and certificates, with access control, auditing, and automated rotation support. App Configuration targets non-secret configuration/feature flags, Blob Storage is general object storage without secret-specific protections, and Monitor is an observability service, not a secrets store.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/azure-app-configuration/overview","topic":"app-configuration","type":"single","options":["Azure Key Vault secrets","Azure App Configuration","Azure Blob Storage acct","Azure Monitor Logs hub"],"answer":0,"setId":"suralmk:secure-monitor-160","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/secure-monitor-160.json","reviewDate":"2026-10-11"},{"id":"suralmk:sec-102","prompt":"You want a database connection secret stored in Key Vault to be automatically rotated on a schedule, with dependent applications picking up the new value without manual redeployment. What should you implement?","explanation":"Key Vault has built-in key rotation policies, but arbitrary database/API secrets need automation that updates both the issuing system and Key Vault. Versionless app references/provider refresh then load the new version, with refresh latency to consider.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/key-vault/secrets/tutorial-rotation","topic":"key-vault","type":"single","options":["Use scheduled or near-expiry-triggered automation to rotate the backing credential and store a new secret version; refresh versionless references","Manual yearly secret update in a maintenance window","Plain env var secret baked into the container image","Versioning disabled so only one secret value exists"],"answer":0,"setId":"suralmk:secure-monitor-160","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/secure-monitor-160.json","reviewDate":"2026-10-11","reviewNote":"Secret rotation requires application automation; key rotation policies do not rotate arbitrary secrets."},{"id":"suralmk:sec-103","prompt":"Which Azure CLI command retrieves the value of a secret stored in Key Vault?","explanation":"az keyvault secret show retrieves the details (including value, with --query) of a specific named secret from the vault. az keyvault secret list only enumerates secret names/metadata (not full values by default), az keyvault create provisions a new vault (not a secret operation), and az keyvault secret delete removes a secret rather than retrieving it.\n\n```bash\naz keyvault secret show --vault-name myVault --name mySecret --query value -o tsv\n```","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/key-vault/general/overview","topic":"key-vault","type":"single","options":["az keyvault secret show --vault-name myVault --name mySecret","az keyvault secret list --vault-name myVault --output table","az keyvault create --name myVault --resource-group myRG","az keyvault secret delete --vault-name myVault --name mySecret"],"answer":0,"setId":"suralmk:secure-monitor-160","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/secure-monitor-160.json","reviewDate":"2026-10-11"},{"id":"suralmk:sec-104","prompt":"An application authenticates to Key Vault using DefaultAzureCredential. In local development it should use the developer's Azure CLI login, and in production it should use a managed identity, without code changes. Why does DefaultAzureCredential satisfy this requirement?","explanation":"DefaultAzureCredential chains multiple credential providers and tries each in a defined order, automatically falling back from managed identity (available in Azure) to Azure CLI credentials (available locally), letting the same code work in both environments without modification. It doesn't require a hardcoded client secret, it does work locally via CLI/VS Code credentials (not just managed identity), and no SDK switch is needed since the chaining behavior is built into azure-identity itself.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/key-vault/general/overview","topic":"key-vault","type":"single","options":["Tries env, managed identity, Azure CLI, etc. in order","Always requires an explicit client secret in code","Works only with managed identity; fails locally","Needs a different SDK for local versus production"],"answer":0,"setId":"suralmk:secure-monitor-160","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/secure-monitor-160.json","reviewDate":"2026-10-11"},{"id":"suralmk:sec-105","prompt":"Your AI application's App Service must call Azure OpenAI, Key Vault, and Cosmos DB, and your organization requires strict least-privilege access with no long-lived credentials anywhere. What is the correct combination of steps?","explanation":"Enabling a managed identity and assigning resource-specific, least-privilege RBAC roles for each dependency is the Microsoft-recommended pattern — it avoids any stored credentials while granting only the exact permissions required per service. An Owner-level service principal or management-group Contributor role grossly over-provisions access, and hardcoding a master API key directly violates the 'no long-lived credentials' requirement.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/key-vault/general/overview","topic":"key-vault","type":"single","options":["System MI plus least-privilege RBAC on each dependency","One Owner service principal shared across all services","Single master API key hardcoded for all three APIs","Management-group Contributor on the App Service MI"],"answer":0,"setId":"suralmk:secure-monitor-160","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/secure-monitor-160.json","reviewDate":"2026-10-11"},{"id":"suralmk:sec-106","prompt":"Which Azure service centrally stores non-secret application settings, such as feature flags and endpoint URLs, and supports dynamic configuration refresh without app restarts?","explanation":"App Configuration is designed for exactly this: centralized non-secret settings and feature flags with a dynamic refresh provider that lets applications pick up changes without restarting. Key Vault is meant for secrets specifically, Azure Files is a file share, and Container Registry stores images — none address dynamic app configuration.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/azure-app-configuration/overview","topic":"app-configuration","type":"single","options":["Azure App Configuration","Azure Key Vault secrets","Azure Files SMB shares","Azure Container Registry"],"answer":0,"setId":"suralmk:secure-monitor-160","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/secure-monitor-160.json","reviewDate":"2026-10-11"},{"id":"suralmk:sec-107","prompt":"You need to trace a request as it flows through an Azure Function, then a Service Bus message, then a downstream Container App, correlating all spans into a single distributed trace. What should you implement?","explanation":"OpenTelemetry SDKs provide standardized instrumentation and context propagation (the W3C traceparent header) across heterogeneous services, letting a single trace ID link spans from the Function, the Service Bus message, and the Container App into one coherent distributed trace. Uncorrelated per-service logging, instrumenting only one component, or manually comparing timestamps after the fact all fail to produce a reliable, queryable end-to-end trace.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/azure-monitor/app/opentelemetry-overview","topic":"opentelemetry","type":"single","options":["OpenTelemetry with W3C traceparent across services","Uncorrelated per-service logs with no shared IDs","App Insights only on the Function, nowhere else","Manual timestamp matching across separate log files"],"answer":0,"setId":"suralmk:secure-monitor-160","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/secure-monitor-160.json","reviewDate":"2026-10-11"},{"id":"suralmk:sec-108","prompt":"You need a KQL query in Log Analytics that finds all failed HTTP requests (5xx) to an App Service-hosted AI API in the last hour, sorted by most recent first. Which query is correct?","explanation":"This query correctly filters AppRequests to the last hour with a ResultCode beginning with '5' (all 5xx codes) and sorts by TimeGenerated descending, exactly matching the requirement. Filtering for ResultCode == \"200\" returns successful (not failed) requests, summarizing AppExceptions by day doesn't isolate 5xx HTTP requests specifically, and 'take 10' returns an arbitrary unsorted, unfiltered sample.","domain":"operations","source":"https://learn.microsoft.com/en-us/kusto/query/","topic":"kql","type":"single","options":["AppRequests | where TimeGenerated > ago(1h) and ResultCode startswith \"5\" | order by TimeGenerated desc","AppRequests | where TimeGenerated > ago(1h) and ResultCode == \"200\" | order by TimeGenerated asc","AppExceptions | where TimeGenerated > ago(1h) | summarize count() by bin(TimeGenerated, 1d)","AppRequests | where TimeGenerated > ago(1h) | take 10 | project TimeGenerated, ResultCode, Name"],"answer":0,"setId":"suralmk:secure-monitor-160","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/secure-monitor-160.json","reviewDate":"2026-10-11"},{"id":"suralmk:sec-109","prompt":"Which Azure Monitor / Application Insights feature captures the full call chain (dependencies, exceptions, custom events) for an individual request to help debug a specific slow or failed transaction?","explanation":"Application Insights' end-to-end transaction view stitches together the request, its dependency calls, exceptions, and custom telemetry for a single operation using distributed tracing, which is exactly what's needed to debug one specific transaction. Metrics Explorer aggregates numeric metrics without per-transaction detail, the Activity Log records control-plane (management) operations rather than application telemetry, and Azure Advisor gives cost/security/performance recommendations, not per-request debugging.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/azure-monitor/app/opentelemetry-overview","topic":"opentelemetry","type":"single","options":["End-to-end transaction details via distributed tracing","Metrics Explorer alone without request-level detail","Activity Log control-plane events for the resource","Azure Advisor cost and security recommendations list"],"answer":0,"setId":"suralmk:secure-monitor-160","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/secure-monitor-160.json","reviewDate":"2026-10-11"},{"id":"suralmk:sec-110","prompt":"An AI service's OpenTelemetry traces show high latency concentrated in a single span calling Azure Database for PostgreSQL, but the database's own server-side metrics show low CPU and query duration. What should you investigate next?","explanation":"When server-side query duration is low but the client-observed span is slow, the discrepancy typically points to time spent outside actual query execution — network round-trip latency, cross-region calls, or connection pool exhaustion waiting for an available connection — which OpenTelemetry span timing includes but server query metrics don't. Scaling compute doesn't address a network/connection-layer bottleneck, dismissing accurate trace data is not a valid diagnostic step, and removing WHERE clauses would harm correctness and likely worsen performance.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/azure-monitor/app/opentelemetry-overview","topic":"opentelemetry","type":"single","options":["Network latency or connection pool wait to PostgreSQL","Immediately scale up the PostgreSQL compute tier","Assume traces are wrong and disable all tracing","Rewrite the query removing every WHERE predicate"],"answer":0,"setId":"suralmk:secure-monitor-160","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/secure-monitor-160.json","reviewDate":"2026-10-11"},{"id":"suralmk:sec-111","prompt":"Which Key Vault access model is recommended over legacy Access Policies for fine-grained, auditable, role-based permission management aligned with the rest of Azure?","explanation":"Microsoft recommends the Azure RBAC permission model for Key Vault because it integrates with the same role-assignment and auditing mechanisms used across Azure, offering finer granularity and centralized management compared to the legacy vault-specific Access Policy model. Sharing a master password or leaving public access unauthenticated are severe security anti-patterns, and continuing to rely exclusively on legacy Access Policies forgoes the improved auditability and consistency RBAC provides.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/key-vault/general/overview","topic":"key-vault","type":"single","options":["Azure RBAC roles such as Key Vault Secrets User","Shared master password distributed through email","Public network access with authentication disabled","Legacy Access Policies only with RBAC turned off"],"answer":0,"setId":"suralmk:secure-monitor-160","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/secure-monitor-160.json","reviewDate":"2026-10-11"},{"id":"suralmk:sec-112","prompt":"Which Azure CLI command lists the secrets currently stored in a given Key Vault (names only, not values)?","explanation":"az keyvault secret list enumerates the secrets (names, IDs, metadata) within a specified vault. az keyvault secret show requires a specific secret name and returns one secret's details, az keyvault list lists vault resources themselves (not their contained secrets), and az keyvault secret backup exports a specific secret's backup blob rather than listing all secrets.\n\n```bash\naz keyvault secret list --vault-name myVault\n```","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/key-vault/general/overview","topic":"key-vault","type":"single","options":["az keyvault secret list --vault-name myVault","az keyvault secret show --vault-name myVault","az keyvault list --resource-group myRG now","az keyvault secret backup --vault-name myVault"],"answer":0,"setId":"suralmk:secure-monitor-160","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/secure-monitor-160.json","reviewDate":"2026-10-11"},{"id":"suralmk:sec-113","prompt":"You need a notification when server-side exception counts exceed a configured operational threshold. What should you configure?","explanation":"Use a supported metric or log alert rule with a threshold and an action group. Automatic anomaly detection is a separate capability such as supported dynamic thresholds or Smart Detection; a static threshold alone is not an anomaly model.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/azure-monitor/alerts/alerts-overview","topic":"opentelemetry","type":"single","options":["Monitor alert rule with threshold and action group","Manually refreshed Workbook checked once per day","Static dashboard tile with no alert evaluation","Sampling raised to 100% without any alert rule"],"answer":0,"setId":"suralmk:secure-monitor-160","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/secure-monitor-160.json","reviewDate":"2026-10-11","reviewNote":"A fixed threshold is not automatic anomaly detection."},{"id":"suralmk:sec-114","prompt":"You must ensure that diagnostic logs from AKS, Container Apps, Service Bus, and Key Vault are all centrally queryable together for a security investigation spanning multiple services. What should you configure?","explanation":"Configuring diagnostic settings on every relevant resource to send logs to the same Log Analytics workspace enables unified cross-resource KQL queries, which is essential for correlated security investigations. Routing to separate storage accounts per resource fragments the data and complicates correlation, enabling logging on only one resource leaves blind spots across the rest of the pipeline, and relying on short built-in retention without export risks losing data needed for the investigation.","domain":"operations","source":"https://learn.microsoft.com/en-us/kusto/query/","topic":"kql","type":"single","options":["Diagnostic settings on each resource to one workspace","Separate storage accounts with no shared query surface","Key Vault logging only, skipping other pipeline logs","Built-in 7-day retention only with no log export"],"answer":0,"setId":"suralmk:secure-monitor-160","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/secure-monitor-160.json","reviewDate":"2026-10-11"},{"id":"suralmk:sec-115","prompt":"Which KQL operator would you use to calculate the 95th percentile response time for AI API requests over the last 24 hours, grouped by operation name?","explanation":"The percentile() aggregation function within summarize computes the specified percentile (95th here) of a numeric column, grouped by the given dimension — exactly what's needed for P95 latency analysis. avg() only computes the mean (not a percentile), project merely selects columns without aggregation, and filtering 'where duration > 95' treats 95 as a literal duration threshold rather than computing a percentile.","domain":"operations","source":"https://learn.microsoft.com/en-us/kusto/query/","topic":"kql","type":"single","options":["summarize percentile(duration, 95) by operation_Name","summarize avg(duration) by operation_Name only","project duration, operation_Name without summarize","where duration > 95 treating 95 as a hard threshold"],"answer":0,"setId":"suralmk:secure-monitor-160","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/secure-monitor-160.json","reviewDate":"2026-10-11"},{"id":"suralmk:sec-116","prompt":"An AI application uses Managed Identity to access Key Vault, but calls started failing after a recent Key Vault firewall change with a 403 error, even though the RBAC role assignment is correct. What is the most likely cause?","explanation":"A 403 despite correct RBAC strongly suggests a network-layer block: Key Vault firewall rules restrict access by IP/VNet, and unless the calling resource's identity is covered by an allowed virtual network, private endpoint, or the 'trusted Microsoft services' exception, requests are rejected at the network layer before RBAC is even evaluated in some configurations. Managed identity client IDs don't change automatically, RBAC role assignments don't expire every 24 hours, and Key Vault fully supports managed identity authentication — this isn't a service limitation.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/key-vault/general/overview","topic":"key-vault","type":"single","options":["Firewall blocks caller IP/VNet despite correct RBAC","Managed identity client ID rotated overnight alone","RBAC assignments expire every 24 hours by design","Key Vault dropped support for managed identity auth"],"answer":0,"setId":"suralmk:secure-monitor-160","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/secure-monitor-160.json","reviewDate":"2026-10-11"},{"id":"suralmk:sec-117","prompt":"Which OpenTelemetry component is responsible for exporting collected spans/traces from your application to a backend such as Azure Monitor?","explanation":"An exporter is the OpenTelemetry component responsible for sending collected telemetry (traces, metrics, logs) to a specific backend — here, the Azure Monitor Exporter sends data to Application Insights/Log Analytics. A sampler decides which traces are recorded (not where they're sent), a meter provider without a configured exporter has nowhere to send metrics, and console-only logging doesn't route data to Azure Monitor at all.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/azure-monitor/app/opentelemetry-overview","topic":"opentelemetry","type":"single","options":["Exporter such as Azure Monitor OpenTelemetry Exporter","Sampler fixed at ratio zero so nothing is recorded","Meter provider with no exporter wired for metrics","Logger writing console output only, not to Azure"],"answer":0,"setId":"suralmk:secure-monitor-160","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/secure-monitor-160.json","reviewDate":"2026-10-11"},{"id":"suralmk:sec-118","prompt":"What Azure Key Vault object type would you use to store an X.509 certificate along with its private key for use in TLS termination?","explanation":"Key Vault certificates are a first-class object type that stores the full certificate (including private key), manages its lifecycle, and can auto-create a corresponding secret/key — purpose-built for TLS scenarios. A plain secret storing only the public key omits the private key needed for TLS termination, a bare RSA key object without certificate metadata isn't a complete certificate, and App Configuration is not designed to securely store private key material.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/azure-app-configuration/overview","topic":"app-configuration","type":"single","options":["Certificate object storing cert and private key","Secret object holding only the public key material","RSA key object without certificate metadata fields","App Configuration pair storing private key material"],"answer":0,"setId":"suralmk:secure-monitor-160","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/secure-monitor-160.json","reviewDate":"2026-10-11"},{"id":"suralmk:sec-119","prompt":"You want distributed tracing enabled for a Python Azure Function calling Azure OpenAI and Cosmos DB, using open standards rather than a vendor-specific SDK. Which library should you use?","explanation":"The OpenTelemetry Python SDK (paired with the Azure Monitor OpenTelemetry Distro for exporting to Azure) provides open-standard, vendor-neutral distributed tracing that instruments common libraries automatically, which is the current Microsoft-recommended approach for Python. The legacy Application Insights SDK is being superseded by OpenTelemetry-based instrumentation, print()-based logging provides no structured trace correlation, and meaningful tracing always requires at least some SDK/library integration, not zero configuration.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/azure-monitor/app/opentelemetry-overview","topic":"opentelemetry","type":"single","options":["OpenTelemetry Python SDK with Azure Monitor Distro","Legacy App Insights SDK only, without OpenTelemetry","Custom print()-based logging without trace context","No library; assume tracing needs zero configuration"],"answer":0,"setId":"suralmk:secure-monitor-160","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/secure-monitor-160.json","reviewDate":"2026-10-11"},{"id":"suralmk:sec-120","prompt":"Your organization requires that Key Vault secrets are never permanently deleted immediately, giving a recovery window in case of accidental or malicious deletion. What Key Vault feature must be enabled?","explanation":"Soft-delete retains deleted secrets/keys/certificates for a recovery window (default 90 days), and purge protection additionally prevents anyone — including privileged admins — from permanently purging them before that window expires, directly satisfying the recovery requirement. Geo-replication addresses regional availability (not deletion protection), manually exporting to a spreadsheet is an insecure, unmanaged workaround, and disabling versioning has nothing to do with deletion recovery and would reduce operational safety.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/key-vault/general/overview","topic":"key-vault","type":"single","options":["Soft-delete with purge protection enabled on vault","Geo-replication configured for regional availability","Daily spreadsheet export of every secret value","Versioning disabled on all secrets in the vault"],"answer":0,"setId":"suralmk:secure-monitor-160","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/secure-monitor-160.json","reviewDate":"2026-10-11"},{"id":"suralmk:sec-121","prompt":"Which KQL command structure would you use to join telemetry from AppRequests with AppDependencies to see which downstream calls were made during slow requests?","explanation":"Workspace tables use DurationMs and OperationId with those exact names. Application Insights table names such as requests use duration and operation_Id instead. OperationId correlates the overall trace; ParentId/Id can narrow exact parent-child relationships.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/azure-monitor/reference/tables/apprequests","topic":"kql","type":"single","options":["AppRequests | where DurationMs > 1000 | join kind=inner AppDependencies on OperationId","AppRequests | union AppDependencies | project name, duration, operation_Id, timestamp","AppRequests | distinct operation_Id | project operation_Id without dependency rows","AppDependencies | summarize count() by type | order by count_ desc"],"answer":0,"setId":"suralmk:secure-monitor-160","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/secure-monitor-160.json","reviewDate":"2026-10-11","reviewNote":"Corrected Log Analytics workspace table column names."},{"id":"suralmk:sec-122","prompt":"An incident review shows that a security breach occurred because a developer's personal Azure CLI credentials (with broad permissions) were used to deploy a production AI service, and those credentials were later compromised. What combination of changes best prevents recurrence?","explanation":"Replacing personal, broadly-privileged credentials with federated workload identities (OIDC-based, short-lived, pipeline-scoped) for CI/CD, combined with least-privilege role assignments and managed identities for runtime access, eliminates the standing long-lived credential risk that caused the breach. Simply changing a password leaves the same broad-permission pattern in place, granting broad access to everyone multiplies the risk rather than reducing it, and storing credentials in a spreadsheet is a severe security anti-pattern.","domain":"operations","source":"https://learn.microsoft.com/en-us/cli/azure/reference-index","topic":"azure-cli","type":"single","options":["OIDC CI/CD identities, least privilege, runtime MIs","Password change while keeping personal deploy creds","Broad permissions granted to every developer equally","Developer credentials stored in a shared spreadsheet"],"answer":0,"setId":"suralmk:secure-monitor-160","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/secure-monitor-160.json","reviewDate":"2026-10-11"},{"id":"suralmk:sec-123","prompt":"Which Azure Monitor concept determines what percentage of telemetry (traces, requests) Application Insights actually collects and stores, to control cost on high-volume AI APIs?","explanation":"Sampling (fixed-rate or adaptive) controls what fraction of telemetry events are actually recorded and billed, letting high-volume applications control Application Insights cost while retaining statistically representative data. Partitioning is a data-distribution concept in databases, geo-replication addresses regional redundancy, and soft-delete is a Key Vault/storage recovery feature — none control telemetry volume/cost.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/key-vault/general/overview","topic":"key-vault","type":"single","options":["Telemetry sampling","Data partitioning","Geo-replication","Soft-delete policy"],"answer":0,"setId":"suralmk:secure-monitor-160","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/secure-monitor-160.json","reviewDate":"2026-10-11"},{"id":"suralmk:sec-124","prompt":"Your AI application logs show a spike in throttling errors (429) from Azure OpenAI. What is the recommended first mitigation?","explanation":"429 responses indicate rate limiting; the standard mitigation is implementing exponential backoff (often built into the SDK's retry policy) to smooth bursty traffic, combined with reviewing actual usage against provisioned quota and requesting an increase if sustained demand exceeds it. Switching providers is a drastic, unnecessary step before trying standard retry/quota remediation, ignoring the errors leaves the reliability problem unresolved, and disabling logging hides symptoms without fixing the underlying throttling.","domain":"operations","source":"https://learn.microsoft.com/en-us/cli/azure/reference-index","topic":"azure-cli","type":"single","options":["Exponential backoff retries; review or raise TPM/RPM","Switch providers immediately with no retry added","Ignore 429s assuming they clear without code changes","Disable logging so throttling errors stop appearing"],"answer":0,"setId":"suralmk:secure-monitor-160","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/secure-monitor-160.json","reviewDate":"2026-10-11"},{"id":"suralmk:sec-001","prompt":"You are using an OpenTelemetry Python SDK setup to monitor a distributed AI pipeline. Which component is responsible for extracting and injecting context (like trace parent IDs) across service boundaries?","explanation":"In OpenTelemetry, **Propagators** serialize and deserialize cross-cutting context (such as `traceparent` headers) across HTTP and messaging boundaries.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/azure-monitor/app/opentelemetry-overview","topic":"opentelemetry","type":"single","options":["Context propagators","Telemetry exporters","Span batch processors","Probability samplers"],"answer":0,"setId":"suralmk:secure-monitor","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/secure-monitor.json","reviewDate":"2026-10-11"},{"id":"suralmk:sec-002","prompt":"In the Application Insights query schema, how do you calculate incoming request duration p95 in five-minute bins?","explanation":"Use requests for incoming server requests and dependencies for outgoing calls. In workspace schema, use AppRequests, DurationMs and TimeGenerated instead.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/azure-monitor/reference/tables/apprequests","topic":"kql","type":"single","options":["requests | summarize p95=percentile(duration, 95) by bin(timestamp, 5m)","dependencies | summarize percentile_95(duration) by bin(timestamp, 5m)","dependencies | summarize avg(duration), p95() by bin(timestamp, 5m)","dependencies | summarize percentiles(duration, 0.95) by bin(timestamp, 5m)"],"answer":0,"setId":"suralmk:secure-monitor","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/secure-monitor.json","reviewDate":"2026-10-11","reviewNote":"Matched request latency to the requests telemetry table."},{"id":"suralmk:sec-003","prompt":"Which Azure event-routing service delivers Key Vault SecretNearExpiry events to a rotation handler?","explanation":"Key Vault publishes lifecycle events and Event Grid routes them. A Function or other handler can rotate a secret and its backing credential.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/key-vault/general/event-grid-overview","topic":"key-vault","type":"single","options":["Azure Event Grid","Azure Event Hubs","Azure Service Bus","Azure Logic Apps"],"answer":0,"setId":"suralmk:secure-monitor","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/secure-monitor.json","reviewDate":"2026-10-11","reviewNote":"Key Vault emits the lifecycle events; Event Grid routes them."},{"id":"suralmk:sec-004","prompt":"To secure a vector database in Azure Database for PostgreSQL, you want to ensure that traffic between your backend service in an Azure VNet and the database does not traverse the public internet. Which feature should you use?","explanation":"**Private Link / Private Endpoint** places a private IP for PostgreSQL in your VNet so traffic stays on the Azure backbone instead of the public internet.","domain":"operations","source":"https://github.com/pgvector/pgvector","topic":"postgresql-pgvector","type":"single","options":["Private Link / Private Endpoint","Service Endpoint with VNet rules","NSG allow rules on public PaaS IP","Azure Firewall DNAT to public DB"],"answer":0,"setId":"suralmk:secure-monitor","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/secure-monitor.json","reviewDate":"2026-10-11"},{"id":"suralmk:sec-005","prompt":"You are setting up an OpenTelemetry Python script to send distributed traces to Azure Monitor Application Insights. Which package provides the standard exporter connection for Azure Monitor?","explanation":"The official exporter package is **azure-monitor-opentelemetry-exporter** (also commonly used via the `azure-monitor-opentelemetry` distribution).","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/azure-monitor/app/opentelemetry-overview","topic":"opentelemetry","type":"single","options":["azure-monitor-opentelemetry-exporter","opentelemetry-exporter-azure-monitor","azure-opentelemetry-monitor-exporter","applicationinsights-otel-exporter"],"answer":0,"setId":"suralmk:secure-monitor","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/secure-monitor.json","reviewDate":"2026-10-11"},{"id":"suralmk:sec-006","prompt":"You are deploying an AI backend to Azure App Service. You want the app to retrieve a secret from Key Vault automatically using the app's System-Assigned Identity. What must be configured?","explanation":"Enable the app’s **Managed Identity**, grant it Key Vault access (for example Key Vault Secrets User), and use Key Vault reference syntax (`@Microsoft.KeyVault(...)`) in Application Settings.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/key-vault/general/overview","topic":"key-vault","type":"single","options":["Managed Identity, Key Vault RBAC, and Key Vault references","Connection string secret stored only in local.settings.json","Shared access signature embedded in the application code","App Service publish profile credentials for vault access"],"answer":0,"setId":"suralmk:secure-monitor","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/secure-monitor.json","reviewDate":"2026-10-11"},{"id":"suralmk:sec-007","prompt":"In a KQL query, you want to correlate entry requests with downstream database dependency calls in Application Insights. Which column is standard for linking operation contexts across telemetry tables?","explanation":"**operation_Id** is the shared correlation ID across Application Insights tables (`requests`, `dependencies`, `traces`, `exceptions`) for one end-to-end operation.","domain":"operations","source":"https://learn.microsoft.com/en-us/kusto/query/","topic":"kql","type":"single","options":["operation_Id field","client_IP address","session_Id value","cloud_RoleName tag"],"answer":0,"setId":"suralmk:secure-monitor","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/secure-monitor.json","reviewDate":"2026-10-11"},{"id":"suralmk:sec-008","prompt":"In OpenTelemetry, you want to add custom key-value metadata (such as the specific LLM model version used) to an active trace span. Which method should you use?","explanation":"OpenTelemetry spans store custom metadata as attributes via **`span.set_attribute(key, value)`**.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/azure-monitor/app/opentelemetry-overview","topic":"opentelemetry","type":"single","options":["span.set_attribute(\"model_version\", \"v2.5\")","span.put_attribute(\"model_version\", \"v2.5\")","span.add_metadata(\"model_version\", \"v2.5\")","span.append_tags(\"model_version\", \"v2.5\")"],"answer":0,"setId":"suralmk:secure-monitor","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/secure-monitor.json","reviewDate":"2026-10-11"},{"id":"suralmk:sec-009","prompt":"In a distributed AI trace, which standard HTTP header key is used by OpenTelemetry W3C Trace Context specification to propagate context between services?","explanation":"W3C Trace Context uses the **`traceparent`** HTTP header (trace ID, parent span ID, and flags) to propagate context across services.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/azure-monitor/app/opentelemetry-overview","topic":"opentelemetry","type":"single","options":["traceparent","tracestate","x-request-id","x-ms-request"],"answer":0,"setId":"suralmk:secure-monitor","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/secure-monitor.json","reviewDate":"2026-10-11"},{"id":"suralmk:sec-010","prompt":"You are using Azure App Configuration in Python. You want your application to automatically reload configuration changes when a designated key changes without restarting the container. What capability is this?","explanation":"Configure refresh_on (for example a sentinel key), a refresh interval, and call provider.refresh() from the application. The Python provider does not autonomously run a background watcher. Update the sentinel after the related key values.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/azure-app-configuration/enable-dynamic-configuration-python","topic":"app-configuration","type":"single","options":["Dynamic configuration refresh","Event Grid configuration push","Key Vault-linked config reload","Snapshot-based config syncing"],"answer":0,"setId":"suralmk:secure-monitor","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/secure-monitor.json","reviewDate":"2026-10-11","reviewNote":"Python refresh must be driven by the application."},{"id":"suralmk:sec-011","prompt":"An AI application generates telemetry in Azure Monitor. You want to use KQL to count the number of unique user IDs that queried the service in the last 24 hours. Which aggregation function should you use?","explanation":"In KQL, **`dcount()`** estimates the distinct count of values. `count()` counts rows, not unique users.\n\n```kusto\nrequests\n| where timestamp > ago(24h)\n| summarize UniqueUsers = dcount(user_Id)\n```","domain":"operations","source":"https://learn.microsoft.com/en-us/kusto/query/","topic":"kql","type":"single","options":["summarize dcount(user_Id)","summarize count(user_Id)","summarize sum(user_Id)","summarize make_set(user_Id)"],"answer":0,"setId":"suralmk:secure-monitor","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/secure-monitor.json","reviewDate":"2026-10-11"},{"id":"suralmk:sec-012","prompt":"You are configuring Azure Key Vault to ensure that deleted vaults or secrets can be recovered within a retention window and cannot be permanently destroyed immediately by unauthorized actors. Which features must be enabled?","explanation":"**Soft Delete** retains deleted vaults/secrets for a retention period (default 90 days). **Purge Protection** blocks permanent deletion until that retention period ends.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/key-vault/general/overview","topic":"key-vault","type":"single","options":["Soft delete with purge protection","Firewall rules and private endpoints","Vault RBAC plus access policy model","Automatic rotation with versioning"],"answer":0,"setId":"suralmk:secure-monitor","practiceSource":"https://github.com/Suralmk/learn-AI-200/blob/93386cbe02a3e4b669f8005657e2e123066506cd/content/questions/secure-monitor.json","reviewDate":"2026-10-11"},{"id":"bouvet:acr-001","prompt":"What is Azure Container Registry (ACR)?","explanation":"ACR is a private, managed Docker/OCI registry hosted in Azure — your own private Docker Hub for storing and distributing container images. Running containers is AKS/Container Apps/ACI; secrets belong in Key Vault.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/container-registry/container-registry-intro","topic":"acr","type":"single","options":["A managed Kubernetes cluster for running containers","A private, managed Docker/OCI registry for storing container images in Azure","A CI/CD pipeline service for building source code","A service for storing application secrets and certificates"],"answer":1,"setId":"bouvet:acr","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/acr.json","reviewDate":"2026-10-11"},{"id":"bouvet:acr-002","prompt":"The registry loginServer property is ai200acr.azurecr.io. Repository web-api contains tag v1.0. What is the fully qualified image reference?","explanation":"Combine the actual login server, repository and tag: ai200acr.azurecr.io/web-api:v1.0. Some registries have a hashed DNS label, so query loginServer instead of constructing it from the resource name.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/container-registry/container-registry-get-started-portal","topic":"acr","type":"single","options":["ai200acr.azure.com/web-api/v1.0","ai200acr.azurecr.io/web-api:v1.0","web-api.ai200acr.azurecr.io:v1.0","azurecr.io/ai200acr/web-api:v1.0"],"answer":1,"setId":"bouvet:acr","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/acr.json","reviewDate":"2026-10-11","reviewNote":"Made the exact login server an explicit premise."},{"id":"bouvet:acr-003","prompt":"How are objects nested inside Azure Container Registry?","explanation":"A registry contains many repositories; each repository contains many image versions identified by a mutable tag or an immutable digest. Registry → repositories → images.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/container-registry/container-registry-intro","topic":"acr","type":"single","options":["Registry → images → repositories","Repository → registry → images","Registry → repositories → images (by tag or digest)","Image → registry → tag"],"answer":2,"setId":"bouvet:acr","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/acr.json","reviewDate":"2026-10-11"},{"id":"bouvet:acr-004","prompt":"What is the key advantage of `az acr build` (ACR Tasks) over `docker build`?","explanation":"`az acr build` runs the build on ACR's cloud builders — no local Docker required — and it both builds AND pushes the image in a single command, streaming the log back to you.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/container-registry/container-registry-intro","topic":"acr","type":"single","options":["It builds the image in the cloud, so you don't need a local Docker daemon","It produces smaller images automatically","It only works with Windows containers","It skips pushing the image to save time"],"answer":0,"setId":"bouvet:acr","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/acr.json","reviewDate":"2026-10-11"},{"id":"bouvet:acr-005","prompt":"Running `az acr build --registry myacr --image web-api:v1 .` is equivalent to which pair of local commands?","explanation":"`az acr build` builds the Dockerfile AND pushes the resulting image, so it replaces both `docker build` and `docker push` — and runs them in ACR's cloud instead of on your machine.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/container-registry/container-registry-intro","topic":"acr","type":"single","options":["docker pull + docker run","docker build + docker push","docker login + docker tag","docker save + docker load"],"answer":1,"setId":"bouvet:acr","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/acr.json","reviewDate":"2026-10-11"},{"id":"bouvet:acr-006","prompt":"Which events can automatically trigger an ACR Task to rebuild an image? (Select all that apply)","explanation":"ACR Tasks support three automatic triggers: source-code commit, base-image update (so your image gets rebuilt when its base is patched), and a schedule. A portal sign-in is not a trigger.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/container-registry/container-registry-intro","topic":"acr","type":"multi","options":["A commit to the linked source-code repository","An update to the base image referenced in the Dockerfile's FROM","A defined schedule (timer)","A user signing in to the Azure portal"],"answer":[0,1,2],"choose":3,"setId":"bouvet:acr","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/acr.json","reviewDate":"2026-10-11"},{"id":"bouvet:acr-007","prompt":"A running App Service needs to pull images from an ACR configured for RBAC Registry Permissions (not ABAC repository permissions). Which least-privilege data-plane role should its managed identity have?","explanation":"For an RBAC-only registry, AcrPull grants registry-wide read/pull access. An ABAC-enabled registry instead uses Container Registry Repository Reader, which can be scoped to repositories.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/container-registry/container-registry-intro","topic":"acr","type":"single","options":["AcrPush","AcrPull","Contributor","AcrDelete"],"answer":1,"setId":"bouvet:acr","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/acr.json","reviewDate":"2026-10-11"},{"id":"bouvet:acr-008","prompt":"A CI/CD pipeline needs to push images into an ACR configured for RBAC Registry Permissions. Which data-plane role does it require?","explanation":"For an RBAC-only registry, AcrPush grants pull and push (read/write). An ABAC-enabled registry uses Container Registry Repository Writer instead.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/container-registry/container-registry-intro","topic":"acr","type":"single","options":["AcrPull","AcrPush","Reader","AcrDelete"],"answer":1,"setId":"bouvet:acr","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/acr.json","reviewDate":"2026-10-11"},{"id":"bouvet:acr-009","prompt":"Which statement about the ACR admin account is correct?","explanation":"The admin account is a single shared username/password that is DISABLED by default and meant for testing/quick demos only. Production should use Entra ID / managed identity.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/container-registry/container-registry-intro","topic":"acr","type":"single","options":["It is enabled by default and recommended for production","It is disabled by default and intended for testing only","It provides per-repository scoped credentials","It is the only way to authenticate to ACR"],"answer":1,"setId":"bouvet:acr","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/acr.json","reviewDate":"2026-10-11"},{"id":"bouvet:acr-010","prompt":"For an ACR configured for RBAC Registry Permissions, what does `az aks update --name \u003ccluster> --resource-group \u003crg> --attach-acr \u003cregistry>` do?","explanation":"For an RBAC-only registry, `--attach-acr` assigns AcrPull to the AKS kubelet managed identity, so nodes can pull without imagePullSecrets. The shortcut is unsupported for ABAC-enabled registries; assign Container Registry Repository Reader manually there.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/aks/cluster-container-registry-integration","topic":"acr","type":"single","options":["Copies all images from the registry into the AKS nodes","Grants the AKS kubelet managed identity the AcrPull role on the registry","Enables the ACR admin account for the cluster","Creates image pull secrets in every namespace"],"answer":1,"setId":"bouvet:acr","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/acr.json","reviewDate":"2026-10-11","reviewNote":"Identified the kubelet identity rather than the control-plane identity."},{"id":"bouvet:acr-011","prompt":"Which statement about tags versus digests is correct?","explanation":"A tag is a mutable label — re-pushing the same tag moves it to a new image. A digest (`sha256:...`) is a content hash and is immutable, so it always refers to the exact same image content.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/container-registry/container-registry-intro","topic":"acr","type":"single","options":["Both tags and digests are immutable","Tags are mutable and can be re-pointed to a new image; a digest always identifies the exact same bytes","Digests are mutable; tags never change","Neither can be used to pull an image"],"answer":1,"setId":"bouvet:acr","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/acr.json","reviewDate":"2026-10-11"},{"id":"bouvet:acr-012","prompt":"For a production deployment that must be perfectly reproducible, how should you reference an image?","explanation":"Digests are immutable, so pinning `\u003crepo>@sha256:...` guarantees the exact same image every time. Avoid `latest` in production because a tag can silently move to a different image.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/container-registry/container-registry-intro","topic":"acr","type":"single","options":["Always use the `latest` tag","Pin the image by its digest (`@sha256:...`)","Use a randomly generated tag each deploy","Reference the repository name with no tag"],"answer":1,"setId":"bouvet:acr","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/acr.json","reviewDate":"2026-10-11"},{"id":"bouvet:acr-013","prompt":"You want to enable anonymous (unauthenticated) pull on a registry. Which minimum SKU is required?","explanation":"Anonymous pull requires at least the Standard tier (also available on Premium). It is NOT available on Basic. Pushing still requires authentication.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/container-registry/container-registry-intro","topic":"acr","type":"single","options":["Basic","Standard","Premium","Any SKU supports it"],"answer":1,"setId":"bouvet:acr","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/acr.json","reviewDate":"2026-10-11"},{"id":"bouvet:acr-014","prompt":"Which features are available ONLY on the Premium SKU of ACR? (Select all that apply)","explanation":"Geo-replication and Private Link/private endpoints require Premium. Repository-scoped permissions, including non-Entra tokens and scope maps, are available in all tiers (with different limits), and Entra data-plane roles are available in all tiers.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/container-registry/container-registry-intro","topic":"acr","type":"multi","options":["Geo-replication across regions","Private Link / private endpoints","Repository-scoped tokens and scope maps","Pushing and pulling images with Entra ID RBAC"],"answer":[0,1],"choose":2,"setId":"bouvet:acr","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/acr.json","reviewDate":"2026-10-11"},{"id":"bouvet:acr-015","prompt":"You must serve container images from a single registry with low latency to users in three regions. Which ACR capability do you use, and which SKU is required?","explanation":"Geo-replication puts replicas of one registry in multiple regions for low-latency pulls and resilience. It is a Premium-only feature.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/container-registry/container-registry-intro","topic":"acr","type":"single","options":["Anonymous pull, on Standard","Geo-replication, on Premium","Webhooks, on Basic","Scope maps, on Standard"],"answer":1,"setId":"bouvet:acr","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/acr.json","reviewDate":"2026-10-11"},{"id":"bouvet:acr-016","prompt":"You need to grant a partner access to pull from ONE repository only, without creating an Entra ID identity for them. Which ACR feature fits?","explanation":"Repository-scoped tokens tied to a scope map grant granular per-repository permissions with a standalone credential and no Entra identity. They are available in all ACR tiers; tier limits differ.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/container-registry/container-registry-intro","topic":"acr","type":"single","options":["The admin account","Repository-scoped tokens with scope maps","AcrPull assigned at the subscription scope","Anonymous pull"],"answer":1,"setId":"bouvet:acr","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/acr.json","reviewDate":"2026-10-11"},{"id":"bouvet:acr-017","prompt":"A security requirement says the registry must not be reachable over the public internet and must use a private endpoint inside your VNet. Which SKU supports this?","explanation":"Private Link / private endpoints for ACR require the Premium tier.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/container-registry/container-registry-intro","topic":"acr","type":"single","options":["Basic","Standard","Premium","It is not possible with ACR"],"answer":2,"setId":"bouvet:acr","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/acr.json","reviewDate":"2026-10-11"},{"id":"bouvet:acr-018","prompt":"You are designing a new ACR image-signing workflow in 2026. Which approach should you choose?","explanation":"Microsoft recommends Notary Project/Notation for new signing and verification workflows. ACR's Docker Content Trust feature has been deprecated since March 2025 and retires on 31 March 2028.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/container-registry/container-registry-intro","topic":"acr","type":"single","options":["Use Notary Project with the Notation CLI and store signatures as OCI artifacts","Enable Docker Content Trust because it has no retirement date","Enable anonymous pull so clients can infer image integrity","Use the ACR admin account to sign each image"],"answer":0,"setId":"bouvet:acr","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/acr.json","reviewDate":"2026-10-11"},{"id":"bouvet:acr-019","prompt":"What does `az acr login --name myacr` do?","explanation":"az acr login uses your Azure sign-in to authenticate Docker. The Docker credential configuration/store can retain the registry token; no long-lived registry admin password is needed. The command does not grant roles.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/container-registry/container-registry-authentication","topic":"acr","type":"single","options":["Enables the admin account on the registry","Authenticates the local Docker client using an Entra-based registry token","Creates a new registry named myacr","Assigns you the AcrPull role"],"answer":1,"setId":"bouvet:acr","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/acr.json","reviewDate":"2026-10-11","reviewNote":"Docker can persist the temporary token in its configured credential store."},{"id":"bouvet:acr-020","prompt":"Which data-plane role grants registry-wide artifact deletion in an ACR configured for RBAC Registry Permissions?","explanation":"For an RBAC-only registry, AcrDelete grants artifact/tag deletion without granting deletion of the registry resource. An ABAC-enabled registry uses Container Registry Repository Contributor for repository content deletion.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/container-registry/container-registry-intro","topic":"acr","type":"single","options":["AcrPull","AcrPush","AcrDelete","Reader"],"answer":2,"setId":"bouvet:acr","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/acr.json","reviewDate":"2026-10-11"},{"id":"bouvet:acr-021","prompt":"Which are valid ways to authenticate to an Azure Container Registry? (Select all that apply)","explanation":"You authenticate with Entra ID (via `az acr login`, or a managed identity granted AcrPull/AcrPush) or, for testing, the admin account. A Key Vault reference is an App Configuration concept, not an ACR authentication method.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/container-registry/container-registry-intro","topic":"acr","type":"multi","options":["Entra ID with `az acr login` (token-based)","A service's managed identity granted AcrPull","The admin account (username/password), if enabled","A Key Vault reference"],"answer":[0,1,2],"choose":3,"setId":"bouvet:acr","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/acr.json","reviewDate":"2026-10-11"},{"id":"bouvet:acr-022","prompt":"Which command copies an image from Docker Hub straight into your registry without a local docker pull/push?","explanation":"`az acr import` copies an image from another registry (e.g. Docker Hub) directly into your ACR — great for mirroring public base images — with no local Docker involved.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/container-registry/container-registry-intro","topic":"acr","type":"single","options":["az acr build","az acr import","az acr login","az acr repository delete"],"answer":1,"setId":"bouvet:acr","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/acr.json","reviewDate":"2026-10-11"},{"id":"bouvet:acr-023","prompt":"Put these Azure CLI steps in order to create a registry and build+push an image into it using ACR Tasks:","explanation":"Correct order: 1) create the resource group, 2) create the registry inside it, 3) build+push the image with ACR Tasks (no local Docker), 4) list the repositories to confirm it landed.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/container-registry/container-registry-intro","topic":"acr","type":"order","options":["az group create --name \u003crg> --location westeurope","az acr create --name \u003cregistry> --resource-group \u003crg> --sku Basic","az acr build --registry \u003cregistry> --image web-api:v1.0 .","az acr repository list --name \u003cregistry>"],"answer":["az group create --name \u003crg> --location westeurope","az acr create --name \u003cregistry> --resource-group \u003crg> --sku Basic","az acr build --registry \u003cregistry> --image web-api:v1.0 .","az acr repository list --name \u003cregistry>"],"setId":"bouvet:acr","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/acr.json","reviewDate":"2026-10-11"},{"id":"bouvet:acr-024","prompt":"Order these Python steps to list a registry's repositories with the azure-containerregistry SDK:","explanation":"Correct order: 1) build the credential (passwordless Entra ID), 2) create the ContainerRegistryClient with the endpoint + credential, 3) loop over repository names, 4) for each repository loop over its tag properties.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/container-registry/container-registry-intro","topic":"acr","type":"order","options":["credential = DefaultAzureCredential()","client = ContainerRegistryClient(endpoint, credential)","for repository in client.list_repository_names():","for tag in client.list_tag_properties(repository):"],"answer":["credential = DefaultAzureCredential()","client = ContainerRegistryClient(endpoint, credential)","for repository in client.list_repository_names():","for tag in client.list_tag_properties(repository):"],"setId":"bouvet:acr","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/acr.json","reviewDate":"2026-10-11"},{"id":"bouvet:acr-025","prompt":"An ABAC-enabled registry must let a workload pull images only from repositories whose names start with `production/`. Which role should you assign with an ABAC repository-name condition?","explanation":"Container Registry Repository Reader is the pull/read role for an ABAC-enabled registry and supports repository-name conditions. AcrPull is a legacy RBAC-only role; Writer over-grants push access; the configuration administrator role is control-plane access.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/container-registry/container-registry-intro","topic":"acr","type":"single","options":["AcrPull","Container Registry Repository Reader","Container Registry Repository Writer","Container Registry Contributor and Data Access Configuration Administrator"],"answer":1,"setId":"bouvet:acr","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/acr.json","reviewDate":"2026-10-11"},{"id":"bouvet:acr-026","prompt":"A script must both list the repository catalog and pull images from every repository in an ABAC-enabled ACR. Which roles are required? (Select all that apply)","explanation":"Repository Reader grants read/pull access but deliberately omits catalog enumeration. Catalog Lister adds the ability to list repository names. Neither delete nor Azure resource ownership is needed.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/container-registry/container-registry-intro","topic":"acr","type":"multi","options":["Container Registry Repository Reader","Container Registry Repository Catalog Lister","AcrDelete","Owner"],"answer":[0,1],"choose":2,"setId":"bouvet:acr","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/acr.json","reviewDate":"2026-10-11"},{"id":"bouvet:acr-027","prompt":"Which statement about ACR availability-zone support is current?","explanation":"All three ACR tiers support availability zones in supported regions. Geo-replication and private endpoints remain Premium-only, which is why older SKU summaries can be misleading.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/container-registry/container-registry-intro","topic":"acr","type":"single","options":["It is Premium-only","It is supported by Basic, Standard, and Premium in supported regions","It requires geo-replication","It is available only for anonymous registries"],"answer":1,"setId":"bouvet:acr","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/acr.json","reviewDate":"2026-10-11"},{"id":"bouvet:acr-028","prompt":"A Standard registry contains one public repository and one confidential repository. Can you safely enable anonymous pull for only the public repository?","explanation":"Anonymous pull is a registry-wide switch, not a per-repository permission. Put confidential and public content in separate registries if the public one must allow unauthenticated pulls.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/container-registry/container-registry-intro","topic":"acr","type":"single","options":["Yes, by adding an anonymous scope map to that repository","Yes, by assigning AcrPull to the anonymous identity","No; enabling anonymous pull makes all repositories in that registry publicly pullable","No; anonymous pull is available only on Premium"],"answer":2,"setId":"bouvet:acr","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/acr.json","reviewDate":"2026-10-11"},{"id":"bouvet:acr-029","prompt":"Why should deployment automation query `az acr show --query loginServer` instead of always constructing `\u003cregistry-name>.azurecr.io`?","explanation":"A registry configured with a DNS name label scope can have a login server such as `\u003cname>-\u003chash>.azurecr.io`. Querying `loginServer` gives the authoritative hostname in both scoped and default configurations.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/container-registry/container-registry-intro","topic":"acr","type":"single","options":["The login server changes after every image push","A DNS name label scope can add a stable hash to the login server","Premium registries use the `.azure.com` suffix","Repository names replace the registry name in the hostname"],"answer":1,"setId":"bouvet:acr","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/acr.json","reviewDate":"2026-10-11"},{"id":"bouvet:acr-030","prompt":"Which ACR policy lets you restore an accidentally deleted image artifact during a configured recovery window?","explanation":"Artifact soft delete (preview) retains deleted artifacts for recovery. The untagged-manifest retention policy does the opposite: it schedules untagged Docker manifests for deletion and is not a recovery feature.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/container-registry/container-registry-intro","topic":"acr","type":"single","options":["The untagged-manifest retention policy","Artifact soft delete (preview)","Repository locking","Geo-replication"],"answer":1,"setId":"bouvet:acr","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/acr.json","reviewDate":"2026-10-11"},{"id":"bouvet:aks-001","prompt":"Which statement correctly describes AKS control-plane management pricing?","explanation":"AKS always operates the control plane, and you still pay for worker-node VMs and connected resources. The Free management tier has no cluster-management fee; Standard and Premium add cluster-management pricing and an uptime SLA, with Premium also adding extended Kubernetes-version support.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/aks/concepts-clusters-workloads","topic":"aks","type":"single","options":["Azure manages worker nodes for free, while every control-plane tier has a management charge.","Azure manages the control plane; the Free tier has no cluster-management fee, while Standard and Premium add one.","Azure manages everything for free, including worker-node compute.","You manage both the control plane and nodes; Azure bills only for storage."],"answer":1,"setId":"bouvet:aks","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/aks.json","reviewDate":"2026-10-11"},{"id":"bouvet:aks-002","prompt":"Which kubectl command applies a manifest declaratively — making the cluster match the desired state described in a YAML file?","explanation":"`kubectl apply -f \u003cfile>` is the declarative command: it reconciles the cluster to match the manifest and is safely re-runnable. `kubectl create`/`run` are one-shot imperative commands.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/aks/concepts-clusters-workloads","topic":"aks","type":"single","options":["kubectl run -f deployment.yaml","kubectl create deployment webapp","kubectl apply -f deployment.yaml","kubectl exec -f deployment.yaml"],"answer":2,"setId":"bouvet:aks","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/aks.json","reviewDate":"2026-10-11"},{"id":"bouvet:aks-003","prompt":"You need a Kubernetes object that keeps 3 replicas of your app running and performs rolling updates. Which object do you declare?","explanation":"A Deployment declares desired state (e.g. 3 replicas), manages a ReplicaSet to keep that many pods alive, and performs rolling updates and rollbacks. A bare Pod is a single disposable instance with none of that.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/aks/concepts-clusters-workloads","topic":"aks","type":"single","options":["A bare Pod","A Service","A Deployment","A ConfigMap"],"answer":2,"setId":"bouvet:aks","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/aks.json","reviewDate":"2026-10-11"},{"id":"bouvet:aks-004","prompt":"Which Service type gives your application a public external IP on AKS?","explanation":"A `LoadBalancer` Service provisions an Azure Load Balancer with a public external IP. ClusterIP (the default) is internal-only; NodePort exposes a high port on each node but is rarely the intended public-access answer.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/aks/concepts-clusters-workloads","topic":"aks","type":"single","options":["ClusterIP","NodePort","LoadBalancer","Headless"],"answer":2,"setId":"bouvet:aks","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/aks.json","reviewDate":"2026-10-11"},{"id":"bouvet:aks-005","prompt":"What is the default Service type, and who can reach it?","explanation":"The default Service type is ClusterIP, which is reachable only from within the cluster. You need LoadBalancer or an Ingress to expose an app externally.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/aks/concepts-clusters-workloads","topic":"aks","type":"single","options":["LoadBalancer — reachable from the public internet","ClusterIP — reachable only from inside the cluster","NodePort — reachable on every node's public IP","Ingress — reachable via a hostname"],"answer":1,"setId":"bouvet:aks","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/aks.json","reviewDate":"2026-10-11"},{"id":"bouvet:aks-006","prompt":"Which command merges an AKS cluster's connection info and credentials into your local kubeconfig so plain `kubectl` commands target that cluster?","explanation":"`az aks get-credentials --resource-group \u003crg> --name \u003ccluster>` merges the cluster's entry into ~/.kube/config. Without it, kubectl doesn't know how to reach or authenticate to the cluster. It does not create the cluster.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/aks/concepts-clusters-workloads","topic":"aks","type":"single","options":["az aks create","az aks get-credentials","az aks update --attach-acr","kubectl config use-context"],"answer":1,"setId":"bouvet:aks","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/aks.json","reviewDate":"2026-10-11"},{"id":"bouvet:aks-007","prompt":"Pods on your AKS cluster are stuck in ImagePullBackOff pulling an image from your Azure Container Registry. What is the most likely fix?\nAssume the registry uses classic RBAC Registry Permissions and the image/network settings are valid.","explanation":"ImagePullBackOff from ACR usually means the nodes cannot authenticate to the registry. For an RBAC-only ACR, `az aks update --attach-acr \u003cacr>` grants the kubelet managed identity AcrPull, so no imagePullSecrets are needed. Also verify the image name and tag.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/aks/cluster-container-registry-integration","topic":"aks","type":"single","options":["Restart the control plane","Attach the ACR so the kubelet managed identity gets the AcrPull role","Add a LoadBalancer Service","Increase the node count"],"answer":1,"setId":"bouvet:aks","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/aks.json","reviewDate":"2026-10-11","reviewNote":"Scoped AcrPull/attach-acr to classic registry RBAC."},{"id":"bouvet:aks-008","prompt":"Which role does `az aks update --attach-acr \u003cacr>` grant, and to which identity?\nAssume the registry uses classic RBAC Registry Permissions and the image/network settings are valid.","explanation":"Attaching an RBAC-only ACR grants AcrPull to the kubelet managed identity, which is the identity used by nodes to pull images. An ABAC-enabled registry needs a repository-scoped reader role instead.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/aks/cluster-container-registry-integration","topic":"aks","type":"single","options":["Contributor, to your user account","AcrPush, to the ACR admin user","AcrPull, to the kubelet managed identity","Reader, to the node pool"],"answer":2,"setId":"bouvet:aks","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/aks.json","reviewDate":"2026-10-11","reviewNote":"Scoped AcrPull/attach-acr to classic registry RBAC."},{"id":"bouvet:aks-009","prompt":"A pod shows STATUS CrashLoopBackOff. What does that indicate?","explanation":"CrashLoopBackOff means the image pulled fine but the container starts and then exits over and over (app crash, bad config, or failing liveness probe), so Kubernetes keeps restarting it with growing back-off. Read the logs with `kubectl logs \u003cpod> -p`.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/aks/concepts-clusters-workloads","topic":"aks","type":"single","options":["The image could not be pulled from the registry","The container starts but keeps exiting, so Kubernetes restarts it repeatedly","The pod cannot be scheduled onto any node","The Service has no endpoints"],"answer":1,"setId":"bouvet:aks","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/aks.json","reviewDate":"2026-10-11"},{"id":"bouvet:aks-010","prompt":"A pod is stuck in the Pending phase. What is the most common cause?","explanation":"Pending means the pod hasn't been scheduled onto a node yet — usually insufficient CPU/memory to satisfy its resource requests, or a NotReady node. `kubectl describe pod` shows a FailedScheduling event.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/aks/concepts-clusters-workloads","topic":"aks","type":"single","options":["The application inside the container crashed","The image tag does not exist","It can't be scheduled — no node has enough CPU/memory (or a constraint can't be met)","The readiness probe is failing"],"answer":2,"setId":"bouvet:aks","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/aks.json","reviewDate":"2026-10-11"},{"id":"bouvet:aks-011","prompt":"Which single command is the most useful for seeing why a specific pod is stuck — showing its events, image, probe config, and container states?","explanation":"`kubectl describe pod \u003cpod-name>` prints the pod's events plus each container's State/Last State and Reason — the go-to command for diagnosing scheduling failures, image pull errors, and probe failures.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/aks/concepts-clusters-workloads","topic":"aks","type":"single","options":["kubectl get pods","kubectl describe pod \u003cpod-name>","kubectl apply -f pod.yaml","kubectl rollout status"],"answer":1,"setId":"bouvet:aks","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/aks.json","reviewDate":"2026-10-11"},{"id":"bouvet:aks-012","prompt":"A container in CrashLoopBackOff has already restarted. Which command shows the logs from the crashed (previous) run?","explanation":"`kubectl logs \u003cpod> -p` (--previous) reads the logs of the previous, terminated container instance — essential for CrashLoopBackOff, where the current container may be too short-lived to inspect. `-f` follows live logs of the current container.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/aks/concepts-clusters-workloads","topic":"aks","type":"single","options":["kubectl logs \u003cpod>","kubectl logs \u003cpod> -p","kubectl logs \u003cpod> -f","kubectl describe pod \u003cpod>"],"answer":1,"setId":"bouvet:aks","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/aks.json","reviewDate":"2026-10-11"},{"id":"bouvet:aks-013","prompt":"Your LoadBalancer Service returns nothing and `kubectl get endpoints` shows it has NO endpoints. What's the most likely cause?","explanation":"A Service routes to pods matched by its selector that are also Ready. Empty endpoints means no pod matches the selector's labels, or matching pods are failing their readiness probe and thus excluded from the endpoint list.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/aks/concepts-clusters-workloads","topic":"aks","type":"single","options":["The cluster control plane is down","The Service selector matches no ready pods (wrong label or a failing readiness probe)","ACR is not attached to the cluster","The namespace was deleted"],"answer":1,"setId":"bouvet:aks","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/aks.json","reviewDate":"2026-10-11"},{"id":"bouvet:aks-014","prompt":"From inside a running pod, which command tests in-cluster connectivity to another Service by DNS name?","explanation":"`kubectl exec -it \u003cpod> -- curl http://\u003cservice>.\u003cnamespace>:\u003cport>/` runs a command inside the pod, exercising in-cluster DNS resolution and Service routing end-to-end — the standard connectivity check.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/aks/concepts-clusters-workloads","topic":"aks","type":"single","options":["kubectl logs \u003cpod> -- curl http://webapp","kubectl describe service webapp","kubectl exec -it \u003cpod> -- curl http://webapp.demo:80/","kubectl apply -f service.yaml"],"answer":2,"setId":"bouvet:aks","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/aks.json","reviewDate":"2026-10-11"},{"id":"bouvet:aks-015","prompt":"What is the difference between a liveness probe and a readiness probe?","explanation":"A failing liveness probe causes Kubernetes to restart the container. A failing readiness probe leaves the container running but removes the pod from the Service's endpoints, so it receives no traffic until it passes.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/aks/concepts-clusters-workloads","topic":"aks","type":"single","options":["Liveness gates traffic; readiness restarts the container","Liveness restarts the container when it fails; readiness removes the pod from Service traffic when it fails","They are identical; the names are interchangeable","Readiness restarts the node; liveness restarts the pod"],"answer":1,"setId":"bouvet:aks","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/aks.json","reviewDate":"2026-10-11"},{"id":"bouvet:aks-016","prompt":"Where should you store a NON-secret setting (like a greeting string) versus a sensitive value (like an API key) for a pod?","explanation":"Non-secret configuration belongs in a ConfigMap and sensitive configuration belongs in a Secret. Base64 in a Secret manifest is only an API representation, not a confidentiality boundary. AKS storage is encrypted at rest separately; still restrict Secret access with RBAC and use Key Vault/workload identity when appropriate.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/aks/concepts-clusters-workloads","topic":"aks","type":"single","options":["Both in a ConfigMap","Non-secret in a ConfigMap; sensitive value in a Secret","Both in a Secret","Non-secret in a Secret; sensitive value in a ConfigMap"],"answer":1,"setId":"bouvet:aks","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/aks.json","reviewDate":"2026-10-11"},{"id":"bouvet:aks-017","prompt":"What does the base64 value in a Kubernetes Secret manifest mean?","explanation":"Base64 makes binary data safe for a text manifest; anyone able to read the Secret can decode it. That fact is separate from AKS platform encryption at rest and optional Key Vault KMS integration. Use Kubernetes RBAC and avoid committing Secret manifests.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/aks/concepts-clusters-workloads","topic":"aks","type":"single","options":["It is strongly encrypted with a customer-managed key.","It is base64-encoded for the Kubernetes API; that encoding is not a confidentiality boundary.","It is plaintext and is never encrypted at rest by AKS.","It is hashed and cannot be recovered by a pod."],"answer":1,"setId":"bouvet:aks","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/aks.json","reviewDate":"2026-10-11"},{"id":"bouvet:aks-018","prompt":"A pod's container was terminated with reason OOMKilled. What happened?","explanation":"Inspect memory usage, the container limit and node pressure/events. A limit breach is common, but the reason alone does not prove it was that container limit rather than node-wide exhaustion.","domain":"containers","source":"https://kubernetes.io/docs/concepts/configuration/manage-resources-containers/","topic":"aks","type":"single","options":["The image was not found in the registry","The kernel killed the container during an out-of-memory condition","The pod could not be scheduled","The readiness probe failed"],"answer":1,"setId":"bouvet:aks","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/aks.json","reviewDate":"2026-10-11","reviewNote":"OOMKilled can result from a container limit or node-level memory exhaustion."},{"id":"bouvet:aks-019","prompt":"You need AKS container stdout/stderr retained centrally after pods disappear and queryable with KQL. Which configured monitoring feature provides that?","explanation":"Container Insights can send selected container logs to a Log Analytics workspace, subject to collection and retention configuration. kubectl logs also returns retained node-local logs and can show the previous container instance; it is not a durable central archive.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/azure-monitor/containers/container-insights-overview","topic":"aks","type":"single","options":["In the pod's local disk forever","In Container Insights, which ships stdout/stderr to a Log Analytics workspace","In the ACR registry","In the kubeconfig file"],"answer":1,"setId":"bouvet:aks","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/aks.json","reviewDate":"2026-10-11","reviewNote":"kubectl logs is not restricted to a live follow stream."},{"id":"bouvet:aks-020","prompt":"Which commands help you troubleshoot why a pod is failing? (Select all that apply)","explanation":"`describe pod` shows events and container states, `logs` shows what the app printed, and `get events` surfaces cluster-level failures (scheduling, image pull, probes). `az aks get-credentials` just sets up kubeconfig — it isn't a diagnostic command.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/aks/concepts-clusters-workloads","topic":"aks","type":"multi","options":["kubectl describe pod \u003cpod>","kubectl logs \u003cpod>","kubectl get events","az aks get-credentials"],"answer":[0,1,2],"choose":3,"setId":"bouvet:aks","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/aks.json","reviewDate":"2026-10-11"},{"id":"bouvet:aks-021","prompt":"Which statements about the AKS cluster hierarchy are correct? (Select all that apply)","explanation":"The nesting is Cluster → node pool → node (VM) → pod → container. A node does NOT run inside a pod — it's the other way around: pods run on nodes.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/aks/concepts-clusters-workloads","topic":"aks","type":"multi","options":["A cluster contains one or more node pools","A node pool contains nodes (worker VMs)","A pod is the smallest deployable unit and usually runs one container","A node runs inside a pod"],"answer":[0,1,2],"choose":3,"setId":"bouvet:aks","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/aks.json","reviewDate":"2026-10-11"},{"id":"bouvet:aks-022","prompt":"Which statements correctly contrast ImagePullBackOff and CrashLoopBackOff? (Select all that apply)","explanation":"ImagePullBackOff is about fetching the image; CrashLoopBackOff is about the container repeatedly exiting after it started. Neither is a scheduling problem — that's the Pending phase (FailedScheduling).","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/aks/concepts-clusters-workloads","topic":"aks","type":"multi","options":["ImagePullBackOff means the image could not be fetched (bad name/tag or registry auth)","CrashLoopBackOff means the container pulled but keeps starting and exiting","Attaching ACR (AcrPull) can fix ImagePullBackOff caused by missing registry auth","Both states mean the pod could not be scheduled to a node"],"answer":[0,1,2],"choose":3,"setId":"bouvet:aks","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/aks.json","reviewDate":"2026-10-11"},{"id":"bouvet:aks-023","prompt":"Order the steps to deploy an app to a freshly created AKS cluster and confirm the rollout:","explanation":"First pull cluster credentials so kubectl can reach the cluster, then apply the Deployment, then the Service that fronts it, then verify the rollout completed. (A single combined manifest works too, but the order of connect → deploy → expose → verify holds.)","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/aks/concepts-clusters-workloads","topic":"aks","type":"order","options":["az aks get-credentials --resource-group \u003crg> --name \u003ccluster>","kubectl apply -f deployment.yaml","kubectl apply -f service.yaml","kubectl rollout status deployment/webapp"],"answer":["az aks get-credentials --resource-group \u003crg> --name \u003ccluster>","kubectl apply -f deployment.yaml","kubectl apply -f service.yaml","kubectl rollout status deployment/webapp"],"setId":"bouvet:aks","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/aks.json","reviewDate":"2026-10-11"},{"id":"bouvet:aks-024","prompt":"Pods are in ImagePullBackOff after deploying. Order the troubleshooting steps to diagnose and fix it:","explanation":"Spot the failing status, describe the pod to read the Events explaining the pull/auth failure, attach the ACR so the cluster's managed identity gets AcrPull, then re-check that pods reach Running.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/aks/concepts-clusters-workloads","topic":"aks","type":"order","options":["kubectl get pods  (see STATUS = ImagePullBackOff)","kubectl describe pod \u003cpod>  (Events show the pull/auth failure)","az aks update --attach-acr \u003cacr>  (grant AcrPull)","kubectl get pods  (confirm STATUS = Running)"],"answer":["kubectl get pods  (see STATUS = ImagePullBackOff)","kubectl describe pod \u003cpod>  (Events show the pull/auth failure)","az aks update --attach-acr \u003cacr>  (grant AcrPull)","kubectl get pods  (confirm STATUS = Running)"],"setId":"bouvet:aks","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/aks.json","reviewDate":"2026-10-11"},{"id":"bouvet:aks-025","prompt":"Which best describes the difference between a Deployment, a Pod, and a Service?","explanation":"A Pod is one disposable running instance; a Deployment maintains a desired number of pods and performs rolling updates/rollbacks; a Service provides a stable name/IP that load-balances across the pods it selects.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/aks/concepts-clusters-workloads","topic":"aks","type":"single","options":["They are three names for the same object","A Pod is a running instance; a Deployment keeps N pods alive and does rolling updates; a Service is a stable network endpoint in front of pods","A Service runs containers; a Deployment stores config; a Pod exposes an IP","A Deployment is a single container; a Pod is a group of nodes; a Service is a VM"],"answer":1,"setId":"bouvet:aks","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/aks.json","reviewDate":"2026-10-11"},{"id":"bouvet:aks-026","prompt":"A pod is healthy enough to keep running, but it must be removed from a Service until it can accept requests. Which probe should fail?","explanation":"A failed readiness probe removes the pod from Service endpoints without restarting it. A failed liveness probe tells Kubernetes to restart the container.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/aks/concepts-clusters-workloads","topic":"aks","type":"single","options":["Readiness probe","Liveness probe","Startup probe only","Image pull probe"],"answer":0,"setId":"bouvet:aks","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/aks.json","reviewDate":"2026-10-11"},{"id":"bouvet:aks-027","prompt":"A newly deployed pod remains Pending. Which investigation is most likely to reveal the immediate scheduling cause?","explanation":"Pending commonly means the scheduler cannot place the pod because of insufficient requested CPU/memory or a NotReady node. kubectl describe exposes the scheduler Events that state the reason.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/aks/concepts-clusters-workloads","topic":"aks","type":"single","options":["Run kubectl describe pod \u003cpod-name> and inspect Events for FailedScheduling","Run kubectl logs \u003cpod-name>; Pending pods always have application logs","Rebuild the image with a different tag","Create a deployment slot"],"answer":0,"setId":"bouvet:aks","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/aks.json","reviewDate":"2026-10-11"},{"id":"bouvet:aks-028","prompt":"An AKS cluster uses an ACR configured for RBAC plus ABAC repository permissions. What should you do instead of using az aks update --attach-acr?","explanation":"The attach-acr shortcut does not support an ACR using RBAC plus ABAC repository permissions. Grant the kubelet identity the least-privilege Container Registry Repository Reader permission instead.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/aks/concepts-clusters-workloads","topic":"aks","type":"single","options":["Grant the kubelet managed identity Container Registry Repository Reader for the needed repository","Give every pod an AcrPush role","Store the ACR admin password in each Deployment manifest","Grant Reader to the AKS control plane only"],"answer":0,"setId":"bouvet:aks","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/aks.json","reviewDate":"2026-10-11"},{"id":"bouvet:app-service-containers-001","prompt":"What is Azure App Service when used with containers?","explanation":"Azure App Service is a managed web-app hosting Platform-as-a-Service (PaaS) that can run your app from a container image, while Azure handles the servers, scaling, and TLS certificates. Kubernetes is AKS; serverless scale-to-zero is Container Apps; CI/CD pipelines are separate services.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/app-service/configure-custom-container","topic":"app-service-containers","type":"single","options":["A managed Kubernetes cluster for running container workloads","A managed web-app hosting PaaS that can run a container image instead of raw code","A serverless container platform that scales to zero by default","A CI/CD pipeline service that builds and deploys container images"],"answer":1,"setId":"bouvet:app-service-containers","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/app-service-containers.json","reviewDate":"2026-10-11"},{"id":"bouvet:app-service-containers-002","prompt":"Which statement accurately describes containers in a modern Linux Azure App Service app?","explanation":"A classic custom-container app has one container. A Linux app configured for App Service sidecars has one main container and optional sidecars that share the app lifecycle and scale together. This is App Service configuration, not a Kubernetes Pod API.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/app-service/configure-custom-container","topic":"app-service-containers","type":"single","options":["It can run one classic custom container, or one main container with optional sidecars when sidecar support is enabled","It always runs an arbitrary Kubernetes Pod manifest","It can run unlimited main containers that each receive public HTTP traffic","It can only run Windows containers"],"answer":0,"setId":"bouvet:app-service-containers","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/app-service-containers.json","reviewDate":"2026-10-11"},{"id":"bouvet:app-service-containers-003","prompt":"What is the minimum App Service Plan tier that supports Linux containers with deployment slots?","explanation":"Standard (S1) is the minimum tier that supports both a Linux custom container and deployment slots. Basic can host a Linux custom container, but it does not include deployment slots.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/app-service/configure-custom-container","topic":"app-service-containers","type":"single","options":["Free (F1)","Basic (B1)","Standard (S1)","Premium (P1)"],"answer":2,"setId":"bouvet:app-service-containers","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/app-service-containers.json","reviewDate":"2026-10-11"},{"id":"bouvet:app-service-containers-004","prompt":"For a classic App Service custom container, which setting must match the port on which the process actually listens?","explanation":"In classic mode, set WEBSITES_PORT to the process listening port when needed. The process must listen on the appropriate interface. For sidecar-enabled apps, configure the main container target port instead.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/app-service/configure-custom-container","topic":"app-service-containers","type":"single","options":["The container name","The startup command","The WEBSITES_PORT application setting in classic custom-container mode","The Dockerfile location"],"answer":2,"setId":"bouvet:app-service-containers","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/app-service-containers.json","reviewDate":"2026-10-11","reviewNote":"Named the setting rather than repeating the question."},{"id":"bouvet:app-service-containers-005","prompt":"For an Azure Container Registry using RBAC Registry Permissions, what role does an App Service app's managed identity need to pull images?","explanation":"On an ACR using RBAC Registry Permissions, the app's managed identity needs AcrPull. AcrPush is for pushing images (CI/CD pipelines); AcrDelete is for deleting images; Reader is for viewing registry metadata but not pulling images. An ABAC-enabled registry uses Container Registry Repository Reader instead.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/app-service/configure-custom-container","topic":"app-service-containers","type":"single","options":["AcrPush","AcrPull","AcrDelete","Reader"],"answer":1,"setId":"bouvet:app-service-containers","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/app-service-containers.json","reviewDate":"2026-10-11"},{"id":"bouvet:app-service-containers-006","prompt":"What is the primary method for injecting environment variables into an App Service container?","explanation":"App Settings in the App Service configuration are injected as environment variables into the running container. You can also use Key Vault references within App Settings for secrets, but the primary method is App Settings.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/app-service/configure-custom-container","topic":"app-service-containers","type":"single","options":["Docker ENV instructions in the image","App Settings in the App Service configuration","Command-line arguments to the container","Azure Key Vault direct integration"],"answer":1,"setId":"bouvet:app-service-containers","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/app-service-containers.json","reviewDate":"2026-10-11"},{"id":"bouvet:app-service-containers-007","prompt":"What feature allows you to test a new container image with zero downtime before promoting it to production?","explanation":"Deployment slots are live staging environments with their own hostname. You can deploy a different container image to a slot (e.g., staging), test it, then swap it with production instantly for zero-downtime deployment.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/app-service/configure-custom-container","topic":"app-service-containers","type":"single","options":["Blue-green deployments","Deployment slots with swap","Container rollouts","Canary releases"],"answer":1,"setId":"bouvet:app-service-containers","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/app-service-containers.json","reviewDate":"2026-10-11"},{"id":"bouvet:app-service-containers-008","prompt":"Which of the following are TRUE about App Service containers? (Select all that apply)","explanation":"App Service supports both Linux and Windows containers. It can auto-pull new image tags via Continuous Deployment. You can mount Azure Files or Blob Storage for persistent data. However, App Service containers do NOT scale to zero — they are always-on on paid tiers.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/app-service/configure-custom-container","topic":"app-service-containers","type":"multi","options":["Containers run on Linux or Windows","App Service can auto-pull new image tags from ACR","You can mount Azure Files for persistent storage","App Service containers scale to zero when idle"],"answer":[0,1,2],"choose":3,"setId":"bouvet:app-service-containers","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/app-service-containers.json","reviewDate":"2026-10-11"},{"id":"bouvet:app-service-containers-009","prompt":"What happens to the old production container when you swap a staging slot into production?","explanation":"A swap exchanges the slots' non-sticky app content and settings. The previous production version therefore becomes the staging version, which gives you a convenient rollback path. Settings marked as deployment-slot settings stay with their slot.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/app-service/configure-custom-container","topic":"app-service-containers","type":"single","options":["It is restarted with the new configuration","It continues running alongside the new container","It is stopped and replaced by a new container from the new image","It is moved to the staging slot"],"answer":3,"setId":"bouvet:app-service-containers","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/app-service-containers.json","reviewDate":"2026-10-11"},{"id":"bouvet:app-service-containers-010","prompt":"What is the CLI command to create an App Service web app from a container image?","explanation":"Use `az webapp create` with the resource group, App Service plan, app name, and current `--container-image-name` option. `--deployment-container-image-name` is a deprecated option with a different spelling; `--deploy-container-image-name` is not valid.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/app-service/configure-custom-container","topic":"app-service-containers","type":"single","options":["az webapp create --resource-group \u003crg> --plan \u003cplan> --name \u003capp> --container-image-name \u003cimage>","az webapp create --resource-group \u003crg> --plan \u003cplan> --name \u003capp> --deploy-container-image-name \u003cimage>","az container create --app-name \u003capp> --image \u003cimage>","az appservice webapp new --container-image \u003cimage>"],"answer":0,"setId":"bouvet:app-service-containers","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/app-service-containers.json","reviewDate":"2026-10-11"},{"id":"bouvet:app-service-containers-011","prompt":"What is the symptom when an App Service container cannot pull an image from ACR due to missing permissions?","explanation":"On an ACR using RBAC Registry Permissions, a managed identity without AcrPull cannot pull the image, resulting in an 'Image pull failed' or 'Unauthorized' error in the logs. An ABAC-enabled registry instead needs Container Registry Repository Reader. 502 errors are typically due to port mismatches; 404 is not applicable; exit code 137 is an OOM kill.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/app-service/configure-custom-container","topic":"app-service-containers","type":"single","options":["404 Not Found error","502 Bad Gateway error","Image pull failed or Unauthorized error","Container exits with code 137"],"answer":2,"setId":"bouvet:app-service-containers","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/app-service-containers.json","reviewDate":"2026-10-11"},{"id":"bouvet:app-service-containers-012","prompt":"What syntax do you use in App Service App Settings to reference a secret from Azure Key Vault?","explanation":"The correct syntax is `@Microsoft.KeyVault(SecretUri=\u003csecret-uri>)`. This tells App Service to resolve the value from Key Vault at runtime, so the secret never appears in your configuration.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/app-service/configure-custom-container","topic":"app-service-containers","type":"single","options":["{{KeyVault:secret-name}}","@Microsoft.KeyVault(SecretUri=\u003curi>)","keyvault://\u003cvault>/\u003csecret>","${KEYVAULT_SECRET_\u003cname>}"],"answer":1,"setId":"bouvet:app-service-containers","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/app-service-containers.json","reviewDate":"2026-10-11"},{"id":"bouvet:app-service-containers-013","prompt":"Which Azure service should you choose for a single web app that needs the simplest managed hosting with container support?","explanation":"For a single web app/API with the simplest managed hosting, **App Service (containers)** is the right choice. AKS requires Kubernetes expertise; Container Apps is for serverless/microservices with scale-to-zero; ACI is for one-off containers without orchestration.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/app-service/configure-custom-container","topic":"app-service-containers","type":"single","options":["Azure Kubernetes Service (AKS)","Azure Container Apps","Azure App Service (containers)","Azure Container Instances (ACI)"],"answer":2,"setId":"bouvet:app-service-containers","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/app-service-containers.json","reviewDate":"2026-10-11"},{"id":"bouvet:app-service-containers-014","prompt":"How do you enable automatic updates when the container image tag changes in ACR?","explanation":"Enable Continuous Deployment for the container image; App Service uses registry notification to restart/pull when the configured tag is updated. The tag can be a deliberate version tag as well as `latest`; using `latest` alone does not create updates.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/app-service/configure-custom-container","topic":"app-service-containers","type":"single","options":["Use only the 'latest' tag; tags update themselves","Enable Continuous Deployment, which configures registry notification for the configured image tag","Use az acr task create with an App Service trigger","Set auto-update=true in the container configuration"],"answer":1,"setId":"bouvet:app-service-containers","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/app-service-containers.json","reviewDate":"2026-10-11"},{"id":"bouvet:app-service-containers-015","prompt":"Where can you view live stdout/stderr logs from a running App Service container?","explanation":"The **Log Stream** feature in the App Service portal (or `az webapp log tail` CLI) shows live stdout/stderr from the running container. Container Insights requires setup; Diagnose and solve is for guided troubleshooting; the container console is an interactive shell, not log viewing.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/app-service/configure-custom-container","topic":"app-service-containers","type":"single","options":["App Service -> Log Stream","Container Insights in Log Analytics","App Service -> Diagnose and solve problems","The container console"],"answer":0,"setId":"bouvet:app-service-containers","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/app-service-containers.json","reviewDate":"2026-10-11"},{"id":"bouvet:app-service-containers-016","prompt":"For classic App Service custom containers, which port is assumed by default when no explicit routing override is supplied?","explanation":"The documented classic default is port 80; use WEBSITES_PORT for another listening port. Sidecar-enabled apps use their main container target port configuration.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/app-service/configure-custom-container","topic":"app-service-containers","type":"single","options":["80","8080","443","3000"],"answer":0,"setId":"bouvet:app-service-containers","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/app-service-containers.json","reviewDate":"2026-10-11","reviewNote":"Scoped default-port guidance to classic containers."},{"id":"bouvet:app-service-containers-017","prompt":"Which of these are characteristics of App Service containers? (Select all that apply)","explanation":"App Service does not require Kubernetes knowledge, supports custom domains/TLS, and has an ephemeral container filesystem outside its persistent storage path. A sidecar-enabled Linux app can also run a main container plus sidecars, but that is not a Kubernetes Pod model.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/app-service/configure-custom-container","topic":"app-service-containers","type":"multi","options":["Requires Kubernetes knowledge","Supports custom domains and TLS","Has ephemeral filesystem by default","Can run sidecars with explicit sidecar support on Linux"],"answer":[1,2,3],"choose":3,"setId":"bouvet:app-service-containers","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/app-service-containers.json","reviewDate":"2026-10-11"},{"id":"bouvet:app-service-containers-018","prompt":"For an ACR using RBAC Registry Permissions, which command grants an App Service app permission to pull images?","explanation":"For an RBAC-only registry, assign AcrPull to the identity selected for registry authentication, scoped to the registry. Creating a web app and enabling its identity does not by itself grant that registry data-plane permission. An ABAC-enabled registry uses Container Registry Repository Reader instead.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/app-service/configure-custom-container","topic":"app-service-containers","type":"single","options":["az webapp update --attach-acr \u003cacr>","az role assignment create --assignee \u003cprincipal> --role AcrPull --scope \u003cacr-id>","az acr grant --service \u003capp> --permission pull","az appservice identity assign --name \u003capp> --role AcrPull"],"answer":1,"setId":"bouvet:app-service-containers","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/app-service-containers.json","reviewDate":"2026-10-11"},{"id":"bouvet:app-service-containers-019","prompt":"A container listens on port 8080 in a classic Linux App Service app and returns 502 errors after deployment. What is the most direct configuration fix?","explanation":"Classic App Service custom containers default to port 80. Set WEBSITES_PORT to the actual listening port; Dockerfile EXPOSE is not enough for App Service routing.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/app-service/configure-custom-container","topic":"app-service-containers","type":"single","options":["Set the WEBSITES_PORT app setting to 8080","Add EXPOSE 8080 to the Dockerfile only","Create a Kubernetes Service of type LoadBalancer","Assign Contributor on the App Service plan"],"answer":0,"setId":"bouvet:app-service-containers","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/app-service-containers.json","reviewDate":"2026-10-11"},{"id":"bouvet:app-service-containers-020","prompt":"Which setting continues to belong to its deployment slot rather than swapping to production?","explanation":"Settings marked as deployment slot settings are sticky: they remain with their slot during a swap. This lets staging keep its own endpoint, secret, or configuration value while app content is promoted.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/app-service/configure-custom-container","topic":"app-service-containers","type":"single","options":["A setting marked as a deployment slot setting","Every container image tag","Every non-sticky app setting","All application code"],"answer":0,"setId":"bouvet:app-service-containers","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/app-service-containers.json","reviewDate":"2026-10-11"},{"id":"bouvet:app-service-containers-021","prompt":"An App Service app pulls a private image from an ACR using RBAC Registry Permissions with a system-assigned managed identity. Which actions are required? (Select all that apply)","explanation":"For an RBAC-only registry, the identity must exist, have AcrPull at the registry scope, and be selected for registry authentication. Keeping a registry password out of the image avoids both a secret leak and an unnecessary credential. An ABAC-enabled registry needs Container Registry Repository Reader instead of AcrPull.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/app-service/configure-custom-container","topic":"app-service-containers","type":"multi","options":["Enable the system-assigned identity on the web app","Grant that identity AcrPull on the registry","Configure the app to use the selected managed identity for registry authentication","Put an ACR admin password in the image Dockerfile"],"answer":[0,1,2],"choose":3,"setId":"bouvet:app-service-containers","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/app-service-containers.json","reviewDate":"2026-10-11"},{"id":"bouvet:container-apps-keda-001","prompt":"What is Azure Container Apps (ACA)?","explanation":"Azure Container Apps is a serverless containers platform that lets you run containers without managing VMs, clusters, or orchestration. It abstracts away Kubernetes while using it under the hood.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/container-apps/scale-app","topic":"container-apps-keda","type":"single","options":["A managed Kubernetes cluster for running containers","A serverless containers platform that runs containers without managing infrastructure","A CI/CD pipeline service for building and deploying containers","A service for storing application secrets and configuration"],"answer":1,"setId":"bouvet:container-apps-keda","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/container-apps-keda.json","reviewDate":"2026-10-11"},{"id":"bouvet:container-apps-keda-002","prompt":"What does KEDA stand for and what is its role in Azure Container Apps?","explanation":"KEDA stands for Kubernetes Event-Driven Autoscaler. It is built into Azure Container Apps and automatically scales your containers based on event sources like queue length, HTTP traffic, CPU usage, etc.","domain":"containers","source":"https://keda.sh/","topic":"container-apps-keda","type":"single","options":["Kubernetes Event-driven Autoscaling; it scales workloads based on event sources","Key Encryption and Data Access — it manages secrets for container apps","Kubernetes Environment Deployment Agent — it deploys container images","Kernel Extension for Docker Applications — it optimizes container performance"],"answer":0,"setId":"bouvet:container-apps-keda","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/container-apps-keda.json","reviewDate":"2026-10-11","reviewNote":"Corrected the expansion of KEDA."},{"id":"bouvet:container-apps-keda-003","prompt":"What is the hierarchy of Azure Container Apps from largest to smallest scope?","explanation":"The hierarchy is: Environment (the workspace/network boundary) contains Apps and Jobs, which in turn contain Containers. Resource Group is at the Azure level, above Environment.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/container-apps/scale-app","topic":"container-apps-keda","type":"single","options":["Environment → Job → App → Container","Environment → App/Job → Container","Container → App → Job → Environment","Resource Group → Environment → App → Container"],"answer":1,"setId":"bouvet:container-apps-keda","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/container-apps-keda.json","reviewDate":"2026-10-11"},{"id":"bouvet:container-apps-keda-004","prompt":"Which feature enables immutable deployment versions and weighted canary or rollback traffic in Container Apps?","explanation":"Revision-scope changes create immutable revisions. In multiple-revision mode, Container Apps can send weighted traffic to active revisions for canary, blue-green, and rollback workflows. Header-based experiments need an additional routing layer; revisions alone do not add header routing.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/container-apps/scale-app","topic":"container-apps-keda","type":"single","options":["Deployment slots","Immutable revisions","Blue-green deployments via separate apps","Container versioning"],"answer":1,"setId":"bouvet:container-apps-keda","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/container-apps-keda.json","reviewDate":"2026-10-11"},{"id":"bouvet:container-apps-keda-005","prompt":"What is the key difference between an App and a Job in Container Apps?","explanation":"Apps are long-running services (like web APIs). Jobs are event-driven or scheduled containers that run to completion and then exit — like batch processing or scheduled tasks.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/container-apps/scale-app","topic":"container-apps-keda","type":"single","options":["Apps are long-running services; Jobs run to completion and exit","Apps can only have one container; Jobs can have multiple containers","Apps use HTTP scaling; Jobs use queue-based scaling","Apps are for Python; Jobs are for other languages"],"answer":0,"setId":"bouvet:container-apps-keda","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/container-apps-keda.json","reviewDate":"2026-10-11"},{"id":"bouvet:container-apps-keda-006","prompt":"When ingress is enabled and no scale rule is defined, which default scale rule does Container Apps apply?","explanation":"With ingress enabled and no explicit rule, Container Apps applies a default HTTP scale rule with a minimum of 0 and a maximum of 10 replicas. Define an explicit rule for a different threshold or a queue event source.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/container-apps/scale-app","topic":"container-apps-keda","type":"single","options":["cpu","memory","http","azure-queue"],"answer":2,"setId":"bouvet:container-apps-keda","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/container-apps-keda.json","reviewDate":"2026-10-11"},{"id":"bouvet:container-apps-keda-007","prompt":"Which of the following are valid KEDA scaler types in Azure Container Apps? (Select all that apply)","explanation":"Container Apps supports custom KEDA scale rules such as azure-servicebus, azure-queue, and cron. The invented cosmos-universe name is not a KEDA scaler. Treat a short list as examples, not an exhaustive catalogue.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/container-apps/scale-app","topic":"container-apps-keda","type":"multi","options":["azure-servicebus","azure-queue","cron","cosmos-universe"],"answer":[0,1,2],"choose":3,"setId":"bouvet:container-apps-keda","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/container-apps-keda.json","reviewDate":"2026-10-11"},{"id":"bouvet:container-apps-keda-008","prompt":"What is the minimum number of replicas a Container App can scale to?","explanation":"Container Apps can scale to 0 replicas when its rules allow it. There are no replica usage charges at zero, but separately configured resources such as logging or networking can still cost money.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/container-apps/scale-app","topic":"container-apps-keda","type":"single","options":["1 (always at least one instance running)","0 (scale to zero when idle)","2 (for high availability)","Depends on the pricing tier"],"answer":1,"setId":"bouvet:container-apps-keda","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/container-apps-keda.json","reviewDate":"2026-10-11"},{"id":"bouvet:container-apps-keda-009","prompt":"Which service in this host comparison uses reserved App Service Plan capacity rather than automatic scale-to-zero?","explanation":"App Service scales the App Service Plan rather than automatically scaling a container workload to zero. Container Apps and an appropriate Azure Functions plan are the serverless choices in this comparison.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/container-apps/scale-app","topic":"container-apps-keda","type":"single","options":["Azure Container Apps","Azure Functions","Azure App Service (containers)","Azure Functions (Flex Consumption)"],"answer":2,"setId":"bouvet:container-apps-keda","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/container-apps-keda.json","reviewDate":"2026-10-11"},{"id":"bouvet:container-apps-keda-010","prompt":"What type of ingress should you use for a microservice that only needs to communicate with other services in the same environment?","explanation":"Use internal ingress for an endpoint intended only for other Container Apps in the same environment. It is more restrictive than general VNet access; environment accessibility and app ingress visibility are separate settings.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/container-apps/scale-app","topic":"container-apps-keda","type":"single","options":["external","internal","none","private"],"answer":1,"setId":"bouvet:container-apps-keda","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/container-apps-keda.json","reviewDate":"2026-10-11"},{"id":"bouvet:container-apps-keda-011","prompt":"What role must you grant to a Container App's managed identity to allow it to pull images from Azure Container Registry?\nAssume the registry uses classic RBAC Registry Permissions and the image/network settings are valid.","explanation":"The AcrPull role grants read/pull access to Azure Container Registry. This is what a Container App needs to pull images. Use --registry-identity system and grant AcrPull on the registry.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/aks/cluster-container-registry-integration","topic":"container-apps-keda","type":"single","options":["AcrPush","AcrPull","Reader","Contributor"],"answer":1,"setId":"bouvet:container-apps-keda","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/container-apps-keda.json","reviewDate":"2026-10-11","reviewNote":"Scoped AcrPull/attach-acr to classic registry RBAC."},{"id":"bouvet:container-apps-keda-012","prompt":"A team needs a containerized web API that scales to zero when idle and processes messages from a Service Bus queue. Which Azure service should they use?","explanation":"Container Apps + KEDA is the best fit for a general containerized API plus queue-driven scaling without managing Kubernetes. Azure Functions can run supported containerized function apps, but it uses the Functions programming model rather than being a general Container Apps workload.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/container-apps/scale-app","topic":"container-apps-keda","type":"single","options":["Azure App Service (containers)","Azure Kubernetes Service (AKS)","Azure Container Apps + KEDA","Azure Functions"],"answer":2,"setId":"bouvet:container-apps-keda","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/container-apps-keda.json","reviewDate":"2026-10-11"},{"id":"bouvet:container-apps-keda-013","prompt":"What command creates a new Container Apps environment?","explanation":"The correct command is 'az containerapp env create' with name, resource-group, and location parameters. The environment must exist before you can deploy apps into it.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/container-apps/scale-app","topic":"container-apps-keda","type":"single","options":["az containerapp create --name myenv --resource-group myrg","az containerapp env create --name myenv --resource-group myrg --location westeurope","az aca environment create --name myenv --resource-group myrg","az appservice plan create --name myenv --resource-group myrg"],"answer":1,"setId":"bouvet:container-apps-keda","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/container-apps-keda.json","reviewDate":"2026-10-11"},{"id":"bouvet:container-apps-keda-014","prompt":"Which of the following are true about revisions in Container Apps? (Select all that apply)","explanation":"Revisions are immutable and traffic can be split between active revisions. A revision-scope change creates a revision; application-scope changes such as ingress or traffic settings do not, so not every deployment action creates one.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/container-apps/scale-app","topic":"container-apps-keda","type":"multi","options":["Revisions are created automatically on every deployment","Revisions can be modified after creation","Traffic can be split between multiple revisions","Revisions are immutable (cannot be changed)"],"answer":[2,3],"choose":2,"setId":"bouvet:container-apps-keda","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/container-apps-keda.json","reviewDate":"2026-10-11"},{"id":"bouvet:container-apps-keda-015","prompt":"What is the default polling interval for KEDA scalers in Container Apps?","explanation":"Custom KEDA rules poll event sources every 30 seconds by default. HTTP and TCP rules use their own built-in behavior, so do not apply this polling interval to every kind of rule.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/container-apps/scale-app","topic":"container-apps-keda","type":"single","options":["5 seconds","15 seconds","30 seconds","60 seconds"],"answer":2,"setId":"bouvet:container-apps-keda","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/container-apps-keda.json","reviewDate":"2026-10-11"},{"id":"bouvet:container-apps-keda-016","prompt":"Which CLI flag enables scale-to-zero for a Container App?","explanation":"A minimum of 0 allows scale-to-zero, provided a scale rule can wake the app and max replicas is at least 1. The current default minimum is already 0; setting it explicitly makes the intended behavior clear.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/container-apps/scale-app","topic":"container-apps-keda","type":"single","options":["--scale-to-zero","--min-replicas 0","--max-replicas 0","--auto-scale"],"answer":1,"setId":"bouvet:container-apps-keda","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/container-apps-keda.json","reviewDate":"2026-10-11"},{"id":"bouvet:container-apps-keda-017","prompt":"What should you do with ingress for a background worker that does not receive HTTP or TCP requests?","explanation":"Ingress is either enabled as external or internal, or disabled. A queue worker that does not need an inbound endpoint should disable ingress and use an event-driven scale rule to wake up.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/container-apps/scale-app","topic":"container-apps-keda","type":"single","options":["Enable external ingress","Enable internal ingress","Disable ingress entirely","Use an unsupported private ingress type"],"answer":2,"setId":"bouvet:container-apps-keda","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/container-apps-keda.json","reviewDate":"2026-10-11"},{"id":"bouvet:container-apps-keda-018","prompt":"How many inactive Container Apps revisions are retained by default?","explanation":"By default, Container Apps retains up to 100 inactive revisions. Active revisions are managed separately, and the inactive-revision threshold can be configured.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/container-apps/revisions","topic":"container-apps-keda","type":"single","options":["10","25","50","100"],"answer":3,"setId":"bouvet:container-apps-keda","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/container-apps-keda.json","reviewDate":"2026-10-11","reviewNote":"The retention limit concerns inactive revisions."},{"id":"bouvet:container-apps-keda-019","prompt":"What is the simplest supported HTTP address for one Container App to call another app in the same environment?","explanation":"Within the same environment, built-in service discovery resolves the short address http://\u003capp-name>. A full internal FQDN has more parts, including the environment identifier and region, so do not invent a shortened .internal format.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/container-apps/scale-app","topic":"container-apps-keda","type":"single","options":["http://\u003capp-name>","http://\u003capp-name>.\u003cenvironment-name>.internal","http://\u003capp-name>.\u003cregion>.internal","http://\u003capp-name>.internal.\u003cenvironment-name>"],"answer":0,"setId":"bouvet:container-apps-keda","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/container-apps-keda.json","reviewDate":"2026-10-11"},{"id":"bouvet:container-apps-keda-020","prompt":"What command family configures traffic weights between two Container App revisions for a canary deployment?","explanation":"Use az containerapp ingress traffic set with --revision-weight values that add to 100. The app must use multiple active revisions for a revision-weight canary.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/container-apps/scale-app","topic":"container-apps-keda","type":"single","options":["az containerapp revision update --traffic-split old=95,new=5","az containerapp ingress traffic set --name myapp --resource-group myrg --revision-weight old=95 new=5","az containerapp deployment create --canary 5","az containerapp scale --revision v2 --percentage 5"],"answer":1,"setId":"bouvet:container-apps-keda","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/container-apps-keda.json","reviewDate":"2026-10-11"},{"id":"bouvet:container-apps-keda-021","prompt":"Which scaler metadata property configures when to scale based on queue length for an azure-queue scaler?","explanation":"The queueLength metadata value is the target queue length per replica. For example, a value of 5 lets KEDA calculate roughly one replica for each five queued messages, subject to the app's min/max limits.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/container-apps/scale-app","topic":"container-apps-keda","type":"single","options":["queueLength","messageCount","queueSize","queueDepth"],"answer":0,"setId":"bouvet:container-apps-keda","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/container-apps-keda.json","reviewDate":"2026-10-11"},{"id":"bouvet:container-apps-keda-022","prompt":"Which scaler metadata property configures when to scale based on HTTP traffic for an http scaler?","explanation":"The concurrentRequests metadata property specifies how many concurrent HTTP requests trigger scaling. For example, concurrentRequests: \"50\" means scale out when there are more than 50 concurrent requests.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/container-apps/scale-app","topic":"container-apps-keda","type":"single","options":["requestCount","httpRequests","concurrentRequests","requestRate"],"answer":2,"setId":"bouvet:container-apps-keda","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/container-apps-keda.json","reviewDate":"2026-10-11"},{"id":"bouvet:container-apps-keda-023","prompt":"What is the purpose of the --revision-suffix flag when deploying a Container App?","explanation":"The --revision-suffix value becomes an identifiable part of the revision name, which is useful in deployment history and traffic-weight commands. It is optional; Container Apps can generate a name when it is omitted.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/container-apps/scale-app","topic":"container-apps-keda","type":"single","options":["To specify which revision to deploy","To create a named revision that can be used for traffic splitting","To set the maximum number of revisions to keep","To enable automatic rollback on failure"],"answer":1,"setId":"bouvet:container-apps-keda","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/container-apps-keda.json","reviewDate":"2026-10-11"},{"id":"bouvet:container-apps-keda-024","prompt":"Which hosting options provide built-in demand-driven scale-to-zero in an appropriate configuration? (Select all that apply)","explanation":"Container Apps and Azure Functions plans that support scale-to-zero provide built-in demand-driven scaling. App Service has reserved plan capacity, while Azure Container Instances does not provide built-in autoscaling.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/container-apps/scale-app","topic":"container-apps-keda","type":"multi","options":["Azure Container Apps","Azure Functions on a scale-to-zero hosting plan","Azure App Service (containers)","Azure Container Instances"],"answer":[0,1],"choose":2,"setId":"bouvet:container-apps-keda","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/container-apps-keda.json","reviewDate":"2026-10-11"},{"id":"bouvet:container-apps-keda-025","prompt":"Put these steps in order to deploy a Container App with KEDA scaling:","explanation":"Correct order: 1) Create resource group, 2) Create Container Apps environment, 3) Create ACR and push image, 4) Deploy the app with scale rules. The environment must exist before deploying apps, and the image must be in ACR before the app can pull it.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/container-apps/scale-app","topic":"container-apps-keda","type":"order","options":["Create a Container Apps environment","Create a resource group","Create an Azure Container Registry and push the container image","Deploy the container app with scale rules"],"answer":["Create a resource group","Create a Container Apps environment","Create an Azure Container Registry and push the container image","Deploy the container app with scale rules"],"setId":"bouvet:container-apps-keda","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/container-apps-keda.json","reviewDate":"2026-10-11"},{"id":"bouvet:container-apps-keda-026","prompt":"What is the current default maximum number of replicas per Container App revision?","explanation":"The default maximum is 10 replicas per revision and the current service limit allows a much larger configured maximum, subject to quota. Set an explicit max-replicas value for production capacity planning.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/container-apps/scale-app","topic":"container-apps-keda","type":"single","options":["10","20","30","100"],"answer":0,"setId":"bouvet:container-apps-keda","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/container-apps-keda.json","reviewDate":"2026-10-11"},{"id":"bouvet:container-apps-keda-027","prompt":"Which two types of managed identities are supported by Container Apps?","explanation":"Container Apps supports both system-assigned managed identities (created automatically) and user-assigned managed identities (created separately and assigned to the app).","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/container-apps/scale-app","topic":"container-apps-keda","type":"single","options":["System-assigned and user-assigned","Built-in and custom","Primary and secondary","Azure AD and service principal"],"answer":0,"setId":"bouvet:container-apps-keda","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/container-apps-keda.json","reviewDate":"2026-10-11"},{"id":"bouvet:container-apps-keda-028","prompt":"What command would you use to view the logs of a running Container App?","explanation":"The correct command is 'az containerapp logs show --name \u003capp> --resource-group \u003crg>' to view the application logs. Use --follow to stream logs in real-time.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/container-apps/scale-app","topic":"container-apps-keda","type":"single","options":["az containerapp show --name myapp --resource-group myrg","az containerapp logs show --name myapp --resource-group myrg","az monitor activity-log list --resource /subscriptions/.../containerApps/myapp","az webapp log tail --name myapp --resource-group myrg"],"answer":1,"setId":"bouvet:container-apps-keda","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/container-apps-keda.json","reviewDate":"2026-10-11"},{"id":"bouvet:container-apps-keda-029","prompt":"Which capability does Container Apps provide that App Service containers do not?","explanation":"Container Apps can use its scale rules to reach zero replicas; App Service runs on reserved App Service Plan capacity. Azure Functions can also provide scale-to-zero, so this is a comparison with App Service rather than a claim of product exclusivity.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/container-apps/scale-app","topic":"container-apps-keda","type":"single","options":["Can run containerized applications","Can scale based on HTTP traffic","Can scale to zero when idle","Can use custom domains"],"answer":2,"setId":"bouvet:container-apps-keda","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/container-apps-keda.json","reviewDate":"2026-10-11"},{"id":"bouvet:container-apps-keda-030","prompt":"How does a Container Apps HTTP scale rule evaluate its concurrency threshold?","explanation":"HTTP scaling is evaluated every 15 seconds using the request count during that 15-second window. Custom event rules, such as Azure Queue, have a separate default polling interval of 30 seconds.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/container-apps/scale-app","topic":"container-apps-keda","type":"single","options":["Every 15 seconds, from the number of requests in the prior 15 seconds divided by 15.","Only when a custom KEDA scaler finishes its default 30-second polling interval.","Once per minute, from total requests since the revision was created.","Continuously, from CPU utilization on the existing replica."],"answer":0,"setId":"bouvet:container-apps-keda","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/container-apps-keda.json","reviewDate":"2026-10-11"},{"id":"bouvet:container-apps-keda-031","prompt":"Which KEDA scaler would you use to scale based on a cron schedule?","explanation":"The 'cron' scaler type is used for scheduled scaling based on cron expressions. This allows you to scale up or down on a schedule.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/container-apps/scale-app","topic":"container-apps-keda","type":"single","options":["azure-queue","cron","timer","schedule"],"answer":1,"setId":"bouvet:container-apps-keda","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/container-apps-keda.json","reviewDate":"2026-10-11"},{"id":"bouvet:container-apps-keda-032","prompt":"What happens when you make a revision-scope Container App update without specifying a --revision-suffix?","explanation":"A revision-scope update creates a new immutable revision with an auto-generated name when no suffix is supplied. Application-scope changes do not create revisions, and a suffix is optional for traffic splitting.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/container-apps/scale-app","topic":"container-apps-keda","type":"single","options":["The existing revision is updated","A new revision is created with an auto-generated name","The deployment fails with an error","The app is restarted without creating a new revision"],"answer":1,"setId":"bouvet:container-apps-keda","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/container-apps-keda.json","reviewDate":"2026-10-11"},{"id":"bouvet:container-apps-keda-033","prompt":"Which are valid ingress types for a Container App? (Select all that apply)","explanation":"When ingress is enabled, its visibility is external or internal. Disabling ingress is valid for a worker, but it is not a third ingress type; internal ingress is reachable only within the Container Apps environment.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/container-apps/scale-app","topic":"container-apps-keda","type":"multi","options":["external","internal","none","private"],"answer":[0,1],"choose":2,"setId":"bouvet:container-apps-keda","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/container-apps-keda.json","reviewDate":"2026-10-11"},{"id":"bouvet:container-apps-keda-034","prompt":"A scenario describes: 'A development team wants to deploy a containerized web API with the least operational overhead. They don't need Kubernetes expertise, want to scale to zero when idle, and need to process messages from a queue.' Which Azure service best fits this scenario?","explanation":"Azure Container Apps + KEDA is the best fit for a general containerized API with queue-driven scale-to-zero and no Kubernetes administration. Azure Functions also supports containerized function apps, but it is a Functions-runtime choice rather than a general container host.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/container-apps/scale-app","topic":"container-apps-keda","type":"single","options":["Azure Kubernetes Service","Azure App Service (containers)","Azure Container Apps + KEDA","Azure Functions"],"answer":2,"setId":"bouvet:container-apps-keda","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/container-apps-keda.json","reviewDate":"2026-10-11"},{"id":"bouvet:container-apps-keda-035","prompt":"What command lists active and inactive revisions of a Container App?","explanation":"`az containerapp revision list` shows revisions, but `--all` includes inactive revisions as well. This matters when diagnosing or reactivating a previously deployed revision.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/container-apps/scale-app","topic":"container-apps-keda","type":"single","options":["az containerapp list --name myapp --resource-group myrg","az containerapp revision list --name myapp --resource-group myrg --all","az containerapp show --name myapp --resource-group myrg","az containerapp history --name myapp --resource-group myrg"],"answer":1,"setId":"bouvet:container-apps-keda","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/container-apps-keda.json","reviewDate":"2026-10-11"},{"id":"bouvet:container-apps-keda-036","prompt":"A queue worker has ingress disabled and minReplicas set to 0. It defines no custom scale rule. What is the likely result?","explanation":"Without ingress, the default HTTP rule cannot wake the app. A background worker that may reach zero needs an explicit event-driven rule, such as azure-servicebus, so Container Apps has a trigger to create a replica.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/container-apps/scale-app","topic":"container-apps-keda","type":"single","options":["It scales to zero and has no trigger that can start it again","Container Apps automatically reads every Service Bus queue","It receives the default HTTP rule even though ingress is disabled","It remains at 10 replicas"],"answer":0,"setId":"bouvet:container-apps-keda","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/container-apps-keda.json","reviewDate":"2026-10-11"},{"id":"bouvet:container-apps-keda-037","prompt":"Which Container Apps change creates a new immutable revision?","explanation":"The image is a revision-scope container setting, so changing it creates a revision. Traffic, ingress, and revision mode are application-scope settings and do not themselves create a revision.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/container-apps/scale-app","topic":"container-apps-keda","type":"single","options":["Changing the container image","Changing traffic weights only","Enabling or disabling ingress only","Changing the active revision mode only"],"answer":0,"setId":"bouvet:container-apps-keda","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/container-apps-keda.json","reviewDate":"2026-10-11"},{"id":"bouvet:container-apps-keda-038","prompt":"A nightly image-processing task should start, process a finite batch, and exit. Which Container Apps resource best matches it?","explanation":"A Container Apps Job is intended for manual, scheduled, or event-driven work that runs to completion. Use a long-running app for an API or service that stays available between requests.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/container-apps/scale-app","topic":"container-apps-keda","type":"single","options":["A Container Apps Job","A long-running Container App with external ingress","An App Service deployment slot","An AKS Service"],"answer":0,"setId":"bouvet:container-apps-keda","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/01-containers/container-apps-keda.json","reviewDate":"2026-10-11"},{"id":"bouvet:azure-managed-redis-001","prompt":"What is Azure Managed Redis?","explanation":"Azure Managed Redis is Microsoft's current managed Redis service, built on Redis Enterprise. It is separate from the retiring Azure Cache for Redis service and supports caching, Redis data structures, and optional modules such as RediSearch.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/redis/","topic":"azure-managed-redis","type":"single","options":["A relational database for storing structured data","A fully managed, in-memory data store based on Redis","A NoSQL document database for JSON storage","A blob storage service for file storage"],"answer":1,"setId":"bouvet:azure-managed-redis","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/azure-managed-redis.json","reviewDate":"2026-10-11"},{"id":"bouvet:azure-managed-redis-002","prompt":"What is a primary use case for Azure Managed Redis in an AI application?","explanation":"Caching frequently requested data or model responses can lower latency and reduce load on the authoritative store. The application must still tolerate a cache miss because cached data can expire, be evicted, or be invalidated.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/redis/","topic":"azure-managed-redis","type":"single","options":["Long-term data storage","Caching frequently accessed data for fast retrieval","Running containerized applications","Processing streaming data"],"answer":1,"setId":"bouvet:azure-managed-redis","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/azure-managed-redis.json","reviewDate":"2026-10-11"},{"id":"bouvet:azure-managed-redis-003","prompt":"Which Redis data type is best for storing a user object with multiple fields (name, email, age)?","explanation":"Hash is the best data type for storing objects with multiple fields. It allows you to store field-value pairs, like a dictionary. Use HSET to set fields and HGET/HGETALL to retrieve them.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/redis/","topic":"azure-managed-redis","type":"single","options":["String","Hash","List","Set"],"answer":1,"setId":"bouvet:azure-managed-redis","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/azure-managed-redis.json","reviewDate":"2026-10-11"},{"id":"bouvet:azure-managed-redis-004","prompt":"Which Redis data type is best for implementing a FIFO queue?","explanation":"A Redis list can implement FIFO by adding at one end and removing at the other, for example RPUSH followed by LPOP. Redis Streams are usually a better fit when consumer groups, acknowledgement, and durable processing semantics are required.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/redis/","topic":"azure-managed-redis","type":"single","options":["String","Hash","List","Set"],"answer":2,"setId":"bouvet:azure-managed-redis","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/azure-managed-redis.json","reviewDate":"2026-10-11"},{"id":"bouvet:azure-managed-redis-005","prompt":"Which Redis data type ensures all values are unique?","explanation":"Set is the data type that stores only unique values. Duplicates are automatically ignored when adding to a set.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/redis/","topic":"azure-managed-redis","type":"single","options":["String","Hash","List","Set"],"answer":3,"setId":"bouvet:azure-managed-redis","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/azure-managed-redis.json","reviewDate":"2026-10-11"},{"id":"bouvet:azure-managed-redis-006","prompt":"What is TTL in Redis?","explanation":"TTL (Time To Live) is a countdown timer that you can set on any Redis key. When the timer reaches zero, the key is automatically deleted from the cache.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/redis/","topic":"azure-managed-redis","type":"single","options":["Time To Load — how long it takes to load data","Time To Live — a countdown timer after which a key is automatically deleted","Total Transaction Latency — network delay","Table Transaction Log — audit trail"],"answer":1,"setId":"bouvet:azure-managed-redis","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/azure-managed-redis.json","reviewDate":"2026-10-11"},{"id":"bouvet:azure-managed-redis-007","prompt":"What happens to a Redis key's TTL when it is accessed (read)?","explanation":"TTL is NOT automatically refreshed on access. Once set, the countdown continues regardless of how many times the key is read. This is a common exam gotcha.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/redis/","topic":"azure-managed-redis","type":"single","options":["The TTL is refreshed to its original value","The TTL is extended by the access duration","The TTL continues counting down regardless of access","The TTL is doubled"],"answer":2,"setId":"bouvet:azure-managed-redis","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/azure-managed-redis.json","reviewDate":"2026-10-11"},{"id":"bouvet:azure-managed-redis-008","prompt":"Which caching pattern involves the application checking the cache first, fetching from the database on a miss, then writing to the cache?","explanation":"Cache-Aside (also called Lazy Loading) is the pattern where the application checks the cache first. On a cache miss, it fetches from the database, writes to the cache, and returns the data. This is the most common pattern.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/redis/","topic":"azure-managed-redis","type":"single","options":["Read-Through","Write-Through","Write-Behind","Cache-Aside (Lazy Loading)"],"answer":3,"setId":"bouvet:azure-managed-redis","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/azure-managed-redis.json","reviewDate":"2026-10-11"},{"id":"bouvet:azure-managed-redis-009","prompt":"Which caching pattern has the cache automatically fetch data from the database on a cache miss?","explanation":"In read-through, a cache abstraction or integration loads a missing value from the source. The Redis server does not automatically know how to query an arbitrary application database; that loader behavior must be implemented by the surrounding solution.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/redis/","topic":"azure-managed-redis","type":"single","options":["Read-Through","Write-Through","Write-Behind","Cache-Aside"],"answer":0,"setId":"bouvet:azure-managed-redis","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/azure-managed-redis.json","reviewDate":"2026-10-11"},{"id":"bouvet:azure-managed-redis-010","prompt":"What is the main risk of the Write-Behind caching pattern?","explanation":"Write-Behind (also called Write-Back) has the risk of data loss. The application writes to cache, and the cache is supposed to write to the database later. If the cache fails before syncing, data can be lost.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/redis/","topic":"azure-managed-redis","type":"single","options":["Data inconsistency between cache and database","Data loss if the cache fails before syncing to the database","Performance degradation","Increased latency"],"answer":1,"setId":"bouvet:azure-managed-redis","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/azure-managed-redis.json","reviewDate":"2026-10-11"},{"id":"bouvet:azure-managed-redis-011","prompt":"What is cache invalidation?","explanation":"Cache invalidation removes or updates a cached value when the authoritative data changes. It can be triggered automatically by the application's write path or by an event; it is not limited to a person manually deleting keys.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/redis/","topic":"azure-managed-redis","type":"single","options":["Automatically removing expired data","Removing or updating a cached value when its source changes","Clearing the entire cache","Refreshing the TTL on all keys"],"answer":1,"setId":"bouvet:azure-managed-redis","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/azure-managed-redis.json","reviewDate":"2026-10-11"},{"id":"bouvet:azure-managed-redis-012","prompt":"An embedding model's documentation says to compare its output with cosine distance. Which RediSearch DISTANCE_METRIC should the vector field use?","explanation":"Use COSINE because the index metric must match the embedding model's guidance. Cosine is common for semantic embeddings, but it is not a universal default for every model.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/redis/","topic":"azure-managed-redis","type":"single","options":["COSINE","L2","IP","MANHATTAN"],"answer":0,"setId":"bouvet:azure-managed-redis","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/azure-managed-redis.json","reviewDate":"2026-10-11"},{"id":"bouvet:azure-managed-redis-013","prompt":"Which Redis module is required for vector similarity search?","explanation":"RediSearch is the Redis module required for vector similarity search. It provides vector indexing and KNN (k-nearest neighbor) search capabilities.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/redis/","topic":"azure-managed-redis","type":"single","options":["RedisJSON","RedisTimeSeries","RediSearch","RedisBloom"],"answer":2,"setId":"bouvet:azure-managed-redis","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/azure-managed-redis.json","reviewDate":"2026-10-11"},{"id":"bouvet:azure-managed-redis-014","prompt":"Which RediSearch command creates an index schema containing a vector field?","explanation":"FT.CREATE defines a RediSearch schema, including a VECTOR field and its algorithm, numeric type, dimensions, and distance metric. Store the actual vector in an indexed Redis hash or JSON document; FT.VECTORADD is not a RediSearch command.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/redis/","topic":"azure-managed-redis","type":"single","options":["FT.CREATE","FT.VECTORADD","VECTOR.CREATE","FT.INDEX"],"answer":0,"setId":"bouvet:azure-managed-redis","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/azure-managed-redis.json","reviewDate":"2026-10-11"},{"id":"bouvet:azure-managed-redis-015","prompt":"Which RediSearch command can execute a KNN vector query?","explanation":"FT.SEARCH (or FT.AGGREGATE) executes RediSearch vector queries. A KNN clause supplies the top-k value, vector field, and binary query vector, and vector syntax requires DIALECT 2 or later.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/redis/","topic":"azure-managed-redis","type":"single","options":["FT.SEARCH","FT.VECTORSEARCH","FT.KNN","VECTOR.QUERY"],"answer":0,"setId":"bouvet:azure-managed-redis","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/azure-managed-redis.json","reviewDate":"2026-10-11"},{"id":"bouvet:azure-managed-redis-016","prompt":"An Azure Managed Redis workload needs the greatest compute throughput for a given memory size. Which tier should you evaluate first?","explanation":"Compute Optimized provides the most vCPUs for a given memory size and is intended for throughput-intensive workloads. Validate the choice with measured memory, latency, throughput, and connection requirements.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/redis/","topic":"azure-managed-redis","type":"single","options":["Memory Optimized","Balanced","Compute Optimized","Flash Optimized"],"answer":2,"setId":"bouvet:azure-managed-redis","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/azure-managed-redis.json","reviewDate":"2026-10-11"},{"id":"bouvet:azure-managed-redis-017","prompt":"Which client port is used by Azure Managed Redis?","explanation":"Azure Managed Redis uses port 10000. Port 6380 belongs to Azure Cache for Redis, while 6379 is the common Redis Open Source port.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/redis/","topic":"azure-managed-redis","type":"single","options":["6379","10000","5432","1433"],"answer":1,"setId":"bouvet:azure-managed-redis","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/azure-managed-redis.json","reviewDate":"2026-10-11"},{"id":"bouvet:azure-managed-redis-018","prompt":"When must RediSearch be enabled on an Azure Managed Redis instance?","explanation":"Modules are selected during Azure Managed Redis provisioning and cannot be added later. RediSearch also requires Enterprise clustering, NoEviction, and a supported in-memory tier.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/redis/","topic":"azure-managed-redis","type":"single","options":["After the first vector is stored","When the instance is created","When the first FT.CREATE command runs","Only after scaling the instance"],"answer":1,"setId":"bouvet:azure-managed-redis","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/azure-managed-redis.json","reviewDate":"2026-10-11"},{"id":"bouvet:azure-managed-redis-019","prompt":"Which of the following are valid Redis data types? (Select all that apply)","explanation":"String, hash, list, and sorted set are core Redis structures. A vector is stored as a field in a hash or JSON document and indexed by RediSearch; it is not a normal core Redis value type.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/redis/","topic":"azure-managed-redis","type":"multi","options":["String","Hash","List","Sorted set","Vector as a standalone core Redis value type"],"answer":[0,1,2,3],"choose":4,"setId":"bouvet:azure-managed-redis","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/azure-managed-redis.json","reviewDate":"2026-10-11"},{"id":"bouvet:azure-managed-redis-020","prompt":"Which Azure Managed Redis clustering policy is required by RediSearch?","explanation":"RediSearch requires EnterpriseCluster. OSSCluster normally offers stronger direct-shard throughput, but it cannot be combined with RediSearch.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/redis/","topic":"azure-managed-redis","type":"single","options":["OSSCluster","EnterpriseCluster","NoCluster","Any clustering policy"],"answer":1,"setId":"bouvet:azure-managed-redis","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/azure-managed-redis.json","reviewDate":"2026-10-11"},{"id":"bouvet:azure-managed-redis-021","prompt":"What command is used to increment a counter in Redis?","explanation":"INCR is the command to increment a counter by 1. For incrementing by a different amount, use INCRBY.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/redis/","topic":"azure-managed-redis","type":"single","options":["INCREMENT","INCR","ADD","INCREMENT_BY"],"answer":1,"setId":"bouvet:azure-managed-redis","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/azure-managed-redis.json","reviewDate":"2026-10-11"},{"id":"bouvet:azure-managed-redis-022","prompt":"What is the difference between expiration and eviction in Redis?","explanation":"A TTL controls expiration. Eviction is driven by memory pressure and the configured eviction policy. RediSearch on Azure Managed Redis specifically requires NoEviction.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/redis/","topic":"azure-managed-redis","type":"single","options":["Expiration follows a key's TTL; eviction removes keys according to policy under memory pressure","Expiration is manual; eviction always follows a TTL","Expiration affects hashes only; eviction affects strings only","There is no difference"],"answer":0,"setId":"bouvet:azure-managed-redis","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/azure-managed-redis.json","reviewDate":"2026-10-11"},{"id":"bouvet:azure-managed-redis-023","prompt":"A cached product price changes frequently and must become fresh soon after the source database is updated. Which strategy is the best fit?","explanation":"Delete or update the cache entry when the source write commits, and also give the entry a bounded TTL. Event-driven invalidation provides prompt freshness; the TTL limits stale-data duration if an invalidation is missed.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/redis/","topic":"azure-managed-redis","type":"single","options":["Only use TTL","Use TTL combined with event-based invalidation","Never cache frequently changing data","Cache forever and manually invalidate"],"answer":1,"setId":"bouvet:azure-managed-redis","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/azure-managed-redis.json","reviewDate":"2026-10-11"},{"id":"bouvet:azure-managed-redis-024","prompt":"What command is used to check the remaining TTL of a key?","explanation":"TTL returns the remaining lifetime in seconds. It returns -1 when the key exists without an expiry and -2 when the key does not exist.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/redis/","topic":"azure-managed-redis","type":"single","options":["TTL","EXPIRE","TIME_REMAINING","GET_TTL"],"answer":0,"setId":"bouvet:azure-managed-redis","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/azure-managed-redis.json","reviewDate":"2026-10-11"},{"id":"bouvet:azure-managed-redis-025","prompt":"How should a redis-py client validate TLS when connecting to Azure Managed Redis?","explanation":"Azure Managed Redis uses publicly trusted certificates. Keep normal hostname and certificate validation enabled. ssl_cert_reqs=None disables verification and makes a TLS connection vulnerable to impersonation.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/redis/","topic":"azure-managed-redis","type":"single","options":["Disable certificate validation with ssl_cert_reqs=None","Keep certificate validation enabled and trust the normal public CA chain","Use plaintext because the connection stays inside Azure","Accept any certificate only when using Microsoft Entra ID"],"answer":1,"setId":"bouvet:azure-managed-redis","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/azure-managed-redis.json","reviewDate":"2026-10-11"},{"id":"bouvet:azure-managed-redis-026","prompt":"A model's evaluation guidance requires Euclidean distance for its output vectors. Which RediSearch DISTANCE_METRIC value should you configure?","explanation":"Configure L2, Redis's name for Euclidean distance, because the index metric should follow the model's evaluation guidance. Do not choose a metric solely from whether the input represents text or geometry.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/redis/","topic":"azure-managed-redis","type":"single","options":["COSINE","L2","DOT_PRODUCT","IP (Inner Product)"],"answer":1,"setId":"bouvet:azure-managed-redis","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/azure-managed-redis.json","reviewDate":"2026-10-11"},{"id":"bouvet:azure-managed-redis-027","prompt":"Which Azure Managed Redis tier is designed for a very large, read-heavy dataset when some extra latency is acceptable to reduce cost?","explanation":"Flash Optimized keeps keys and hot values in RAM while colder values can use NVMe flash. It can reduce the cost of a large read-heavy dataset, but uniform access and write-heavy workloads can suffer.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/redis/","topic":"azure-managed-redis","type":"single","options":["Memory Optimized","Balanced","Compute Optimized","Flash Optimized"],"answer":3,"setId":"bouvet:azure-managed-redis","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/azure-managed-redis.json","reviewDate":"2026-10-11"},{"id":"bouvet:azure-managed-redis-028","prompt":"Which Azure Managed Redis tiers can use high availability? (Select all that apply)","explanation":"All four Azure Managed Redis tier families support high availability. It is enabled by default; disabling it removes data replication and affects the SLA.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/redis/","topic":"azure-managed-redis","type":"multi","options":["Memory Optimized","Balanced","Compute Optimized","Flash Optimized"],"answer":[0,1,2,3],"choose":4,"setId":"bouvet:azure-managed-redis","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/azure-managed-redis.json","reviewDate":"2026-10-11"},{"id":"bouvet:azure-managed-redis-029","prompt":"What command would you use to add a new field to a Redis hash?","explanation":"HSET is the command to set field-value pairs in a Redis hash. It can add new fields or update existing ones.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/redis/","topic":"azure-managed-redis","type":"single","options":["HADD","HSET","HINSERT","HUPDATE"],"answer":1,"setId":"bouvet:azure-managed-redis","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/azure-managed-redis.json","reviewDate":"2026-10-11"},{"id":"bouvet:azure-managed-redis-030","prompt":"Which caching pattern synchronously updates the cache and authoritative store on the write path?","explanation":"In write-through, the write path synchronously updates the authoritative store and cache before completing. The two systems are not magically one atomic transaction, so the design still needs failure handling.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/redis/","topic":"azure-managed-redis","type":"single","options":["Cache-Aside","Read-Through","Write-Through","Write-Behind"],"answer":2,"setId":"bouvet:azure-managed-redis","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/azure-managed-redis.json","reviewDate":"2026-10-11"},{"id":"bouvet:azure-managed-redis-031","prompt":"What must the DIM setting in a RediSearch vector field match?","explanation":"DIM is the number of numeric elements in each vector. It must match the selected embedding output and the query vector; do not hard-code a dimension copied from a different model or deployment.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/redis/","topic":"azure-managed-redis","type":"single","options":["The number of indexed documents","The cache size in GB","The length of every stored and query embedding","The number of metadata fields"],"answer":2,"setId":"bouvet:azure-managed-redis","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/azure-managed-redis.json","reviewDate":"2026-10-11"},{"id":"bouvet:azure-managed-redis-032","prompt":"What happens when you call GET on a Redis key that doesn't exist?","explanation":"When you call GET on a Redis key that doesn't exist, it returns null (in Python, this is None). This is also known as a \"cache miss\".","domain":"data","source":"https://learn.microsoft.com/en-us/azure/redis/","topic":"azure-managed-redis","type":"single","options":["Returns null/None","Raises an exception","Creates the key with a default value","Returns an error message"],"answer":0,"setId":"bouvet:azure-managed-redis","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/azure-managed-redis.json","reviewDate":"2026-10-11"},{"id":"bouvet:azure-managed-redis-033","prompt":"Which Azure CLI command group creates an Azure Managed Redis instance?","explanation":"Azure Managed Redis uses az redisenterprise commands. The az redis command group manages the retiring Basic, Standard, and Premium Azure Cache for Redis tiers.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/redis/","topic":"azure-managed-redis","type":"single","options":["az redisenterprise create","az redis create","az managed-redis create","az cache create"],"answer":0,"setId":"bouvet:azure-managed-redis","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/azure-managed-redis.json","reviewDate":"2026-10-11"},{"id":"bouvet:azure-managed-redis-034","prompt":"What is the primary performance benefit of a redis-py pipeline?","explanation":"A pipeline queues commands and sends them in batches, reducing network round trips. The non-cluster redis.Redis client defaults pipeline() to MULTI/EXEC; pass transaction=False for batching without that transaction. A cluster pipeline cannot make commands across hash slots one global transaction.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/redis/","topic":"azure-managed-redis","type":"single","options":["It sends a batch of commands with fewer network round trips","It makes every command globally atomic across shards","It encrypts values before storage","It compresses values before storage"],"answer":0,"setId":"bouvet:azure-managed-redis","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/azure-managed-redis.json","reviewDate":"2026-10-11"},{"id":"bouvet:azure-managed-redis-035","prompt":"A scenario describes: 'A team needs to cache LLM responses to reduce costs and latency. They need to automatically remove cached responses after 1 hour and also remove them when new data is available.' Which combination of Redis features should they use?","explanation":"The team should use TTL (to automatically expire responses after 1 hour) combined with event-based cache invalidation (to remove stale responses when new data is available). This ensures both automatic expiration and immediate removal of stale data.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/redis/","topic":"azure-managed-redis","type":"single","options":["TTL only","Cache invalidation only","TTL combined with event-based cache invalidation","Persistence with manual deletion"],"answer":2,"setId":"bouvet:azure-managed-redis","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/azure-managed-redis.json","reviewDate":"2026-10-11"},{"id":"bouvet:azure-managed-redis-036","prompt":"Put these steps in order to set up Azure Managed Redis and use it for caching:","explanation":"Create the resource group, provision Azure Managed Redis with its immutable module and clustering choices, assign the client identity a Redis data access policy, connect the authenticated redis-py client, and then issue data commands.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/redis/","topic":"azure-managed-redis","type":"order","options":["Create a resource group","Create an Azure Managed Redis instance","Assign the client identity a Redis data access policy","Connect to Redis using redis-py","Store and retrieve data from the cache"],"answer":["Create a resource group","Create an Azure Managed Redis instance","Assign the client identity a Redis data access policy","Connect to Redis using redis-py","Store and retrieve data from the cache"],"setId":"bouvet:azure-managed-redis","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/azure-managed-redis.json","reviewDate":"2026-10-11"},{"id":"bouvet:azure-managed-redis-037","prompt":"Which Redis command is used to increment a hash field?","explanation":"HINCRBY is the command to increment a numeric hash field by a specified amount. For incrementing by 1, you can also use HINCRBY with value 1.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/redis/","topic":"azure-managed-redis","type":"single","options":["HINCR","HINCRBY","HADD","HSETINCREMENT"],"answer":1,"setId":"bouvet:azure-managed-redis","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/azure-managed-redis.json","reviewDate":"2026-10-11"},{"id":"bouvet:azure-managed-redis-038","prompt":"What is the difference between Sorted Set and Set in Redis?","explanation":"A sorted set (ZSET) associates a score with each unique member and returns members in score order. A set contains unique unordered members. Sorted sets are useful for leaderboards and time- or score-ranked data.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/redis/","topic":"azure-managed-redis","type":"single","options":["Sorted Set has an order based on a score, Set is unordered","Sorted Set can only store numbers, Set can store any string","Sorted Set is faster for lookups","Sorted Set allows duplicates, Set does not"],"answer":0,"setId":"bouvet:azure-managed-redis","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/azure-managed-redis.json","reviewDate":"2026-10-11"},{"id":"bouvet:azure-managed-redis-039","prompt":"A redis-py client uses decode_responses=True and raises a decoding error when it reads a binary FLOAT32 embedding. What should you change?","explanation":"Embedding fields are arbitrary binary bytes and are not necessarily valid UTF-8. Keep binary responses enabled for vector operations; a separate text-decoding client can still be useful for ordinary string cache entries.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/redis/","topic":"azure-managed-redis","type":"single","options":["Use a client with binary responses for vector operations","Convert the vector field to a Redis list of text values","Disable TLS","Change the vector index to FLAT"],"answer":0,"setId":"bouvet:azure-managed-redis","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/azure-managed-redis.json","reviewDate":"2026-10-11"},{"id":"bouvet:azure-managed-redis-040","prompt":"Which Azure Managed Redis tier selection supports RediSearch?","explanation":"RediSearch is supported on the Memory Optimized, Balanced, and Compute Optimized in-memory tiers. It is not supported on Flash Optimized and also requires EnterpriseCluster and NoEviction.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/redis/","topic":"azure-managed-redis","type":"single","options":["Any in-memory tier: Memory Optimized, Balanced, or Compute Optimized","Flash Optimized only","Balanced only","Every tier including Flash Optimized"],"answer":0,"setId":"bouvet:azure-managed-redis","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/azure-managed-redis.json","reviewDate":"2026-10-11"},{"id":"bouvet:azure-managed-redis-041","prompt":"An application uses cache-aside for product records. A database update succeeds, but the cached copy still contains the old value. What should the write path do next?","explanation":"After the authoritative database update commits, invalidate the related key. The next cache-aside read reloads the current record. Deleting one key avoids the broad impact of clearing the entire cache.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/redis/","topic":"azure-managed-redis","type":"single","options":["Delete the product's cache key so the next read repopulates it","Read the old cache value to refresh its TTL","Disable expiration on the product key","Run FLUSHALL on the entire Redis instance"],"answer":0,"setId":"bouvet:azure-managed-redis","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/azure-managed-redis.json","reviewDate":"2026-10-11"},{"id":"bouvet:azure-managed-redis-042","prompt":"You are provisioning Azure Managed Redis for RediSearch vector retrieval. Which settings are required? (Select all that apply)","explanation":"RediSearch must be selected at creation and requires Enterprise clustering plus NoEviction. It is supported by the in-memory tier families, not Flash Optimized.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/redis/","topic":"azure-managed-redis","type":"multi","options":["Enable RediSearch when the instance is created","Use EnterpriseCluster","Use NoEviction","Use the Flash Optimized tier"],"answer":[0,1,2],"choose":3,"setId":"bouvet:azure-managed-redis","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/azure-managed-redis.json","reviewDate":"2026-10-11"},{"id":"bouvet:azure-managed-redis-043","prompt":"A small compliance corpus requires exact top-k vector results, and query latency is acceptable. Which RediSearch vector algorithm should you choose?","explanation":"FLAT performs exact nearest-neighbour search. HNSW is approximate and is normally chosen when lower latency at larger scale is worth a recall and memory trade-off.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/redis/","topic":"azure-managed-redis","type":"single","options":["FLAT","HNSW","OSSCluster","RedisBloom"],"answer":0,"setId":"bouvet:azure-managed-redis","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/azure-managed-redis.json","reviewDate":"2026-10-11"},{"id":"bouvet:cosmos-db-nosql-001","prompt":"What is Azure Cosmos DB for NoSQL?","explanation":"Azure Cosmos DB for NoSQL is a managed, partitioned document database that stores JSON items in containers. An account can replicate data to multiple Azure regions; global distribution is a configuration choice, not a requirement for every account.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/cosmos-db/nosql/","topic":"cosmos-db-nosql","type":"single","options":["A relational database for storing structured data with tables","A fully managed, globally distributed NoSQL database that stores JSON documents","A key/value cache for fast data retrieval","A blob storage service for storing files"],"answer":1,"setId":"bouvet:cosmos-db-nosql","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/cosmos-db-nosql.json","reviewDate":"2026-10-11"},{"id":"bouvet:cosmos-db-nosql-002","prompt":"What is the resource hierarchy in Cosmos DB from top to bottom?","explanation":"The resource hierarchy in Cosmos DB is Account (top-level, globally distributed) → Database (container for containers) → Container (holds items with partitioning/indexing policies) → Item (JSON documents).","domain":"data","source":"https://learn.microsoft.com/en-us/azure/cosmos-db/nosql/","topic":"cosmos-db-nosql","type":"single","options":["Account → Database → Container → Item","Database → Container → Account → Item","Container → Database → Account → Item","Item → Container → Database → Account"],"answer":0,"setId":"bouvet:cosmos-db-nosql","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/cosmos-db-nosql.json","reviewDate":"2026-10-11"},{"id":"bouvet:cosmos-db-nosql-003","prompt":"A team requires every write to be rejected unless it conforms to one fixed JSON schema. Which capability must the application add because Azure Cosmos DB for NoSQL does not provide it automatically?","explanation":"Cosmos DB for NoSQL is schema-flexible: items in one container can have different properties. If the solution requires a fixed schema, validate it in the application or another controlled ingestion layer.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/cosmos-db/nosql/","topic":"cosmos-db-nosql","type":"single","options":["Application-level schema validation","Physical partition management","JSON item storage","SQL-like queries over item properties"],"answer":0,"setId":"bouvet:cosmos-db-nosql","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/cosmos-db-nosql.json","reviewDate":"2026-10-11"},{"id":"bouvet:cosmos-db-nosql-004","prompt":"What is the purpose of the partition key in Cosmos DB?","explanation":"The partition key determines each item's logical partition and how logical partitions are placed across physical partitions. A good key distributes storage and RU load while also aligning with common request and transaction patterns.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/cosmos-db/nosql/","topic":"cosmos-db-nosql","type":"single","options":["To encrypt data at rest","To determine how data is distributed across physical partitions","To set the retention period for documents","To define the indexing policy for the container"],"answer":1,"setId":"bouvet:cosmos-db-nosql","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/cosmos-db-nosql.json","reviewDate":"2026-10-11"},{"id":"bouvet:cosmos-db-nosql-005","prompt":"A user-profile container performs almost all reads by user ID, and each user ID is unique. Which partition key is the best fit for even distribution and targeted reads?","explanation":"userId has high cardinality, distributes users, and aligns with the dominant read pattern. A key should match request routing as well as distribute storage and throughput.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/cosmos-db/nosql/","topic":"cosmos-db-nosql","type":"single","options":["status (with values: active, inactive, pending)","userId (unique for each user)","country (with most users from one country)","timestamp (continuous increasing values)"],"answer":1,"setId":"bouvet:cosmos-db-nosql","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/cosmos-db-nosql.json","reviewDate":"2026-10-11"},{"id":"bouvet:cosmos-db-nosql-006","prompt":"What is the maximum size for a single item in Azure Cosmos DB for NoSQL?","explanation":"The maximum size for a single item (document) in Cosmos DB is 2MB. For larger data, consider storing large fields in blob storage with references.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/cosmos-db/nosql/","topic":"cosmos-db-nosql","type":"single","options":["1MB","2MB","10MB","100MB"],"answer":1,"setId":"bouvet:cosmos-db-nosql","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/cosmos-db-nosql.json","reviewDate":"2026-10-11"},{"id":"bouvet:cosmos-db-nosql-007","prompt":"What is the maximum size for a single logical partition in Cosmos DB?","explanation":"A single logical partition cannot exceed 20GB of data. If a partition grows beyond this, you must migrate to a different partition key with higher cardinality.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/cosmos-db/nosql/","topic":"cosmos-db-nosql","type":"single","options":["1GB","5GB","10GB","20GB"],"answer":3,"setId":"bouvet:cosmos-db-nosql","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/cosmos-db-nosql.json","reviewDate":"2026-10-11"},{"id":"bouvet:cosmos-db-nosql-008","prompt":"Why can a query that omits the partition key consume more RUs than a partition-routed query?","explanation":"Without a partition key value or another routable predicate, the service can fan the query out across physical partitions and merge the results. The actual extra cost depends on partition count, query shape, indexes, and results; there is no fixed multiplier.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/cosmos-db/nosql/","topic":"cosmos-db-nosql","type":"single","options":["It must always rebuild the container's indexes","It can fan out work across multiple physical partitions","Cosmos DB converts it into a stored procedure","It disables query parameterization"],"answer":1,"setId":"bouvet:cosmos-db-nosql","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/cosmos-db-nosql.json","reviewDate":"2026-10-11"},{"id":"bouvet:cosmos-db-nosql-009","prompt":"What is the approximate RU charge for a point read of a 1 KB item by id and partition key using session consistency?","explanation":"A 1 KB point read commonly costs 1 RU with session/eventual/consistent-prefix consistency. Strong or bounded-staleness reads require more RUs, and larger items cost more.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/cosmos-db/optimize-cost-reads-writes","topic":"cosmos-db-nosql","type":"single","options":["0.5 RU","1 RU","2 RUs","5 RUs"],"answer":1,"setId":"bouvet:cosmos-db-nosql","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/cosmos-db-nosql.json","reviewDate":"2026-10-11","reviewNote":"Scoped the one-RU read to weaker consistency."},{"id":"bouvet:cosmos-db-nosql-010","prompt":"Which consistency level is the DEFAULT for new Cosmos DB accounts?","explanation":"Session consistency is the default for new Cosmos DB accounts. It guarantees read-your-writes within the same client session.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/cosmos-db/nosql/","topic":"cosmos-db-nosql","type":"single","options":["Strong","Bounded Staleness","Session","Eventual"],"answer":2,"setId":"bouvet:cosmos-db-nosql","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/cosmos-db-nosql.json","reviewDate":"2026-10-11"},{"id":"bouvet:cosmos-db-nosql-011","prompt":"Which consistency level has the weakest freshness and ordering guarantees and requires the least read coordination?","explanation":"Eventual consistency has the weakest freshness and ordering guarantees. Replicas still converge when writes stop, but a read can lag and observe writes out of order.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/cosmos-db/nosql/","topic":"cosmos-db-nosql","type":"single","options":["Strong","Bounded Staleness","Session","Eventual"],"answer":3,"setId":"bouvet:cosmos-db-nosql","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/cosmos-db-nosql.json","reviewDate":"2026-10-11"},{"id":"bouvet:cosmos-db-nosql-012","prompt":"Which consistency level guarantees READ-YOUR-WRITES within the same client session?","explanation":"Session consistency guarantees read-your-writes within the same client session. It provides a good balance of consistency, latency, and availability.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/cosmos-db/nosql/","topic":"cosmos-db-nosql","type":"single","options":["Strong","Bounded Staleness","Session","Consistent Prefix"],"answer":2,"setId":"bouvet:cosmos-db-nosql","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/cosmos-db-nosql.json","reviewDate":"2026-10-11"},{"id":"bouvet:cosmos-db-nosql-013","prompt":"An Azure Cosmos DB account has one write region and additional read regions. Can the account use Strong consistency?","explanation":"Strong consistency can be used with multiple regions when the account has a single write region. It increases write latency because commits coordinate synchronously across regions. Strong is not supported with multiple write regions.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/cosmos-db/nosql/","topic":"cosmos-db-nosql","type":"single","options":["Yes; Strong can span regions and synchronously coordinates writes","No; Strong is restricted to one Azure region","Only if every region accepts writes","Only when the account uses serverless capacity"],"answer":0,"setId":"bouvet:cosmos-db-nosql","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/cosmos-db-nosql.json","reviewDate":"2026-10-11"},{"id":"bouvet:cosmos-db-nosql-014","prompt":"Which consistency level guarantees that readers observe writes in order, without gaps in the observed prefix, while still allowing the reader to lag?","explanation":"Consistent prefix ensures that replicas never expose writes out of order. A reader can still lag behind the latest write, so it does not provide Strong or session read-your-writes guarantees.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/cosmos-db/nosql/","topic":"cosmos-db-nosql","type":"single","options":["Strong","Bounded Staleness","Session","Consistent Prefix"],"answer":3,"setId":"bouvet:cosmos-db-nosql","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/cosmos-db-nosql.json","reviewDate":"2026-10-11"},{"id":"bouvet:cosmos-db-nosql-015","prompt":"Which capacity choice is the best starting point for a steady workload with a known RU/s requirement?","explanation":"Manual provisioned throughput reserves a known RU/s amount and fits stable demand. Autoscale is useful when demand varies within a configured maximum, while serverless fits intermittent low-volume traffic.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/cosmos-db/nosql/","topic":"cosmos-db-nosql","type":"single","options":["Serverless","Manual provisioned throughput","Shared storage","A change feed lease"],"answer":1,"setId":"bouvet:cosmos-db-nosql","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/cosmos-db-nosql.json","reviewDate":"2026-10-11"},{"id":"bouvet:cosmos-db-nosql-016","prompt":"Which capacity mode is the best fit for an intermittent, low-volume development workload that should pay for requests instead of reserving RU/s?","explanation":"Serverless bills for consumed RUs and storage without reserved throughput, which fits intermittent low-volume workloads. For sustained or high-volume variable demand, compare provisioned autoscale instead of assuming serverless is always best.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/cosmos-db/nosql/","topic":"cosmos-db-nosql","type":"single","options":["Serverless","Provisioned","Standard","Premium"],"answer":0,"setId":"bouvet:cosmos-db-nosql","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/cosmos-db-nosql.json","reviewDate":"2026-10-11"},{"id":"bouvet:cosmos-db-nosql-017","prompt":"Where can provisioned throughput be allocated in Cosmos DB?","explanation":"Provisioned throughput can be allocated at either the database level (shared across all containers in the database) or at the container level (dedicated to a specific container).","domain":"data","source":"https://learn.microsoft.com/en-us/azure/cosmos-db/nosql/","topic":"cosmos-db-nosql","type":"single","options":["Only at the account level","Only at the container level","At the database level or container level","Only at the item level"],"answer":2,"setId":"bouvet:cosmos-db-nosql","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/cosmos-db-nosql.json","reviewDate":"2026-10-11"},{"id":"bouvet:cosmos-db-nosql-018","prompt":"What is the primary purpose of the indexing policy in Cosmos DB?","explanation":"The indexing policy controls which paths and specialized indexes support queries. Normal new containers can use consistent indexing or no indexing; lazy indexing cannot be selected for a normal new container.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/cosmos-db/nosql/","topic":"cosmos-db-nosql","type":"single","options":["To determine which fields are automatically indexed for querying","To control access permissions for users","To set the retention period for documents","To configure backup schedules"],"answer":0,"setId":"bouvet:cosmos-db-nosql","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/cosmos-db-nosql.json","reviewDate":"2026-10-11"},{"id":"bouvet:cosmos-db-nosql-019","prompt":"A new queryable container must update its indexes synchronously with item writes. Which indexing mode should you use?","explanation":"Consistent indexing updates the index as items are created, updated, or deleted. New containers cannot normally select lazy indexing, and none disables indexing.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/cosmos-db/nosql/","topic":"cosmos-db-nosql","type":"single","options":["Consistent","Lazy","None","Deferred"],"answer":0,"setId":"bouvet:cosmos-db-nosql","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/cosmos-db-nosql.json","reviewDate":"2026-10-11"},{"id":"bouvet:cosmos-db-nosql-020","prompt":"What index kind is used for geospatial queries (e.g., ST_DISTANCE, ST_WITHIN)?","explanation":"Spatial index is used for geospatial queries that involve spatial data types like POINT, POLYGON, etc., with functions like ST_DISTANCE and ST_WITHIN.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/cosmos-db/nosql/","topic":"cosmos-db-nosql","type":"single","options":["Range","Hash","Spatial","Composite"],"answer":2,"setId":"bouvet:cosmos-db-nosql","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/cosmos-db-nosql.json","reviewDate":"2026-10-11"},{"id":"bouvet:cosmos-db-nosql-021","prompt":"What does an included path of /* do when there are no more-specific excluded paths?","explanation":"The root wildcard includes every property path unless a more-specific exclusion overrides it. This is the normal default and is flexible, but excluding large unqueried paths can reduce index storage and write RU cost.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/cosmos-db/nosql/","topic":"cosmos-db-nosql","type":"single","options":["Indexes every item property under the root","Indexes only the partition key","Disables all indexing","Indexes numeric values only"],"answer":0,"setId":"bouvet:cosmos-db-nosql","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/cosmos-db-nosql.json","reviewDate":"2026-10-11"},{"id":"bouvet:cosmos-db-nosql-022","prompt":"A query repeatedly orders by tenantId ascending and updatedAt descending. Which index should you evaluate for that exact multi-property order?","explanation":"A composite index with the matching paths and sort directions can support a multi-property ORDER BY. Measure query and index metrics because not every query with multiple predicates needs a composite index.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/cosmos-db/nosql/","topic":"cosmos-db-nosql","type":"single","options":["Increasing the provisioned RU/s","Using cross-partition queries","Creating composite indexes","Disabling indexing"],"answer":2,"setId":"bouvet:cosmos-db-nosql","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/cosmos-db-nosql.json","reviewDate":"2026-10-11"},{"id":"bouvet:cosmos-db-nosql-023","prompt":"What is the Azure Cosmos DB change feed?","explanation":"The change feed is a persistent record that consumers read asynchronously and incrementally. Latest-version mode contains creates and updates; all-versions-and-deletes mode also captures intermediate versions and deletes within continuous-backup retention.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/cosmos-db/nosql/","topic":"cosmos-db-nosql","type":"single","options":["A synchronous webhook invoked inside every item transaction","A persistent, incremental record of container changes","A point-in-time backup mechanism","A replacement for multi-region replication"],"answer":1,"setId":"bouvet:cosmos-db-nosql","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/cosmos-db-nosql.json","reviewDate":"2026-10-11"},{"id":"bouvet:cosmos-db-nosql-024","prompt":"Which event is NOT captured by latest-version change feed mode?","explanation":"Latest-version mode captures creates and the latest update state, but not deletes or the operation type. Use a soft-delete marker or all-versions-and-deletes mode when delete events are required.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/cosmos-db/nosql/","topic":"cosmos-db-nosql","type":"single","options":["An item creation","The latest item update","An item deletion","An item upsert"],"answer":2,"setId":"bouvet:cosmos-db-nosql","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/cosmos-db-nosql.json","reviewDate":"2026-10-11"},{"id":"bouvet:cosmos-db-nosql-025","prompt":"What is the purpose of checkpointing in change feed processing?","explanation":"Checkpointing tracks which changes have been processed. This allows the change feed processor to resume from the last checkpoint if it fails or is restarted.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/cosmos-db/nosql/","topic":"cosmos-db-nosql","type":"single","options":["To validate data before processing","To track which changes have been processed","To encrypt the change feed data","To replicate changes to other regions"],"answer":1,"setId":"bouvet:cosmos-db-nosql","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/cosmos-db-nosql.json","reviewDate":"2026-10-11"},{"id":"bouvet:cosmos-db-nosql-026","prompt":"What is the purpose of lease management in change feed processing?","explanation":"Lease records coordinate ownership of change-feed ranges and store checkpoints. That lets multiple processor instances share work and rebalance when workers join or leave.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/cosmos-db/nosql/","topic":"cosmos-db-nosql","type":"single","options":["To coordinate parallel processors across change-feed ranges","To encrypt data in transit","To control access to containers","To set retention policies"],"answer":0,"setId":"bouvet:cosmos-db-nosql","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/cosmos-db-nosql.json","reviewDate":"2026-10-11"},{"id":"bouvet:cosmos-db-nosql-027","prompt":"What is vector search in Cosmos DB used for?","explanation":"Vector search in Cosmos DB is used for storing and retrieving vector embeddings (arrays of floats) and executing similarity search (k-nearest neighbor queries) for AI workloads.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/cosmos-db/nosql/","topic":"cosmos-db-nosql","type":"single","options":["Storing and retrieving vector embeddings and executing similarity search","Encryption of data at rest","Geospatial queries","Full-text search"],"answer":0,"setId":"bouvet:cosmos-db-nosql","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/cosmos-db-nosql.json","reviewDate":"2026-10-11"},{"id":"bouvet:cosmos-db-nosql-028","prompt":"What is the current release status of vector search in Azure Cosmos DB for NoSQL?","explanation":"Vector search in Azure Cosmos DB for NoSQL is generally available. The account capability still must be enabled before a vector container is created.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/cosmos-db/nosql/","topic":"cosmos-db-nosql","type":"single","options":["Generally available","Private preview only","Deprecated","Unavailable"],"answer":0,"setId":"bouvet:cosmos-db-nosql","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/cosmos-db-nosql.json","reviewDate":"2026-10-11"},{"id":"bouvet:cosmos-db-nosql-029","prompt":"A container stores 1,536-dimensional embeddings. Which Azure Cosmos DB vector index types support that dimension? (Select all that apply)","explanation":"quantizedFlat and diskANN support up to 4,096 dimensions. flat is exact but supports at most 505 dimensions, and spatial is not a vector index.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/cosmos-db/nosql/","topic":"cosmos-db-nosql","type":"multi","options":["flat","quantizedFlat","diskANN","spatial"],"answer":[1,2],"choose":2,"setId":"bouvet:cosmos-db-nosql","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/cosmos-db-nosql.json","reviewDate":"2026-10-11"},{"id":"bouvet:cosmos-db-nosql-030","prompt":"An embedding model's evaluation guidance specifies cosine distance. Which Cosmos DB vector distance function should the container policy use?","explanation":"Use cosine because the vector policy must match the embedding model's guidance. Cosine is common for semantic embeddings, but dot product or Euclidean can be correct for other models.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/cosmos-db/nosql/","topic":"cosmos-db-nosql","type":"single","options":["EUCLIDEAN","COSINE","DOT_PRODUCT","MANHATTAN"],"answer":1,"setId":"bouvet:cosmos-db-nosql","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/cosmos-db-nosql.json","reviewDate":"2026-10-11"},{"id":"bouvet:cosmos-db-nosql-031","prompt":"Which vector index type provides EXACT search results?","explanation":"flat performs an exact brute-force vector search and provides full recall. quantizedFlat can lose a small amount of accuracy through compression, while diskANN is approximate.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/cosmos-db/nosql/","topic":"cosmos-db-nosql","type":"single","options":["flat","quantizedFlat","diskANN","spatial"],"answer":0,"setId":"bouvet:cosmos-db-nosql","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/cosmos-db-nosql.json","reviewDate":"2026-10-11"},{"id":"bouvet:cosmos-db-nosql-032","prompt":"Which system-generated field is used as a timestamp in Cosmos DB items?","explanation":"The _ts field is the system-generated timestamp in Cosmos DB items. It represents the last modified timestamp as a Unix epoch value.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/cosmos-db/nosql/","topic":"cosmos-db-nosql","type":"single","options":["_rid","_self","_ts","_etag"],"answer":2,"setId":"bouvet:cosmos-db-nosql","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/cosmos-db-nosql.json","reviewDate":"2026-10-11"},{"id":"bouvet:cosmos-db-nosql-033","prompt":"What is the purpose of the _etag field in Cosmos DB items?","explanation":"The _etag field provides a version identifier for optimistic concurrency control. It changes with every update to the item and can be used to implement optimistic concurrency patterns.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/cosmos-db/nosql/","topic":"cosmos-db-nosql","type":"single","options":["To store the item's creation timestamp","To provide a version identifier for optimistic concurrency control","To encrypt the item","To store the partition key"],"answer":1,"setId":"bouvet:cosmos-db-nosql","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/cosmos-db-nosql.json","reviewDate":"2026-10-11"},{"id":"bouvet:cosmos-db-nosql-034","prompt":"What is the Azure CLI command to create a Cosmos DB account?","explanation":"The Azure CLI command to create a Cosmos DB account is 'az cosmosdb create'. This creates the top-level Cosmos DB resource.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/cosmos-db/nosql/","topic":"cosmos-db-nosql","type":"single","options":["az cosmosdb create","az cosmos create","az database cosmosdb create","az cosmosdb account create"],"answer":0,"setId":"bouvet:cosmos-db-nosql","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/cosmos-db-nosql.json","reviewDate":"2026-10-11"},{"id":"bouvet:cosmos-db-nosql-035","prompt":"What is the Azure CLI command to create a SQL database in Cosmos DB?","explanation":"The Azure CLI command to create a SQL database in Cosmos DB is 'az cosmosdb sql database create'.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/cosmos-db/nosql/","topic":"cosmos-db-nosql","type":"single","options":["az cosmosdb sql database create","az cosmosdb database create","az sql database create","az database create"],"answer":0,"setId":"bouvet:cosmos-db-nosql","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/cosmos-db-nosql.json","reviewDate":"2026-10-11"},{"id":"bouvet:cosmos-db-nosql-036","prompt":"What is the Azure CLI command to create a container in Cosmos DB?","explanation":"The Azure CLI command to create a container in Cosmos DB is 'az cosmosdb sql container create'.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/cosmos-db/nosql/","topic":"cosmos-db-nosql","type":"single","options":["az cosmosdb sql container create","az cosmosdb container create","az sql container create","az container create"],"answer":0,"setId":"bouvet:cosmos-db-nosql","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/cosmos-db-nosql.json","reviewDate":"2026-10-11"},{"id":"bouvet:cosmos-db-nosql-037","prompt":"Which Python SDK is used for Cosmos DB for NoSQL?","explanation":"The azure-cosmos Python SDK is used for Cosmos DB for NoSQL. It provides the CosmosClient class and related functionality for interacting with Cosmos DB.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/cosmos-db/nosql/","topic":"cosmos-db-nosql","type":"single","options":["azure-cosmos","azure-documentdb","cosmos-db","pymongo"],"answer":0,"setId":"bouvet:cosmos-db-nosql","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/cosmos-db-nosql.json","reviewDate":"2026-10-11"},{"id":"bouvet:cosmos-db-nosql-038","prompt":"What method is used for point reads in Cosmos DB (reading by ID and partition key)?","explanation":"The read_item() method is used for point reads in Cosmos DB, which reads a single item by its ID and partition key. This is the most efficient read operation with the lowest RU cost.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/cosmos-db/nosql/","topic":"cosmos-db-nosql","type":"single","options":["query_items()","read_item()","get_item()","upsert_item()"],"answer":1,"setId":"bouvet:cosmos-db-nosql","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/cosmos-db-nosql.json","reviewDate":"2026-10-11"},{"id":"bouvet:cosmos-db-nosql-039","prompt":"What method is used to create or replace an item in Cosmos DB?","explanation":"upsert_item() creates an item when the id and partition-key identity does not exist, or replaces that matching item when it does.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/cosmos-db/nosql/","topic":"cosmos-db-nosql","type":"single","options":["insert_item()","create_item()","upsert_item()","replace_item()"],"answer":2,"setId":"bouvet:cosmos-db-nosql","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/cosmos-db-nosql.json","reviewDate":"2026-10-11"},{"id":"bouvet:cosmos-db-nosql-040","prompt":"What method is used for partial updates (PATCH) in Cosmos DB?","explanation":"The patch_item() method is used for partial updates in Cosmos DB. It accepts patch operations (like JSON Patch) to modify specific fields of an item without replacing the entire document.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/cosmos-db/nosql/","topic":"cosmos-db-nosql","type":"single","options":["update_item()","patch_item()","modify_item()","upsert_item()"],"answer":1,"setId":"bouvet:cosmos-db-nosql","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/cosmos-db-nosql.json","reviewDate":"2026-10-11"},{"id":"bouvet:cosmos-db-nosql-041","prompt":"What method is used to execute SQL queries in Cosmos DB?","explanation":"The query_items() method is used to execute SQL queries in Cosmos DB. It returns an iterable of query results and supports parameterized queries.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/cosmos-db/nosql/","topic":"cosmos-db-nosql","type":"single","options":["query()","execute_query()","query_items()","sql_query()"],"answer":2,"setId":"bouvet:cosmos-db-nosql","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/cosmos-db-nosql.json","reviewDate":"2026-10-11"},{"id":"bouvet:cosmos-db-nosql-042","prompt":"Which current Python SDK method reads the Azure Cosmos DB for NoSQL change feed?","explanation":"ContainerProxy.query_items_change_feed() returns an iterable of changes. The application must preserve continuation state when it uses the pull model.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/cosmos-db/nosql/","topic":"cosmos-db-nosql","type":"single","options":["read_change_feed()","get_change_feed()","query_items_change_feed()","stream_changes()"],"answer":2,"setId":"bouvet:cosmos-db-nosql","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/cosmos-db-nosql.json","reviewDate":"2026-10-11"},{"id":"bouvet:cosmos-db-nosql-043","prompt":"What is the HTTP status code returned when exceeding provisioned RU/s?","explanation":"HTTP 429 (Too Many Requests) means the request exceeded available RU/s. Current Cosmos DB SDKs honor the service's retry delay according to their retry policy; persistent throttling calls for query, partitioning, or capacity changes rather than unbounded retries.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/cosmos-db/nosql/","topic":"cosmos-db-nosql","type":"single","options":["400 Bad Request","403 Forbidden","429 Too Many Requests","500 Internal Server Error"],"answer":2,"setId":"bouvet:cosmos-db-nosql","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/cosmos-db-nosql.json","reviewDate":"2026-10-11"},{"id":"bouvet:cosmos-db-nosql-044","prompt":"Which property must ALL Cosmos DB items have?","explanation":"Every item must have a string id. The combination of id and partition-key value identifies the item, so id is unique within a logical partition rather than necessarily across the whole container.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/cosmos-db/nosql/","topic":"cosmos-db-nosql","type":"single","options":["name","id","partitionKey","timestamp"],"answer":1,"setId":"bouvet:cosmos-db-nosql","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/cosmos-db-nosql.json","reviewDate":"2026-10-11"},{"id":"bouvet:cosmos-db-nosql-045","prompt":"What is the purpose of the enable_cross_partition_query parameter in query_items()?","explanation":"Setting enable_cross_partition_query=True allows query_items() to fan a query across partitions when no partition_key is supplied. Prefer partition routing when the request is naturally partition-scoped.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/cosmos-db/nosql/","topic":"cosmos-db-nosql","type":"single","options":["To allow queries that don't filter on the partition key","To enable parallel query execution","To encrypt query results","To cache query results"],"answer":0,"setId":"bouvet:cosmos-db-nosql","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/cosmos-db-nosql.json","reviewDate":"2026-10-11"},{"id":"bouvet:cosmos-db-nosql-046","prompt":"Which of the following are valid Cosmos DB consistency levels? (Select all that apply)","explanation":"The five valid Cosmos DB consistency levels are: Strong, Bounded Staleness, Session, Consistent Prefix, and Eventual. Immediate is not a valid consistency level.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/cosmos-db/nosql/","topic":"cosmos-db-nosql","type":"multi","options":["Strong","Bounded Staleness","Session","Immediate"],"answer":[0,1,2],"choose":3,"setId":"bouvet:cosmos-db-nosql","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/cosmos-db-nosql.json","reviewDate":"2026-10-11"},{"id":"bouvet:cosmos-db-nosql-047","prompt":"Which statements describe the Azure Cosmos DB change feed? (Select all that apply)","explanation":"Every container has a change feed and consumers can process it incrementally. Latest-version mode does not capture deletes, and ordering is guaranteed only within a partition-key value.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/cosmos-db/nosql/","topic":"cosmos-db-nosql","type":"multi","options":["It is available for every container","Consumers can process it incrementally","Latest-version mode captures item deletes","Ordering is guaranteed globally across all partition-key values"],"answer":[0,1],"choose":2,"setId":"bouvet:cosmos-db-nosql","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/cosmos-db-nosql.json","reviewDate":"2026-10-11"},{"id":"bouvet:cosmos-db-nosql-048","prompt":"A scenario describes: 'A team needs to store user profiles and query them by user ID. They want the most efficient read performance.' Which should they use?","explanation":"Use read_item() with both id and the complete partition key. This avoids a query and costs 1 RU for a 1-KB item under session or eventual consistency.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/cosmos-db/nosql/","topic":"cosmos-db-nosql","type":"single","options":["Point read by ID and partition key","SQL query with WHERE clause on ID","Cross-partition query","Stored procedure"],"answer":0,"setId":"bouvet:cosmos-db-nosql","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/cosmos-db-nosql.json","reviewDate":"2026-10-11"},{"id":"bouvet:cosmos-db-nosql-049","prompt":"A scenario describes: 'A team has a container with a hot partition causing performance issues.' What is the BEST solution?","explanation":"The best solution is to create a new container with a different partition key that distributes data more evenly. A hot partition occurs when one partition receives disproportionate traffic or storage, which can be resolved by choosing a better partition key.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/cosmos-db/nosql/","topic":"cosmos-db-nosql","type":"single","options":["Increase provisioned RU/s","Create a new container with a different partition key that distributes data more evenly","Switch to Serverless mode","Enable change feed"],"answer":1,"setId":"bouvet:cosmos-db-nosql","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/cosmos-db-nosql.json","reviewDate":"2026-10-11"},{"id":"bouvet:cosmos-db-nosql-050","prompt":"A scenario describes: 'A team needs to implement real-time analytics on data changes.' Which Cosmos DB feature should they use?","explanation":"The change feed supports near-real-time processing of creates and updates. A change feed processor or Azure Functions trigger can distribute work and checkpoint progress automatically.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/cosmos-db/nosql/","topic":"cosmos-db-nosql","type":"single","options":["Vector search","Change feed","Indexing policies","Stored procedures"],"answer":1,"setId":"bouvet:cosmos-db-nosql","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/cosmos-db-nosql.json","reviewDate":"2026-10-11"},{"id":"bouvet:cosmos-db-nosql-051","prompt":"A scenario describes: 'A team needs to store LLM embeddings (1536 dimensions) and perform similarity search.' Which Cosmos DB feature should they use?","explanation":"Vector search with vector indexing is the Cosmos DB feature for storing embeddings and performing similarity search. The vector index must be configured with dimensions matching the embeddings (1536 in this case).","domain":"data","source":"https://learn.microsoft.com/en-us/azure/cosmos-db/nosql/","topic":"cosmos-db-nosql","type":"single","options":["Change feed","Vector search with vector indexing","Spatial indexing","Composite indexes"],"answer":1,"setId":"bouvet:cosmos-db-nosql","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/cosmos-db-nosql.json","reviewDate":"2026-10-11"},{"id":"bouvet:cosmos-db-nosql-052","prompt":"Put these steps in order to set up Cosmos DB and query data:","explanation":"Create the resource hierarchy first, assign the application's identity a native Cosmos DB data-plane role, then connect and query. Management-plane access alone does not grant item access.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/cosmos-db/nosql/","topic":"cosmos-db-nosql","type":"order","options":["Create a resource group","Create a Cosmos DB account","Create a database","Create a container with a partition key","Assign the client identity a Cosmos DB data role","Connect and execute a query"],"answer":["Create a resource group","Create a Cosmos DB account","Create a database","Create a container with a partition key","Assign the client identity a Cosmos DB data role","Connect and execute a query"],"setId":"bouvet:cosmos-db-nosql","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/cosmos-db-nosql.json","reviewDate":"2026-10-11"},{"id":"bouvet:cosmos-db-nosql-053","prompt":"What is the purpose of the Free Tier in Cosmos DB?","explanation":"An eligible free-tier account receives the first 1,000 RU/s and 25 GB free for the lifetime of that account. A subscription can have one free-tier account, it must be selected at account creation, and serverless accounts are not eligible.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/cosmos-db/nosql/","topic":"cosmos-db-nosql","type":"single","options":["The first 1,000 RU/s and 25 GB are free for the eligible account's lifetime","All storage and throughput are free without a limit","Every subscription can create unlimited free-tier accounts","The discount applies only to serverless accounts"],"answer":0,"setId":"bouvet:cosmos-db-nosql","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/cosmos-db-nosql.json","reviewDate":"2026-10-11"},{"id":"bouvet:cosmos-db-nosql-054","prompt":"What system-generated field is used as a unique resource identifier in Cosmos DB items?","explanation":"The _rid field is the system-generated unique resource identifier in Cosmos DB items. It is a short, unique string that identifies the resource.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/cosmos-db/nosql/","topic":"cosmos-db-nosql","type":"single","options":["_rid","_self","_ts","_etag"],"answer":0,"setId":"bouvet:cosmos-db-nosql","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/cosmos-db-nosql.json","reviewDate":"2026-10-11"},{"id":"bouvet:cosmos-db-nosql-055","prompt":"A transactional batch contains writes for two different tenantId partition-key values. Can Cosmos DB execute the whole batch atomically?","explanation":"Standard transactional batches and stored procedures are scoped to one logical partition. Writes for different partition-key values cannot be one normal transactional batch; a separately enabled distributed-transactions feature has different constraints.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/cosmos-db/nosql/","topic":"cosmos-db-nosql","type":"single","options":["No; every operation in the batch must share one logical partition","Yes; a batch can span any items in one container","Yes; if both items use Session consistency","Only when cross-partition query is enabled"],"answer":0,"setId":"bouvet:cosmos-db-nosql","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/cosmos-db-nosql.json","reviewDate":"2026-10-11"},{"id":"bouvet:cosmos-db-nosql-056","prompt":"A compliance processor must observe every update and deletion for seven days. Which change-feed configuration should you use?","explanation":"All-versions-and-deletes mode captures creates, intermediate updates, deletes, and TTL expirations within the account's continuous-backup retention window. It requires continuous backup and enabling the account feature; latest-version mode does not capture deletes.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/cosmos-db/nosql/","topic":"cosmos-db-nosql","type":"single","options":["Latest-version mode with no backup","All-versions-and-deletes mode with continuous backup and the account feature enabled","Latest-version mode with eventual consistency","A cross-partition SQL query"],"answer":1,"setId":"bouvet:cosmos-db-nosql","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/cosmos-db-nosql.json","reviewDate":"2026-10-11"},{"id":"bouvet:cosmos-db-nosql-057","prompt":"A team enabled NoSQL vector search but cannot create a vector index in a database that uses shared throughput. What should it change?","explanation":"Cosmos DB vector indexing does not support shared database throughput. Create the vector container with dedicated throughput and define its vector embedding and indexing policies at creation.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/cosmos-db/nosql/","topic":"cosmos-db-nosql","type":"single","options":["Create the vector container with dedicated throughput","Disable the ordinary range index","Change the consistency level to Strong","Use a lease container"],"answer":0,"setId":"bouvet:cosmos-db-nosql","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/cosmos-db-nosql.json","reviewDate":"2026-10-11"},{"id":"bouvet:cosmos-db-nosql-058","prompt":"Two services read and then replace the same item. The second replacement must fail if the first service already changed it. What should the second service send?","explanation":"Use optimistic concurrency: send the _etag from the version that was read as an If-Match condition. Cosmos DB rejects the write if that version is no longer current.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/cosmos-db/nosql/","topic":"cosmos-db-nosql","type":"single","options":["The original _etag in an If-Match condition","The item's _ts as the partition key","enable_cross_partition_query=True","A weaker consistency override"],"answer":0,"setId":"bouvet:cosmos-db-nosql","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/cosmos-db-nosql.json","reviewDate":"2026-10-11"},{"id":"bouvet:postgresql-pgvector-001","prompt":"What is Azure Database for PostgreSQL flexible server?","explanation":"It is Microsoft's managed PostgreSQL service. Azure operates backups, patching, storage, and optional high availability, while you choose and scale the compute and continue to use PostgreSQL SQL and clients.","domain":"data","source":"https://github.com/pgvector/pgvector","topic":"postgresql-pgvector","type":"single","options":["A fully managed relational database service based on PostgreSQL","A NoSQL document database","An in-memory cache service","A vector database only"],"answer":0,"setId":"bouvet:postgresql-pgvector","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/postgresql-pgvector.json","reviewDate":"2026-10-11"},{"id":"bouvet:postgresql-pgvector-002","prompt":"What does the pgvector extension add to PostgreSQL?","explanation":"pgvector adds vector column types, distance operators, exact search, and the HNSW and IVFFlat approximate index access methods. Azure also offers DiskANN through the separate pg_diskann extension.","domain":"data","source":"https://github.com/pgvector/pgvector","topic":"postgresql-pgvector","type":"single","options":["A vector data type and similarity search indexes","A full-text search capability","A time-series database","A graph database"],"answer":0,"setId":"bouvet:postgresql-pgvector","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/postgresql-pgvector.json","reviewDate":"2026-10-11"},{"id":"bouvet:postgresql-pgvector-003","prompt":"Which AI workload is a strong fit for Azure Database for PostgreSQL with pgvector?","explanation":"PostgreSQL with pgvector is a strong fit when vector embeddings, source text, and relational metadata need to be queried or updated together, such as tenant-filtered RAG retrieval.","domain":"data","source":"https://github.com/pgvector/pgvector","topic":"postgresql-pgvector","type":"single","options":["Storing and querying vector embeddings for AI/ML applications like RAG","High-frequency trading","Real-time analytics on time-series data","Serving static websites"],"answer":0,"setId":"bouvet:postgresql-pgvector","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/postgresql-pgvector.json","reviewDate":"2026-10-11"},{"id":"bouvet:postgresql-pgvector-004","prompt":"What is RAG in the context of AI?","explanation":"Retrieval-augmented generation retrieves relevant source context before asking a model to generate an answer. Vector similarity is a common retrieval method, but RAG can also use keyword, hybrid, or structured retrieval.","domain":"data","source":"https://github.com/pgvector/pgvector","topic":"postgresql-pgvector","type":"single","options":["Retrieval-Augmented Generation - an LLM retrieves relevant context before generating a response","Really Awesome Graphics - a rendering technique","Rapid Application Generation - a development methodology","Redundant Array of Generators - a backup system"],"answer":0,"setId":"bouvet:postgresql-pgvector","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/postgresql-pgvector.json","reviewDate":"2026-10-11"},{"id":"bouvet:postgresql-pgvector-005","prompt":"What is an embedding vector?","explanation":"An embedding is a fixed-length sequence of numeric values produced by a model. The model's intended distance metric determines how proximity should be interpreted.","domain":"data","source":"https://github.com/pgvector/pgvector","topic":"postgresql-pgvector","type":"single","options":["A fixed-length numeric representation whose geometry encodes model-learned relationships","A compressed database index","A type of encryption key","A PostgreSQL connection string"],"answer":0,"setId":"bouvet:postgresql-pgvector","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/postgresql-pgvector.json","reviewDate":"2026-10-11"},{"id":"bouvet:postgresql-pgvector-006","prompt":"An embedding model's evaluation guidance specifies cosine distance. Which metric should the PostgreSQL retrieval query use?","explanation":"Use cosine because the query metric should match the model's guidance. Cosine is common for text embeddings, but L2 or inner product can be correct for other models.","domain":"data","source":"https://github.com/pgvector/pgvector","topic":"postgresql-pgvector","type":"single","options":["Cosine distance","L2 (Euclidean) distance","Inner product","Manhattan distance"],"answer":0,"setId":"bouvet:postgresql-pgvector","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/postgresql-pgvector.json","reviewDate":"2026-10-11"},{"id":"bouvet:postgresql-pgvector-007","prompt":"What is the range of cosine distance?","explanation":"For nonzero vectors, cosine distance ranges from 0 to 2. A distance of 0 means the vectors point in the same direction; 2 means they point in opposite directions. Magnitude does not have to be identical.","domain":"data","source":"https://github.com/pgvector/pgvector","topic":"postgresql-pgvector","type":"single","options":["0 to 2, where lower values indicate more similarity","0 to 1, where higher values indicate more similarity","-1 to 1, where 1 is most similar","0 to infinity, where 0 is most similar"],"answer":0,"setId":"bouvet:postgresql-pgvector","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/postgresql-pgvector.json","reviewDate":"2026-10-11"},{"id":"bouvet:postgresql-pgvector-008","prompt":"Which pgvector operator is used for L2 (Euclidean) distance?","explanation":"The \u003c-> operator is used for L2 (Euclidean) distance calculations in pgvector.","domain":"data","source":"https://github.com/pgvector/pgvector","topic":"postgresql-pgvector","type":"single","options":["\u003c->","\u003c=>","\u003c#>","\u003c==>"],"answer":0,"setId":"bouvet:postgresql-pgvector","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/postgresql-pgvector.json","reviewDate":"2026-10-11"},{"id":"bouvet:postgresql-pgvector-009","prompt":"Which pgvector operator is used for cosine distance?","explanation":"The \u003c=> operator calculates cosine distance. Use it when cosine is the metric validated for the embedding model; it is common for semantic retrieval but is not universally correct.","domain":"data","source":"https://github.com/pgvector/pgvector","topic":"postgresql-pgvector","type":"single","options":["\u003c->","\u003c=>","\u003c#>","\u003c==>"],"answer":1,"setId":"bouvet:postgresql-pgvector","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/postgresql-pgvector.json","reviewDate":"2026-10-11"},{"id":"bouvet:postgresql-pgvector-010","prompt":"You need an approximate pgvector index with no training step and a strong speed/recall trade-off. Which index should you evaluate first?","explanation":"HNSW has no training step and usually offers a better speed/recall trade-off than IVFFlat, at the cost of slower builds and more memory. Benchmark it rather than treating it as universally best.","domain":"data","source":"https://github.com/pgvector/pgvector","topic":"postgresql-pgvector","type":"single","options":["HNSW","IVFFlat","Exact scan","B-tree"],"answer":0,"setId":"bouvet:postgresql-pgvector","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/postgresql-pgvector.json","reviewDate":"2026-10-11"},{"id":"bouvet:postgresql-pgvector-011","prompt":"What does HNSW stand for?","explanation":"HNSW stands for Hierarchical Navigable Small World, which is a graph-based algorithm for approximate nearest neighbor search.","domain":"data","source":"https://github.com/pgvector/pgvector","topic":"postgresql-pgvector","type":"single","options":["Hierarchical Navigable Small World","High-performance Nearest Neighbor Search","Hybrid Non-sequential Search","Heap-based Nearest Neighbor"],"answer":0,"setId":"bouvet:postgresql-pgvector","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/postgresql-pgvector.json","reviewDate":"2026-10-11"},{"id":"bouvet:postgresql-pgvector-012","prompt":"Which Azure-specific vector index is provided by the separate pg_diskann extension rather than by pgvector itself?","explanation":"DiskANN is supplied by Azure's pg_diskann extension. pgvector itself provides HNSW and IVFFlat; IVF + HNSW is not a pgvector access method.","domain":"data","source":"https://github.com/pgvector/pgvector","topic":"postgresql-pgvector","type":"single","options":["DiskANN","HNSW","IVFFlat","IVF + HNSW"],"answer":0,"setId":"bouvet:postgresql-pgvector","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/postgresql-pgvector.json","reviewDate":"2026-10-11"},{"id":"bouvet:postgresql-pgvector-013","prompt":"What SQL syntax creates a vector column with 1536 dimensions?","explanation":"The correct syntax is embedding vector(1536), where vector is the pgvector data type and 1536 is the number of dimensions.","domain":"data","source":"https://github.com/pgvector/pgvector","topic":"postgresql-pgvector","type":"single","options":["embedding vector(1536)","embedding FLOAT[1536]","embedding VECTOR(1536)","embedding ARRAY[1536]"],"answer":0,"setId":"bouvet:postgresql-pgvector","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/postgresql-pgvector.json","reviewDate":"2026-10-11"},{"id":"bouvet:postgresql-pgvector-014","prompt":"Which operator class must be used in an index for cosine distance queries?","explanation":"The index must use vector_cosine_ops operator class to support cosine distance queries with the \u003c=> operator.","domain":"data","source":"https://github.com/pgvector/pgvector","topic":"postgresql-pgvector","type":"single","options":["vector_cosine_ops","vector_l2_ops","vector_ip_ops","vector_ops"],"answer":0,"setId":"bouvet:postgresql-pgvector","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/postgresql-pgvector.json","reviewDate":"2026-10-11"},{"id":"bouvet:postgresql-pgvector-015","prompt":"What is the correct SQL to create an HNSW index for cosine distance?","explanation":"The HNSW index uses vector_cosine_ops for \u003c=> queries. Its build options are m and ef_construction; hnsw.ef_search is a separate query-time setting, and ef is not a valid index option.","domain":"data","source":"https://github.com/pgvector/pgvector","topic":"postgresql-pgvector","type":"single","options":["CREATE INDEX ON items USING hnsw (embedding vector_cosine_ops) WITH (m = 16, ef_construction = 64);","CREATE INDEX ON items USING hnsw (embedding vector_l2_ops) WITH (m = 16, ef = 64);","CREATE INDEX ON items USING ivfflat (embedding vector_cosine_ops) WITH (m = 16);","CREATE INDEX ON items USING gin (embedding vector_cosine_ops);"],"answer":0,"setId":"bouvet:postgresql-pgvector","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/postgresql-pgvector.json","reviewDate":"2026-10-11"},{"id":"bouvet:postgresql-pgvector-016","prompt":"What happens if the index operator class does not match the query operator?","explanation":"An index built for a different operator class cannot support that distance ordering. PostgreSQL can still return correct results with an exact plan, often a sequential scan, but it cannot use that vector index for the mismatched operator.","domain":"data","source":"https://github.com/pgvector/pgvector","topic":"postgresql-pgvector","type":"single","options":["That index cannot support the ordering, so the planner may use an exact scan","The query will return incorrect results","PostgreSQL will automatically convert between operators","The query will fail with an error"],"answer":0,"setId":"bouvet:postgresql-pgvector","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/postgresql-pgvector.json","reviewDate":"2026-10-11"},{"id":"bouvet:postgresql-pgvector-017","prompt":"Which SQL query finds the 5 nearest neighbors using cosine distance?","explanation":"The \u003c=> operator calculates cosine distance, and ORDER BY ... ASC LIMIT 5 returns the 5 rows with the smallest (most similar) distances.","domain":"data","source":"https://github.com/pgvector/pgvector","topic":"postgresql-pgvector","type":"single","options":["SELECT * FROM items ORDER BY embedding \u003c=> '[0.1,0.2,0.3]' ASC LIMIT 5;","SELECT * FROM items ORDER BY embedding \u003c-> '[0.1,0.2,0.3]' ASC LIMIT 5;","SELECT * FROM items WHERE embedding \u003c=> '[0.1,0.2,0.3]' LIMIT 5;","SELECT * FROM items ORDER BY embedding \u003c=> '[0.1,0.2,0.3]' DESC LIMIT 5;"],"answer":0,"setId":"bouvet:postgresql-pgvector","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/postgresql-pgvector.json","reviewDate":"2026-10-11"},{"id":"bouvet:postgresql-pgvector-018","prompt":"How do you combine vector search with metadata filtering (e.g., filter by category)?","explanation":"Express metadata restrictions in the WHERE clause and create suitable relational indexes for common filters. PostgreSQL's planner chooses the execution plan; with an approximate vector index, selective filters can require iterative scans or additional tuning to return enough matches.","domain":"data","source":"https://github.com/pgvector/pgvector","topic":"postgresql-pgvector","type":"single","options":["Add a WHERE clause with the filter conditions","Use a JOIN with a separate table","Create a separate index for metadata","Use the index parameter in the vector query"],"answer":0,"setId":"bouvet:postgresql-pgvector","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/postgresql-pgvector.json","reviewDate":"2026-10-11"},{"id":"bouvet:postgresql-pgvector-019","prompt":"What is the purpose of the 'm' parameter in HNSW indexes?","explanation":"The m parameter controls the maximum graph connections per point per layer. Raising it can improve recall, but increases index size, build time, and memory use.","domain":"data","source":"https://github.com/pgvector/pgvector","topic":"postgresql-pgvector","type":"single","options":["Controls the maximum graph connections per point per layer","Controls the number of clusters","Controls the maximum number of vectors","Controls the query timeout"],"answer":0,"setId":"bouvet:postgresql-pgvector","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/postgresql-pgvector.json","reviewDate":"2026-10-11"},{"id":"bouvet:postgresql-pgvector-020","prompt":"What does the hnsw.ef_search setting control?","explanation":"hnsw.ef_search is a session or transaction setting for query-time candidate exploration. A higher value can improve recall but increases query work. ef_construction is the separate build-time option.","domain":"data","source":"https://github.com/pgvector/pgvector","topic":"postgresql-pgvector","type":"single","options":["The query-time candidate list, trading more work for potentially higher recall","The vector column's dimensions","The number of database replicas","The index build memory allocation"],"answer":0,"setId":"bouvet:postgresql-pgvector","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/postgresql-pgvector.json","reviewDate":"2026-10-11"},{"id":"bouvet:postgresql-pgvector-021","prompt":"What does the lists option control in an IVFFlat index?","explanation":"lists controls the IVFFlat partitioning created during index training. Query-time ivfflat.probes controls how many lists are searched; lists and probes must be tuned together for the data and recall target.","domain":"data","source":"https://github.com/pgvector/pgvector","topic":"postgresql-pgvector","type":"single","options":["The number of clusters into which vectors are partitioned","The HNSW links per graph node","The number of query results","The connection-pool size"],"answer":0,"setId":"bouvet:postgresql-pgvector","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/postgresql-pgvector.json","reviewDate":"2026-10-11"},{"id":"bouvet:postgresql-pgvector-022","prompt":"A steady production vector workload needs balanced compute and memory, and measurements do not show a memory bottleneck. Which tier is the most reasonable starting point?","explanation":"General Purpose is the balanced production starting point when measurements do not justify extra memory. Memory Optimized can help when the hot data and indexes are memory constrained; Burstable is aimed at low-concurrency, nonsustained demand.","domain":"data","source":"https://github.com/pgvector/pgvector","topic":"postgresql-pgvector","type":"single","options":["Memory Optimized","Burstable","General Purpose","Basic"],"answer":2,"setId":"bouvet:postgresql-pgvector","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/postgresql-pgvector.json","reviewDate":"2026-10-11"},{"id":"bouvet:postgresql-pgvector-023","prompt":"A table has an embedding vector(3072) column. What happens if you try to create a pgvector HNSW index on that vector column?","explanation":"Current pgvector HNSW and IVFFlat indexes support vector columns up to 2,000 dimensions. Choose an intentional reduced embedding size, evaluate halfvec with its precision trade-off, use exact search, or evaluate an index with different limits.","domain":"data","source":"https://github.com/pgvector/pgvector","topic":"postgresql-pgvector","type":"single","options":["The index creation fails because indexed vector columns are limited to 2,000 dimensions","PostgreSQL silently truncates every vector to 2,000 dimensions","The index is automatically converted to a B-tree","HNSW always supports 16,000 vector dimensions"],"answer":0,"setId":"bouvet:postgresql-pgvector","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/postgresql-pgvector.json","reviewDate":"2026-10-11"},{"id":"bouvet:postgresql-pgvector-024","prompt":"Which Azure Database for PostgreSQL flexible server tier does NOT support built-in high availability?","explanation":"Burstable does not support built-in high availability. General Purpose and Memory Optimized support same-zone or, in supported regions, zone-redundant high availability.","domain":"data","source":"https://github.com/pgvector/pgvector","topic":"postgresql-pgvector","type":"single","options":["Burstable","General Purpose","Memory Optimized","Both General Purpose and Memory Optimized"],"answer":0,"setId":"bouvet:postgresql-pgvector","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/postgresql-pgvector.json","reviewDate":"2026-10-11"},{"id":"bouvet:postgresql-pgvector-025","prompt":"Which import uses the current Psycopg 3 PostgreSQL driver?","explanation":"Psycopg 3 is installed from the psycopg package and imported as psycopg. psycopg2 is the older major version with different context-manager and pooling behavior.","domain":"data","source":"https://github.com/pgvector/pgvector","topic":"postgresql-pgvector","type":"single","options":["import psycopg","import psycopg2","import redis","import azure.cosmos"],"answer":0,"setId":"bouvet:postgresql-pgvector","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/postgresql-pgvector.json","reviewDate":"2026-10-11"},{"id":"bouvet:postgresql-pgvector-026","prompt":"A client has the correct trusted root certificate and must encrypt the connection and verify the Azure PostgreSQL server's hostname. Which libpq setting provides that stronger validation?","explanation":"sslmode=verify-full encrypts the connection, validates the certificate chain, and checks the hostname. sslmode=require encrypts traffic but does not provide the same server-identity verification.","domain":"data","source":"https://github.com/pgvector/pgvector","topic":"postgresql-pgvector","type":"single","options":["sslmode=verify-full","sslmode=disable","port=1433","sslmode=allow"],"answer":0,"setId":"bouvet:postgresql-pgvector","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/postgresql-pgvector.json","reviewDate":"2026-10-11"},{"id":"bouvet:postgresql-pgvector-027","prompt":"What is the purpose of connection pooling?","explanation":"Connection pooling maintains a pool of open database connections that can be reused, avoiding the overhead of establishing a new connection (SSL handshake, authentication, etc.) for each query.","domain":"data","source":"https://github.com/pgvector/pgvector","topic":"postgresql-pgvector","type":"single","options":["To reuse connections instead of creating a new one for each query, reducing overhead","To cache query results","To encrypt connections","To load balance across multiple servers"],"answer":0,"setId":"bouvet:postgresql-pgvector","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/postgresql-pgvector.json","reviewDate":"2026-10-11"},{"id":"bouvet:postgresql-pgvector-028","prompt":"Which Psycopg 3 class provides a bounded, thread-safe synchronous connection pool?","explanation":"psycopg_pool.ConnectionPool is Psycopg 3's synchronous pool and can serve multiple threads. Configure min_size and max_size so the application reuses a bounded number of server connections.","domain":"data","source":"https://github.com/pgvector/pgvector","topic":"postgresql-pgvector","type":"single","options":["psycopg_pool.ConnectionPool","psycopg2.pool.SimpleConnectionPool","psycopg.Cursor","redis.ConnectionPool"],"answer":0,"setId":"bouvet:postgresql-pgvector","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/postgresql-pgvector.json","reviewDate":"2026-10-11"},{"id":"bouvet:postgresql-pgvector-029","prompt":"Which name must be placed in Azure's extension allowlist before CREATE EXTENSION can install pgvector?","explanation":"The project is called pgvector, but its binary and PostgreSQL extension name are vector. Set azure.extensions to include vector, then run CREATE EXTENSION vector in each database that needs it.","domain":"data","source":"https://github.com/pgvector/pgvector","topic":"postgresql-pgvector","type":"single","options":["vector","pgvector","hnsw","azure_vector"],"answer":0,"setId":"bouvet:postgresql-pgvector","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/postgresql-pgvector.json","reviewDate":"2026-10-11"},{"id":"bouvet:postgresql-pgvector-030","prompt":"What SQL command installs the pgvector extension?","explanation":"CREATE EXTENSION vector; is the standard PostgreSQL command to install the pgvector extension.","domain":"data","source":"https://github.com/pgvector/pgvector","topic":"postgresql-pgvector","type":"single","options":["CREATE EXTENSION vector;","INSTALL EXTENSION vector;","ENABLE EXTENSION vector;","ADD EXTENSION vector;"],"answer":0,"setId":"bouvet:postgresql-pgvector","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/postgresql-pgvector.json","reviewDate":"2026-10-11"},{"id":"bouvet:postgresql-pgvector-031","prompt":"Which Azure CLI command creates a current Azure Database for PostgreSQL flexible server?","explanation":"Use az postgres flexible-server create. The az postgres server command group belongs to the retired Single Server deployment model.","domain":"data","source":"https://github.com/pgvector/pgvector","topic":"postgresql-pgvector","type":"single","options":["az postgres flexible-server create","az postgres server create","az sql server create","az database postgres create"],"answer":0,"setId":"bouvet:postgresql-pgvector","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/postgresql-pgvector.json","reviewDate":"2026-10-11"},{"id":"bouvet:postgresql-pgvector-032","prompt":"Which Azure CLI command creates a database on an existing PostgreSQL flexible server?","explanation":"Use az postgres flexible-server db create with the resource group, server name, and database name.","domain":"data","source":"https://github.com/pgvector/pgvector","topic":"postgresql-pgvector","type":"single","options":["az postgres flexible-server db create","az postgres database create","az postgres flexible-server create","az sql database create"],"answer":0,"setId":"bouvet:postgresql-pgvector","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/postgresql-pgvector.json","reviewDate":"2026-10-11"},{"id":"bouvet:postgresql-pgvector-033","prompt":"What is the default port for PostgreSQL?","explanation":"PostgreSQL uses port 5432 by default. Azure Database for PostgreSQL also uses this port.","domain":"data","source":"https://github.com/pgvector/pgvector","topic":"postgresql-pgvector","type":"single","options":["5432","1433","3306","6379"],"answer":0,"setId":"bouvet:postgresql-pgvector","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/postgresql-pgvector.json","reviewDate":"2026-10-11"},{"id":"bouvet:postgresql-pgvector-034","prompt":"Which pgvector operator returns the negative inner product so an ascending index scan can be used?","explanation":"The \u003c#> operator returns the negative inner product. Larger positive inner products therefore become smaller returned values and sort first in ascending order.","domain":"data","source":"https://github.com/pgvector/pgvector","topic":"postgresql-pgvector","type":"single","options":["\u003c#>","\u003c->","\u003c=>","\u003c==>"],"answer":0,"setId":"bouvet:postgresql-pgvector","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/postgresql-pgvector.json","reviewDate":"2026-10-11"},{"id":"bouvet:postgresql-pgvector-035","prompt":"What is the relationship between cosine similarity and cosine distance in pgvector?","explanation":"Cosine distance is 1 - cosine similarity. For nonzero vectors it ranges from 0 (same direction, similarity 1) to 2 (opposite directions, similarity -1).","domain":"data","source":"https://github.com/pgvector/pgvector","topic":"postgresql-pgvector","type":"single","options":["Cosine distance = 1 - cosine similarity","Cosine distance = cosine similarity","Cosine distance = 2 - cosine similarity","They are unrelated"],"answer":0,"setId":"bouvet:postgresql-pgvector","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/postgresql-pgvector.json","reviewDate":"2026-10-11"},{"id":"bouvet:postgresql-pgvector-036","prompt":"A deployment emits 1,024-element embeddings, but the PostgreSQL column is vector(1536). What should you do?","explanation":"A fixed-dimension vector column rejects vectors of another length. Make the model deployment, stored column, index, and query vectors agree; changing embedding size normally requires re-embedding and rebuilding the index.","domain":"data","source":"https://github.com/pgvector/pgvector","topic":"postgresql-pgvector","type":"single","options":["Change the schema or model output so stored and query vectors use the same intentional dimension","Pad every vector without validating retrieval quality","Rely on pgvector to infer a different size for each row","Change only the HNSW m option"],"answer":0,"setId":"bouvet:postgresql-pgvector","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/postgresql-pgvector.json","reviewDate":"2026-10-11"},{"id":"bouvet:postgresql-pgvector-037","prompt":"What is the purpose of metadata filtering in RAG?","explanation":"Metadata filtering (e.g., by category, date, author) restricts the vector similarity search to a relevant subset, improving both performance and result quality in RAG applications.","domain":"data","source":"https://github.com/pgvector/pgvector","topic":"postgresql-pgvector","type":"single","options":["To restrict similarity search to a subset of vectors based on attributes","To encrypt the vectors","To compress the vectors","To normalize the vectors"],"answer":0,"setId":"bouvet:postgresql-pgvector","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/postgresql-pgvector.json","reviewDate":"2026-10-11"},{"id":"bouvet:postgresql-pgvector-038","prompt":"Which of the following is NOT a benefit of using PostgreSQL + pgvector for RAG?","explanation":"The pgvector extension itself does not generate embeddings. The application or a separate model integration must create them before pgvector can store and compare them.","domain":"data","source":"https://github.com/pgvector/pgvector","topic":"postgresql-pgvector","type":"single","options":["Combining vector search with SQL filtering in a single query","Full transaction support (ACID compliance)","Automatic embedding generation","Storing vectors alongside relational data"],"answer":2,"setId":"bouvet:postgresql-pgvector","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/postgresql-pgvector.json","reviewDate":"2026-10-11"},{"id":"bouvet:postgresql-pgvector-039","prompt":"Measurements show that a production vector index's hot pages do not fit in memory. Which compute tier should you evaluate?","explanation":"Memory Optimized provides more memory per vCore and is worth evaluating for a measured memory bottleneck. It is not automatically fastest for every workload; CPU, I/O, concurrency, and cost still require benchmarking.","domain":"data","source":"https://github.com/pgvector/pgvector","topic":"postgresql-pgvector","type":"single","options":["Memory Optimized","Burstable","General Purpose only","Every tier has identical memory per vCore"],"answer":0,"setId":"bouvet:postgresql-pgvector","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/postgresql-pgvector.json","reviewDate":"2026-10-11"},{"id":"bouvet:postgresql-pgvector-040","prompt":"Which command both executes a representative vector query and reports its plan and buffer activity?","explanation":"EXPLAIN (ANALYZE, BUFFERS) executes the query and reports the actual plan, timing, and buffer activity. Plain EXPLAIN estimates a plan without running the query.","domain":"data","source":"https://github.com/pgvector/pgvector","topic":"postgresql-pgvector","type":"single","options":["EXPLAIN (ANALYZE, BUFFERS)","ANALYZE","CHECK INDEX","SHOW INDEX"],"answer":0,"setId":"bouvet:postgresql-pgvector","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/postgresql-pgvector.json","reviewDate":"2026-10-11"},{"id":"bouvet:postgresql-pgvector-041","prompt":"Which are pgvector approximate index access methods? (Select all that apply)","explanation":"pgvector provides HNSW and IVFFlat. DiskANN is supplied by Azure's separate pg_diskann extension, and an exact sequential scan is a search plan rather than an index type.","domain":"data","source":"https://github.com/pgvector/pgvector","topic":"postgresql-pgvector","type":"multi","options":["HNSW","IVFFlat","DiskANN","Exact sequential scan"],"answer":[0,1],"choose":2,"setId":"bouvet:postgresql-pgvector","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/postgresql-pgvector.json","reviewDate":"2026-10-11"},{"id":"bouvet:postgresql-pgvector-042","prompt":"Which of the following are valid pgvector operators? (Select all that apply)","explanation":"The listed valid operators are \u003c-> for L2 distance, \u003c=> for cosine distance, \u003c#> for negative inner product, and \u003c+> for L1 distance. \u003c==> is not a pgvector operator.","domain":"data","source":"https://github.com/pgvector/pgvector","topic":"postgresql-pgvector","type":"multi","options":["\u003c-> (L2 distance)","\u003c=> (cosine distance)","\u003c#> (negative inner product)","\u003c+> (L1 distance)","\u003c==> (exact match)"],"answer":[0,1,2,3],"choose":4,"setId":"bouvet:postgresql-pgvector","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/postgresql-pgvector.json","reviewDate":"2026-10-11","reviewNote":"Corrected the negative sign of the inner-product operator."},{"id":"bouvet:postgresql-pgvector-043","prompt":"Which of the following are benefits of using Azure Database for PostgreSQL + pgvector for RAG? (Select all that apply)","explanation":"Benefits include: combined vector + metadata filtering, ACID compliance, and having both relational data and vectors in one database. Embedding generation is NOT automatic and requires external models.","domain":"data","source":"https://github.com/pgvector/pgvector","topic":"postgresql-pgvector","type":"multi","options":["Combined vector and metadata filtering in SQL","ACID compliance and transaction support","Automatic embedding generation from text","No need to manage separate vector database"],"answer":[0,1,3],"choose":3,"setId":"bouvet:postgresql-pgvector","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/postgresql-pgvector.json","reviewDate":"2026-10-11"},{"id":"bouvet:postgresql-pgvector-044","prompt":"A new sample follows the current guide and installs psycopg[binary,pool]. Which module should it import to open a database connection?","explanation":"The current Psycopg 3 package is imported as psycopg. The optional pool dependency exposes psycopg_pool for bounded connection pools.","domain":"data","source":"https://github.com/pgvector/pgvector","topic":"postgresql-pgvector","type":"single","options":["psycopg","psycopg2","asyncpg","redis"],"answer":0,"setId":"bouvet:postgresql-pgvector","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/postgresql-pgvector.json","reviewDate":"2026-10-11"},{"id":"bouvet:postgresql-pgvector-045","prompt":"How should you choose a flexible-server SKU for a vector workload?","explanation":"Vector count alone cannot determine a SKU. Benchmark representative dimensions, index type, filters, concurrency, recall target, ingestion, cache behavior, CPU, memory, storage IOPS, and throughput, then choose a current flexible-server SKU.","domain":"data","source":"https://github.com/pgvector/pgvector","topic":"postgresql-pgvector","type":"single","options":["Measure dimension, index, filters, concurrency, recall, CPU, memory, and I/O, then select a current SKU","Always use a retired GP_Gen5_4 SKU below 100,000 vectors","Always use Memory Optimized regardless of workload","Size only from the number of rows"],"answer":0,"setId":"bouvet:postgresql-pgvector","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/postgresql-pgvector.json","reviewDate":"2026-10-11"},{"id":"bouvet:postgresql-pgvector-046","prompt":"What two steps enable pgvector on Azure Database for PostgreSQL flexible server?","explanation":"Azure first requires vector in the server's azure.extensions allowlist. CREATE EXTENSION vector then installs it separately in each database that uses vector types and operators.","domain":"data","source":"https://github.com/pgvector/pgvector","topic":"postgresql-pgvector","type":"single","options":["Allowlist vector in azure.extensions, then run CREATE EXTENSION vector in each target database","Install only the Python pgvector package","Run CREATE INDEX before creating the extension","Enable the Redis RediSearch module"],"answer":0,"setId":"bouvet:postgresql-pgvector","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/postgresql-pgvector.json","reviewDate":"2026-10-11"},{"id":"bouvet:postgresql-pgvector-047","prompt":"Which PostgreSQL mechanism is normally the most efficient starting point for bulk-loading a large vector corpus?","explanation":"COPY is PostgreSQL's bulk-loading mechanism and avoids the round trips of individual inserts. Load representative data before building IVFFlat, and often before building any large ANN index.","domain":"data","source":"https://github.com/pgvector/pgvector","topic":"postgresql-pgvector","type":"single","options":["COPY","One INSERT and commit per row","SELECT for every vector","A Redis pipeline"],"answer":0,"setId":"bouvet:postgresql-pgvector","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/postgresql-pgvector.json","reviewDate":"2026-10-11"},{"id":"bouvet:postgresql-pgvector-048","prompt":"A team increased flexible-server storage for an index build and now wants to shrink the allocated storage. What should it expect?","explanation":"Flexible-server storage capacity can be increased but not later reduced. Plan headroom and cost before scaling; deleting data or an index does not lower the configured allocation.","domain":"data","source":"https://github.com/pgvector/pgvector","topic":"postgresql-pgvector","type":"single","options":["Allocated storage can be increased but cannot later be shrunk","Storage always shrinks automatically after VACUUM","Changing to Burstable shrinks storage","Dropping the index immediately reduces the allocated storage setting"],"answer":0,"setId":"bouvet:postgresql-pgvector","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/postgresql-pgvector.json","reviewDate":"2026-10-11"},{"id":"bouvet:postgresql-pgvector-049","prompt":"An HNSW index build reports that its graph no longer fits in maintenance_work_mem. What is the sound response?","explanation":"Sufficient maintenance_work_mem can speed an HNSW build, but an excessive value risks memory pressure. Increase it within measured capacity and monitor progress; there is no universal HNSW-to-raw-data size multiplier.","domain":"data","source":"https://github.com/pgvector/pgvector","topic":"postgresql-pgvector","type":"single","options":["Increase maintenance_work_mem only within available memory and monitor the build","Set maintenance_work_mem larger than all server RAM","Change the query operator without rebuilding","Open more client connections"],"answer":0,"setId":"bouvet:postgresql-pgvector","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/postgresql-pgvector.json","reviewDate":"2026-10-11"},{"id":"bouvet:postgresql-pgvector-050","prompt":"What best practice should you follow for connection management in a production application?","explanation":"Connection pooling is the best practice for production applications as it reuses connections, avoiding the overhead of establishing a new connection (SSL, authentication) for each query.","domain":"data","source":"https://github.com/pgvector/pgvector","topic":"postgresql-pgvector","type":"single","options":["Use connection pooling","Create a new connection for each query","Use a single global connection","Never close connections"],"answer":0,"setId":"bouvet:postgresql-pgvector","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/postgresql-pgvector.json","reviewDate":"2026-10-11"},{"id":"bouvet:postgresql-pgvector-051","prompt":"An HNSW query requests 10 tenant-filtered matches but sometimes returns fewer because the filter removes approximate candidates. What should you evaluate first?","explanation":"Approximate search and selective filters can leave too few qualifying candidates. Current pgvector iterative scans can continue scanning; increasing hnsw.ef_search or using partitioning/exact search for a selective subset are other measured options. Do not remove an access boundary.","domain":"data","source":"https://github.com/pgvector/pgvector","topic":"postgresql-pgvector","type":"single","options":["Enable/tune iterative scans or raise the query-time candidate search setting","Remove the tenant filter","Change the primary key to the embedding","Create a new connection for every query"],"answer":0,"setId":"bouvet:postgresql-pgvector","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/postgresql-pgvector.json","reviewDate":"2026-10-11"},{"id":"bouvet:postgresql-pgvector-052","prompt":"A query orders by embedding \u003c=> $1, but the only vector index uses vector_l2_ops. What should you change to make a cosine index usable?","explanation":"The \u003c=> cosine operator pairs with vector_cosine_ops. An L2 operator class supports \u003c-> instead, so PostgreSQL cannot use that index for cosine ordering.","domain":"data","source":"https://github.com/pgvector/pgvector","topic":"postgresql-pgvector","type":"single","options":["Build the index with vector_cosine_ops","Reverse the ORDER BY direction","Change LIMIT to OFFSET","Use a B-tree on the vector"],"answer":0,"setId":"bouvet:postgresql-pgvector","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/postgresql-pgvector.json","reviewDate":"2026-10-11"},{"id":"bouvet:postgresql-pgvector-053","prompt":"A connection-heavy service uses General Purpose flexible server and thousands of short transactions. Which change reduces server connection overhead?","explanation":"Built-in PgBouncer pools server connections and listens on port 6432. Azure uses transaction pooling by default, so test session state, temporary tables, settings, and prepared-statement behavior before production use.","domain":"data","source":"https://github.com/pgvector/pgvector","topic":"postgresql-pgvector","type":"single","options":["Enable built-in PgBouncer and test the app on port 6432","Open a new direct port-5432 connection for every statement","Increase vector dimensions","Disable TLS"],"answer":0,"setId":"bouvet:postgresql-pgvector","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/02-data-services/postgresql-pgvector.json","reviewDate":"2026-10-11"},{"id":"bouvet:azure-functions-001","prompt":"Which Azure service allows you to run code in response to events without managing servers?","explanation":"Azure Functions is Azure's serverless compute service: the platform runs event-driven code and manages the infrastructure. Consumption options meter on-demand executions; Premium, Dedicated, and configured always-ready capacity also charge for allocated capacity.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/azure-functions/functions-overview","topic":"azure-functions","type":"single","options":["Azure Virtual Machines","Azure Functions","Azure Container Instances","Azure Kubernetes Service"],"answer":1,"setId":"bouvet:azure-functions","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/03-connect-consume/azure-functions.json","reviewDate":"2026-10-11"},{"id":"bouvet:azure-functions-002","prompt":"In the Python v1 programming model, which file defines the trigger and bindings for one function?","explanation":"In Python v1, function.json configures one function's trigger and input/output bindings, while host.json applies globally. In Python v2, you author decorators in function_app.py or a registered blueprint instead of authoring function.json.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/azure-functions/functions-overview","topic":"azure-functions","type":"single","options":["host.json","function.json","app.json","trigger.json"],"answer":1,"setId":"bouvet:azure-functions","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/03-connect-consume/azure-functions.json","reviewDate":"2026-10-11"},{"id":"bouvet:azure-functions-003","prompt":"Which legacy hosting plan scales to zero, meters executions on demand, and has a hard 10-minute function timeout?","explanation":"The classic Consumption plan scales to zero and doesn't charge for function execution while idle, although its required Storage account and other connected resources can still cost money. Its function timeout defaults to five minutes and has a hard ten-minute maximum. Flex Consumption also scales to zero, but it is a different plan with optional always-ready capacity and an unbounded configured function timeout.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/azure-functions/functions-overview","topic":"azure-functions","type":"single","options":["Premium","Dedicated (App Service Plan)","Consumption","Basic"],"answer":2,"setId":"bouvet:azure-functions","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/03-connect-consume/azure-functions.json","reviewDate":"2026-10-11"},{"id":"bouvet:azure-functions-004","prompt":"What is the default execution timeout for a classic Consumption-plan function?","explanation":"Consumption-plan functions time out after five minutes by default, extendable to a maximum of ten minutes through functionTimeout in host.json. Flex Consumption and Premium default to 30 minutes and can be configured with no enforced function-timeout maximum; Dedicated can do so with Always On. Platform lifecycle events can still end an execution.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/azure-functions/functions-overview","topic":"azure-functions","type":"single","options":["1 minute","5 minutes","10 minutes","60 minutes"],"answer":1,"setId":"bouvet:azure-functions","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/03-connect-consume/azure-functions.json","reviewDate":"2026-10-11"},{"id":"bouvet:azure-functions-005","prompt":"Which trigger should you use to process files automatically when they are uploaded to Azure Blob Storage?","explanation":"The Blob Storage trigger automatically invokes your function when a new blob is created or updated in a specified container.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/azure-functions/functions-overview","topic":"azure-functions","type":"single","options":["HTTP trigger","Queue trigger","Blob trigger","Timer trigger"],"answer":2,"setId":"bouvet:azure-functions","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/03-connect-consume/azure-functions.json","reviewDate":"2026-10-11"},{"id":"bouvet:azure-functions-006","prompt":"What must every Azure Function App have, regardless of which triggers it uses?","explanation":"Every Azure Function App requires a Storage account for host state and keys. Selected plans, deployment methods, and extensions can also use it for deployment artifacts, diagnostic data, trigger state, or Durable Functions state. It is required even for an app that has only HTTP triggers.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/azure-functions/functions-overview","topic":"azure-functions","type":"single","options":["A Cosmos DB account","A Storage account","An Application Insights resource","A Key Vault"],"answer":1,"setId":"bouvet:azure-functions","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/03-connect-consume/azure-functions.json","reviewDate":"2026-10-11"},{"id":"bouvet:azure-functions-007","prompt":"Which of these are valid triggers for Azure Functions? (Select all that apply)","explanation":"Azure Functions has trigger bindings for HTTP, Queue Storage, Service Bus, and SignalR Service. A virtual-machine lifecycle action is not itself a Functions trigger binding; when an Azure resource emits a matching Event Grid resource event, you can route that event through an Event Grid trigger instead.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/azure-functions/functions-overview","topic":"azure-functions","type":"multi","options":["HTTP","Queue Storage","Service Bus","SignalR","Virtual Machine start"],"answer":[0,1,2,3],"choose":4,"setId":"bouvet:azure-functions","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/03-connect-consume/azure-functions.json","reviewDate":"2026-10-11"},{"id":"bouvet:azure-functions-008","prompt":"Which hosting plan does NOT support VNet integration?","explanation":"The classic Consumption plan is the only plan without VNet integration - functions on it cannot reach resources inside a virtual network. Flex Consumption, Premium and Dedicated all support it. (Flex Consumption is the newer serverless plan: it still scales to zero, but adds VNet support and always-ready instances.)","domain":"services","source":"https://learn.microsoft.com/en-us/azure/azure-functions/functions-overview","topic":"azure-functions","type":"single","options":["Flex Consumption","Premium","Dedicated (App Service Plan)","Consumption"],"answer":3,"setId":"bouvet:azure-functions","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/03-connect-consume/azure-functions.json","reviewDate":"2026-10-11"},{"id":"bouvet:azure-functions-009","prompt":"How do you access application settings (configuration) in a Python Azure Function?","explanation":"Application settings are injected as environment variables. In Python, use os.environ.get('SettingName') to access them.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/azure-functions/functions-overview","topic":"azure-functions","type":"single","options":["settings.get('name')","os.environ.get('name')","config['name']","app.settings.name"],"answer":1,"setId":"bouvet:azure-functions","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/03-connect-consume/azure-functions.json","reviewDate":"2026-10-11"},{"id":"bouvet:azure-functions-010","prompt":"Which file contains global configuration for all functions in a Function App?","explanation":"host.json contains global settings that apply to all functions in the app, such as version, timeout, retry policies, and logging configuration. function.json configures individual functions.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/azure-functions/functions-overview","topic":"azure-functions","type":"single","options":["function.json","app.json","host.json","settings.json"],"answer":2,"setId":"bouvet:azure-functions","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/03-connect-consume/azure-functions.json","reviewDate":"2026-10-11"},{"id":"bouvet:azure-functions-011","prompt":"What is a 'binding' in Azure Functions?","explanation":"A binding is a declarative connection to another service. Input bindings read data into your function, output bindings write data from your function. Bindings eliminate boilerplate connection code.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/azure-functions/functions-overview","topic":"azure-functions","type":"single","options":["A connection between a function and another Azure service for input or output","A way to tie multiple functions together in sequence","A type of trigger that can be used multiple times","A deployment slot for staging functions"],"answer":0,"setId":"bouvet:azure-functions","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/03-connect-consume/azure-functions.json","reviewDate":"2026-10-11"},{"id":"bouvet:azure-functions-012","prompt":"How many triggers can a single Azure Function have?","explanation":"A function can have exactly one trigger. However, it can have multiple input and output bindings in addition to its single trigger.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/azure-functions/functions-overview","topic":"azure-functions","type":"single","options":["One","Up to three","Unlimited","Depends on the hosting plan"],"answer":0,"setId":"bouvet:azure-functions","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/03-connect-consume/azure-functions.json","reviewDate":"2026-10-11"},{"id":"bouvet:azure-functions-013","prompt":"Which trigger should you use to run a function on a schedule (e.g., every hour)?","explanation":"The Timer trigger uses a CRON expression to run a function on a schedule. It's perfect for periodic tasks like cleanup, reports, or data synchronization.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/azure-functions/functions-overview","topic":"azure-functions","type":"single","options":["HTTP trigger","Queue trigger","Timer trigger","Blob trigger"],"answer":2,"setId":"bouvet:azure-functions","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/03-connect-consume/azure-functions.json","reviewDate":"2026-10-11"},{"id":"bouvet:azure-functions-014","prompt":"What is a 'cold start' in Azure Functions?","explanation":"A cold start is the latency experienced when a function is invoked after being idle. In the Consumption plan, functions scale to zero when idle, so the first request after a period of inactivity may experience a delay while Azure provisions a new instance. Premium plan has pre-warmed instances to minimize this.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/azure-functions/functions-overview","topic":"azure-functions","type":"single","options":["When a function fails to execute","The delay when a function is invoked after being idle (scaled to zero)","When a function times out","When a function is deployed for the first time"],"answer":1,"setId":"bouvet:azure-functions","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/03-connect-consume/azure-functions.json","reviewDate":"2026-10-11"},{"id":"bouvet:azure-functions-015","prompt":"Which configuration keeps a Dedicated-plan function host loaded so cold start is not normally an issue?","explanation":"On a Dedicated App Service plan, enabling Always On keeps the Functions host loaded, so cold start is not normally an issue and non-HTTP triggers continue running. Premium uses prewarmed workers to avoid idle-start delay, while Consumption can scale to zero.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/azure-functions/functions-overview","topic":"azure-functions","type":"single","options":["Consumption with no always-ready instances","Premium with its minimum instance count set to zero","Dedicated (App Service Plan) with Always On enabled","Basic"],"answer":2,"setId":"bouvet:azure-functions","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/03-connect-consume/azure-functions.json","reviewDate":"2026-10-11"},{"id":"bouvet:azure-functions-016","prompt":"What CLI command creates a new Function App in Azure?","explanation":"The Azure CLI command to create a Function App is 'az functionapp create' with parameters for name, resource group, runtime, etc.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/azure-functions/functions-overview","topic":"azure-functions","type":"single","options":["az functionapp create","az functions create","az webapp create --functions","az serverless create"],"answer":0,"setId":"bouvet:azure-functions","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/03-connect-consume/azure-functions.json","reviewDate":"2026-10-11"},{"id":"bouvet:azure-functions-017","prompt":"Which Python decorator defines an HTTP-triggered function?","explanation":"In Azure Functions Python, the @app.route decorator defines the HTTP route for a function. The @app.function_name decorator specifies the function name, and the trigger type is defined by additional decorators or in function.json.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/azure-functions/functions-overview","topic":"azure-functions","type":"single","options":["@app.http_trigger","@app.route","@app.function","@app.endpoint"],"answer":1,"setId":"bouvet:azure-functions","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/03-connect-consume/azure-functions.json","reviewDate":"2026-10-11"},{"id":"bouvet:azure-functions-018","prompt":"Which of these are valid authorization levels for HTTP-triggered functions? (Select all that apply)","explanation":"Azure Functions HTTP triggers support three authorization levels: anonymous (no key required), function (function-specific key required), and admin (master key required).","domain":"services","source":"https://learn.microsoft.com/en-us/azure/azure-functions/functions-overview","topic":"azure-functions","type":"multi","options":["anonymous","function","admin","user","api-key"],"answer":[0,1,2],"choose":3,"setId":"bouvet:azure-functions","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/03-connect-consume/azure-functions.json","reviewDate":"2026-10-11"},{"id":"bouvet:azure-functions-019","prompt":"Which six-field NCRONTAB expression runs a timer trigger every 5 minutes?","explanation":"In the six-field form, the first field is seconds. '0 */5 * * * *' means second 0 of every fifth minute. Azure Functions also accepts a five-field form, where '*/5 * * * *' means every five minutes.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/azure-functions/functions-overview","topic":"azure-functions","type":"single","options":["0 */5 * * * *","*/5 * * * * *","0 5 * * * *","5 * * * * *"],"answer":0,"setId":"bouvet:azure-functions","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/03-connect-consume/azure-functions.json","reviewDate":"2026-10-11"},{"id":"bouvet:azure-functions-020","prompt":"Which Azure Functions extension adds code-based, stateful orchestration patterns such as fan-out/fan-in and long-running workflows?","explanation":"Durable Functions is an extension of Azure Functions that enables stateful workflows in a serverless environment. It supports orchestration, fan-out/fan-in, and entity patterns for complex, long-running workflows.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/azure-functions/functions-overview","topic":"azure-functions","type":"single","options":["Azure Logic Apps","Azure Functions with Durable Functions","Azure Service Bus","Azure Event Grid"],"answer":1,"setId":"bouvet:azure-functions","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/03-connect-consume/azure-functions.json","reviewDate":"2026-10-11"},{"id":"bouvet:azure-functions-021","prompt":"What happens to a queue message after a Queue-triggered function processes it successfully?","explanation":"By default, when a Queue-triggered function completes successfully, the message is automatically deleted from the queue. If the function fails, the message becomes visible again and will be retried.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/azure-functions/functions-overview","topic":"azure-functions","type":"single","options":["It remains in the queue for manual deletion","It is automatically deleted from the queue","It is moved to a dead-letter queue","It becomes invisible for 7 days"],"answer":1,"setId":"bouvet:azure-functions","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/03-connect-consume/azure-functions.json","reviewDate":"2026-10-11"},{"id":"bouvet:azure-functions-022","prompt":"Which file is excluded from a normal Azure Functions deployment by default?","explanation":"local.settings.json is for local development and is excluded from normal deployment. Core Tools can publish its values only when explicitly requested, so inspect it for secrets first. Configure deployed values as Function App application settings instead.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/azure-functions/functions-overview","topic":"azure-functions","type":"single","options":["host.json","function.json","local.settings.json","requirements.txt"],"answer":2,"setId":"bouvet:azure-functions","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/03-connect-consume/azure-functions.json","reviewDate":"2026-10-11"},{"id":"bouvet:azure-functions-023","prompt":"What command deploys a Function App to Azure from the local filesystem?","explanation":"The Azure Functions Core Tools command 'func azure functionapp publish \u003capp-name>' deploys the local function app to Azure.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/azure-functions/functions-overview","topic":"azure-functions","type":"single","options":["az functionapp deploy","func azure functionapp publish","az webapp publish","func deploy"],"answer":1,"setId":"bouvet:azure-functions","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/03-connect-consume/azure-functions.json","reviewDate":"2026-10-11"},{"id":"bouvet:azure-functions-024","prompt":"Which complete list contains supported HTTP request locations that a Function can read?","explanation":"An HTTP-triggered function can receive data via query string parameters (req.params), request body (req.get_body() or req.get_json()), and HTTP headers (req.headers).","domain":"services","source":"https://learn.microsoft.com/en-us/azure/azure-functions/functions-bindings-http-webhook-trigger","topic":"azure-functions","type":"single","options":["Query parameters, request body, and HTTP headers","Only the query string","Only the request body","Only the headers"],"answer":0,"setId":"bouvet:azure-functions","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/03-connect-consume/azure-functions.json","reviewDate":"2026-10-11","reviewNote":"Made a single-choice item unambiguous when options are shuffled."},{"id":"bouvet:azure-functions-025","prompt":"What property of a QueueMessage indicates how many times a message has been dequeued?","explanation":"The dequeue_count property records how many times the Storage Queue message has been retrieved. A value greater than one means a prior delivery was not completed successfully; that can follow a function exception, a visibility-timeout expiry, or a host interruption.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/azure-functions/functions-overview","topic":"azure-functions","type":"single","options":["retry_count","attempts","dequeue_count","visibility_count"],"answer":2,"setId":"bouvet:azure-functions","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/03-connect-consume/azure-functions.json","reviewDate":"2026-10-11"},{"id":"bouvet:azure-functions-026","prompt":"In the Python v2 programming model, what role does function_app.py have?","explanation":"Python v2 requires function_app.py as the main app entry point. A small project can define decorated functions there; a larger project can define them on Blueprint objects in other modules and register those blueprints with the FunctionApp.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/azure-functions/functions-overview","topic":"azure-functions","type":"single","options":["It is the v1 folder file that stores one function's binding JSON","It is the main app entry point; it can define functions and register blueprints from other modules","It is optional whenever functions are split into blueprint files","It contains only global retry and logging configuration"],"answer":1,"setId":"bouvet:azure-functions","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/03-connect-consume/azure-functions.json","reviewDate":"2026-10-11"},{"id":"bouvet:azure-functions-027","prompt":"A queue binding is declared with connection=\"StorageConnection\". What does that value refer to?","explanation":"A binding connection value names either one application setting containing a connection string or a prefix shared by a collection of identity-based settings. It is never the literal connection string in the decorator. In this guide, StorageConnection prefixes StorageConnection__queueServiceUri and StorageConnection__credential in Azure.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/azure-functions/functions-overview","topic":"azure-functions","type":"single","options":["The literal storage connection string","The name of an application setting or the prefix of an identity-based setting collection","The name of the Storage account","The name of the queue"],"answer":1,"setId":"bouvet:azure-functions","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/03-connect-consume/azure-functions.json","reviewDate":"2026-10-11"},{"id":"bouvet:azure-functions-028","prompt":"A queue-triggered function keeps throwing an exception on the same message. What happens to that message?","explanation":"When a queue-triggered function throws, the message becomes visible again and is retried. After maxDequeueCount attempts (default 5, configurable in host.json) the host moves it to \u003cqueue-name>-poison so it stops blocking the queue. On success the host deletes the message automatically - you never write delete code.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/azure-functions/functions-overview","topic":"azure-functions","type":"single","options":["It is deleted immediately after the first failure","It is retried forever until the function succeeds","It is retried up to maxDequeueCount times (5 by default), then moved to a poison queue","It is returned to the caller as an HTTP 500"],"answer":2,"setId":"bouvet:azure-functions","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/03-connect-consume/azure-functions.json","reviewDate":"2026-10-11"},{"id":"bouvet:azure-functions-029","prompt":"Your function is defined as @app.route(route=\"hello\") inside a function named greet_user, registered as \"HttpHello\". What URL invokes it locally?","explanation":"The route is the entire path after the /api prefix - the function name never appears in the URL. So route=\"hello\" is reachable at /api/hello. The /api prefix itself can be changed with extensions.http.routePrefix in host.json.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/azure-functions/functions-overview","topic":"azure-functions","type":"single","options":["http://localhost:7071/api/HttpHello","http://localhost:7071/api/hello","http://localhost:7071/api/greet_user","http://localhost:7071/api/HttpHello/hello"],"answer":1,"setId":"bouvet:azure-functions","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/03-connect-consume/azure-functions.json","reviewDate":"2026-10-11"},{"id":"bouvet:azure-functions-030","prompt":"You deploy a Python function app to a Dedicated (App Service) plan. Its timer trigger stops firing after a period of inactivity. What should you enable?","explanation":"On a Dedicated (App Service) plan an idle app is unloaded, which stops non-HTTP triggers such as timer and queue triggers. Always On keeps the app loaded. It is a Dedicated-plan setting only - Consumption and Premium neither need nor offer it.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/azure-functions/functions-overview","topic":"azure-functions","type":"single","options":["Always On","Pre-warmed instances","Application Insights","Managed identity"],"answer":0,"setId":"bouvet:azure-functions","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/03-connect-consume/azure-functions.json","reviewDate":"2026-10-11"},{"id":"bouvet:azure-functions-031","prompt":"Which statement about Azure Functions timer-trigger NCRONTAB expressions is correct?","explanation":"Azure Functions NCRONTAB accepts either the five-field form (without seconds) or the six-field form (with leading seconds). Therefore '*/5 * * * *' and '0 */5 * * * *' both express every five minutes. Schedules use UTC by default; WEBSITE_TIME_ZONE support depends on the OS and plan and is not available on Linux Flex Consumption.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/azure-functions/functions-overview","topic":"azure-functions","type":"single","options":["They accept only five fields, exactly like Linux cron.","They accept only six fields, with a leading seconds field.","They accept five or six fields; the six-field form has a leading seconds field.","They must have seven fields, including a year."],"answer":2,"setId":"bouvet:azure-functions","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/03-connect-consume/azure-functions.json","reviewDate":"2026-10-11"},{"id":"bouvet:azure-functions-032","prompt":"Your HTTP-triggered function must also write a message to a Storage queue. Which statements are true? (Select all that apply)","explanation":"A function has exactly one trigger but can have multiple input and output bindings. Adding @app.queue_output alongside the HTTP trigger lets the host deliver the message for you - no QueueClient and no connection code. Adding a second trigger is not possible.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/azure-functions/functions-overview","topic":"azure-functions","type":"multi","options":["You can add a queue output binding alongside the HTTP trigger","You must add a second trigger to the function","The function can have only one trigger but multiple bindings","You must construct a QueueClient yourself; output bindings only work with HTTP"],"answer":[0,2],"choose":2,"setId":"bouvet:azure-functions","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/03-connect-consume/azure-functions.json","reviewDate":"2026-10-11"},{"id":"bouvet:azure-functions-033","prompt":"An HTTP-triggered function can need 20 minutes to process a request. Clients must not hold an HTTP connection open and the work must survive restarts. What should you do?","explanation":"Even plans with an unbounded configured function timeout still face the platform's roughly 230-second HTTP response limit. Return an acceptance response quickly and defer the durable work to a queue-triggered function, or use the Durable Functions asynchronous pattern.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/azure-functions/functions-overview","topic":"azure-functions","type":"single","options":["Increase functionTimeout and keep the same synchronous HTTP response open","Return promptly, place the work on a queue, and process it with a queue trigger","Switch the route authorization level to admin","Run the HTTP request twice so one copy succeeds"],"answer":1,"setId":"bouvet:azure-functions","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/03-connect-consume/azure-functions.json","reviewDate":"2026-10-11"},{"id":"bouvet:azure-functions-034","prompt":"A deployed queue binding uses connection=\"StorageConnection\" with a system-assigned managed identity. Which app settings belong to that named identity-based connection? (Select all that apply)","explanation":"The decorator value is a prefix. queueServiceUri identifies the Queue service and credential=managedidentity selects the app's managed identity. A system-assigned identity needs no clientId; that extra setting is for selecting a particular user-assigned identity.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/azure-functions/functions-overview","topic":"azure-functions","type":"multi","options":["StorageConnection__queueServiceUri=https://\u003caccount>.queue.core.windows.net","StorageConnection__credential=managedidentity","StorageConnection=\u003craw-account-key>","StorageConnection__clientId=\u003cclient-id> is always required for a system-assigned identity"],"answer":[0,1],"choose":2,"setId":"bouvet:azure-functions","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/03-connect-consume/azure-functions.json","reviewDate":"2026-10-11"},{"id":"bouvet:azure-functions-035","prompt":"A large Python v2 function app is becoming difficult to maintain because every function is in function_app.py. Which supported organization should you use?","explanation":"Blueprints let a Python v2 app define related decorated functions in separate modules. function_app.py remains the main entry point and registers those blueprints with its FunctionApp object.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/azure-functions/functions-overview","topic":"azure-functions","type":"single","options":["Create Blueprint objects in feature modules and register them with the FunctionApp","Give every function a second trigger so the host groups them","Move each decorator into host.json","Replace function_app.py with one function.json at the project root"],"answer":0,"setId":"bouvet:azure-functions","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/03-connect-consume/azure-functions.json","reviewDate":"2026-10-11"},{"id":"bouvet:azure-functions-036","prompt":"A Flex Consumption app contains HTTP, queue, timer, and Service Bus triggers. Which statement describes its scaling?","explanation":"Flex Consumption uses per-function scaling for most triggers. All HTTP triggers in the app share one scale group; Blob (Event Grid) triggers and Durable Functions triggers also use their respective groups.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/azure-functions/functions-overview","topic":"azure-functions","type":"single","options":["Every trigger always scales as one indivisible app-level unit","Most non-HTTP triggers can scale independently, while all HTTP triggers share a scale group","Only timer triggers can scale independently","Flex Consumption never scales to zero"],"answer":1,"setId":"bouvet:azure-functions","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/03-connect-consume/azure-functions.json","reviewDate":"2026-10-11"},{"id":"bouvet:azure-functions-037","prompt":"Put the normal deployed queue-trigger processing path in order.","explanation":"The trigger host owns polling and message settlement. It receives the message, invokes your function with the binding value, and deletes the message after a successful return. An exception leaves it available for retry; your function does not manually delete it.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/azure-functions/functions-overview","topic":"azure-functions","type":"drag","options":["The Functions host receives and hides a queue message","The host invokes the function with the bound QueueMessage","The function finishes successfully","The host deletes the queue message","Your Python code constructs a QueueClient and deletes the message"],"answer":["The Functions host receives and hides a queue message","The host invokes the function with the bound QueueMessage","The function finishes successfully","The host deletes the queue message"],"setId":"bouvet:azure-functions","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/03-connect-consume/azure-functions.json","reviewDate":"2026-10-11"},{"id":"bouvet:event-grid-001","prompt":"What is the core delivery model of Azure Event Grid Basic?","explanation":"Event Grid Basic is a push-based pub/sub service - it calls each subscriber's handler when a matching event occurs. This is the key contrast with Service Bus and Event Hubs, which subscribers pull from.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/event-grid/overview","topic":"event-grid","type":"single","options":["Subscribers poll a queue for new events","Event Grid pushes matching events to each subscriber's registered handler","Subscribers open a persistent TCP stream to read events in order","Events are written to a shared database table that subscribers query"],"answer":1,"setId":"bouvet:event-grid","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/03-connect-consume/event-grid.json","reviewDate":"2026-10-11"},{"id":"bouvet:event-grid-002","prompt":"Which statement about system topics is correct?","explanation":"A system topic is an Event Grid resource associated with an Azure event source. Creating an event subscription with --source-resource-id pointing at a Storage account can create that system topic automatically.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/event-grid/overview","topic":"event-grid","type":"single","options":["You must create a system topic resource before subscribing to a Storage account's events","System topics are only available for custom application events","A system topic represents built-in events from an Azure resource, and you subscribe directly against that resource's ID","System topics require the CloudEvents schema"],"answer":2,"setId":"bouvet:event-grid","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/03-connect-consume/event-grid.json","reviewDate":"2026-10-11"},{"id":"bouvet:event-grid-003","prompt":"You need many custom topics (one per tenant) managed and secured as a unit. Which Event Grid concept fits?","explanation":"An event domain is a management tool for large numbers of custom topics - for example, one topic per tenant - letting you manage and secure them together under one endpoint.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/event-grid/overview","topic":"event-grid","type":"single","options":["Event domain","Event Hub","System topic","Dead-letter container"],"answer":0,"setId":"bouvet:event-grid","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/03-connect-consume/event-grid.json","reviewDate":"2026-10-11"},{"id":"bouvet:event-grid-004","prompt":"Which event schema does Microsoft recommend for new Event Grid topics?","explanation":"CloudEvents v1.0 is an open, cross-cloud standard and is Microsoft's recommended schema for new topics. The original Event Grid schema is Azure-only and still appears on older or system topics.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/event-grid/overview","topic":"event-grid","type":"single","options":["Event Grid schema","CloudEvents v1.0 schema","Avro schema","Protobuf schema"],"answer":1,"setId":"bouvet:event-grid","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/03-connect-consume/event-grid.json","reviewDate":"2026-10-11"},{"id":"bouvet:event-grid-005","prompt":"In the CloudEvents schema, which field would a subject filter (subjectBeginsWith/EndsWith) match against?","explanation":"subject identifies the specific resource the event is about (e.g. 'orders/12345') and is what subjectBeginsWith/subjectEndsWith filters match. type identifies the kind of event and is matched by includedEventTypes instead.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/event-grid/overview","topic":"event-grid","type":"single","options":["type","source","subject","data"],"answer":2,"setId":"bouvet:event-grid","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/03-connect-consume/event-grid.json","reviewDate":"2026-10-11"},{"id":"bouvet:event-grid-006","prompt":"An event subscription has both a subject filter and an advanced filter configured. How are they evaluated?","explanation":"Filters on an Event Grid subscription are combined with AND logic - an event must satisfy every configured filter to be delivered, not just one of them.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/event-grid/overview","topic":"event-grid","type":"single","options":["Either filter matching is enough for delivery (OR logic)","Both filters must match for the event to be delivered (AND logic)","Only the advanced filter is evaluated; the subject filter is ignored","The filters are evaluated in the order they were created, and the first match wins"],"answer":1,"setId":"bouvet:event-grid","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/03-connect-consume/event-grid.json","reviewDate":"2026-10-11"},{"id":"bouvet:event-grid-007","prompt":"You need a subscription to only receive events whose data field 'quantityRemaining' is less than 5. Which filter type do you need?","explanation":"Advanced filters can match supported envelope fields and nested data fields, using an operator (for example, NumberLessThan) and a value. Subject and event-type filters target the subject and type fields instead.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/event-grid/overview","topic":"event-grid","type":"single","options":["Subject filter","Event type filter","Advanced filter","This is not possible - only subject and type can be filtered on"],"answer":2,"setId":"bouvet:event-grid","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/03-connect-consume/event-grid.json","reviewDate":"2026-10-11"},{"id":"bouvet:event-grid-008","prompt":"What is the default maximum number of delivery attempts Event Grid makes for an event?","explanation":"Event Grid allows up to 30 delivery attempts by default, including the initial attempt, with an exponential-backoff schedule. The subscription can configure a value from 1 through 30 with --max-delivery-attempts.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/event-grid/overview","topic":"event-grid","type":"single","options":["3","10","30","Unlimited"],"answer":2,"setId":"bouvet:event-grid","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/03-connect-consume/event-grid.json","reviewDate":"2026-10-11"},{"id":"bouvet:event-grid-009","prompt":"An event's TTL is set to 60 minutes and max delivery attempts is set to 30. The retry-attempt cap has not been reached when the TTL expires. What stops further retries?","explanation":"Event Grid stops retrying at the retry-attempt cap OR the event TTL, whichever happens first. Retry timing is nondeterministic, and Event Grid checks expiration at the next scheduled delivery attempt.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/event-grid/overview","topic":"event-grid","type":"single","options":["After 30 attempts, regardless of the 60-minute TTL","The first scheduled delivery attempt after the 60-minute TTL detects expiry","Only after both the attempt count AND the TTL have been exceeded","Event Grid retries forever once a subscription exists"],"answer":1,"setId":"bouvet:event-grid","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/03-connect-consume/event-grid.json","reviewDate":"2026-10-11"},{"id":"bouvet:event-grid-010","prompt":"An event exhausts its retry attempts and no dead-letter destination is configured on the subscription. What happens to it?","explanation":"Dead-lettering in Event Grid is opt-in and always a Storage Blob container you configure via --deadletter-endpoint. Without it, an event that exhausts retries or TTL is simply dropped.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/event-grid/overview","topic":"event-grid","type":"single","options":["It is moved to a default Event Grid dead-letter queue","It is redelivered to Service Bus automatically","It is dropped - Event Grid has no built-in dead-letter destination unless you configure one","The topic is automatically paused until the event is manually acknowledged"],"answer":2,"setId":"bouvet:event-grid","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/03-connect-consume/event-grid.json","reviewDate":"2026-10-11"},{"id":"bouvet:event-grid-011","prompt":"For an Event Grid Basic subscription, where can Event Grid dead-letter undeliverable events?","explanation":"Event Grid's dead-letter destination is always a Storage Blob container, configured with --deadletter-endpoint on the event subscription. This is unlike Service Bus, which has a built-in dead-letter sub-queue.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/event-grid/overview","topic":"event-grid","type":"single","options":["A Service Bus dead-letter queue","A Storage Blob container","A Cosmos DB container","An Event Hub"],"answer":1,"setId":"bouvet:event-grid","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/03-connect-consume/event-grid.json","reviewDate":"2026-10-11"},{"id":"bouvet:event-grid-012","prompt":"Which HTTP response status range does Event Grid treat as a successful delivery?","explanation":"Event Grid treats HTTP 200, 201, 202, 203, and 204 as successful delivery. Other status codes, a timeout, or an unreachable endpoint are failed deliveries.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/event-grid/overview","topic":"event-grid","type":"single","options":["200 only","200-204","200-299","Any status that isn't a 5xx"],"answer":1,"setId":"bouvet:event-grid","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/03-connect-consume/event-grid.json","reviewDate":"2026-10-11"},{"id":"bouvet:event-grid-013","prompt":"You configure CloudEvents v1.0 delivery to a plain HTTPS webhook (not an Azure Function). What must the endpoint do before it starts receiving real events?","explanation":"For CloudEvents delivery, Event Grid validates a raw webhook by sending HTTP OPTIONS. A production endpoint grants permission with the CloudEvents WebHook-Allowed-Origin and WebHook-Allowed-Rate headers. For Event Grid Basic, a request-capture endpoint such as webhook.site can instead use the WebHook-Request-Callback header for manual approval. SubscriptionValidationEvent applies to Event Grid-schema delivery instead.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/event-grid/overview","topic":"event-grid","type":"single","options":["Nothing - delivery starts immediately after the subscription is created","Respond to a SubscriptionValidationEvent by echoing back its validationCode","Grant permission for Event Grid's HTTP OPTIONS request with the headers or its WebHook-Request-Callback","Register an SSL certificate with Event Grid's certificate authority"],"answer":2,"setId":"bouvet:event-grid","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/03-connect-consume/event-grid.json","reviewDate":"2026-10-11"},{"id":"bouvet:event-grid-014","prompt":"Which handler type does NOT require you to manually implement the Event Grid webhook validation handshake?","explanation":"The Azure Functions Event Grid trigger auto-handles platform validation. A plain webhook implementation - Flask, Express, or otherwise - must handle the validation required by its delivery schema: validationCode for Event Grid schema, or HTTP OPTIONS with CloudEvents permission headers (or its callback alternative) for CloudEvents.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/event-grid/overview","topic":"event-grid","type":"single","options":["A plain HTTPS webhook you write yourself","An Azure Function with an Event Grid trigger","A raw Express.js endpoint","A Flask endpoint with no special handling"],"answer":1,"setId":"bouvet:event-grid","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/03-connect-consume/event-grid.json","reviewDate":"2026-10-11"},{"id":"bouvet:event-grid-015","prompt":"Which of these are valid Event Grid Basic event handlers? (Select all that apply)","explanation":"Event Grid can deliver to Azure Functions, Storage Queues, Service Bus queues/topics, Event Hubs, Logic Apps, webhooks, and Relay hybrid connections. It has no built-in handler that connects directly to a SQL Server database.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/event-grid/overview","topic":"event-grid","type":"multi","options":["Azure Function (Event Grid trigger)","Storage Queue","Service Bus queue/topic","A direct SQL Server connection","Event Hubs"],"answer":[0,1,2,4],"choose":4,"setId":"bouvet:event-grid","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/03-connect-consume/event-grid.json","reviewDate":"2026-10-11"},{"id":"bouvet:event-grid-016","prompt":"A scenario requires reliably processing business-critical order transactions, with ordering guarantees and possible transactional locks. Which service best fits?","explanation":"Service Bus is designed for reliable business-message processing with FIFO ordering (via sessions) and transactional semantics. Event Grid is for lightweight notifications; Event Hubs is for high-volume streaming telemetry.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/event-grid/overview","topic":"event-grid","type":"single","options":["Event Grid","Service Bus","Event Hubs","Azure Cache for Redis"],"answer":1,"setId":"bouvet:event-grid","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/03-connect-consume/event-grid.json","reviewDate":"2026-10-11"},{"id":"bouvet:event-grid-017","prompt":"A scenario requires ingesting 100,000 telemetry events per second from IoT devices for stream analytics. Which service best fits?","explanation":"Event Hubs is built for high-throughput, partitioned event streaming with replay support - the right fit for ingesting a high-volume telemetry firehose. Event Grid is for lower-volume notifications; Service Bus is for business messages.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/event-grid/overview","topic":"event-grid","type":"single","options":["Event Grid","Service Bus","Event Hubs","Azure Functions Queue trigger"],"answer":2,"setId":"bouvet:event-grid","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/03-connect-consume/event-grid.json","reviewDate":"2026-10-11"},{"id":"bouvet:event-grid-018","prompt":"A scenario says a Storage account should notify multiple independent systems whenever a blob is created, with each system reacting differently, and no polling loop should be written. Which service best fits?","explanation":"Event Grid's push-based pub/sub model fans a single event out to many independent subscribers, each with its own handler - exactly the 'react to something that happened, no polling' scenario.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/event-grid/overview","topic":"event-grid","type":"single","options":["Event Grid","Service Bus","Event Hubs","Azure SQL Database change tracking"],"answer":0,"setId":"bouvet:event-grid","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/03-connect-consume/event-grid.json","reviewDate":"2026-10-11"},{"id":"bouvet:event-grid-019","prompt":"Which Azure CLI command creates a custom Event Grid topic?","explanation":"az eventgrid topic create creates a custom Event Grid topic, with --input-schema selecting cloudeventschemav1_0 or the default Event Grid schema.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/event-grid/overview","topic":"event-grid","type":"single","options":["az eventgrid topic create","az eventgrid custom-topic create","az messaging topic create --type eventgrid","az eventgrid create --kind topic"],"answer":0,"setId":"bouvet:event-grid","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/03-connect-consume/event-grid.json","reviewDate":"2026-10-11"},{"id":"bouvet:event-grid-020","prompt":"Which CLI flag configures the subject-prefix filter when creating an event subscription?","explanation":"--subject-begins-with (paired with --subject-ends-with for suffix matching) sets the subject filter on `az eventgrid event-subscription create`.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/event-grid/overview","topic":"event-grid","type":"single","options":["--filter-subject","--subject-begins-with","--prefix-filter","--includedEventTypes"],"answer":1,"setId":"bouvet:event-grid","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/03-connect-consume/event-grid.json","reviewDate":"2026-10-11"},{"id":"bouvet:event-grid-021","prompt":"In the Python SDK, which class represents an event in the CloudEvents v1.0 schema when publishing?","explanation":"azure.core.messaging.CloudEvent is the SDK type for CloudEvents-schema events. EventGridEvent is the older, Event-Grid-schema equivalent. EventGridPublisherClient is the client used to send either type; AzureKeyCredential just wraps the access key.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/event-grid/overview","topic":"event-grid","type":"single","options":["EventGridEvent","CloudEvent","EventGridPublisherClient","AzureKeyCredential"],"answer":1,"setId":"bouvet:event-grid","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/03-connect-consume/event-grid.json","reviewDate":"2026-10-11"},{"id":"bouvet:event-grid-022","prompt":"In a CloudEvent, if you omit the `id` and `time` fields when constructing it in Python, what happens?","explanation":"The Python SDK's CloudEvent fills in a unique id and the current UTC time automatically when they aren't supplied, so callers only need to set source, type, subject, and data for a typical publish.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/event-grid/overview","topic":"event-grid","type":"single","options":["The SDK raises a validation error - both are required arguments","The SDK automatically generates a unique id and sets time to the current UTC timestamp","Event Grid rejects the publish request at the service level","The event is published with id and time set to null"],"answer":1,"setId":"bouvet:event-grid","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/03-connect-consume/event-grid.json","reviewDate":"2026-10-11"},{"id":"bouvet:event-grid-023","prompt":"What does the `source` field on a CloudEvent represent?","explanation":"source identifies WHERE an event came from (the publisher), typically reused across many events from the same app - distinct from subject, which identifies WHICH specific resource the event is about.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/event-grid/overview","topic":"event-grid","type":"single","options":["The specific resource instance the event is about, e.g. 'orders/12345'","Where the event came from - conventionally a URI-like path identifying the publisher","The Azure region the topic was created in","The name of the event subscription that will receive it"],"answer":1,"setId":"bouvet:event-grid","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/03-connect-consume/event-grid.json","reviewDate":"2026-10-11"},{"id":"bouvet:event-grid-024","prompt":"What is the maximum number of advanced filters on one Event Grid subscription?","explanation":"An event subscription supports up to 25 advanced filters and 25 filter values in total across those filters, letting you build granular routing logic without a custom relay function.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/event-grid/overview","topic":"event-grid","type":"single","options":["5","10","25","Unlimited"],"answer":2,"setId":"bouvet:event-grid","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/03-connect-consume/event-grid.json","reviewDate":"2026-10-11"},{"id":"bouvet:event-grid-025","prompt":"A webhook returns HTTP 403 for an Event Grid delivery, and the subscription has a valid Blob dead-letter destination. What happens?","explanation":"For webhook endpoints, 400, 401, 403, and 413 are configuration-related failures that Event Grid does not normally retry. It schedules the event for the configured Blob dead-letter destination; without one, the event is dropped.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/event-grid/overview","topic":"event-grid","type":"single","options":["Event Grid treats 403 as success","Event Grid immediately schedules the event for dead-lettering instead of normal retries","Event Grid retries forever","Event Grid moves the event to a Service Bus DLQ"],"answer":1,"setId":"bouvet:event-grid","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/03-connect-consume/event-grid.json","reviewDate":"2026-10-11"},{"id":"bouvet:event-grid-026","prompt":"A custom topic accepts CloudEvents v1.0 as its input schema. Which delivery schema can an event subscription choose?","explanation":"A CloudEvents-input custom topic can deliver only CloudEvents. By contrast, a topic using the Event Grid input schema can deliver either the Event Grid schema or CloudEvents, so input and delivery schemas are related but separate settings.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/event-grid/overview","topic":"event-grid","type":"single","options":["CloudEvents v1.0 only","Event Grid schema only","Either CloudEvents or Event Grid schema","Avro only"],"answer":0,"setId":"bouvet:event-grid","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/03-connect-consume/event-grid.json","reviewDate":"2026-10-11"},{"id":"bouvet:event-grid-027","prompt":"A Python publisher uses DefaultAzureCredential and only needs to send custom events to one topic. Which role is the least-privileged choice at that topic's scope?","explanation":"EventGrid Data Sender grants the data-plane publish operation. Contributor manages resources but does not grant event publishing, while Owner is unnecessarily broad. Scope the sender role to the one topic when possible.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/event-grid/overview","topic":"event-grid","type":"single","options":["Owner","Contributor","EventGrid Data Sender","Azure Service Bus Data Sender"],"answer":2,"setId":"bouvet:event-grid","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/03-connect-consume/event-grid.json","reviewDate":"2026-10-11"},{"id":"bouvet:event-grid-028","prompt":"A handler successfully writes an event's business effect, but its HTTP acknowledgement is lost and Event Grid delivers the same event again. What design prevents a duplicate business effect?","explanation":"Event Grid provides at-least-once delivery, so duplicates are possible when an acknowledgement is lost or a retry was already queued. An idempotent handler recognizes the event ID or another stable business key and does not repeat an already-applied effect.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/event-grid/overview","topic":"event-grid","type":"single","options":["Assume Event Grid provides exactly-once delivery","Record processed event IDs or use an idempotency key before applying the effect","Return HTTP 500 for every event","Disable the event subscription after each delivery"],"answer":1,"setId":"bouvet:event-grid","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/03-connect-consume/event-grid.json","reviewDate":"2026-10-11"},{"id":"bouvet:event-grid-029","prompt":"A subscription has subjectBeginsWith=\"orders/\", included event type Orders.OrderCreated, and an advanced filter data.total > 100. Which event is delivered?","explanation":"Different filters on one subscription are combined with AND. Only the first event has the required subject prefix, event type, and total. Multiple accepted values within one In-style filter would be OR alternatives, but that does not make separate filters optional.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/event-grid/overview","topic":"event-grid","type":"single","options":["Orders.OrderCreated, subject orders/42, total 150","Orders.OrderShipped, subject orders/42, total 150","Orders.OrderCreated, subject inventory/42, total 150","Orders.OrderCreated, subject orders/43, total 75"],"answer":0,"setId":"bouvet:event-grid","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/03-connect-consume/event-grid.json","reviewDate":"2026-10-11"},{"id":"bouvet:service-bus-001","prompt":"What problem does Azure Service Bus primarily solve?","explanation":"Service Bus is a durable message broker. A producer can send work now, while a consumer retrieves and processes it later, which decouples their availability and throughput.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/service-bus-messaging/service-bus-messaging-overview","topic":"service-bus","type":"single","options":["It stores relational data for a web application","It durably brokers messages between applications that can run at different times and speeds","It renders server-side web pages","It performs distributed cache invalidation only"],"answer":1,"setId":"bouvet:service-bus","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/03-connect-consume/service-bus.json","reviewDate":"2026-10-11"},{"id":"bouvet:service-bus-002","prompt":"Several workers compete so that only one worker handles each delivery of an invoice command. Which Service Bus entity should receive it?","explanation":"A queue uses competing consumers: one queue message goes to one receiver for a given delivery. Peek-Lock can redeliver after a failure, so this is not an exactly-once guarantee and the invoice processor must still be idempotent. A topic with separate subscriptions would intentionally create independent copies.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/service-bus-messaging/service-bus-messaging-overview","topic":"service-bus","type":"single","options":["A queue","A topic with one subscription per worker","A dead-letter queue","A Service Bus namespace"],"answer":0,"setId":"bouvet:service-bus","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/03-connect-consume/service-bus.json","reviewDate":"2026-10-11"},{"id":"bouvet:service-bus-003","prompt":"A publisher sends one message to a topic and it matches three subscriptions. What happens?","explanation":"Topics implement publish/subscribe. Each matching subscription is a separate durable message store, so it gets its own copy and settles that copy independently.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/service-bus-messaging/service-bus-messaging-overview","topic":"service-bus","type":"single","options":["Only the first subscription created receives it","The topic chooses one subscription at random","Each matching subscription gets its own durable copy","The message is moved immediately to the topic's dead-letter queue"],"answer":2,"setId":"bouvet:service-bus","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/03-connect-consume/service-bus.json","reviewDate":"2026-10-11"},{"id":"bouvet:service-bus-004","prompt":"After a producer sends to a Service Bus topic, where does a consumer receive the message?","explanation":"Senders target a topic, but consumers create receivers for named subscriptions. A subscription behaves like the durable virtual queue that holds the topic's copy for that consumer.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/service-bus-messaging/service-bus-messaging-overview","topic":"service-bus","type":"single","options":["Directly from the topic","From a subscription under that topic","From the namespace root","From the producer's outbox"],"answer":1,"setId":"bouvet:service-bus","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/03-connect-consume/service-bus.json","reviewDate":"2026-10-11"},{"id":"bouvet:service-bus-005","prompt":"What is the effect of the $Default rule on a newly created topic subscription?","explanation":"New subscriptions begin with $Default, a TrueFilter that accepts all topic messages. Delete it before adding a selective rule, otherwise the default rule still allows every message into the subscription.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/service-bus-messaging/service-bus-messaging-overview","topic":"service-bus","type":"single","options":["It rejects all messages until a custom SQL rule is added","It accepts every topic message through a TrueFilter","It dead-letters messages that do not have a MessageId","It forwards all messages to the namespace's first queue"],"answer":1,"setId":"bouvet:service-bus","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/03-connect-consume/service-bus.json","reviewDate":"2026-10-11"},{"id":"bouvet:service-bus-006","prompt":"A subscription rule must route only messages marked priority = high without parsing their JSON bodies. Where should that value be placed?","explanation":"Subscription rules inspect system and application properties. Put routing metadata such as priority in application_properties so the broker can filter before a subscription receives the message.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/service-bus-messaging/service-bus-messaging-overview","topic":"service-bus","type":"single","options":["In an application property","Only in the message body","In the queue name","In the namespace's resource group tag"],"answer":0,"setId":"bouvet:service-bus","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/03-connect-consume/service-bus.json","reviewDate":"2026-10-11"},{"id":"bouvet:service-bus-007","prompt":"Which receive mode is the Service Bus default and is normally used for important business work?","explanation":"Peek-Lock is the default. It locks a message while the receiver works and removes it only after an explicit completion, avoiding silent loss if the receiver fails.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/service-bus-messaging/service-bus-messaging-overview","topic":"service-bus","type":"single","options":["Receive-and-Delete","Peek-Lock","Fire-and-Forget","Read-Only"],"answer":1,"setId":"bouvet:service-bus","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/03-connect-consume/service-bus.json","reviewDate":"2026-10-11"},{"id":"bouvet:service-bus-008","prompt":"A worker uses Receive-and-Delete, receives a payment message, and crashes before processing it. What is the result?","explanation":"Receive-and-Delete settles the message as soon as Service Bus sends it to the receiver. It provides at-most-once delivery, so a crash after receipt can lose the work.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/service-bus-messaging/service-bus-messaging-overview","topic":"service-bus","type":"single","options":["The message returns to the queue after its lock expires","The message is automatically copied to the DLQ","The message is lost because Service Bus removed it when it was delivered","Another worker receives an identical copy immediately"],"answer":2,"setId":"bouvet:service-bus","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/03-connect-consume/service-bus.json","reviewDate":"2026-10-11"},{"id":"bouvet:service-bus-009","prompt":"Put the normal Peek-Lock success path in order.","explanation":"With Peek-Lock, receive first creates a temporary lock. Perform the work while holding the lock, then complete only after it succeeds. Dead-lettering is for known-bad work, not the normal success path.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/service-bus-messaging/service-bus-messaging-overview","topic":"service-bus","type":"drag","options":["Receive and lock the message","Perform the business work successfully","Complete the message to remove it","Dead-letter the successful message"],"answer":["Receive and lock the message","Perform the business work successfully","Complete the message to remove it"],"setId":"bouvet:service-bus","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/03-connect-consume/service-bus.json","reviewDate":"2026-10-11"},{"id":"bouvet:service-bus-010","prompt":"A Peek-Lock receiver crashes before it calls complete_message. What does Service Bus do after the lock expires?","explanation":"When a Peek-Lock message is not settled and its lock expires, Service Bus unlocks it for redelivery. This protects against loss but means the consumer must tolerate duplicate processing.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/service-bus-messaging/service-bus-messaging-overview","topic":"service-bus","type":"single","options":["It removes the message permanently","It makes the message available for redelivery","It immediately deletes the whole queue","It sends the message to every topic subscription"],"answer":1,"setId":"bouvet:service-bus","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/03-connect-consume/service-bus.json","reviewDate":"2026-10-11"},{"id":"bouvet:service-bus-011","prompt":"What normally happens when a message repeatedly exceeds a queue's MaxDeliveryCount?","explanation":"Repeated abandonment or lock expiry increments delivery count. Once it exceeds MaxDeliveryCount, Service Bus moves the message to the associated built-in DLQ for investigation.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/service-bus-messaging/service-bus-messaging-overview","topic":"service-bus","type":"single","options":["It is moved to that queue's built-in dead-letter queue","It becomes a topic message","It is automatically completed as successful","It stays locked forever"],"answer":0,"setId":"bouvet:service-bus","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/03-connect-consume/service-bus.json","reviewDate":"2026-10-11"},{"id":"bouvet:service-bus-012","prompt":"Which can place a Service Bus message in a dead-letter queue? (Select all that apply)","explanation":"Max delivery exhaustion, explicit application dead-lettering, and configured dead-letter-on-expiration can all move a message to a DLQ. A nonmatching rule simply does not copy the message into that subscription, and completion removes a successful message.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/service-bus-messaging/service-bus-messaging-overview","topic":"service-bus","type":"multi","options":["It exceeds MaxDeliveryCount after repeated failed deliveries","A receiver explicitly dead-letters it with a reason","It expires when dead-lettering on expiration is enabled","It does not match a topic subscription rule","A receiver completes it successfully"],"answer":[0,1,2],"choose":3,"setId":"bouvet:service-bus","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/03-connect-consume/service-bus.json","reviewDate":"2026-10-11"},{"id":"bouvet:service-bus-013","prompt":"After inspecting and correcting a dead-lettered message, what does completing the original DLQ copy do?","explanation":"A DLQ has no automatic replay. Send a corrected new message to the original entity first, then complete the old DLQ copy only when it is safe to remove it.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/service-bus-messaging/service-bus-messaging-overview","topic":"service-bus","type":"single","options":["It automatically resubmits the message to the original queue","It deletes that DLQ copy permanently","It resets the message delivery count to zero in the main queue","It copies the message to every topic subscription"],"answer":1,"setId":"bouvet:service-bus","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/03-connect-consume/service-bus.json","reviewDate":"2026-10-11"},{"id":"bouvet:service-bus-014","prompt":"A normal-priority topic message does not match the high-priority subscription rule. Where does that message go for that subscription?","explanation":"A filter miss is normal routing, not an error. The subscription receives no copy, while other subscriptions whose rules match can still receive their own copies.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/service-bus-messaging/service-bus-messaging-overview","topic":"service-bus","type":"single","options":["Into the subscription's DLQ","Back to the topic for retry","Nowhere; it is not copied into that subscription","Into the namespace's RootManageSharedAccessKey policy"],"answer":2,"setId":"bouvet:service-bus","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/03-connect-consume/service-bus.json","reviewDate":"2026-10-11"},{"id":"bouvet:service-bus-015","prompt":"What Service Bus feature provides FIFO processing for messages related to the same order?","explanation":"Enable sessions on the queue or subscription, assign the same SessionId to all messages for one order, and use a session-aware receiver. Sessions preserve order within that group while unrelated sessions can still run in parallel.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/service-bus-messaging/service-bus-messaging-overview","topic":"service-bus","type":"single","options":["Message sessions","Receive-and-Delete","A dead-letter queue","A shared access policy"],"answer":0,"setId":"bouvet:service-bus","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/03-connect-consume/service-bus.json","reviewDate":"2026-10-11"},{"id":"bouvet:service-bus-016","prompt":"Which property groups related messages into the same Service Bus session?","explanation":"SessionId identifies the related sequence that a session-aware receiver locks and processes in order. MessageId identifies one message, while CorrelationId connects related requests and replies.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/service-bus-messaging/service-bus-messaging-overview","topic":"service-bus","type":"single","options":["MessageId","CorrelationId","SessionId","TimeToLive"],"answer":2,"setId":"bouvet:service-bus","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/03-connect-consume/service-bus.json","reviewDate":"2026-10-11"},{"id":"bouvet:service-bus-017","prompt":"What does Service Bus duplicate detection protect against?","explanation":"Duplicate detection is sender-side protection: it discards a second submission with a repeated MessageId during the configured window. It does not remove the need for idempotent consumer processing.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/service-bus-messaging/service-bus-messaging-overview","topic":"service-bus","type":"single","options":["A repeated send using the same MessageId within its configured history window","A worker receiving a Peek-Lock message twice after a failed completion","A subscription rule matching the same application property twice","A message body containing the same JSON twice"],"answer":0,"setId":"bouvet:service-bus","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/03-connect-consume/service-bus.json","reviewDate":"2026-10-11"},{"id":"bouvet:service-bus-018","prompt":"Which statement best describes a Service Bus transaction?","explanation":"Service Bus transactions provide all-or-nothing behavior for supported broker operations, such as completing an input and sending a next-step message. They are not an end-to-end transaction with an external database.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/service-bus-messaging/service-bus-messaging-overview","topic":"service-bus","type":"single","options":["It makes a database write and any Service Bus operation one global database transaction","It groups supported Service Bus operations so they commit together or roll back together","It is another name for Receive-and-Delete","It can only be used to create a namespace"],"answer":1,"setId":"bouvet:service-bus","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/03-connect-consume/service-bus.json","reviewDate":"2026-10-11"},{"id":"bouvet:service-bus-019","prompt":"Which Service Bus tier is the minimum choice when a solution needs topics and subscriptions?","explanation":"Basic is queues-only. Standard supports topics and subscriptions, as well as the other brokered messaging features used in this guide.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/service-bus-messaging/service-bus-messaging-overview","topic":"service-bus","type":"single","options":["Basic","Standard","Free","Developer"],"answer":1,"setId":"bouvet:service-bus","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/03-connect-consume/service-bus.json","reviewDate":"2026-10-11"},{"id":"bouvet:service-bus-020","prompt":"Which Azure CLI command creates the Standard Service Bus namespace in this guide?","explanation":"az servicebus namespace create provisions the namespace, and --sku Standard selects the tier that supports the topic and subscription entities created in the later setup steps.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/service-bus-messaging/service-bus-messaging-overview","topic":"service-bus","type":"single","options":["az servicebus namespace create --sku Standard","az servicebus queue create --sku Standard","az eventgrid topic create --sku Standard","az messaging namespace add --type servicebus"],"answer":0,"setId":"bouvet:service-bus","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/03-connect-consume/service-bus.json","reviewDate":"2026-10-11"},{"id":"bouvet:service-bus-021","prompt":"Which Python expression creates the passwordless namespace client used in the walkthrough?","explanation":"The walkthrough passes the fully qualified namespace and a DefaultAzureCredential token credential to ServiceBusClient. Locally the credential can reuse az login; in Azure the same code can use a managed identity. No SAS connection string is stored.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/service-bus-messaging/service-bus-messaging-overview","topic":"service-bus","type":"single","options":["ServiceBusClient(fully_qualified_namespace, DefaultAzureCredential())","ServiceBusClient.from_connection_string(SERVICEBUS_CONNECTION_STRING)","ServiceBusMessage(fully_qualified_namespace)","ServiceBusSubQueue(DefaultAzureCredential())"],"answer":0,"setId":"bouvet:service-bus","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/03-connect-consume/service-bus.json","reviewDate":"2026-10-11"},{"id":"bouvet:service-bus-022","prompt":"Which Python SDK value opens the receiver for a queue's built-in dead-letter subqueue?","explanation":"Pass ServiceBusSubQueue.DEAD_LETTER as the receiver's sub_queue parameter. The returned receiver works like a normal receiver and needs an explicit completion to remove a DLQ copy.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/service-bus-messaging/service-bus-messaging-overview","topic":"service-bus","type":"single","options":["sub_queue=ServiceBusSubQueue.DEAD_LETTER","receive_mode=ServiceBusReceiveMode.RECEIVE_AND_DELETE","queue_name='$Default'","dead_letter=True on ServiceBusClient"],"answer":0,"setId":"bouvet:service-bus","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/03-connect-consume/service-bus.json","reviewDate":"2026-10-11"},{"id":"bouvet:service-bus-023","prompt":"A business-critical payment command needs durable storage, explicit completion after processing, retries, and a built-in DLQ. Which Azure service best fits?","explanation":"Service Bus is the reliable brokered-messaging choice for commands that need locks, explicit settlement, retries, DLQs, sessions, or transactions. Event Grid is for pushed notifications, and Event Hubs is for stream ingestion.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/service-bus-messaging/service-bus-messaging-overview","topic":"service-bus","type":"single","options":["Azure Event Grid","Azure Service Bus","Azure Event Hubs","Azure Cache for Redis"],"answer":1,"setId":"bouvet:service-bus","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/03-connect-consume/service-bus.json","reviewDate":"2026-10-11"},{"id":"bouvet:service-bus-024","prompt":"Which statements correctly distinguish Service Bus from related Azure messaging services? (Select all that apply)","explanation":"Service Bus is pull-based brokered messaging with settlement. Event Grid pushes event notifications. Event Hubs is a replayable stream rather than per-message work completion, and Storage Queues do not provide Service Bus topics/subscriptions.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/service-bus-messaging/service-bus-messaging-overview","topic":"service-bus","type":"multi","options":["Service Bus consumers normally pull durable messages from queues or subscriptions","Event Grid normally pushes a notification to a handler","Service Bus supports explicit Peek-Lock settlement for business messages","Event Hubs removes each event as soon as one consumer reads it","Azure Storage Queues provide Service Bus topics and subscriptions"],"answer":[0,1,2],"choose":3,"setId":"bouvet:service-bus","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/03-connect-consume/service-bus.json","reviewDate":"2026-10-11"},{"id":"bouvet:service-bus-025","prompt":"A Peek-Lock worker legitimately needs eight minutes to process a message, but the entity's lock duration is five minutes. What should the worker do?","explanation":"Entity lock duration can be at most five minutes, but a Peek-Lock receiver can renew a live lock. The SDK's automatic lock renewal helper is appropriate for legitimately longer work. Complete only after the business work succeeds; MaxDeliveryCount controls retries, not lock length.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/service-bus-messaging/service-bus-messaging-overview","topic":"service-bus","type":"single","options":["Complete the message before starting the work","Renew the message lock while processing, for example with the SDK's automatic lock renewer","Switch to Receive-and-Delete","Increase MaxDeliveryCount to make the current lock longer"],"answer":1,"setId":"bouvet:service-bus","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/03-connect-consume/service-bus.json","reviewDate":"2026-10-11"},{"id":"bouvet:service-bus-026","prompt":"A production app has one managed identity that only sends to a queue and another that only receives. Which least-privilege assignments are correct? (Select all that apply)","explanation":"Use the dedicated data-plane roles and scope them to the smallest practical entity. A management-plane Contributor assignment does not grant send or receive operations, and sharing the namespace's all-powerful SAS policy is broader and secret-based.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/service-bus-messaging/service-bus-messaging-overview","topic":"service-bus","type":"multi","options":["Assign Azure Service Bus Data Sender to the sending identity","Assign Azure Service Bus Data Receiver to the receiving identity","Assign namespace Contributor to both; it automatically grants send and receive","Give both identities RootManageSharedAccessKey"],"answer":[0,1],"choose":2,"setId":"bouvet:service-bus","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/03-connect-consume/service-bus.json","reviewDate":"2026-10-11"},{"id":"bouvet:service-bus-027","prompt":"Put the setup for a selective high-priority topic subscription in order.","explanation":"A new subscription starts with $Default, which accepts everything. Delete it before adding the selective SQL rule; otherwise the default rule still copies normal-priority messages. Consumers then receive from the subscription, never directly from the topic.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/service-bus-messaging/service-bus-messaging-overview","topic":"service-bus","type":"order","options":["Create the topic subscription","Delete its $Default TrueFilter rule","Create a rule with the SQL filter priority = 'high'","Receive matching messages from the subscription"],"answer":["Create the topic subscription","Delete its $Default TrueFilter rule","Create a rule with the SQL filter priority = 'high'","Receive matching messages from the subscription"],"setId":"bouvet:service-bus","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/03-connect-consume/service-bus.json","reviewDate":"2026-10-11"},{"id":"bouvet:service-bus-028","prompt":"A dead-lettered message has remained in a Service Bus DLQ longer than its original time-to-live. Why is it still present?","explanation":"The built-in DLQ does not observe normal message TTL and does not purge itself. A receiver must inspect and deliberately settle DLQ messages; completing a DLQ copy deletes it rather than replaying it.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/service-bus-messaging/service-bus-messaging-overview","topic":"service-bus","type":"single","options":["DLQs ignore normal message TTL and have no automatic cleanup","DLQs automatically renew the original message lock forever","The topic recreates every expired message","MaxDeliveryCount resets the TTL each hour"],"answer":0,"setId":"bouvet:service-bus","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/03-connect-consume/service-bus.json","reviewDate":"2026-10-11"},{"id":"bouvet:service-bus-029","prompt":"A worker commits an order to a database, but its complete_message call fails after the lock is lost. Service Bus later redelivers the message. What prevents a duplicate order?","explanation":"Peek-Lock protects against loss but permits redelivery when settlement is not confirmed. Store a stable message or business key with the database effect so a repeated delivery detects that the order was already applied. Broker duplicate detection protects repeated sends, not this receive-side case.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/service-bus-messaging/service-bus-messaging-overview","topic":"service-bus","type":"single","options":["Use Receive-and-Delete for all orders","Make the database operation idempotent using MessageId or a stable business key","Assume Peek-Lock guarantees exactly-once processing","Remove MessageId so Service Bus cannot recognize the message"],"answer":1,"setId":"bouvet:service-bus","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/03-connect-consume/service-bus.json","reviewDate":"2026-10-11"},{"id":"bouvet:app-config-001","prompt":"What kind of data is Azure App Configuration designed to store?","explanation":"App Configuration is a central store for non-secret application settings and feature flags. Secrets (passwords, keys, certificates) belong in Key Vault. App Configuration can hold a *reference* to a Key Vault secret, but never the secret value itself.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/azure-app-configuration/overview","topic":"app-configuration","type":"single","options":["Secrets like passwords, API keys, and certificates","Non-secret application settings and feature flags","Application log and telemetry data","Blob and file storage for large binary objects"],"answer":1,"setId":"bouvet:app-configuration","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/app-configuration.json","reviewDate":"2026-10-11"},{"id":"bouvet:app-config-002","prompt":"You need the same configuration key to return a different value in dev versus prod. Which App Configuration feature do you use?","explanation":"Labels are the per-environment mechanism: the same key can hold a different value per label (e.g. `dev`, `prod`). You don't create separate keys per environment.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/azure-app-configuration/overview","topic":"app-configuration","type":"single","options":["Content types","Labels","Snapshots","Separate keys, one per environment"],"answer":1,"setId":"bouvet:app-configuration","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/app-configuration.json","reviewDate":"2026-10-11"},{"id":"bouvet:app-config-003","prompt":"How does App Configuration store a database password that lives in Key Vault?","explanation":"A Key Vault reference is a key whose value is a URI pointing at the secret in Key Vault. The secret value never sits in App Configuration, and the app needs its own Key Vault permission to resolve it.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/azure-app-configuration/overview","topic":"app-configuration","type":"single","options":["It copies the secret value into App Configuration for fast reads","It stores a Key Vault reference — a URI pointing at the secret, not the value","It encrypts the secret and stores the ciphertext","It cannot store anything related to Key Vault secrets"],"answer":1,"setId":"bouvet:app-configuration","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/app-configuration.json","reviewDate":"2026-10-11"},{"id":"bouvet:app-config-004","prompt":"An app reads a Key Vault reference from App Configuration but fails to get the secret value. What is the most likely cause?","explanation":"App Configuration only hands back the reference (URI). Resolving the actual secret requires the app's identity to have its OWN read permission on the Key Vault secret. Access to App Configuration does not grant access to Key Vault.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/azure-app-configuration/overview","topic":"app-configuration","type":"single","options":["The reference must be created with a special CLI command","The app's identity lacks permission to read the secret in Key Vault","Key Vault references can only be resolved from .NET, not Python","App Configuration must be on the Standard tier to resolve references"],"answer":1,"setId":"bouvet:app-configuration","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/app-configuration.json","reviewDate":"2026-10-11"},{"id":"bouvet:app-config-005","prompt":"What is a feature flag in App Configuration, technically?","explanation":"A feature flag is an ordinary key with the reserved prefix `.appconfig.featureflag/` and a feature-flag content type. Its value is structured JSON; the application observes a changed flag after its provider reloads or refreshes, without a code deployment.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/azure-app-configuration/overview","topic":"app-configuration","type":"single","options":["A separate Azure resource linked to the store","A specially-namespaced key (prefix `.appconfig.featureflag/`) whose value is on/off JSON","A label named 'feature' applied to any key","A snapshot that toggles keys on and off"],"answer":1,"setId":"bouvet:app-configuration","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/app-configuration.json","reviewDate":"2026-10-11"},{"id":"bouvet:app-config-006","prompt":"Which RBAC role lets an identity READ key-values (but not write them) from an App Configuration store?","explanation":"App Configuration Data Reader grants read access to the key-values. Data Owner adds write. Contributor and Reader are resource-management roles and do NOT grant data-plane read/write.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/azure-app-configuration/overview","topic":"app-configuration","type":"single","options":["Contributor","App Configuration Data Reader","App Configuration Data Owner","Reader"],"answer":1,"setId":"bouvet:app-configuration","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/app-configuration.json","reviewDate":"2026-10-11"},{"id":"bouvet:app-config-007","prompt":"A user has the Contributor role on an App Configuration store but gets 'forbidden' when reading key-values with Entra ID auth. Why?","explanation":"Contributor manages the resource (create/delete/configure the store) but does not grant data-plane access to the key-values. Reading/writing data requires App Configuration Data Reader or Data Owner.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/azure-app-configuration/overview","topic":"app-configuration","type":"single","options":["Contributor only manages the resource, not the data plane; they need Data Reader/Owner","Contributor is a read-only role","They must also be a Global Administrator","Entra ID auth is not supported by App Configuration"],"answer":0,"setId":"bouvet:app-configuration","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/app-configuration.json","reviewDate":"2026-10-11"},{"id":"bouvet:app-config-008","prompt":"Which are valid ways for an application to authenticate to App Configuration? (Select all that apply)","explanation":"You authenticate with either a connection string (access key) or Entra ID — via a managed identity in Azure or DefaultAzureCredential (your `az login`) in dev. A Key Vault reference is a kind of stored value, not an authentication method.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/azure-app-configuration/overview","topic":"app-configuration","type":"multi","options":["A connection string (access key)","Entra ID via a managed identity with a data-plane role","Entra ID via DefaultAzureCredential in development","A Key Vault reference"],"answer":[0,1,2],"choose":3,"setId":"bouvet:app-configuration","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/app-configuration.json","reviewDate":"2026-10-11"},{"id":"bouvet:app-config-009","prompt":"In the key `App:Api:Timeout`, what does the `:` character mean to App Configuration?","explanation":"`:` is just a naming convention that implies hierarchy. App Configuration stores a flat list of keys — there are no real folders. The label is a separate field, not part of the key string.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/azure-app-configuration/overview","topic":"app-configuration","type":"single","options":["It creates real folders/containers in the store","It is a naming convention for hierarchy; the store is actually a flat list of keys","It separates the key from its label","It marks the value as a Key Vault reference"],"answer":1,"setId":"bouvet:app-configuration","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/app-configuration.json","reviewDate":"2026-10-11"},{"id":"bouvet:app-config-010","prompt":"Which is the recommended way for a production app to authenticate to App Configuration?","explanation":"Entra ID with a managed identity + a data-plane role (Data Reader/Owner) is the recommended passwordless approach — there is no secret to store or rotate. Connection strings work but are a shared secret you must protect.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/azure-app-configuration/overview","topic":"app-configuration","type":"single","options":["A connection string stored in an environment variable","Entra ID with a managed identity and a data-plane RBAC role (passwordless)","An account key embedded in the app's source code","A shared access signature (SAS) token"],"answer":1,"setId":"bouvet:app-configuration","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/app-configuration.json","reviewDate":"2026-10-11"},{"id":"bouvet:app-config-011","prompt":"You deleted a Standard-tier App Configuration store and immediately try to recreate one with the same name, but it fails. Why?","explanation":"Standard and Premium stores have automatic soft delete, which retains the deleted store and reserves its name. Purge it to request early removal when purge protection permits, then allow for asynchronous cleanup before recreating it. Free and Developer stores do not have soft delete.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/azure-app-configuration/overview","topic":"app-configuration","type":"single","options":["Store names can never be reused","Soft-delete reserves the name until the retention window elapses or you purge it","You must wait 24 hours after any create operation","The Free tier only allows one store ever"],"answer":1,"setId":"bouvet:app-configuration","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/app-configuration.json","reviewDate":"2026-10-11"},{"id":"bouvet:app-config-012","prompt":"Which capabilities does the Standard tier add over the Free tier of App Configuration? (Select all that apply)","explanation":"Standard adds geo-replication, an SLA, and higher limits. Feature flags are available on both tiers — they are just specially-namespaced keys, not a paid feature.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/azure-app-configuration/overview","topic":"app-configuration","type":"multi","options":["Geo-replication (replicas)","A financially-backed SLA","Higher storage limits","The ability to store feature flags"],"answer":[0,1,2],"choose":3,"setId":"bouvet:app-configuration","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/app-configuration.json","reviewDate":"2026-10-11"},{"id":"bouvet:app-config-013","prompt":"What is an App Configuration snapshot?","explanation":"A snapshot is an immutable, named, point-in-time collection of key-values — useful for pinning a known-good config or rolling back.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/azure-app-configuration/overview","topic":"app-configuration","type":"single","options":["A backup of the entire Azure subscription","An immutable, named, point-in-time set of key-values","A live view that updates as keys change","A copy of the store's access keys"],"answer":1,"setId":"bouvet:app-configuration","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/app-configuration.json","reviewDate":"2026-10-11"},{"id":"bouvet:app-config-014","prompt":"Which Python class from the `azure-appconfiguration` SDK represents a plain key/value setting?","explanation":"`ConfigurationSetting(key=..., value=...)` represents a plain key/value. `FeatureFlagConfigurationSetting` is for feature flags, `SecretReferenceConfigurationSetting` for Key Vault references, and `AzureAppConfigurationClient` is the client.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/azure-app-configuration/overview","topic":"app-configuration","type":"single","options":["ConfigurationSetting","FeatureFlagConfigurationSetting","SecretReferenceConfigurationSetting","AzureAppConfigurationClient"],"answer":0,"setId":"bouvet:app-configuration","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/app-configuration.json","reviewDate":"2026-10-11"},{"id":"bouvet:app-config-015","prompt":"Which client method reads a single setting back from App Configuration in the Python SDK?","explanation":"`get_configuration_setting(key=..., label=...)` reads one setting. `set_configuration_setting` writes one, and `list_configuration_settings` streams multiple matching settings.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/azure-app-configuration/overview","topic":"app-configuration","type":"single","options":["list_configuration_settings","get_configuration_setting","set_configuration_setting","read_key"],"answer":1,"setId":"bouvet:app-configuration","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/app-configuration.json","reviewDate":"2026-10-11"},{"id":"bouvet:app-config-016","prompt":"Which library loads selected App Configuration settings into a dict-like object and supports refresh and Key Vault reference resolution?","explanation":"The `azure-appconfiguration-provider` library's `load(...)` returns a dict-like provider with refresh and feature-management integration. Key Vault references are resolved when you also supply a Key Vault credential, per-vault client configuration, or resolver. The raw SDK exposes explicit get/set operations.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/azure-app-configuration/overview","topic":"app-configuration","type":"single","options":["azure-appconfiguration (the raw SDK)","azure-appconfiguration-provider","azure-identity","azure-keyvault-secrets"],"answer":1,"setId":"bouvet:app-configuration","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/app-configuration.json","reviewDate":"2026-10-11"},{"id":"bouvet:app-config-017","prompt":"Which CLI command grants your signed-in user read access to an App Configuration store's data via Entra ID?","explanation":"You grant the data-plane role `App Configuration Data Reader` (or Data Owner for write) scoped to the store's resource ID. `Reader` is a resource-management role and does not grant data-plane access.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/azure-app-configuration/overview","topic":"app-configuration","type":"single","options":["az appconfig kv set --key ...","az role assignment create --role \"App Configuration Data Reader\" --scope \u003cstore-id>","az appconfig credential list","az role assignment create --role \"Reader\" --scope \u003cstore-id>"],"answer":1,"setId":"bouvet:app-configuration","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/app-configuration.json","reviewDate":"2026-10-11"},{"id":"bouvet:app-config-018","prompt":"Which statements about labels are true? (Select all that apply)","explanation":"A label is a separate axis on a key: the same key can carry different values per label, and you retrieve one by passing key + label. Labels have nothing to do with encryption.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/azure-app-configuration/overview","topic":"app-configuration","type":"multi","options":["The same key can have different values under different labels","A label is a separate field from the key, not part of the key string","You read a specific environment's value by passing both key and label","Labels encrypt the value at rest"],"answer":[0,1,2],"choose":3,"setId":"bouvet:app-configuration","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/app-configuration.json","reviewDate":"2026-10-11"},{"id":"bouvet:app-config-019","prompt":"A teammate says 'just put the DB password in App Configuration so everything reads one store.' What's the correct guidance?","explanation":"Secrets belong in Key Vault. Store only the Key Vault secret URI in App Configuration. A configured provider can present one merged configuration view to the app, but it resolves the value by calling Key Vault with the application's authorized identity.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/azure-app-configuration/overview","topic":"app-configuration","type":"single","options":["Agree — App Configuration is a secure secret store","Store the secret in Key Vault and put a Key Vault reference in App Configuration","Store the password as a feature flag","Store the password in a snapshot for immutability"],"answer":1,"setId":"bouvet:app-configuration","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/app-configuration.json","reviewDate":"2026-10-11"},{"id":"bouvet:app-config-020","prompt":"Put these Azure CLI steps in order to create an App Configuration store, seed a key, and read its value:","explanation":"Correct order: 1) create the resource group, 2) create the App Configuration store inside it, 3) set a key-value, 4) read the value back. You must create the store before you can write keys, and write a key before you can read it.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/azure-app-configuration/overview","topic":"app-configuration","type":"order","options":["az group create --name \u003crg> --location westeurope","az appconfig create --name \u003cstore> --resource-group \u003crg> --sku Free","az appconfig kv set --name \u003cstore> --key App:Greeting --value Hello --yes","az appconfig kv show --name \u003cstore> --key App:Greeting --query value"],"answer":["az group create --name \u003crg> --location westeurope","az appconfig create --name \u003cstore> --resource-group \u003crg> --sku Free","az appconfig kv set --name \u003cstore> --key App:Greeting --value Hello --yes","az appconfig kv show --name \u003cstore> --key App:Greeting --query value"],"setId":"bouvet:app-configuration","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/app-configuration.json","reviewDate":"2026-10-11"},{"id":"bouvet:app-config-021","prompt":"Put these Python SDK steps in order to write and read back a labeled setting:","explanation":"Correct order: 1) create the client, 2) build the ConfigurationSetting (with its label), 3) write it, 4) read it back by key + label. The label narrows the read to the prod value.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/azure-app-configuration/overview","topic":"app-configuration","type":"order","options":["client = AzureAppConfigurationClient.from_connection_string(conn)","setting = ConfigurationSetting(key='App:Greeting', label='prod', value='Hi')","client.set_configuration_setting(setting)","client.get_configuration_setting(key='App:Greeting', label='prod')"],"answer":["client = AzureAppConfigurationClient.from_connection_string(conn)","setting = ConfigurationSetting(key='App:Greeting', label='prod', value='Hi')","client.set_configuration_setting(setting)","client.get_configuration_setting(key='App:Greeting', label='prod')"],"setId":"bouvet:app-configuration","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/app-configuration.json","reviewDate":"2026-10-11"},{"id":"bouvet:app-config-022","prompt":"What does a feature flag add beyond storing a plain Boolean-like configuration value?","explanation":"Any App Configuration setting can change independently of an application deployment. A feature flag adds a standard schema and feature-management tooling, including conditions such as targeting and time windows that the application library evaluates.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/azure-app-configuration/overview","topic":"app-configuration","type":"single","options":["It encrypts the feature's code","A standard feature-management schema and library evaluation, including conditional rollout filters","It automatically scales the feature across regions","It stores the feature's source code in Azure"],"answer":1,"setId":"bouvet:app-configuration","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/app-configuration.json","reviewDate":"2026-10-11"},{"id":"bouvet:app-config-023","prompt":"Which CLI command retrieves the connection string an app would use for access-key authentication?","explanation":"`az appconfig credential list` returns the access keys, including the Primary/Secondary connection strings. `az appconfig show` returns resource metadata (like the endpoint), not the credentials.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/azure-app-configuration/overview","topic":"app-configuration","type":"single","options":["az appconfig kv list --name \u003cstore>","az appconfig credential list --name \u003cstore> --resource-group \u003crg>","az appconfig feature list --name \u003cstore>","az appconfig show --name \u003cstore>"],"answer":1,"setId":"bouvet:app-configuration","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/app-configuration.json","reviewDate":"2026-10-11"},{"id":"bouvet:app-config-024","prompt":"In the Python SDK, which method would you use to stream all keys matching `App:*`?","explanation":"`list_configuration_settings(key_filter='App:*')` streams every matching setting (the `*` is a wildcard). `get_configuration_setting` reads exactly one key.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/azure-app-configuration/overview","topic":"app-configuration","type":"single","options":["get_configuration_setting(key='App:*')","list_configuration_settings(key_filter='App:*')","set_configuration_setting(key='App:*')","get_keys(prefix='App:')"],"answer":1,"setId":"bouvet:app-configuration","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/app-configuration.json","reviewDate":"2026-10-11"},{"id":"bouvet:app-config-025","prompt":"A Python app calls the App Configuration provider's `load(...)` with no selectors. Which label does it load by default?","explanation":"The Python provider loads key-values with no label by default. Use ordered `SettingSelector` entries when you need a base set plus labeled overrides; later selectors win for duplicate keys.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/azure-app-configuration/overview","topic":"app-configuration","type":"single","options":["Every label","Only key-values with no label","Only the `prod` label","The label matching the Azure region"],"answer":1,"setId":"bouvet:app-configuration","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/app-configuration.json","reviewDate":"2026-10-11"},{"id":"bouvet:app-config-026","prompt":"You enable provider refresh, but settings never change while the application is idle. Why?","explanation":"Enabling refresh configures the provider's refresh behavior and interval, but the application must trigger `refresh()`, commonly when processing activity. This avoids background requests while the app is idle.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/azure-app-configuration/overview","topic":"app-configuration","type":"single","options":["App Configuration can refresh only after redeployment","The Python provider checks for changes when the application calls `refresh()`; it does not run a background refresh loop","Refresh requires a Premium store","Labels prevent all refresh operations"],"answer":1,"setId":"bouvet:app-configuration","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/app-configuration.json","reviewDate":"2026-10-11"},{"id":"bouvet:app-config-027","prompt":"A provider loads a Key Vault reference from App Configuration. What is required to resolve it to the secret value? (Select all that apply)","explanation":"The reference stores a URI, not the value. Configure the provider's Key Vault resolution path and grant the chosen identity Key Vault data-plane access. App Configuration permission does not imply Key Vault permission.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/azure-app-configuration/overview","topic":"app-configuration","type":"multi","options":["A Key Vault credential, per-vault client configuration, or secret resolver configured on the provider","The application's identity must be authorized to read the Key Vault secret when a credential is used","The App Configuration Data Reader role automatically grants Key Vault access","The secret value must first be copied into App Configuration"],"answer":[0,1],"choose":2,"setId":"bouvet:app-configuration","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/app-configuration.json","reviewDate":"2026-10-11"},{"id":"bouvet:app-config-028","prompt":"Development and production settings require different access permissions. Should labels be the only isolation boundary?","explanation":"Labels distinguish values inside one store, but access control is primarily per store. Microsoft recommends separate stores for environments that require different permissions; labels are suitable when that security isolation is unnecessary.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/azure-app-configuration/overview","topic":"app-configuration","type":"single","options":["Yes; every label has its own independent RBAC scope","No; use separate stores when environments require security isolation, and labels when shared store permissions are acceptable","Yes; labels automatically create separate encryption keys","No; App Configuration supports only one environment per subscription"],"answer":1,"setId":"bouvet:app-configuration","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/app-configuration.json","reviewDate":"2026-10-11"},{"id":"bouvet:app-config-029","prompt":"Put these provider steps in order to load no-label defaults and then override them with `prod` values:","explanation":"Authenticate, define ordered selectors, load, then consume the merged provider. When selectors return the same key, the later selector wins, so `prod` must follow the no-label defaults.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/azure-app-configuration/overview","topic":"app-configuration","type":"order","options":["Create `DefaultAzureCredential`","Create selectors for no-label values first and `prod` values second","Call `load(endpoint=..., credential=..., selects=selectors)`","Read the merged value from the returned provider"],"answer":["Create `DefaultAzureCredential`","Create selectors for no-label values first and `prod` values second","Call `load(endpoint=..., credential=..., selects=selectors)`","Read the merged value from the returned provider"],"setId":"bouvet:app-configuration","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/app-configuration.json","reviewDate":"2026-10-11"},{"id":"bouvet:kv-001","prompt":"What is the primary purpose of Azure Key Vault?","explanation":"Azure Key Vault is a cloud service for securely storing and managing secrets, keys, and certificates used by applications and services. It solves the problem of hardcoded credentials in code or configuration files.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/key-vault/general/overview","topic":"key-vault","type":"single","options":["To store and manage virtual machine images","To securely store and manage secrets, keys, and certificates","To host web applications","To provide a managed database service"],"answer":1,"setId":"bouvet:key-vault","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/key-vault.json","reviewDate":"2026-10-11"},{"id":"bouvet:kv-002","prompt":"Which of the following is NOT a type of object that can be stored in Azure Key Vault?","explanation":"Azure Key Vault stores secrets, keys, and certificates. Virtual Machines are compute resources, not objects stored in Key Vault.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/key-vault/general/overview","topic":"key-vault","type":"single","options":["Secrets","Keys","Certificates","Virtual Machines"],"answer":3,"setId":"bouvet:key-vault","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/key-vault.json","reviewDate":"2026-10-11"},{"id":"bouvet:kv-003","prompt":"What is the maximum size of a secret that can be stored in Azure Key Vault?","explanation":"Secrets in Azure Key Vault can be up to 25 KB each. This is sufficient for most sensitive configuration values like connection strings, passwords, and API keys.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/key-vault/general/overview","topic":"key-vault","type":"single","options":["1 KB","10 KB","25 KB","100 KB"],"answer":2,"setId":"bouvet:key-vault","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/key-vault.json","reviewDate":"2026-10-11"},{"id":"bouvet:kv-004","prompt":"Which authentication method is recommended for applications running on Azure services?","explanation":"Managed Identity is the recommended authentication method for Azure-hosted applications. Azure automatically creates and manages the identity, so there are no credentials to manage or rotate.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/key-vault/general/overview","topic":"key-vault","type":"single","options":["Connection strings","Service Principal with client secret","Managed Identity","Username and password"],"answer":2,"setId":"bouvet:key-vault","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/key-vault.json","reviewDate":"2026-10-11"},{"id":"bouvet:kv-005","prompt":"Which of the following are valid authentication methods for Azure Key Vault? (Select all that apply)","explanation":"Valid authentication methods for Key Vault include: Managed Identity (for Azure-hosted resources), Service Principal (standalone identity), and User Identity (for development/testing). Connection strings and SAS are not authentication methods for Key Vault.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/key-vault/general/overview","topic":"key-vault","type":"multi","options":["Managed Identity","Service Principal","User Identity","Connection String","Shared Access Signature (SAS)"],"answer":[0,1,2],"choose":3,"setId":"bouvet:key-vault","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/key-vault.json","reviewDate":"2026-10-11"},{"id":"bouvet:kv-006","prompt":"What happens when you update a secret in Azure Key Vault?","explanation":"When you update a secret, Key Vault creates a new version and retains the prior version as an independently addressable version. This versioning enables safe rotation: an application can pin a known version while versionless reads resolve to the latest. Soft-delete recovery is a separate feature for deleted objects.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/key-vault/general/overview","topic":"key-vault","type":"single","options":["The old secret is deleted permanently","A new version is created and the old version remains independently addressable","The secret name changes automatically","The application using it must be redeployed immediately"],"answer":1,"setId":"bouvet:key-vault","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/key-vault.json","reviewDate":"2026-10-11"},{"id":"bouvet:kv-007","prompt":"What is the purpose of soft delete in Azure Key Vault?","explanation":"Soft delete retains deleted items (secrets, keys, certificates, vaults) for a configurable period (7-90 days) before permanent deletion. This provides a safety net against accidental deletion.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/key-vault/general/overview","topic":"key-vault","type":"single","options":["To encrypt secrets at rest","To retain deleted items for a configurable period before permanent deletion","To automatically rotate secrets","To compress secrets to save space"],"answer":1,"setId":"bouvet:key-vault","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/key-vault.json","reviewDate":"2026-10-11"},{"id":"bouvet:kv-008","prompt":"What does purge protection do in Azure Key Vault?","explanation":"Purge protection prevents a soft-deleted vault or object from being purged until its retention period expires. Once purge protection is enabled, nobody — including Microsoft — can disable or bypass it.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/key-vault/general/overview","topic":"key-vault","type":"single","options":["Prevents permanent deletion until the retention period expires, and cannot be disabled once enabled","Automatically purges old versions of secrets","Encrypts all secrets with a master key","Prevents creation of new secrets"],"answer":0,"setId":"bouvet:key-vault","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/key-vault.json","reviewDate":"2026-10-11"},{"id":"bouvet:kv-009","prompt":"Which tier of Azure Key Vault supports HSM-backed keys?","explanation":"The Premium tier supports HSM-backed keys; the Standard tier stores software-protected keys. Do not confuse a Premium Key Vault with Azure Managed HSM, which is a separate dedicated-HSM resource type.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/key-vault/general/overview","topic":"key-vault","type":"single","options":["Basic","Standard","Premium","Free"],"answer":2,"setId":"bouvet:key-vault","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/key-vault.json","reviewDate":"2026-10-11"},{"id":"bouvet:kv-010","prompt":"Which Azure service is best suited for storing application configuration settings?","explanation":"Azure App Configuration is designed for storing application configuration settings and feature flags. Azure Key Vault is for secrets, keys, and certificates. However, App Configuration can reference secrets stored in Key Vault.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/key-vault/general/overview","topic":"key-vault","type":"single","options":["Azure Key Vault","Azure App Configuration","Azure Storage","Azure SQL Database"],"answer":1,"setId":"bouvet:key-vault","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/key-vault.json","reviewDate":"2026-10-11"},{"id":"bouvet:kv-011","prompt":"Why is `DefaultAzureCredential` useful when the same application runs locally and in Azure?","explanation":"`DefaultAzureCredential` is a credential chain. It can use a supported developer credential locally and a managed identity after deployment, so the application code stays the same. The chain has evolved over time, so a fixed memorized order is not a safe design assumption.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/key-vault/general/overview","topic":"key-vault","type":"single","options":["It grants Key Vault permissions without an RBAC role","It can use a developer sign-in locally and a managed identity in Azure without environment-specific authentication code","It stores the Key Vault access key in the application binary","It disables all credential types except Azure CLI"],"answer":1,"setId":"bouvet:key-vault","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/key-vault.json","reviewDate":"2026-10-11"},{"id":"bouvet:kv-012","prompt":"Which of the following are valid RBAC roles for Azure Key Vault? (Select all that apply)","explanation":"Valid roles include Key Vault Reader (object metadata), Key Vault Secrets User (secret values), Key Vault Contributor (control-plane vault management), and Key Vault Administrator (all Key Vault data-plane operations). Administrator does not grant control-plane management or role-assignment permission, and 'Key Vault Owner' is not a built-in role name.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/key-vault/general/overview","topic":"key-vault","type":"multi","options":["Key Vault Reader","Key Vault Secrets User","Key Vault Contributor","Key Vault Owner","Key Vault Administrator"],"answer":[0,1,2,4],"choose":4,"setId":"bouvet:key-vault","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/key-vault.json","reviewDate":"2026-10-11"},{"id":"bouvet:kv-013","prompt":"What is the maximum length for a Key Vault name?","explanation":"Key Vault names are globally unique and 3-24 characters long. They can contain letters, digits, and hyphens, must start with a letter, must end with a letter or digit, and cannot contain consecutive hyphens.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/key-vault/general/overview","topic":"key-vault","type":"single","options":["16 characters","24 characters","32 characters","64 characters"],"answer":1,"setId":"bouvet:key-vault","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/key-vault.json","reviewDate":"2026-10-11"},{"id":"bouvet:kv-014","prompt":"Which CLI command creates a new secret in Azure Key Vault?","explanation":"The az keyvault secret set command creates a new secret or updates an existing one in Azure Key Vault.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/key-vault/general/overview","topic":"key-vault","type":"single","options":["az keyvault secret create","az keyvault secret set","az keyvault secret add","az keyvault secret new"],"answer":1,"setId":"bouvet:key-vault","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/key-vault.json","reviewDate":"2026-10-11"},{"id":"bouvet:kv-015","prompt":"Which command retrieves the value of a secret from Azure Key Vault?","explanation":"The az keyvault secret show command retrieves a secret from Azure Key Vault. Use --query value --output tsv to get just the value as plain text.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/key-vault/general/overview","topic":"key-vault","type":"single","options":["az keyvault secret get","az keyvault secret show","az keyvault secret retrieve","az keyvault secret read"],"answer":1,"setId":"bouvet:key-vault","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/key-vault.json","reviewDate":"2026-10-11"},{"id":"bouvet:kv-016","prompt":"An application calls `get_secret(name)` without a version after a new secret version is created. What does Key Vault return?","explanation":"A versionless read targets the latest version. A consumer that pins a version or caches the old value does not automatically change; it must perform a versionless read again or refresh its cache.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/key-vault/general/overview","topic":"key-vault","type":"single","options":["The latest version on that read","The application must be restarted to pick up the new value","The application must be redeployed with the new value","The old value is no longer accessible"],"answer":0,"setId":"bouvet:key-vault","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/key-vault.json","reviewDate":"2026-10-11"},{"id":"bouvet:kv-017","prompt":"Which type of object in Key Vault can be used for TLS/SSL certificates?","explanation":"Certificates in Azure Key Vault are X.509 certificates that can be used for TLS/SSL and authentication. They contain a public key + private key pair with a certificate.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/key-vault/general/overview","topic":"key-vault","type":"single","options":["Secrets","Keys","Certificates","All of the above"],"answer":2,"setId":"bouvet:key-vault","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/key-vault.json","reviewDate":"2026-10-11","preserveOrder":true},{"id":"bouvet:kv-018","prompt":"Which command lists all versions of a specific secret?","explanation":"The az keyvault secret list-versions command lists all versions of a specific secret in Azure Key Vault.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/key-vault/general/overview","topic":"key-vault","type":"single","options":["az keyvault secret list","az keyvault secret list-versions","az keyvault secret show --all-versions","az keyvault secret get-versions"],"answer":1,"setId":"bouvet:key-vault","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/key-vault.json","reviewDate":"2026-10-11"},{"id":"bouvet:kv-019","prompt":"Which statement correctly distinguishes Key Vault's control plane from its data plane?","explanation":"Creating or configuring the vault is a control-plane operation. Getting a secret or using a cryptographic key is a data-plane operation. Permissions for the two planes are independent.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/key-vault/general/overview","topic":"key-vault","type":"single","options":["Both planes use the same role and endpoint for every operation","The control plane manages the vault resource; the data plane works with secrets, keys, and certificates","The control plane reads secret values; the data plane creates resource groups","Only the control plane uses Microsoft Entra ID"],"answer":1,"setId":"bouvet:key-vault","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/key-vault.json","reviewDate":"2026-10-11"},{"id":"bouvet:kv-020","prompt":"Which of these is a valid software-protected key type in a Standard Azure Key Vault?","explanation":"Standard Key Vault supports software-protected RSA and EC keys, so RSA is correct. AES is available only as the preview `oct-HSM` symmetric key type in Premium Key Vault, not as a software-protected Standard-vault key. DES is not a supported Key Vault key type, and SHA is a hashing algorithm.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/key-vault/general/overview","topic":"key-vault","type":"single","options":["AES","RSA","DES","SHA"],"answer":1,"setId":"bouvet:key-vault","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/key-vault.json","reviewDate":"2026-10-11"},{"id":"bouvet:kv-021","prompt":"Which of the following can be done with Azure Key Vault secrets? (Select all that apply)","explanation":"Azure Key Vault secrets can store connection strings, API keys, passwords, and other sensitive data. Secrets can have expiration dates. Virtual machine images are not stored in Key Vault.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/key-vault/general/overview","topic":"key-vault","type":"multi","options":["Store connection strings","Store API keys","Store passwords","Store virtual machine images","Set expiration dates"],"answer":[0,1,2,4],"choose":4,"setId":"bouvet:key-vault","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/key-vault.json","reviewDate":"2026-10-11"},{"id":"bouvet:kv-022","prompt":"What is the purpose of Access Policies in Azure Key Vault?","explanation":"Access Policies in Azure Key Vault provide granular control over which users and applications can perform operations (get, list, set, delete, recover, purge) on secrets, keys, or certificates. This is the legacy access control model.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/key-vault/general/overview","topic":"key-vault","type":"single","options":["To encrypt secrets at rest","To control which users and applications can perform operations on secrets, keys, and certificates","To automatically rotate secrets","To backup and restore secrets"],"answer":1,"setId":"bouvet:key-vault","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/key-vault.json","reviewDate":"2026-10-11"},{"id":"bouvet:kv-023","prompt":"Which command grants a service principal access to secrets in a Key Vault using Access Policies?","explanation":"The az keyvault set-policy command grants access to secrets, keys, or certificates in a Key Vault using the Access Policies model.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/key-vault/general/overview","topic":"key-vault","type":"single","options":["az keyvault grant-access","az keyvault set-policy","az keyvault assign-role","az keyvault add-user"],"answer":1,"setId":"bouvet:key-vault","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/key-vault.json","reviewDate":"2026-10-11"},{"id":"bouvet:kv-024","prompt":"Which command enables Azure RBAC for a Key Vault?","explanation":"The `--enable-rbac-authorization true` option selects Azure RBAC for data actions. Prepare equivalent role assignments first: after the switch, legacy access policies are ignored.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/key-vault/general/overview","topic":"key-vault","type":"single","options":["az keyvault enable-rbac","az keyvault update --enable-rbac-authorization true","az keyvault set-rbac true","az keyvault convert-to-rbac"],"answer":1,"setId":"bouvet:key-vault","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/key-vault.json","reviewDate":"2026-10-11"},{"id":"bouvet:kv-025","prompt":"What is a disabled secret in Azure Key Vault?","explanation":"A disabled secret in Azure Key Vault cannot be retrieved but still exists. This is useful for temporarily disabling access without losing the secret value.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/key-vault/general/overview","topic":"key-vault","type":"single","options":["A secret that has been deleted and can be recovered","A secret that cannot be retrieved but still exists","A secret that has been encrypted","A secret that has expired"],"answer":1,"setId":"bouvet:key-vault","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/key-vault.json","reviewDate":"2026-10-11"},{"id":"bouvet:kv-026","prompt":"Which of the following are network security options for Azure Key Vault? (Select all that apply)","explanation":"Network security options for Azure Key Vault include: Public endpoint (default), Private endpoint (VNet-only access), Firewall (IP range restrictions), and Service endpoints (Azure service traffic). VPN Gateway is not a Key Vault-specific feature.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/key-vault/general/overview","topic":"key-vault","type":"multi","options":["Public endpoint","Private endpoint","Firewall","Service endpoints","VPN Gateway"],"answer":[0,1,2,3],"choose":4,"setId":"bouvet:key-vault","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/key-vault.json","reviewDate":"2026-10-11"},{"id":"bouvet:kv-027","prompt":"What is the difference between secrets and keys in Azure Key Vault?","explanation":"Secrets in Azure Key Vault are string key-value pairs used for sensitive data like passwords and connection strings. Keys are cryptographic material (RSA, EC) used for encryption, decryption, signing, and verification operations.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/key-vault/general/overview","topic":"key-vault","type":"single","options":["Secrets are for passwords, keys are for encryption","Secrets are string values, keys are cryptographic material","Keys are string values, secrets are cryptographic material","There is no difference"],"answer":1,"setId":"bouvet:key-vault","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/key-vault.json","reviewDate":"2026-10-11"},{"id":"bouvet:kv-028","prompt":"Which Python library is used to interact with secrets in Azure Key Vault?","explanation":"The azure-keyvault-secrets Python library is used to interact with secrets in Azure Key Vault. Similarly, azure-keyvault-keys is used for keys, and azure-keyvault-certificates for certificates.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/key-vault/general/overview","topic":"key-vault","type":"single","options":["azure-keyvault","azure-keyvault-secrets","azure-secrets","azure-vault"],"answer":1,"setId":"bouvet:key-vault","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/key-vault.json","reviewDate":"2026-10-11"},{"id":"bouvet:kv-029","prompt":"Which Python library provides DefaultAzureCredential?","explanation":"The azure-identity Python library provides DefaultAzureCredential and other credential classes for authenticating with Azure services.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/key-vault/general/overview","topic":"key-vault","type":"single","options":["azure-identity","azure-authentication","azure-credentials","azure-security"],"answer":0,"setId":"bouvet:key-vault","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/key-vault.json","reviewDate":"2026-10-11"},{"id":"bouvet:kv-030","prompt":"Put these steps in the correct order to retrieve a secret from Key Vault using Python:","explanation":"Correct order: 1) Create credential, 2) Create client with vault URL and credential, 3) Call get_secret with the secret name, 4) Access the .value property to get the actual secret value.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/key-vault/general/overview","topic":"key-vault","type":"order","options":["Create DefaultAzureCredential","Create SecretClient with vault URL and credential","Call client.get_secret(secret_name)","Access the .value property of the returned secret"],"answer":["Create DefaultAzureCredential","Create SecretClient with vault URL and credential","Call client.get_secret(secret_name)","Access the .value property of the returned secret"],"setId":"bouvet:key-vault","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/key-vault.json","reviewDate":"2026-10-11"},{"id":"bouvet:kv-031","prompt":"What is the primary benefit of using Managed Identity with Azure Key Vault?","explanation":"The primary benefit of Managed Identity is that it eliminates the need to manage credentials in code or configuration. Azure automatically creates and manages the identity for your Azure resources.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/key-vault/general/overview","topic":"key-vault","type":"single","options":["It provides the highest level of encryption","It eliminates the need to manage credentials in code or configuration","It allows access from any location","It automatically rotates all secrets"],"answer":1,"setId":"bouvet:key-vault","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/key-vault.json","reviewDate":"2026-10-11"},{"id":"bouvet:kv-032","prompt":"A database password is stored as a Key Vault secret. Which action is required for a complete rotation?","explanation":"Key Vault does not know how to change an arbitrary credential in its source system. A rotation workflow must update the database or service, store the corresponding new secret version, refresh consumers, and retire the old version safely.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/key-vault/general/overview","topic":"key-vault","type":"single","options":["Create a new Key Vault version only","Update the database credential and Key Vault value, then refresh consumers before retiring the old version","Rename the vault so consumers reconnect","Enable the Premium tier so Key Vault changes the database automatically"],"answer":1,"setId":"bouvet:key-vault","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/key-vault.json","reviewDate":"2026-10-11"},{"id":"bouvet:kv-033","prompt":"How can App Configuration reference secrets from Key Vault?","explanation":"An App Configuration Key Vault reference stores a secret URI plus a reserved content type; it does not copy the secret value. A provider can resolve the reference only when configured with a Key Vault credential, and the application identity still needs Key Vault data-plane permission.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/key-vault/general/overview","topic":"key-vault","type":"single","options":["Using a direct connection string","Using a Key Vault reference in the value","Using a shared access signature","Using a REST API call"],"answer":1,"setId":"bouvet:key-vault","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/key-vault.json","reviewDate":"2026-10-11"},{"id":"bouvet:kv-034","prompt":"Which command creates an RSA key in Azure Key Vault?","explanation":"`az keyvault key create` needs the vault, key name, and `--kty` key type. `--size 2048` selects a 2,048-bit RSA key; `--type` and `--algorithm` are not the CLI parameters for this operation.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/key-vault/general/overview","topic":"key-vault","type":"single","options":["az keyvault key create --vault-name \u003cvault> --name \u003ckey> --kty RSA --size 2048","az keyvault key create --vault-name \u003cvault> --name \u003ckey> --type RSA --size 2048","az keyvault key new --vault-name \u003cvault> --name \u003ckey> --kty RSA --size 2048","az keyvault key generate --vault-name \u003cvault> --name \u003ckey> --algorithm RSA --size 2048"],"answer":0,"setId":"bouvet:key-vault","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/key-vault.json","reviewDate":"2026-10-11"},{"id":"bouvet:kv-035","prompt":"What is the default soft-delete retention period for Azure Key Vault when no different value is configured?","explanation":"The default is 90 days. At vault creation you can configure a retention period from 7 through 90 days; the study setup deliberately uses 7 days for a disposable resource.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/key-vault/general/overview","topic":"key-vault","type":"single","options":["7 days","30 days","90 days","180 days"],"answer":2,"setId":"bouvet:key-vault","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/key-vault.json","reviewDate":"2026-10-11"},{"id":"bouvet:kv-036","prompt":"Which of the following are operations that can be performed on secrets in Key Vault? (Select all that apply)","explanation":"All are valid secret operations: create/set, get, list, soft-delete, recover, and purge. Purge is permitted only when the item is soft-deleted, the caller is authorized, and purge protection was not enabled.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/key-vault/general/overview","topic":"key-vault","type":"multi","options":["Create/Set","Get/Retrieve","List","Delete","Recover","Purge"],"answer":[0,1,2,3,4,5],"choose":6,"setId":"bouvet:key-vault","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/key-vault.json","reviewDate":"2026-10-11"},{"id":"bouvet:kv-037","prompt":"Which command recovers a soft-deleted secret in Azure Key Vault?","explanation":"The az keyvault secret recover command recovers a soft-deleted secret in Azure Key Vault, as long as it's within the soft delete retention period.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/key-vault/general/overview","topic":"key-vault","type":"single","options":["az keyvault secret recover","az keyvault secret restore","az keyvault secret undelete","az keyvault secret retrieve"],"answer":0,"setId":"bouvet:key-vault","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/key-vault.json","reviewDate":"2026-10-11"},{"id":"bouvet:kv-038","prompt":"A production vault currently uses legacy access policies. What should you do before switching its data plane to Azure RBAC?","explanation":"Switching to RBAC makes existing access policies ineffective. Create and verify equivalent data-plane role assignments first to avoid an outage, then change the vault authorization model.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/key-vault/general/overview","topic":"key-vault","type":"single","options":["Delete every access policy and wait for clients to fail","Create equivalent RBAC role assignments, then switch the authorization model","Assign Key Vault Contributor to every application","Enable public anonymous access during the migration"],"answer":1,"setId":"bouvet:key-vault","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/key-vault.json","reviewDate":"2026-10-11"},{"id":"bouvet:kv-039","prompt":"Which command permanently deletes (purges) a secret from Azure Key Vault?","explanation":"The `az keyvault secret purge` command permanently removes a soft-deleted secret. It can run only when the caller has purge permission and purge protection was never enabled; enabled purge protection cannot be turned off.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/key-vault/general/overview","topic":"key-vault","type":"single","options":["az keyvault secret delete --purge","az keyvault secret purge","az keyvault secret remove","az keyvault secret hard-delete"],"answer":1,"setId":"bouvet:key-vault","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/key-vault.json","reviewDate":"2026-10-11"},{"id":"bouvet:kv-040","prompt":"Which statements about versioned and versionless secret identifiers are true? (Select all that apply)","explanation":"Versionless reads target the latest version; versioned identifiers pin one immutable value version. Older versions remain stored under the secret until that secret is deleted. Key Vault versioning does not update the external system that issued a password.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/key-vault/general/overview","topic":"key-vault","type":"multi","options":["A versionless read targets the latest version","A versioned identifier remains pinned to one immutable version","Creating a new version automatically changes a database password","Older secret versions can remain available for rollback","A versioned identifier always follows future rotations"],"answer":[0,1,3],"choose":3,"setId":"bouvet:key-vault","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/key-vault.json","reviewDate":"2026-10-11"},{"id":"bouvet:kv-041","prompt":"What is the purpose of the Key Vault URI?","explanation":"The Key Vault URI (e.g., https://myvault.vault.azure.net/) uniquely identifies the vault and is used in API calls and SDK operations to specify which vault to interact with.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/key-vault/general/overview","topic":"key-vault","type":"single","options":["To uniquely identify the vault for API calls","To encrypt data before sending to Azure","To authenticate with Azure AD","To store the vault's secrets locally"],"answer":0,"setId":"bouvet:key-vault","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/key-vault.json","reviewDate":"2026-10-11"},{"id":"bouvet:kv-042","prompt":"Which command sets attributes on a secret, such as enabling or disabling it?","explanation":"The az keyvault secret set-attributes command is used to set attributes on a secret, such as enabling/disabling it, setting expiration dates, or setting content types.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/key-vault/general/overview","topic":"key-vault","type":"single","options":["az keyvault secret set-attributes","az keyvault secret update","az keyvault secret modify","az keyvault secret configure"],"answer":0,"setId":"bouvet:key-vault","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/key-vault.json","reviewDate":"2026-10-11"},{"id":"bouvet:kv-043","prompt":"Which authorization model is recommended for the Key Vault data plane?","explanation":"Microsoft recommends Azure RBAC for Key Vault data-plane authorization. Access policies are the legacy model; they let principals with vault write permission modify data access, which weakens separation of duties.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/key-vault/general/overview","topic":"key-vault","type":"single","options":["Azure RBAC, because it provides centralized role assignments and better separation of access management","Legacy access policies, because Contributors should grant themselves secret access","Storage account shared access signatures","Anonymous public access"],"answer":0,"setId":"bouvet:key-vault","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/key-vault.json","reviewDate":"2026-10-11"},{"id":"bouvet:kv-044","prompt":"Put these steps in order to set up a Key Vault and store a secret using CLI:","explanation":"Correct order: 1) Login to Azure CLI, 2) Create resource group, 3) Create Key Vault, 4) Set secret. You must authenticate first, then create the container (resource group), then the vault itself, before storing secrets.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/key-vault/general/overview","topic":"key-vault","type":"order","options":["az login","az group create --name myrg --location westeurope","az keyvault create --name myvault --resource-group myrg","az keyvault secret set --name MySecret --vault-name myvault --value MyValue"],"answer":["az login","az group create --name myrg --location westeurope","az keyvault create --name myvault --resource-group myrg","az keyvault secret set --name MySecret --vault-name myvault --value MyValue"],"setId":"bouvet:key-vault","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/key-vault.json","reviewDate":"2026-10-11"},{"id":"bouvet:kv-045","prompt":"Which command shows the vault URI for a Key Vault?","explanation":"The az keyvault show --name myvault --query properties.vaultUri --output tsv command shows the vault URI for a Key Vault.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/key-vault/general/overview","topic":"key-vault","type":"single","options":["az keyvault show --name myvault --query properties.vaultUri","az keyvault uri --name myvault","az keyvault get-uri --name myvault","az keyvault list --name myvault --query vaultUri"],"answer":0,"setId":"bouvet:key-vault","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/key-vault.json","reviewDate":"2026-10-11"},{"id":"bouvet:kv-046","prompt":"You saved the version string from yesterday's secret and need to read that exact version for rollback. Which Python call does that?","explanation":"The optional second argument to SecretClient.get_secret is the version. Omitting it targets the latest version; listing versions returns metadata rather than the value; set_secret creates a new version.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/key-vault/general/overview","topic":"key-vault","type":"single","options":["`client.get_secret('db-password', saved_version)`","`client.get_secret('db-password')`","`client.list_properties_of_secret_versions('db-password')`","`client.set_secret('db-password', saved_version)`"],"answer":0,"setId":"bouvet:key-vault","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/key-vault.json","reviewDate":"2026-10-11"},{"id":"bouvet:kv-047","prompt":"Which of these is NOT a valid secret permission in Access Policies?","explanation":"Valid secret permissions in Access Policies are: get, list, set, delete, recover, purge, backup, restore. 'execute' is not a valid permission for secrets.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/key-vault/general/overview","topic":"key-vault","type":"single","options":["get","list","set","execute"],"answer":3,"setId":"bouvet:key-vault","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/key-vault.json","reviewDate":"2026-10-11"},{"id":"bouvet:kv-048","prompt":"A service uses a versionless Key Vault reference but still uses yesterday's secret after rotation. Which causes are plausible? (Select all that apply)","explanation":"A versionless identifier targets the latest version when it is read, but an application or provider may cache the previously resolved value. It must read or refresh again after rotation.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/key-vault/general/overview","topic":"key-vault","type":"multi","options":["The application cached the resolved value and has not refreshed it","A configuration provider's secret refresh interval has not elapsed","Versionless identifiers are permanently pinned to their first version","The application never performed another read after the new version was created","Key Vault deletes the newest version until the app restarts"],"answer":[0,1,3],"choose":3,"setId":"bouvet:key-vault","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/key-vault.json","reviewDate":"2026-10-11"},{"id":"bouvet:kv-049","prompt":"You need to verify that an application adopted a rotated secret without leaking sensitive data. What is the safest diagnostic?","explanation":"The version identifier proves which version was resolved without exposing the value. Secret values must not appear in logs, metrics, responses, terminal history, or CI output.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/key-vault/general/overview","topic":"key-vault","type":"single","options":["Log the complete secret value and compare it with Key Vault","Log only the resolved secret version identifier","Put the secret in a metric dimension","Return the secret in an HTTP response header"],"answer":1,"setId":"bouvet:key-vault","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/key-vault.json","reviewDate":"2026-10-11"},{"id":"bouvet:kv-050","prompt":"Which environment variables form the client-secret service-principal credential used by `DefaultAzureCredential`? (Select all that apply)","explanation":"EnvironmentCredential, which is part of `DefaultAzureCredential`, can use AZURE_CLIENT_ID, AZURE_TENANT_ID, and AZURE_CLIENT_SECRET for client-secret authentication. Subscription, resource group, and vault names identify resources; they do not authenticate the principal.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/key-vault/general/overview","topic":"key-vault","type":"multi","options":["AZURE_CLIENT_ID","AZURE_TENANT_ID","AZURE_CLIENT_SECRET","AZURE_SUBSCRIPTION_ID","AZURE_VAULT_NAME"],"answer":[0,1,2],"choose":3,"setId":"bouvet:key-vault","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/key-vault.json","reviewDate":"2026-10-11"},{"id":"bouvet:kv-051","prompt":"An Azure Function only needs to retrieve secret values. Which vault-scope role follows least privilege?","explanation":"Key Vault Secrets User can read secret contents. Key Vault Reader sees metadata but not values, Key Vault Contributor is control-plane only, and Administrator grants much broader data-plane access than the function needs.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/key-vault/general/overview","topic":"key-vault","type":"single","options":["Key Vault Contributor","Key Vault Reader","Key Vault Secrets User","Key Vault Administrator"],"answer":2,"setId":"bouvet:key-vault","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/key-vault.json","reviewDate":"2026-10-11"},{"id":"bouvet:kv-052","prompt":"The database supports overlapping credentials so both old and new credentials can work during rollout. Put these rotation steps in a safe order.","explanation":"With overlap supported, create the new credential, allow it at the database, publish it in Key Vault, refresh and verify clients, then retire the old credential at the database and disable the old secret version. Without overlap, coordinate the downtime/cutover explicitly; disabling a Key Vault version does not revoke the database credential.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/key-vault/secrets/tutorial-rotation-dual","topic":"key-vault","type":"order","options":["Generate a new password","Update the database to accept the new password","Store the matching value as a new Key Vault secret version","Refresh and verify application consumers","Revoke the old database credential and disable its Key Vault version after the transition"],"answer":["Generate a new password","Update the database to accept the new password","Store the matching value as a new Key Vault secret version","Refresh and verify application consumers","Revoke the old database credential and disable its Key Vault version after the transition"],"setId":"bouvet:key-vault","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/key-vault.json","reviewDate":"2026-10-11","reviewNote":"Included revocation at the issuing database, not only in Key Vault."},{"id":"bouvet:kv-053","prompt":"You need Key Vault itself to create new versions of a cryptographic key on a schedule. What should you configure?","explanation":"Cryptographic keys support native rotation policies that create new key versions on a schedule. Arbitrary external credentials stored as secrets generally need an integration workflow that also updates the issuing system.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/key-vault/general/overview","topic":"key-vault","type":"single","options":["A key rotation policy","A secret content type","A Key Vault Reader role","A versioned secret URI"],"answer":0,"setId":"bouvet:key-vault","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/key-vault.json","reviewDate":"2026-10-11"},{"id":"bouvet:kv-054","prompt":"A user can create and configure the vault but receives 403 when calling `get_secret`. What is the most likely explanation?","explanation":"Control-plane permissions to manage the vault do not grant data-plane access to secret values. Assign a suitable data role such as Key Vault Secrets User at an appropriate scope.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/key-vault/general/overview","topic":"key-vault","type":"single","options":["The vault URI must use HTTP instead of HTTPS","The user has control-plane permission but lacks a secret data-plane role","Secret retrieval requires the Premium tier","Key Vault never supports interactive developer identities"],"answer":1,"setId":"bouvet:key-vault","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/key-vault.json","reviewDate":"2026-10-11"},{"id":"bouvet:kv-055","prompt":"Which statements about Key Vault deletion protection are true? (Select all that apply)","explanation":"Soft delete provides a recoverable state and defaults to 90 days. Purge protection adds a non-bypassable time-based lock during retention; once enabled it cannot be disabled, even by an Owner or Microsoft.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/key-vault/general/overview","topic":"key-vault","type":"multi","options":["Soft delete retains a deleted vault or object for recovery","Purge protection prevents early permanent deletion during retention","Purge protection can be disabled by a subscription Owner","The default soft-delete retention period is 90 days","Soft delete and purge protection are the same feature"],"answer":[0,1,3],"choose":3,"setId":"bouvet:key-vault","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/key-vault.json","reviewDate":"2026-10-11"},{"id":"bouvet:kql-001","prompt":"Which KQL operator filters rows based on a condition?","explanation":"The `where` operator filters rows that match a condition. It's the primary filtering operator in KQL, similar to SQL's WHERE clause. `project` selects columns, `summarize` aggregates data, and `extend` adds computed columns.","domain":"operations","source":"https://learn.microsoft.com/en-us/kusto/query/","topic":"kql","type":"single","options":["project","where","summarize","extend"],"answer":1,"setId":"bouvet:kql","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/kql.json","reviewDate":"2026-10-11"},{"id":"bouvet:kql-002","prompt":"What does `ago(1h)` represent in a KQL query?","explanation":"`ago(1h)` means 'one hour ago from the current time'. All timestamps in Azure Monitor are UTC, so `ago()` also uses UTC. This is a common gotcha — don't confuse it with local time.","domain":"operations","source":"https://learn.microsoft.com/en-us/kusto/query/","topic":"kql","type":"single","options":["One hour from now","One hour ago from the current time (UTC)","The timestamp exactly one hour old in local time","A duration of one hour"],"answer":1,"setId":"bouvet:kql","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/kql.json","reviewDate":"2026-10-11"},{"id":"bouvet:kql-003","prompt":"Which operator would you use to count the number of failed requests in the last hour?","explanation":"To count failed requests: `requests | where timestamp > ago(1h) | where success == false | count`. The `count` operator counts all rows in the pipeline. You must filter first, then count.","domain":"operations","source":"https://learn.microsoft.com/en-us/kusto/query/","topic":"kql","type":"single","options":["`requests | count`","`requests | summarize count() by success`","`requests | where timestamp > ago(1h) and success == false | count`","`requests | summarize failures = count() where success == false`"],"answer":2,"setId":"bouvet:kql","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/kql.json","reviewDate":"2026-10-11"},{"id":"bouvet:kql-004","prompt":"Which of these are valid Application Insights tables that contain telemetry data? (Select all that apply)","explanation":"The core Application Insights tables are: `requests` (incoming HTTP), `dependencies` (outbound calls), `exceptions` (errors), `traces` (log lines), and `customEvents`. There is no `users` table by default.","domain":"operations","source":"https://learn.microsoft.com/en-us/kusto/query/","topic":"kql","type":"multi","options":["requests","dependencies","exceptions","users","traces"],"answer":[0,1,2,4],"choose":4,"setId":"bouvet:kql","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/kql.json","reviewDate":"2026-10-11"},{"id":"bouvet:kql-005","prompt":"In KQL, which comparison operator is case-SENSITIVE for string equality?","explanation":"`==` is case-sensitive exact match. `=~` is case-INsensitive equality. `contains` is case-insensitive substring matching. This is a classic exam gotcha.","domain":"operations","source":"https://learn.microsoft.com/en-us/kusto/query/","topic":"kql","type":"single","options":["`==`","`=`","`=~`","`contains`"],"answer":0,"setId":"bouvet:kql","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/kql.json","reviewDate":"2026-10-11"},{"id":"bouvet:kql-006","prompt":"What is the correct pipe order for: filter to last 24h, then group by request name, then count?","explanation":"Pipe order matters. Filter first (`where timestamp > ago(1d)`), then aggregate (`summarize count() by name`). Once you summarize, individual row data like timestamp is gone, so filtering on timestamp after summarize won't work.","domain":"operations","source":"https://learn.microsoft.com/en-us/kusto/query/","topic":"kql","type":"single","options":["`where timestamp > ago(1d) | summarize count() by name | where timestamp > ago(1d)`","`where timestamp > ago(1d) | summarize count() by name`","`summarize count() by name | where timestamp > ago(1d)`","`where name == 'GET /api' | summarize count() by timestamp`"],"answer":1,"setId":"bouvet:kql","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/kql.json","reviewDate":"2026-10-11"},{"id":"bouvet:kql-007","prompt":"Which operator adds a computed column without removing existing ones?","explanation":"`extend` adds computed columns while keeping all existing columns. `project` selects specific columns (can also compute), `summarize` aggregates, `where` filters rows.","domain":"operations","source":"https://learn.microsoft.com/en-us/kusto/query/","topic":"kql","type":"single","options":["`project`","`extend`","`summarize`","`where`"],"answer":1,"setId":"bouvet:kql","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/kql.json","reviewDate":"2026-10-11"},{"id":"bouvet:kql-008","prompt":"What does `bin(timestamp, 5m)` do?","explanation":"`bin(timestamp, 5m)` rounds each value down to its 5-minute boundary. It becomes a grouping key only when used in an expression such as `summarize count() by bin(timestamp, 5m)`.","domain":"operations","source":"https://learn.microsoft.com/en-us/kusto/query/","topic":"kql","type":"single","options":["Counts all rows in each 5-minute interval by itself","Creates a timestamp exactly 5 minutes in the future","Filters to only timestamps exactly on 5-minute boundaries","Rounds each timestamp down to a 5-minute boundary"],"answer":3,"setId":"bouvet:kql","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/kql.json","reviewDate":"2026-10-11"},{"id":"bouvet:kql-009","prompt":"Put these query fragments in the correct order to find the 5 most frequent exception types in the last day:","explanation":"Correct order: 1) Start with table `exceptions`, 2) Filter to last day `where timestamp > ago(1d)`, 3) Aggregate by type `summarize failures = count() by type`, 4) Get top 5 `top 5 by failures`.","domain":"operations","source":"https://learn.microsoft.com/en-us/kusto/query/","topic":"kql","type":"order","options":["exceptions","where timestamp > ago(1d)","summarize failures = count() by type","top 5 by failures"],"answer":["exceptions","where timestamp > ago(1d)","summarize failures = count() by type","top 5 by failures"],"setId":"bouvet:kql","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/kql.json","reviewDate":"2026-10-11"},{"id":"bouvet:kql-010","prompt":"Which operator would you use to select only the 'name' and 'duration' columns from a table?","explanation":"`project` selects/chooses specific columns, similar to SQL's SELECT. `where` filters rows, `summarize` aggregates, `extend` adds columns.","domain":"operations","source":"https://learn.microsoft.com/en-us/kusto/query/","topic":"kql","type":"single","options":["`where name, duration`","`project name, duration`","`summarize name, duration`","`extend name, duration`"],"answer":1,"setId":"bouvet:kql","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/kql.json","reviewDate":"2026-10-11"},{"id":"bouvet:kql-011","prompt":"What does the `distinct` operator do in KQL?","explanation":"The `distinct` operator returns only unique/distinct rows, similar to SQL's DISTINCT. It removes duplicate rows from the result set.","domain":"operations","source":"https://learn.microsoft.com/en-us/kusto/query/","topic":"kql","type":"single","options":["Returns only unique rows","Counts distinct values","Removes duplicate columns","Filters to a specific value"],"answer":0,"setId":"bouvet:kql","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/kql.json","reviewDate":"2026-10-11"},{"id":"bouvet:kql-012","prompt":"Which operator combines rows from multiple tables?","explanation":"`union` combines rows from multiple tables into a single result set, similar to SQL's UNION. `join` combines columns from tables based on a key.","domain":"operations","source":"https://learn.microsoft.com/en-us/kusto/query/","topic":"kql","type":"single","options":["`join`","`union`","`merge`","`combine`"],"answer":1,"setId":"bouvet:kql","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/kql.json","reviewDate":"2026-10-11"},{"id":"bouvet:kql-013","prompt":"Which operator is used to create a chart visualization in KQL?","explanation":"The `render` operator is used to create visualizations like timechart, barchart, etc. in KQL.","domain":"operations","source":"https://learn.microsoft.com/en-us/kusto/query/","topic":"kql","type":"single","options":["`chart`","`graph`","`render`","`plot`"],"answer":2,"setId":"bouvet:kql","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/kql.json","reviewDate":"2026-10-11"},{"id":"bouvet:kql-014","prompt":"Which of these are valid time-related expressions used for filtering in KQL? (Select all that apply)","explanation":"All are valid when supplied with their required arguments. `ago(timespan)` returns the UTC datetime that far before now, `now()` returns the current UTC time, and `startofday()`/`endofweek()` align datetimes to boundaries. `between` is an operator (`x between (a .. b)`), not a function.","domain":"operations","source":"https://learn.microsoft.com/en-us/kusto/query/","topic":"kql","type":"multi","options":["`ago()`","`between`","`now()`","`startofday()`","`endofweek()`"],"answer":[0,1,2,3,4],"choose":5,"setId":"bouvet:kql","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/kql.json","reviewDate":"2026-10-11"},{"id":"bouvet:kql-015","prompt":"What is the severity level for ERROR logs in Application Insights?","explanation":"In Application Insights, severity levels are: 0=Verbose, 1=Information, 2=Warning, 3=Error, 4=Critical. So ERROR is level 3.","domain":"operations","source":"https://learn.microsoft.com/en-us/kusto/query/","topic":"kql","type":"single","options":["0","1","2","3"],"answer":3,"setId":"bouvet:kql","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/kql.json","reviewDate":"2026-10-11"},{"id":"bouvet:kql-016","prompt":"Which operator would you use to remove specific columns from the result?","explanation":"`project-away` is used to drop/remove specific columns. For example: `requests | project-away duration, resultCode`.","domain":"operations","source":"https://learn.microsoft.com/en-us/kusto/query/","topic":"kql","type":"single","options":["`project-away`","`project`","`remove`","`exclude`"],"answer":0,"setId":"bouvet:kql","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/kql.json","reviewDate":"2026-10-11"},{"id":"bouvet:kql-017","prompt":"What does `take 10` do in a KQL query?","explanation":"`take N` returns arbitrary rows - it's for a quick peek at some data, not sorted or guaranteed. Use `top N by col` or `order by ... | take N` for ordered results.","domain":"operations","source":"https://learn.microsoft.com/en-us/kusto/query/","topic":"kql","type":"single","options":["Returns the first 10 rows (no ordering guarantee)","Returns 10 random rows","Returns the top 10 rows sorted by a column","Returns rows with exactly 10 matches"],"answer":0,"setId":"bouvet:kql","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/kql.json","reviewDate":"2026-10-11"},{"id":"bouvet:kql-018","prompt":"Which operator is the default join type in KQL?","explanation":"The default join type in KQL is `innerunique` which deduplicates the left side key. This is different from SQL's default INNER JOIN.","domain":"operations","source":"https://learn.microsoft.com/en-us/kusto/query/","topic":"kql","type":"single","options":["inner","leftouter","innerunique","fullouter"],"answer":2,"setId":"bouvet:kql","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/kql.json","reviewDate":"2026-10-11"},{"id":"bouvet:kql-019","prompt":"Put these query fragments in order to find average request duration by name, sorted descending:","explanation":"Correct order: 1) Start with table, 2) Filter by time, 3) Aggregate with summarize, 4) Sort with order by. The aggregate creates a new column 'avg_duration' which can then be used for sorting.","domain":"operations","source":"https://learn.microsoft.com/en-us/kusto/query/","topic":"kql","type":"order","options":["requests","where timestamp > ago(1h)","summarize avg(duration) by name","order by avg_duration desc"],"answer":["requests","where timestamp > ago(1h)","summarize avg(duration) by name","order by avg_duration desc"],"setId":"bouvet:kql","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/kql.json","reviewDate":"2026-10-11"},{"id":"bouvet:kql-020","prompt":"Which table would contain data about outbound HTTP calls from your application?","explanation":"The `dependencies` table contains outbound calls your app made (to a DB, another API, etc.). `requests` is for incoming HTTP requests.","domain":"operations","source":"https://learn.microsoft.com/en-us/kusto/query/","topic":"kql","type":"single","options":["`requests`","`dependencies`","`exceptions`","`traces`"],"answer":1,"setId":"bouvet:kql","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/kql.json","reviewDate":"2026-10-11"},{"id":"bouvet:kql-021","prompt":"Which two KQL tabular operators are aliases that filter rows by a predicate? (Select all that apply)","explanation":"`where` and `filter` are aliases and keep rows whose predicate evaluates to true. String operators such as `has` can be used inside that predicate, but they are not standalone tabular operators.","domain":"operations","source":"https://learn.microsoft.com/en-us/kusto/query/","topic":"kql","type":"multi","options":["`where`","`filter`","`project`","`summarize`","`extend`"],"answer":[0,1],"choose":2,"setId":"bouvet:kql","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/kql.json","reviewDate":"2026-10-11"},{"id":"bouvet:kql-022","prompt":"What is the purpose of the `operation_Id` column in Application Insights tables?","explanation":"`operation_Id` is a correlation ID that links together all telemetry items (requests, dependencies, exceptions, traces) from the same end-to-end operation. This allows you to trace a request across multiple services.","domain":"operations","source":"https://learn.microsoft.com/en-us/kusto/query/","topic":"kql","type":"single","options":["Uniquely identifies a single telemetry item","Correlates multiple telemetry items from the same operation","Identifies the Azure operation that created the resource","Tracks the order of operations"],"answer":1,"setId":"bouvet:kql","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/kql.json","reviewDate":"2026-10-11"},{"id":"bouvet:kql-023","prompt":"Which query will find all requests that took longer than 1 second?","explanation":"The requests query column duration is measured numerically in milliseconds. Filter with duration > 1000. In workspace schema the corresponding field is AppRequests.DurationMs. A timespan literal such as 1s is a different type.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/azure-monitor/app/metrics-overview","topic":"kql","type":"single","options":["requests | where duration > 1000","`requests | where duration > 1`","`requests | where DurationMs > 1000`","`requests | where duration > '1s'`"],"answer":0,"setId":"bouvet:kql","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/kql.json","reviewDate":"2026-10-11","reviewNote":"Corrected the numeric duration unit in Application Insights queries."},{"id":"bouvet:kql-024","prompt":"Put these in order to create a time chart of exception counts per hour for the last day:","explanation":"Correct order: 1) Start with exceptions table, 2) Filter to last day, 3) Aggregate count by 1-hour bins, 4) Render as timechart. The `bin()` function groups timestamps into intervals.","domain":"operations","source":"https://learn.microsoft.com/en-us/kusto/query/","topic":"kql","type":"order","options":["exceptions","where timestamp > ago(1d)","summarize count() by bin(timestamp, 1h)","render timechart"],"answer":["exceptions","where timestamp > ago(1d)","summarize count() by bin(timestamp, 1h)","render timechart"],"setId":"bouvet:kql","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/kql.json","reviewDate":"2026-10-11"},{"id":"bouvet:kql-025","prompt":"What does `sort by` do differently from `order by` in KQL?","explanation":"There is no difference — the KQL docs state that the `sort` and `order` operators are equivalent (`sort by` and `order by` are exact synonyms). Both default to descending order; neither guarantees a stable sort.","domain":"operations","source":"https://learn.microsoft.com/en-us/kusto/query/","topic":"kql","type":"single","options":["`sort by` is case-sensitive","`sort by` sorts descending by default","`sort by` is stable (preserves order of equal elements)","There is no difference"],"answer":3,"setId":"bouvet:kql","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/kql.json","reviewDate":"2026-10-11"},{"id":"bouvet:kql-026","prompt":"Which of these aggregate functions are available in `summarize`? (Select all that apply)","explanation":"All of these aggregate functions are available in KQL's summarize operator: count, sum, avg, min, max. There is no built-in median() function.","domain":"operations","source":"https://learn.microsoft.com/en-us/kusto/query/","topic":"kql","type":"multi","options":["`count()`","`sum()`","`avg()`","`min()`","`max()`","`median()`"],"answer":[0,1,2,3,4],"choose":5,"setId":"bouvet:kql","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/kql.json","reviewDate":"2026-10-11"},{"id":"bouvet:kql-027","prompt":"Which KQL elements are case-sensitive? (Select all that apply)","explanation":"KQL is case-sensitive for identifiers, operators, and functions. `==` is case-sensitive string equality; use an explicitly case-insensitive operator such as `=~` when that is the intended comparison.","domain":"operations","source":"https://learn.microsoft.com/en-us/kusto/query/","topic":"kql","type":"multi","options":["Table names","Column names","Operators and functions","String equality with `==`","Nothing in KQL is case-sensitive"],"answer":[0,1,2,3],"choose":4,"setId":"bouvet:kql","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/kql.json","reviewDate":"2026-10-11"},{"id":"bouvet:kql-028","prompt":"Which operator extracts fields from a string column using a pattern?","explanation":"The `parse` operator extracts fields out of a string column using a pattern. For example: `parse message with 'Processing order ' orderId:long`.","domain":"operations","source":"https://learn.microsoft.com/en-us/kusto/query/","topic":"kql","type":"single","options":["`extract`","`parse`","`split`","`tokenize`"],"answer":1,"setId":"bouvet:kql","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/kql.json","reviewDate":"2026-10-11"},{"id":"bouvet:kql-029","prompt":"What is the result of `requests | count`?","explanation":"`count` (as an operator, not a function) returns a single row with the total count of all rows. To count by groups, use `summarize count() by col`.","domain":"operations","source":"https://learn.microsoft.com/en-us/kusto/query/","topic":"kql","type":"single","options":["Returns a single row with the count of all requests","Returns the count per request name","Returns all request rows with a count column added","Returns an error"],"answer":0,"setId":"bouvet:kql","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/kql.json","reviewDate":"2026-10-11"},{"id":"bouvet:kql-030","prompt":"Which query correctly counts distinct users?","explanation":"To count distinct values: first use `distinct` to get unique values, then `count`: `requests | distinct user_Id | count`. Alternatively: `requests | summarize dcount(user_Id)`.","domain":"operations","source":"https://learn.microsoft.com/en-us/kusto/query/","topic":"kql","type":"single","options":["`requests | distinct user_Id | count`","`requests | summarize count() by user_Id`","`requests | summarize count() by distinct user_Id`","`requests | count user_Id`"],"answer":0,"setId":"bouvet:kql","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/kql.json","reviewDate":"2026-10-11"},{"id":"bouvet:kql-031","prompt":"Where do standard application log records and explicitly tracked custom named events appear? (Select all that apply)","explanation":"Standard logging records appear in `traces`; explicitly tracked named events appear in `customEvents`. Requests, exceptions, and dependencies represent different telemetry types rather than generic log/event records.","domain":"operations","source":"https://learn.microsoft.com/en-us/kusto/query/","topic":"kql","type":"multi","options":["`traces`","`customEvents`","`requests`","`exceptions`","`dependencies`"],"answer":[0,1],"choose":2,"setId":"bouvet:kql","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/kql.json","reviewDate":"2026-10-11"},{"id":"bouvet:kql-032","prompt":"What does `top 5 by duration` do?","explanation":"`top N by col` returns the N rows with the highest values in the specified column. It's equivalent to `order by col desc | take N`.","domain":"operations","source":"https://learn.microsoft.com/en-us/kusto/query/","topic":"kql","type":"single","options":["Returns the 5 newest rows sorted by duration","Returns the 5 rows with the highest duration values","Returns the 5 most recent rows and sorts them by duration","Returns rows where duration is in the top 5 values"],"answer":1,"setId":"bouvet:kql","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/kql.json","reviewDate":"2026-10-11"},{"id":"bouvet:kql-033","prompt":"How do you perform a case-insensitive string comparison in KQL?","explanation":"Use `=~` for case-insensitive equality. `==` is case-sensitive. This is a classic exam gotcha.","domain":"operations","source":"https://learn.microsoft.com/en-us/kusto/query/","topic":"kql","type":"single","options":["`==`","`=~`","`===`","`equals`"],"answer":1,"setId":"bouvet:kql","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/kql.json","reviewDate":"2026-10-11"},{"id":"bouvet:kql-034","prompt":"Put these in order to find requests with failures and their corresponding dependencies:","explanation":"Correct order: 1) Filter requests to failures, 2) Select and rename columns, 3) Join with dependencies table, 4) Specify join key. This traces one request end-to-end.","domain":"operations","source":"https://learn.microsoft.com/en-us/kusto/query/","topic":"kql","type":"order","options":["requests | where success == false","project operation_Id, requestName = name, resultCode","join kind=inner (dependencies | project operation_Id, dependencyName = name, target)","on operation_Id"],"answer":["requests | where success == false","project operation_Id, requestName = name, resultCode","join kind=inner (dependencies | project operation_Id, dependencyName = name, target)","on operation_Id"],"setId":"bouvet:kql","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/kql.json","reviewDate":"2026-10-11"},{"id":"bouvet:kql-035","prompt":"Which function returns the current UTC timestamp in KQL?","explanation":"`now()` returns the current UTC timestamp. All timestamps in Azure Monitor are UTC.","domain":"operations","source":"https://learn.microsoft.com/en-us/kusto/query/","topic":"kql","type":"single","options":["`now()`","`utcnow()`","`datetime()`","`current_timestamp()`"],"answer":0,"setId":"bouvet:kql","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/kql.json","reviewDate":"2026-10-11"},{"id":"bouvet:kql-036","prompt":"What information is stored in the `requests` table? (Select all that apply)","explanation":"The `requests` table contains: name (request name), duration, resultCode, success. Outbound calls go in the `dependencies` table.","domain":"operations","source":"https://learn.microsoft.com/en-us/kusto/query/","topic":"kql","type":"multi","options":["Incoming HTTP request name","Request duration","Result code","Success status","Outbound dependency calls"],"answer":[0,1,2,3],"choose":4,"setId":"bouvet:kql","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/kql.json","reviewDate":"2026-10-11"},{"id":"bouvet:kql-037","prompt":"What is the difference between `has` and `contains` in KQL?","explanation":"`has` searches for an indexed term (case-insensitive), while `contains` searches for a substring (also case-insensitive). `has` is normally faster when term matching expresses the requirement.","domain":"operations","source":"https://learn.microsoft.com/en-us/kusto/query/","topic":"kql","type":"single","options":["`has` is case-sensitive, `contains` is case-insensitive","`has` matches whole words, `contains` matches substrings","`has` interprets its right-hand value as a regular expression","There is no difference"],"answer":1,"setId":"bouvet:kql","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/kql.json","reviewDate":"2026-10-11"},{"id":"bouvet:kql-038","prompt":"Which query finds all WARNING level traces from the last hour?","explanation":"Filter the timestamp to the requested hour and compare the numeric severity. Application Insights uses 0=Verbose, 1=Information, 2=Warning, 3=Error, and 4=Critical.","domain":"operations","source":"https://learn.microsoft.com/en-us/kusto/query/","topic":"kql","type":"single","options":["`traces | where timestamp > ago(1h) and severityLevel == 2`","`traces | where timestamp > ago(1h) and severityLevel == 'WARNING'`","`traces | where timestamp > ago(1h) and severityLevel == 1`","`traces | where timestamp > ago(1h) and message contains 'WARNING'`"],"answer":0,"setId":"bouvet:kql","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/kql.json","reviewDate":"2026-10-11"},{"id":"bouvet:kql-039","prompt":"What does `between(ago(1d) .. ago(1h))` represent?","explanation":"`between(ago(1d) .. ago(1h))` creates a time range from 1 day ago to 1 hour ago. The `..` operator creates an inclusive range.","domain":"operations","source":"https://learn.microsoft.com/en-us/kusto/query/","topic":"kql","type":"single","options":["From 1 day ago to 1 hour ago","From 1 hour ago to now","From now to 1 day from now","From 1 hour ago to 1 day from now"],"answer":0,"setId":"bouvet:kql","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/kql.json","reviewDate":"2026-10-11"},{"id":"bouvet:kql-040","prompt":"Which operator renames a column while retaining the other columns?","explanation":"`project-rename NewName = OldName` renames columns while retaining the remaining schema. Plain `project` can also alias a selected column, but it keeps only the columns explicitly projected.","domain":"operations","source":"https://learn.microsoft.com/en-us/kusto/query/","topic":"kql","type":"single","options":["`project-rename`","`project`","`extend`","`set`"],"answer":0,"setId":"bouvet:kql","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/kql.json","reviewDate":"2026-10-11"},{"id":"bouvet:kql-041","prompt":"You open Logs from the Log Analytics workspace rather than from the Application Insights resource. Which table contains incoming request telemetry?","explanation":"Workspace scope uses the Log Analytics schema (`AppRequests`, `TimeGenerated`, `OperationId`, and `DurationMs`). Application Insights resource scope exposes the backward-compatible `requests` schema.","domain":"operations","source":"https://learn.microsoft.com/en-us/kusto/query/","topic":"kql","type":"single","options":["`requests`","`AppRequests`","`AzureRequests`","`RequestLogs`"],"answer":1,"setId":"bouvet:kql","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/kql.json","reviewDate":"2026-10-11"},{"id":"bouvet:kql-042","prompt":"Which workspace-scoped query finds failed requests from the last hour?","explanation":"The workspace schema uses `AppRequests`, `TimeGenerated`, and `Success`. The other options mix the application and workspace schemas or select the log-record table.","domain":"operations","source":"https://learn.microsoft.com/en-us/kusto/query/","topic":"kql","type":"single","options":["`AppRequests | where TimeGenerated > ago(1h) and Success == false`","`requests | where TimeGenerated > ago(1h) and success == false`","`AppRequests | where timestamp > ago(1h) and Success == false`","`AppTraces | where TimeGenerated > ago(1h) and Success == false`"],"answer":0,"setId":"bouvet:kql","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/kql.json","reviewDate":"2026-10-11"},{"id":"bouvet:kql-043","prompt":"A query scans 30 days of telemetry but only needs the last hour. Which change usually reduces the amount of data processed?","explanation":"Filter on time and other selective predicates early so later operators process fewer rows. This is both clearer and generally more efficient than joining or aggregating the full range first.","domain":"operations","source":"https://learn.microsoft.com/en-us/kusto/query/","topic":"kql","type":"single","options":["Place the timestamp `where` filter as early as practical in the pipeline","Add `render timechart` before filtering","Convert every column to a string","Move the timestamp filter after every `join` and `summarize`"],"answer":0,"setId":"bouvet:kql","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/kql.json","reviewDate":"2026-10-11"},{"id":"bouvet:kql-044","prompt":"Put these application-scoped query fragments in order to chart average request duration per 15-minute interval:","explanation":"Choose the table, restrict the time range, aggregate by a binned timestamp, and render the resulting time series. `bin` supplies the interval key; `summarize` performs the grouping.","domain":"operations","source":"https://learn.microsoft.com/en-us/kusto/query/","topic":"kql","type":"order","options":["requests","where timestamp > ago(6h)","summarize AverageDuration = avg(duration) by bin(timestamp, 15m)","render timechart"],"answer":["requests","where timestamp > ago(6h)","summarize AverageDuration = avg(duration) by bin(timestamp, 15m)","render timechart"],"setId":"bouvet:kql","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/kql.json","reviewDate":"2026-10-11"},{"id":"bouvet:kql-045","prompt":"Why can a query written with `requests | where timestamp > ago(1h)` fail when pasted into a Log Analytics workspace query?","explanation":"The same telemetry has different table and field names by query scope. In workspace scope, the equivalent starts with `AppRequests | where TimeGenerated > ago(1h)`.","domain":"operations","source":"https://learn.microsoft.com/en-us/kusto/query/","topic":"kql","type":"single","options":["KQL is unavailable in Log Analytics","The query uses Application Insights resource-scope table and column names instead of workspace names","`ago()` works only in Azure Data Explorer","Workspace queries require SQL syntax"],"answer":1,"setId":"bouvet:kql","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/kql.json","reviewDate":"2026-10-11"},{"id":"bouvet:otel-001","prompt":"What is OpenTelemetry?","explanation":"OpenTelemetry (OTel) is a vendor-neutral, open standard plus SDK for generating telemetry. You instrument your code once against the OTel API and can export to any backend (Azure Monitor, Jaeger, Prometheus, ...). In Azure, the backend is Application Insights, which you then query with KQL.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/azure-monitor/app/opentelemetry-overview","topic":"opentelemetry","type":"single","options":["A vendor-neutral, open standard and SDK for producing telemetry (traces, metrics, logs)","An Azure-only logging service that replaces Application Insights","A KQL query engine for analyzing telemetry","A dashboard product for visualizing metrics"],"answer":0,"setId":"bouvet:opentelemetry","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/opentelemetry.json","reviewDate":"2026-10-11"},{"id":"bouvet:otel-002","prompt":"Which are the three signals defined by OpenTelemetry? (Select all that apply)","explanation":"OpenTelemetry defines three signals: traces (a request's journey across services), metrics (numeric measurements over time), and logs (timestamped text records). Alerts and dashboards are features of the backend (Azure Monitor), not OTel signals.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/azure-monitor/app/opentelemetry-overview","topic":"opentelemetry","type":"multi","options":["Traces","Metrics","Logs","Alerts","Dashboards"],"answer":[0,1,2],"choose":3,"setId":"bouvet:opentelemetry","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/opentelemetry.json","reviewDate":"2026-10-11"},{"id":"bouvet:otel-003","prompt":"What is the relationship between a trace and a span?","explanation":"A trace represents one logical end-to-end operation (e.g. 'checkout') and is made up of spans. Each span is a single unit of work with a name, start/end time (a duration), and optional attributes. The span with no parent is the root span.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/azure-monitor/app/opentelemetry-overview","topic":"opentelemetry","type":"single","options":["A trace is a single unit of work; a span is a collection of traces","A trace is a tree of spans representing one end-to-end operation; a span is a single unit of work within it","They are two words for the same thing","A span is the backend; a trace is the query language"],"answer":1,"setId":"bouvet:opentelemetry","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/opentelemetry.json","reviewDate":"2026-10-11"},{"id":"bouvet:otel-004","prompt":"Which single function does the Azure Monitor OpenTelemetry Distro provide to wire OpenTelemetry to Application Insights?","explanation":"`configure_azure_monitor(connection_string=...)` from the `azure-monitor-opentelemetry` package configures traces, metrics, and logs and points them at Application Insights in one call. This is Microsoft's recommended onboarding path.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/azure-monitor/app/opentelemetry-overview","topic":"opentelemetry","type":"single","options":["`enable_app_insights()`","`configure_azure_monitor()`","`start_tracing()`","`connect_opentelemetry()`"],"answer":1,"setId":"bouvet:opentelemetry","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/opentelemetry.json","reviewDate":"2026-10-11"},{"id":"bouvet:otel-005","prompt":"Which Python package is the recommended way to send OpenTelemetry data to Application Insights?","explanation":"`azure-monitor-opentelemetry` (the Azure Monitor OpenTelemetry Distro) bundles the OTel SDK plus the Azure exporter. `opencensus-ext-azure` is the retired OpenCensus approach — OpenTelemetry replaced OpenCensus, so pick the OTel/distro answer.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/azure-monitor/app/opentelemetry-overview","topic":"opentelemetry","type":"single","options":["`opencensus-ext-azure`","`applicationinsights`","`azure-monitor-opentelemetry`","`azure-appinsights-sdk`"],"answer":2,"setId":"bouvet:opentelemetry","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/opentelemetry.json","reviewDate":"2026-10-11"},{"id":"bouvet:otel-006","prompt":"What is the current, recommended value used to point telemetry at an Application Insights resource?","explanation":"The connection string is the current way to point telemetry at Application Insights. The bare instrumentation key is legacy/deprecated — a classic 'which is right' exam distractor.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/azure-monitor/app/opentelemetry-overview","topic":"opentelemetry","type":"single","options":["The instrumentation key","The connection string","The subscription ID","The workspace resource ID"],"answer":1,"setId":"bouvet:opentelemetry","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/opentelemetry.json","reviewDate":"2026-10-11"},{"id":"bouvet:otel-007","prompt":"In Application Insights, which column correlates all telemetry belonging to one end-to-end operation (the OpenTelemetry trace ID)?","explanation":"The OpenTelemetry trace ID surfaces as the `operation_Id` correlation column in Application Insights. You join telemetry on `operation_Id` in KQL to follow one request across requests, dependencies, exceptions, and traces.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/azure-monitor/app/opentelemetry-overview","topic":"opentelemetry","type":"single","options":["`session_Id`","`operation_Id`","`trace_Id`","`request_Id`"],"answer":1,"setId":"bouvet:opentelemetry","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/opentelemetry.json","reviewDate":"2026-10-11"},{"id":"bouvet:otel-008","prompt":"What makes tracing 'distributed' across multiple services?","explanation":"When service A calls service B, A injects the trace context into the W3C `traceparent` request header; B reads it and continues the SAME trace. This context propagation is what stitches one request together across many services.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/azure-monitor/app/opentelemetry-overview","topic":"opentelemetry","type":"single","options":["Each service writes to the same database table","Context propagation via the W3C `traceparent` header carries the trace context between services","The Azure exporter merges traces by timestamp","KQL joins unrelated requests automatically"],"answer":1,"setId":"bouvet:opentelemetry","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/opentelemetry.json","reviewDate":"2026-10-11"},{"id":"bouvet:otel-009","prompt":"You want to see how long each step of a single checkout request took as it moved across services. Which signal answers this?","explanation":"Traces answer 'what happened during this one request and how long did each step take?' — they are the tree of timed spans for a single operation. Metrics answer 'how many/how much over time', and logs are free-text records.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/azure-monitor/app/opentelemetry-overview","topic":"opentelemetry","type":"single","options":["Metrics","Logs","Traces","Alerts"],"answer":2,"setId":"bouvet:opentelemetry","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/opentelemetry.json","reviewDate":"2026-10-11"},{"id":"bouvet:otel-010","prompt":"You want to track the number of orders processed per minute as a numeric value over time. Which signal fits best?","explanation":"Metrics are numeric measurements over time (counts, latency, queue depth). A counter incremented per order, aggregated over time, is a metric — it lands in the customMetrics table in Application Insights.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/azure-monitor/app/opentelemetry-overview","topic":"opentelemetry","type":"single","options":["Traces","Metrics","Logs","Spans"],"answer":1,"setId":"bouvet:opentelemetry","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/opentelemetry.json","reviewDate":"2026-10-11"},{"id":"bouvet:otel-011","prompt":"What is the difference between auto-instrumentation and manual instrumentation?","explanation":"Auto-instrumentation gives you request and dependency spans from instrumented libraries (Flask, requests, psycopg, ...) without touching that code. Manual instrumentation is where you create your own spans for business logic OTel can't see. Real apps use both.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/azure-monitor/app/opentelemetry-overview","topic":"opentelemetry","type":"single","options":["Auto-instrumentation only works in Azure; manual works anywhere","Auto-instrumentation records spans for known libraries/frameworks for free; manual instrumentation is spans you create for your own business logic","Auto-instrumentation is for metrics; manual is for traces","There is no difference"],"answer":1,"setId":"bouvet:opentelemetry","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/opentelemetry.json","reviewDate":"2026-10-11"},{"id":"bouvet:otel-012","prompt":"A pure in-process calculation with no library calls produces no span. How do you get telemetry for it?","explanation":"Auto-instrumentation only covers known libraries/frameworks. For your own in-process business logic you must create a manual span, e.g. `with tracer.start_as_current_span('reprice basket'):`.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/azure-monitor/app/opentelemetry-overview","topic":"opentelemetry","type":"single","options":["Enable auto-instrumentation harder","Create a manual span around it with the tracer (e.g. `with tracer.start_as_current_span(...)`)","Add a KQL query for it","It is impossible to instrument in-process code"],"answer":1,"setId":"bouvet:opentelemetry","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/opentelemetry.json","reviewDate":"2026-10-11"},{"id":"bouvet:otel-013","prompt":"What is the main purpose of sampling in OpenTelemetry?","explanation":"Sampling controls telemetry volume and ingestion cost. The Azure distro supports both its current rate-limited default and explicitly configured fixed-percentage sampling.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/azure-monitor/app/opentelemetry-overview","topic":"opentelemetry","type":"single","options":["To encrypt telemetry in transit","To keep a representative fraction of traces, reducing telemetry volume and cost","To speed up KQL queries","To remove personally identifiable information"],"answer":1,"setId":"bouvet:opentelemetry","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/opentelemetry.json","reviewDate":"2026-10-11"},{"id":"bouvet:otel-014","prompt":"In the normal parent-aware setup, what keeps a sampling decision consistent across child spans?","explanation":"The sampled flag travels with the W3C trace context, and a parent-aware sampler honours it for child spans. This normally keeps a trace coherent, but broken propagation, different service settings, or a custom sampler can still create incomplete traces.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/azure-monitor/app/opentelemetry-overview","topic":"opentelemetry","type":"single","options":["Because child spans are always kept","The decision is carried in the trace context and child spans honour their parent's decision","Because the exporter re-creates missing parents","Because KQL fills in the gaps"],"answer":1,"setId":"bouvet:opentelemetry","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/opentelemetry.json","reviewDate":"2026-10-11"},{"id":"bouvet:otel-015","prompt":"Why must a short-lived Python script pause (or explicitly flush) before exiting after emitting telemetry?","explanation":"The SDK batches spans and flushes them in the background (BatchSpanProcessor). A script that exits immediately can lose the un-flushed telemetry, so you sleep or flush before exiting. Data also takes 1-3 minutes to appear regardless.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/azure-monitor/app/opentelemetry-overview","topic":"opentelemetry","type":"single","options":["Application Insights rate-limits new resources","Telemetry is buffered and flushed in the background (BatchSpanProcessor); exiting immediately can drop the un-flushed tail","The connection string expires after each run","Python requires a sleep after every network call"],"answer":1,"setId":"bouvet:opentelemetry","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/opentelemetry.json","reviewDate":"2026-10-11"},{"id":"bouvet:otel-016","prompt":"An incoming HTTP request (a server span) lands in which Application Insights table?","explanation":"Server spans (incoming requests) land in the `requests` table. Outbound/client spans go to `dependencies`, log records to `traces`, and recorded exceptions to `exceptions`.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/azure-monitor/app/opentelemetry-overview","topic":"opentelemetry","type":"single","options":["`dependencies`","`requests`","`traces`","`exceptions`"],"answer":1,"setId":"bouvet:opentelemetry","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/opentelemetry.json","reviewDate":"2026-10-11"},{"id":"bouvet:otel-017","prompt":"An auto-instrumented outbound HTTP call your app makes (a client span) lands in which table?","explanation":"Client spans — outbound calls your app makes to a DB, another API, etc. — land in the `dependencies` table, sharing the operation_Id of the request that triggered them.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/azure-monitor/app/opentelemetry-overview","topic":"opentelemetry","type":"single","options":["`requests`","`dependencies`","`customMetrics`","`customEvents`"],"answer":1,"setId":"bouvet:opentelemetry","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/opentelemetry.json","reviewDate":"2026-10-11"},{"id":"bouvet:otel-018","prompt":"The `configure_azure_monitor()` call also routes standard Python `logging` output. Which table do those log lines appear in?","explanation":"Log records (e.g. `logger.info(...)`) land in the `traces` table, each with a severityLevel. This is the same `traces` table you query in the KQL topic.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/azure-monitor/app/opentelemetry-overview","topic":"opentelemetry","type":"single","options":["`requests`","`traces`","`exceptions`","`customMetrics`"],"answer":1,"setId":"bouvet:opentelemetry","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/opentelemetry.json","reviewDate":"2026-10-11"},{"id":"bouvet:otel-019","prompt":"What are span attributes?","explanation":"Attributes are key/value tags on a span that record searchable context about the operation, such as `order.id` or `http.method`. They are how you enrich a span with domain-specific detail.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/azure-monitor/app/opentelemetry-overview","topic":"opentelemetry","type":"single","options":["The start and end timestamps of a span","Key/value tags that add searchable context to a span (e.g. order.id = 42)","The child spans nested under a span","The exporter configuration for a span"],"answer":1,"setId":"bouvet:opentelemetry","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/opentelemetry.json","reviewDate":"2026-10-11"},{"id":"bouvet:otel-020","prompt":"In the OpenTelemetry pipeline, what is the job of the exporter?","explanation":"The pipeline is API -> SDK -> exporter. The API is what your code calls, the SDK records/batches/samples, and the exporter translates and ships the telemetry to a backend. The Azure Monitor exporter sends to Application Insights.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/azure-monitor/app/opentelemetry-overview","topic":"opentelemetry","type":"single","options":["To define the API your code calls","To translate the batched telemetry and ship it to a backend (e.g. Application Insights)","To sample traces at the root","To store telemetry as KQL tables"],"answer":1,"setId":"bouvet:opentelemetry","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/opentelemetry.json","reviewDate":"2026-10-11"},{"id":"bouvet:otel-021","prompt":"Put these in the correct order to instrument a Python app with the Azure Monitor OpenTelemetry Distro:","explanation":"Correct order: 1) install the distro, 2) provide the connection string (usually via env var), 3) call configure_azure_monitor() to wire the OTel pipeline to Application Insights, 4) then your spans, metrics, and logs are exported.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/azure-monitor/app/opentelemetry-overview","topic":"opentelemetry","type":"order","options":["pip install azure-monitor-opentelemetry","Set APPLICATIONINSIGHTS_CONNECTION_STRING to your resource's connection string","Call configure_azure_monitor(connection_string=...)","Create spans / metrics and emit logs in your app code"],"answer":["pip install azure-monitor-opentelemetry","Set APPLICATIONINSIGHTS_CONNECTION_STRING to your resource's connection string","Call configure_azure_monitor(connection_string=...)","Create spans / metrics and emit logs in your app code"],"setId":"bouvet:opentelemetry","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/opentelemetry.json","reviewDate":"2026-10-11"},{"id":"bouvet:otel-022","prompt":"What does 'vendor-neutral' mean in the context of OpenTelemetry?","explanation":"Vendor-neutral means you instrument once against the OpenTelemetry API and can point the telemetry at any compatible backend (Azure Monitor, Jaeger, Prometheus, Datadog, ...) just by swapping the exporter — no app rewrite.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/azure-monitor/app/opentelemetry-overview","topic":"opentelemetry","type":"single","options":["It only works with open-source backends","You instrument your code once against the OTel API and can export to any backend without rewriting the app","It is free of charge for all Azure customers","It does not require a connection string"],"answer":1,"setId":"bouvet:opentelemetry","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/opentelemetry.json","reviewDate":"2026-10-11"},{"id":"bouvet:otel-023","prompt":"Distributed tracing shows that a downstream service is starting a brand-new trace instead of continuing the caller's trace. What is the most likely cause?","explanation":"If a downstream service starts a new trace, the trace context (W3C `traceparent` header) wasn't propagated — typically because the outbound or inbound hop isn't instrumented, or the header was stripped. Fixing propagation restores the single end-to-end trace.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/azure-monitor/app/opentelemetry-overview","topic":"opentelemetry","type":"single","options":["Sampling dropped the trace","Context propagation is broken — the `traceparent` header wasn't passed, or that hop is uninstrumented","The connection string is wrong","The metric counter was not incremented"],"answer":1,"setId":"bouvet:opentelemetry","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/opentelemetry.json","reviewDate":"2026-10-11"},{"id":"bouvet:otel-024","prompt":"Which statement about the root span of a trace is correct?","explanation":"The root span is the top of the trace tree — it has no parent span ID. All other spans in the trace descend from it, and they all share the same trace ID (operation_Id).","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/azure-monitor/app/opentelemetry-overview","topic":"opentelemetry","type":"single","options":["It has no parent span","It is always the shortest span","It is the exporter's configuration span","It is created only when sampling is disabled"],"answer":0,"setId":"bouvet:opentelemetry","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/opentelemetry.json","reviewDate":"2026-10-11"},{"id":"bouvet:otel-025","prompt":"Which of these does the Azure Monitor OpenTelemetry Distro configure with its single setup call? (Select all that apply)","explanation":"configure_azure_monitor() sets up all three signals — traces, metrics, and logs — and exports them to Application Insights. It does not manage KQL saved queries or Azure RBAC roles.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/azure-monitor/app/opentelemetry-overview","topic":"opentelemetry","type":"multi","options":["Traces","Metrics","Logs","KQL saved queries","Azure RBAC roles"],"answer":[0,1,2],"choose":3,"setId":"bouvet:opentelemetry","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/opentelemetry.json","reviewDate":"2026-10-11"},{"id":"bouvet:otel-026","prompt":"A Python developer creates a manual span without specifying its SpanKind. Where does Azure Monitor normally map that span?","explanation":"A manually created span defaults to SpanKind.INTERNAL. Azure Monitor maps INTERNAL spans to dependencies with the InProc type. Use SpanKind.SERVER for incoming request handling or a deliberately request-like top-level background operation, not merely to relabel arbitrary internal work.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/azure-monitor/app/opentelemetry-overview","topic":"opentelemetry","type":"single","options":["To `requests`, because every root span is a request","To `dependencies` with type `InProc`, because the default kind is INTERNAL","To `traces`, because all OpenTelemetry spans are log records","To `customEvents`, because the span was created manually"],"answer":1,"setId":"bouvet:opentelemetry","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/opentelemetry.json","reviewDate":"2026-10-11"},{"id":"bouvet:otel-027","prompt":"With a current Azure Monitor OpenTelemetry Python distro and no sampling options, which sampler behaviour should you expect?","explanation":"Current versions of the Python distro default to a rate-limited sampler that targets five traces per second when no sampling configuration is supplied. A fixed percentage requires an explicit sampling_ratio.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/azure-monitor/app/opentelemetry-overview","topic":"opentelemetry","type":"single","options":["Every trace is exported without sampling","A rate-limited sampler targeting five traces per second","Exactly 5% of traces are exported","Only failed traces are exported"],"answer":1,"setId":"bouvet:opentelemetry","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/opentelemetry.json","reviewDate":"2026-10-11"},{"id":"bouvet:otel-028","prompt":"You must keep approximately 10% of traces rather than use the distro's default rate limit. Which configuration is appropriate?","explanation":"The sampling_ratio argument selects fixed-percentage sampling; 0.10 means approximately 10%. Query limits and logging levels do not reduce trace ingestion.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/azure-monitor/app/opentelemetry-overview","topic":"opentelemetry","type":"single","options":["`configure_azure_monitor(sampling_ratio=0.10)`","`configure_azure_monitor(traces_per_second=0.10)`","Set the KQL query to `take 10 percent`","Set the logger level to 10"],"answer":0,"setId":"bouvet:opentelemetry","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/opentelemetry.json","reviewDate":"2026-10-11"},{"id":"bouvet:otel-029","prompt":"Put the distributed trace propagation steps in order when Service A calls Service B over instrumented HTTP:","explanation":"The caller creates a client span and injects its trace context. The receiver extracts that context before creating its server span, so both services share one trace ID while each span keeps its own span ID.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/azure-monitor/app/opentelemetry-overview","topic":"opentelemetry","type":"order","options":["Service A creates an outbound client span","Service A injects the W3C trace context into the HTTP headers","Service B extracts the trace context from the incoming request","Service B creates a server span that continues the same trace"],"answer":["Service A creates an outbound client span","Service A injects the W3C trace context into the HTTP headers","Service B extracts the trace context from the incoming request","Service B creates a server span that continues the same trace"],"setId":"bouvet:opentelemetry","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/opentelemetry.json","reviewDate":"2026-10-11"},{"id":"bouvet:otel-030","prompt":"Your code catches an exception inside a span. Which actions provide complete trace diagnostics? (Select all that apply)","explanation":"Recording the exception captures its details, while setting an ERROR status represents the failed outcome. record_exception does not itself change the span status, and trace identifiers must remain stable for correlation.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/azure-monitor/app/opentelemetry-overview","topic":"opentelemetry","type":"multi","options":["Call `span.record_exception(error)` to attach the exception details","Set the span status to ERROR to mark the operation as failed","Change the span's trace ID after recording the exception","Delete the parent span so the exception becomes a root operation"],"answer":[0,1],"choose":2,"setId":"bouvet:opentelemetry","practiceSource":"https://github.com/Bouvet-deler/AI-200-Bootcamp/blob/cb616523401765277a983c61d22d96c8551476ab/quiz/src/questions/04-secure-monitor/opentelemetry.json","reviewDate":"2026-10-11"},{"id":"ai200-s3-01-stellmarsh-workload-profile","prompt":"You must host the new Stellmarsh turbine-anomaly model, which requires GPU compute, inside the existing `stell-env` Container Apps environment. The team will not create or operate a Kubernetes cluster.\n\nWhat should you do?\nAssume serverless GPUs are supported in the environment region and the subscription has sufficient quota.","explanation":"Use a supported serverless GPU workload profile and assign the application to it. Increasing CPU allocation cannot provide a GPU. Check supported regions, quotas and replica sizing first. Dedicated GPU profiles can require a new environment; they are not interchangeable with serverless GPU profiles.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/container-apps/gpu-serverless-overview","practiceSource":"https://github.com/quizplay-io/quiz-player-quizzes-ai-200-question-set-3/blob/b158ee5f8717ecd671bf6ea2b748cf09e83e048b/questions/01-stellmarsh-workload-profile.json","type":"single","options":["Add a GPU workload profile to `stell-env` (for example `az containerapp env workload-profile add --workload-profile-type Consumption-GPU-NC24-A100`), then deploy the inference app with `--workload-profile-name` set to that profile.","Keep the app on the Consumption profile and raise its resource allocation to the maximum `--cpu` and `--memory` values so the model runs faster.","Add a GPU node pool to the `stell-batch` AKS cluster and move the inference API there with a `nvidia.com/gpu` resource request in its Deployment manifest.","Add a custom KEDA scale rule to the app so it scales out to enough CPU replicas to match GPU throughput."],"answer":0,"caseId":"quizplay:case_study_stellmarsh_aviation","caseTitle":"Stellmarsh Aviation","caseData":{"Company Overview":"**Stellmarsh Aviation** provides predictive-maintenance analytics for regional airlines. Its Python services analyze engine-sensor telemetry and predict component failures before they occur.\n\n**Current Environment:**\n- All container images are built in CI and stored in the Azure Container Registry `stellmarshacr`.\n- Real-time inference APIs run in an **Azure Container Apps** environment named `stell-env`, which has workload profiles enabled. All apps currently run on the Consumption profile.\n- A nightly fleet-wide batch scorer runs as a Deployment on an existing **Azure Kubernetes Service** cluster named `stell-batch`.\n- Trained model weights are versioned and stored in an **Azure Blob Storage** container named `models`. The current turbine-anomaly model is approximately **8 GB**.","Requirements":"**Inference Requirements:**\n- A new turbine-anomaly detection model requires **GPU compute**. It must run inside the existing `stell-env` environment; the team will not create or operate a Kubernetes cluster for it.\n- The inference API container image must stay small: the 8 GB model weights must **not** be baked into the image, must be fully present on a local volume **before** the API container starts accepting traffic, and a new model version must be deployable without rebuilding the API image.\n\n**Batch Scoring Requirements:**\n- The nightly scorer on `stell-batch` is currently unhealthy: its pods restart repeatedly and `kubectl get pods` shows `CrashLoopBackOff`. Each container exits roughly 20 seconds after starting. Engineers need to see the output the crashed container produced before it exited.\n\n**General:**\n- All services authenticate to Azure resources with managed identities; no keys or passwords in images or manifests.","Review notes":"Assume supported serverless GPU region/quota, appropriately sized shared storage, and a supported download authentication method. Init-container managed identity availability depends on the workload profile. Roll out a pinned model version to new replicas."},"setId":"quizplay-set-3","reviewDate":"2026-10-11","reviewNote":"Clarified that adding a serverless GPU profile depends on regional support and quota; dedicated GPU profiles have different creation constraints."},{"id":"ai200-s3-02-stellmarsh-init-container","prompt":"You must satisfy the Stellmarsh model-loading requirement: the 8 GB turbine-anomaly weights must not be baked into the API image, must be fully present on a local volume **before** the API container starts accepting traffic, and a new model version must be deployable without rebuilding the API image.\n\nHow should you configure the container app?\nAssume the download credentials and a sufficiently sized shared volume are configured for the chosen workload profile.","explanation":"An init container finishes downloading a pinned model version before the application container starts; both mount the same volume. Roll out a new model-version setting/revision to initialize fresh replicas. Updating a blob alone does not refresh running replicas. Managed identity access from init containers depends on the environment/profile; it is not supported in consumption-only or dedicated-profile environments. Verify volume capacity for the 8 GB model.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/container-apps/containers","practiceSource":"https://github.com/quizplay-io/quiz-player-quizzes-ai-200-question-set-3/blob/b158ee5f8717ecd671bf6ea2b748cf09e83e048b/questions/02-stellmarsh-init-container.json","type":"single","options":["Define an **init container** in the app's template that downloads the weights from the `models` blob container to a shared volume; mount the same volume into the API container. The API container starts only after the init container completes.","Add a `COPY models/ /models/` instruction to the API image's Dockerfile so the weights ship inside the image layer cache.","Run the downloader as a **sidecar container** in the same replica so it fetches the weights in parallel while the API container boots.","Download the weights lazily inside the API process when the first inference request arrives, caching them in memory for later requests."],"answer":0,"caseId":"quizplay:case_study_stellmarsh_aviation","caseTitle":"Stellmarsh Aviation","caseData":{"Company Overview":"**Stellmarsh Aviation** provides predictive-maintenance analytics for regional airlines. Its Python services analyze engine-sensor telemetry and predict component failures before they occur.\n\n**Current Environment:**\n- All container images are built in CI and stored in the Azure Container Registry `stellmarshacr`.\n- Real-time inference APIs run in an **Azure Container Apps** environment named `stell-env`, which has workload profiles enabled. All apps currently run on the Consumption profile.\n- A nightly fleet-wide batch scorer runs as a Deployment on an existing **Azure Kubernetes Service** cluster named `stell-batch`.\n- Trained model weights are versioned and stored in an **Azure Blob Storage** container named `models`. The current turbine-anomaly model is approximately **8 GB**.","Requirements":"**Inference Requirements:**\n- A new turbine-anomaly detection model requires **GPU compute**. It must run inside the existing `stell-env` environment; the team will not create or operate a Kubernetes cluster for it.\n- The inference API container image must stay small: the 8 GB model weights must **not** be baked into the image, must be fully present on a local volume **before** the API container starts accepting traffic, and a new model version must be deployable without rebuilding the API image.\n\n**Batch Scoring Requirements:**\n- The nightly scorer on `stell-batch` is currently unhealthy: its pods restart repeatedly and `kubectl get pods` shows `CrashLoopBackOff`. Each container exits roughly 20 seconds after starting. Engineers need to see the output the crashed container produced before it exited.\n\n**General:**\n- All services authenticate to Azure resources with managed identities; no keys or passwords in images or manifests.","Review notes":"Assume supported serverless GPU region/quota, appropriately sized shared storage, and a supported download authentication method. Init-container managed identity availability depends on the workload profile. Roll out a pinned model version to new replicas."},"setId":"quizplay-set-3","reviewDate":"2026-10-11","reviewNote":"Removed the blanket claim that init containers can always use managed identity; clarified model rollout."},{"id":"ai200-s3-03-stellmarsh-aks-crashloop","prompt":"The Stellmarsh nightly scorer pods on `stell-batch` are in `CrashLoopBackOff`: each container exits about 20 seconds after starting, and Kubernetes keeps restarting it. Engineers need to see the output the **crashed** container wrote before it exited.\n\nWhich command should they run?","explanation":"`kubectl logs \u003cpod> --previous` (`-p`) returns the stdout/stderr of the **previous, terminated instance** of the container — exactly what you need in a crash loop, where the *current* instance has just restarted and its log stream is empty or about to die again. Kubelet retains the last terminated container's log for this purpose. The exit output usually contains the stack trace or fatal error that explains the ~20-second crash.\n\n**Why not the other options:**\n- **`kubectl exec`** — `exec` needs a *running* container. In `CrashLoopBackOff` the container is either dead or lives only a few seconds, so an interactive shell is impractical — and the crash output went to stdout, not necessarily to a file inside the container.\n- **`kubectl get events`** — Events show lifecycle facts (`Back-off restarting failed container`, probe failures, image pulls) but **not the application's own output**. They tell you *that* it crashed, not *why* the process exited.\n- **`az aks update --attach-acr`** — Registry integration fixes `ImagePullBackOff` (401s from the registry). These pods pull fine and *start*; the failure is inside the running process, so registry permissions are irrelevant.","domain":"containers","source":"https://kubernetes.io/docs/reference/kubectl/generated/kubectl_logs/","practiceSource":"https://github.com/quizplay-io/quiz-player-quizzes-ai-200-question-set-3/blob/b158ee5f8717ecd671bf6ea2b748cf09e83e048b/questions/03-stellmarsh-aks-crashloop.json","type":"single","options":["kubectl logs \u003cpod-name> --previous","kubectl exec -it \u003cpod-name> -- cat /var/log/app.log","kubectl get events --field-selector involvedObject.name=\u003cpod-name>","az aks update --attach-acr stellmarshacr"],"answer":0,"caseId":"quizplay:case_study_stellmarsh_aviation","caseTitle":"Stellmarsh Aviation","caseData":{"Company Overview":"**Stellmarsh Aviation** provides predictive-maintenance analytics for regional airlines. Its Python services analyze engine-sensor telemetry and predict component failures before they occur.\n\n**Current Environment:**\n- All container images are built in CI and stored in the Azure Container Registry `stellmarshacr`.\n- Real-time inference APIs run in an **Azure Container Apps** environment named `stell-env`, which has workload profiles enabled. All apps currently run on the Consumption profile.\n- A nightly fleet-wide batch scorer runs as a Deployment on an existing **Azure Kubernetes Service** cluster named `stell-batch`.\n- Trained model weights are versioned and stored in an **Azure Blob Storage** container named `models`. The current turbine-anomaly model is approximately **8 GB**.","Requirements":"**Inference Requirements:**\n- A new turbine-anomaly detection model requires **GPU compute**. It must run inside the existing `stell-env` environment; the team will not create or operate a Kubernetes cluster for it.\n- The inference API container image must stay small: the 8 GB model weights must **not** be baked into the image, must be fully present on a local volume **before** the API container starts accepting traffic, and a new model version must be deployable without rebuilding the API image.\n\n**Batch Scoring Requirements:**\n- The nightly scorer on `stell-batch` is currently unhealthy: its pods restart repeatedly and `kubectl get pods` shows `CrashLoopBackOff`. Each container exits roughly 20 seconds after starting. Engineers need to see the output the crashed container produced before it exited.\n\n**General:**\n- All services authenticate to Azure resources with managed identities; no keys or passwords in images or manifests.","Review notes":"Assume supported serverless GPU region/quota, appropriately sized shared storage, and a supported download authentication method. Init-container managed identity availability depends on the workload profile. Roll out a pinned model version to new replicas."},"setId":"quizplay-set-3","reviewDate":"2026-10-11","reviewNote":"Answer and explanation reviewed against the linked product documentation."},{"id":"ai200-s3-04-tarnwell-cosmos-ttl","prompt":"You must implement the Tarnwell retention requirement: every document in the `chat-sessions` container must be deleted automatically 30 days after it was last updated, with no cleanup job to build or operate.\n\nWhat should you do?\nAssume provisioned throughput and no item-level TTL overrides.","explanation":"Enable the container TTL and set its default to 2592000 seconds. Expiry is relative to the last modification timestamp. Expired items stop appearing in queries; physical deletion runs in the background. Spare RUs are used for TTL deletion under provisioned throughput; serverless deletion is billed. Item-level TTL values can override the default.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/cosmos-db/time-to-live","practiceSource":"https://github.com/quizplay-io/quiz-player-quizzes-ai-200-question-set-3/blob/b158ee5f8717ecd671bf6ea2b748cf09e83e048b/questions/04-tarnwell-cosmos-ttl.json","type":"single","options":["Set the container's default time-to-live to 2,592,000 seconds (`DefaultTimeToLive = 2592000`); Cosmos DB then deletes each document 30 days after its last write, using leftover RUs in the background.","Create an Azure Functions timer trigger that runs nightly, queries for documents whose `_ts` is older than 30 days, and deletes them in batches.","Add a `deleteAfter` property to each document and configure an Event Grid subscription that fires when the date passes and calls a deletion webhook.","Set `time_to_live` on the Cosmos client so the SDK filters out documents older than 30 days from every query result."],"answer":0,"caseId":"quizplay:case_study_tarnwell_hospitality","caseTitle":"Tarnwell Hospitality","caseData":{"Company Overview":"**Tarnwell Hospitality** operates a booking platform for boutique hotels. An AI concierge answers guest questions about properties, availability, and local activities. The back end is a set of Python services.\n\n**Current Environment:**\n- **Azure Cosmos DB for NoSQL** hosts the `concierge` database with two containers:\n  - `chat-sessions` — concierge conversation transcripts, partitioned on `/sessionId`.\n  - `reviews` — guest reviews, partitioned on `/hotelId`. Each document has `hotelId`, `rating` (number), and `stayDate` (ISO 8601 string) properties. The container uses the default indexing policy.\n- **Azure Managed Redis** caches rendered concierge answers keyed by a hash of the normalized question. Answers are written with a 1-hour expiration.\n- Embeddings for review search are produced by an external embedding model.","Requirements":"**Data Retention Requirements:**\n- Privacy policy: a chat-session document must be deleted automatically **30 days after it was last updated**. The team must not build or operate any cleanup job, and deletions must not consume RUs reserved for user traffic beyond what the platform manages itself.\n\n**Review Browsing Requirements:**\n- The hotel detail page runs this query, which currently fails:\n\n```sql\nSELECT * FROM c\nWHERE c.hotelId = @hotelId\nORDER BY c.rating DESC, c.stayDate DESC\n```\n\n- The query must run as-is, sorted by the service, with low RU cost.\n\n**Caching Requirements:**\n- Frequently asked questions must stay cached as long as guests keep asking them: every cache **read** must extend the entry's remaining lifetime back to 1 hour, in a single round trip. Entries nobody reads must still expire on their own.","Review notes":"Assume provisioned Cosmos DB throughput with no per-item TTL overrides. Measure composite-index request charges; the sort index alone does not guarantee a fixed RU cost."},"setId":"quizplay-set-3","reviewDate":"2026-10-11","reviewNote":"Scoped spare-RU TTL deletion behavior to provisioned throughput and excluded per-item overrides."},{"id":"ai200-s3-05-tarnwell-cosmos-composite-index","prompt":"The Tarnwell hotel-detail query fails when it runs against the `reviews` container:\n\n```sql\nSELECT * FROM c\nWHERE c.hotelId = @hotelId\nORDER BY c.rating DESC, c.stayDate DESC\n```\n\nThe query must run as-is, with the sorting done by Cosmos DB at low RU cost. What should you do?","explanation":"A multi-property ORDER BY requires a composite index matching the ordered paths and directions. The (/rating DESC, /stayDate DESC) index supports this query. Measure request charges and index metrics; a matching sort index does not by itself guarantee a particular RU cost for the filter.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/cosmos-db/index-policy","practiceSource":"https://github.com/quizplay-io/quiz-player-quizzes-ai-200-question-set-3/blob/b158ee5f8717ecd671bf6ea2b748cf09e83e048b/questions/05-tarnwell-cosmos-composite-index.json","type":"single","options":["Add a **composite index** on `(/rating DESC, /stayDate DESC)` to the container's indexing policy.","Remove the second sort key and re-sort the page of results by `stayDate` in the Python service.","Increase the container's provisioned throughput; multi-property `ORDER BY` succeeds once enough RU/s are available.","Add separate range indexes for `/rating/?` and `/stayDate/?` to the indexing policy."],"answer":0,"caseId":"quizplay:case_study_tarnwell_hospitality","caseTitle":"Tarnwell Hospitality","caseData":{"Company Overview":"**Tarnwell Hospitality** operates a booking platform for boutique hotels. An AI concierge answers guest questions about properties, availability, and local activities. The back end is a set of Python services.\n\n**Current Environment:**\n- **Azure Cosmos DB for NoSQL** hosts the `concierge` database with two containers:\n  - `chat-sessions` — concierge conversation transcripts, partitioned on `/sessionId`.\n  - `reviews` — guest reviews, partitioned on `/hotelId`. Each document has `hotelId`, `rating` (number), and `stayDate` (ISO 8601 string) properties. The container uses the default indexing policy.\n- **Azure Managed Redis** caches rendered concierge answers keyed by a hash of the normalized question. Answers are written with a 1-hour expiration.\n- Embeddings for review search are produced by an external embedding model.","Requirements":"**Data Retention Requirements:**\n- Privacy policy: a chat-session document must be deleted automatically **30 days after it was last updated**. The team must not build or operate any cleanup job, and deletions must not consume RUs reserved for user traffic beyond what the platform manages itself.\n\n**Review Browsing Requirements:**\n- The hotel detail page runs this query, which currently fails:\n\n```sql\nSELECT * FROM c\nWHERE c.hotelId = @hotelId\nORDER BY c.rating DESC, c.stayDate DESC\n```\n\n- The query must run as-is, sorted by the service, with low RU cost.\n\n**Caching Requirements:**\n- Frequently asked questions must stay cached as long as guests keep asking them: every cache **read** must extend the entry's remaining lifetime back to 1 hour, in a single round trip. Entries nobody reads must still expire on their own.","Review notes":"Assume provisioned Cosmos DB throughput with no per-item TTL overrides. Measure composite-index request charges; the sort index alone does not guarantee a fixed RU cost."},"setId":"quizplay-set-3","reviewDate":"2026-10-11","reviewNote":"Clarified required sorting index versus measured RU optimization."},{"id":"ai200-s3-06-tarnwell-redis-getex","prompt":"You must implement the Tarnwell caching requirement in Azure Managed Redis: every read of a cached concierge answer must also reset that entry's remaining lifetime to 1 hour, in a **single round trip**, while unread entries still expire on their own.\n\nWhich command should the Python service use on the read path?","explanation":"`GETEX` retrieves a key's value **and atomically updates its expiration in the same command** — `GETEX answer:\u003chash> EX 3600` returns the cached answer and resets the TTL to 3,600 seconds. That produces exactly the required *sliding expiration*: popular answers are refreshed on every read and stay warm, while entries nobody reads keep their last TTL and expire naturally. One command, one round trip.\n\n**Why not the other options:**\n- **Plain `GET`** — Reading with `GET` does not touch the TTL, so an answer written once always dies 1 hour after the *write*, no matter how popular it is. That is absolute expiration, not the required sliding behavior.\n- **`PERSIST` + `GET`** — `PERSIST` *removes* the expiration entirely, so entries never expire again — violating \"unread entries must still expire\" — and it is two round trips (or needs a pipeline) instead of one.\n- **`TTL` + conditional `GET`** — `TTL` only *inspects* the remaining lifetime; it never extends it. This adds a round trip, still lets hot entries expire mid-popularity, and solves nothing.","domain":"data","source":"https://redis.io/docs/latest/commands/getex/","practiceSource":"https://github.com/quizplay-io/quiz-player-quizzes-ai-200-question-set-3/blob/b158ee5f8717ecd671bf6ea2b748cf09e83e048b/questions/06-tarnwell-redis-getex.json","type":"single","options":["GETEX answer:\u003cquestion-hash> EX 3600","GET answer:\u003cquestion-hash>, and rely on the 1-hour expiration set when the entry was written.","PERSIST answer:\u003cquestion-hash> followed by GET answer:\u003cquestion-hash>.","TTL answer:\u003cquestion-hash>, then GET the key if the returned TTL is greater than zero."],"answer":0,"caseId":"quizplay:case_study_tarnwell_hospitality","caseTitle":"Tarnwell Hospitality","caseData":{"Company Overview":"**Tarnwell Hospitality** operates a booking platform for boutique hotels. An AI concierge answers guest questions about properties, availability, and local activities. The back end is a set of Python services.\n\n**Current Environment:**\n- **Azure Cosmos DB for NoSQL** hosts the `concierge` database with two containers:\n  - `chat-sessions` — concierge conversation transcripts, partitioned on `/sessionId`.\n  - `reviews` — guest reviews, partitioned on `/hotelId`. Each document has `hotelId`, `rating` (number), and `stayDate` (ISO 8601 string) properties. The container uses the default indexing policy.\n- **Azure Managed Redis** caches rendered concierge answers keyed by a hash of the normalized question. Answers are written with a 1-hour expiration.\n- Embeddings for review search are produced by an external embedding model.","Requirements":"**Data Retention Requirements:**\n- Privacy policy: a chat-session document must be deleted automatically **30 days after it was last updated**. The team must not build or operate any cleanup job, and deletions must not consume RUs reserved for user traffic beyond what the platform manages itself.\n\n**Review Browsing Requirements:**\n- The hotel detail page runs this query, which currently fails:\n\n```sql\nSELECT * FROM c\nWHERE c.hotelId = @hotelId\nORDER BY c.rating DESC, c.stayDate DESC\n```\n\n- The query must run as-is, sorted by the service, with low RU cost.\n\n**Caching Requirements:**\n- Frequently asked questions must stay cached as long as guests keep asking them: every cache **read** must extend the entry's remaining lifetime back to 1 hour, in a single round trip. Entries nobody reads must still expire on their own.","Review notes":"Assume provisioned Cosmos DB throughput with no per-item TTL overrides. Measure composite-index request charges; the sort index alone does not guarantee a fixed RU cost."},"setId":"quizplay-set-3","reviewDate":"2026-10-11","reviewNote":"Answer and explanation reviewed against the linked product documentation."},{"id":"ai200-s3-07-polwarren-servicebus-defer","prompt":"A clearance command arrives before its vessel manifest. It must be set aside without blocking other vessels, then retrieved individually without resending. Assume its TTL exceeds the expected wait. What should the worker do?","explanation":"Defer the message and durably retain its sequence number. Retrieve it using receive_deferred_messages, process idempotently, and complete it. Deferred messages stay in the main entity and ordinary receives skip them. Expiration is checked when a deferred receive is attempted; deferral does not extend TTL. Failures can still cause repeated processing.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/service-bus-messaging/message-deferral","practiceSource":"https://github.com/quizplay-io/quiz-player-quizzes-ai-200-question-set-3/blob/b158ee5f8717ecd671bf6ea2b748cf09e83e048b/questions/07-polwarren-servicebus-defer.json","type":"single","options":["Call `receiver.defer_message(msg)` and durably record the message's sequence number against the vessel; when the manifest arrives, retrieve exactly that command with `receiver.receive_deferred_messages(sequence_numbers=[seq])`, process it, and complete it.","Call `receiver.abandon_message(msg)` so the command returns to the queue and is redelivered until the manifest is ready.","Call `receiver.dead_letter_message(msg, reason=\"manifest-missing\")` and replay the dead-letter sub-queue after each manifest registration.","Complete the message, then re-send a copy of it with `sender.schedule_messages(copy, enqueue_time_utc)` set 15 minutes in the future, repeating until the manifest exists."],"answer":0,"caseId":"quizplay:case_study_polwarren_shipping","caseTitle":"Polwarren Shipping","caseData":{"Company Overview":"**Polwarren Shipping** operates container-port terminals. Its Python services coordinate vessel arrivals, customs clearance, and yard planning.\n\n**Current Environment:**\n- Customs-clearance commands for arriving vessels flow through an **Azure Service Bus** queue named `clearance-commands`. Workers receive in PEEK_LOCK mode.\n- Vessel status changes are published to an **Azure Event Grid** custom topic named `pol-vessel-events`. A customs-broker partner subscribes with an HTTPS webhook.\n- Customs declaration PDFs are uploaded by shipping agents to the **Azure Blob Storage** container `customs-inbound`.\n- Document processing runs on **Azure Functions** (Python v2 programming model).","Requirements":"**Clearance Processing Requirements:**\n- A clearance command sometimes arrives **before** the vessel's cargo manifest has been registered. Such a command cannot be processed yet, but it must not be lost, must not block other vessels' commands, and must be retrievable **individually and exactly** once its manifest arrives — without re-sending it or letting it expire.\n\n**Partner Webhook Requirements:**\n- The customs broker's gateway rate-limits aggressively. If the webhook is down, Event Grid must stop retrying a given event after **at most 10 attempts** and must consider an event expired **1 hour** after publication. Undeliverable events are already captured by an existing dead-letter destination.\n\n**Document Processing Requirements:**\n- When an agent uploads a PDF to `customs-inbound`, a function must begin processing it **within a few seconds**. The current polling-based blob trigger sometimes takes several minutes to fire and scans the container continuously.\n\n**General:**\n- All services authenticate with managed identities.","Review notes":"Deferred commands must be received before their configured TTL expires. Use idempotent processing; neither Service Bus deferral nor Event Grid retries promise exactly-once business effects."},"setId":"quizplay-set-3","reviewDate":"2026-10-11","reviewNote":"Deferral neither suspends TTL nor guarantees exactly-once business processing."},{"id":"ai200-s3-08-polwarren-eventgrid-retry","prompt":"You must implement the Polwarren webhook requirement: for the customs broker's subscription on `pol-vessel-events`, Event Grid must stop retrying a given event after at most 10 delivery attempts and must consider an event expired 1 hour after publication. The dead-letter destination already exists.\n\nWhat should you do?","explanation":"Set max-delivery-attempts to 10 and event-ttl to 60 minutes on the Event Grid subscription. Retry processing stops at the first reached limit. Some response codes end delivery without ordinary retries. Configure and authorize the dead-letter destination and monitor dead-letter failures; persistence is not an unconditional guarantee.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/event-grid/delivery-and-retry","practiceSource":"https://github.com/quizplay-io/quiz-player-quizzes-ai-200-question-set-3/blob/b158ee5f8717ecd671bf6ea2b748cf09e83e048b/questions/08-polwarren-eventgrid-retry.json","type":"single","options":["Update the event subscription's retry policy: `az eventgrid event-subscription update --name broker-sub ... --max-delivery-attempts 10 --event-ttl 60`. Delivery stops when either limit is reached first.","Update the event subscription with `--max-delivery-attempts 10 --event-ttl 3600`, specifying the time-to-live as 3,600 seconds.","Have the webhook count deliveries per event `id` in its own store and return `200 OK` for any event it has already seen 10 times or that is older than 1 hour.","Add a lifecycle management rule on the dead-letter storage container that deletes blobs 1 hour after creation."],"answer":0,"caseId":"quizplay:case_study_polwarren_shipping","caseTitle":"Polwarren Shipping","caseData":{"Company Overview":"**Polwarren Shipping** operates container-port terminals. Its Python services coordinate vessel arrivals, customs clearance, and yard planning.\n\n**Current Environment:**\n- Customs-clearance commands for arriving vessels flow through an **Azure Service Bus** queue named `clearance-commands`. Workers receive in PEEK_LOCK mode.\n- Vessel status changes are published to an **Azure Event Grid** custom topic named `pol-vessel-events`. A customs-broker partner subscribes with an HTTPS webhook.\n- Customs declaration PDFs are uploaded by shipping agents to the **Azure Blob Storage** container `customs-inbound`.\n- Document processing runs on **Azure Functions** (Python v2 programming model).","Requirements":"**Clearance Processing Requirements:**\n- A clearance command sometimes arrives **before** the vessel's cargo manifest has been registered. Such a command cannot be processed yet, but it must not be lost, must not block other vessels' commands, and must be retrievable **individually and exactly** once its manifest arrives — without re-sending it or letting it expire.\n\n**Partner Webhook Requirements:**\n- The customs broker's gateway rate-limits aggressively. If the webhook is down, Event Grid must stop retrying a given event after **at most 10 attempts** and must consider an event expired **1 hour** after publication. Undeliverable events are already captured by an existing dead-letter destination.\n\n**Document Processing Requirements:**\n- When an agent uploads a PDF to `customs-inbound`, a function must begin processing it **within a few seconds**. The current polling-based blob trigger sometimes takes several minutes to fire and scans the container continuously.\n\n**General:**\n- All services authenticate with managed identities.","Review notes":"Deferred commands must be received before their configured TTL expires. Use idempotent processing; neither Service Bus deferral nor Event Grid retries promise exactly-once business effects."},"setId":"quizplay-set-3","reviewDate":"2026-10-11","reviewNote":"Removed guaranteed dead-letter persistence and clarified early terminal failures."},{"id":"ai200-s3-09-polwarren-blob-eventgrid-trigger","prompt":"You must fix the Polwarren document-processing latency: a PDF uploaded to `customs-inbound` must start processing within a few seconds, but the current polling-based blob trigger sometimes takes minutes to fire and continuously scans the container.\n\nHow should you change the Azure Functions (Python v2) trigger?","explanation":"The blob trigger's default detection mechanism is polling-based container scanning, which is explicitly documented as *best effort* — it can take minutes on busy or large containers. The fix is to keep the same blob-trigger programming model but change its **source to Event Grid**: `source=\"EventGrid\"` in the decorator, plus a `BlobCreated` event subscription on the storage account. Uploads then *push* an event to the function within seconds, the continuous scanning stops, and the shipping agents' workflow is untouched — the binding still hands the function the blob itself.\n\n**Why not the other options:**\n- **Faster polling interval** — Blob-trigger detection is not governed by a simple per-second polling knob; it relies on container scans and log processing whose latency is inherently best-effort. Even more frequent scanning keeps the expensive continuous listing the requirement says to eliminate.\n- **Queue trigger with agent-enqueued messages** — Shipping agents are external parties who upload files; forcing every agent's system to also send a queue message changes the public contract, and any agent that forgets produces a silently unprocessed PDF.\n- **Per-second timer that lists the container** — This is hand-rolled polling: it pays for a listing every second forever, needs its own \"already seen\" state store, and still races against listing consistency. The platform's event-driven trigger does the same job natively.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/azure-functions/functions-bindings-storage-blob-trigger","practiceSource":"https://github.com/quizplay-io/quiz-player-quizzes-ai-200-question-set-3/blob/b158ee5f8717ecd671bf6ea2b748cf09e83e048b/questions/09-polwarren-blob-eventgrid-trigger.json","type":"single","options":["Switch the blob trigger to the Event Grid source — `@app.blob_trigger(arg_name=\"blob\", path=\"customs-inbound/{name}\", source=\"EventGrid\", connection=\"StorageConnection\")` — and create an Event Grid subscription for `Microsoft.Storage.BlobCreated` on the storage account that targets the function.","Keep the polling blob trigger but set a 1-second polling interval in `host.json` so the container is scanned more often.","Replace the blob trigger with a queue trigger and require shipping agents to enqueue a message after each upload.","Replace the blob trigger with a timer trigger that runs every second and lists the container for blobs it has not seen before."],"answer":0,"caseId":"quizplay:case_study_polwarren_shipping","caseTitle":"Polwarren Shipping","caseData":{"Company Overview":"**Polwarren Shipping** operates container-port terminals. Its Python services coordinate vessel arrivals, customs clearance, and yard planning.\n\n**Current Environment:**\n- Customs-clearance commands for arriving vessels flow through an **Azure Service Bus** queue named `clearance-commands`. Workers receive in PEEK_LOCK mode.\n- Vessel status changes are published to an **Azure Event Grid** custom topic named `pol-vessel-events`. A customs-broker partner subscribes with an HTTPS webhook.\n- Customs declaration PDFs are uploaded by shipping agents to the **Azure Blob Storage** container `customs-inbound`.\n- Document processing runs on **Azure Functions** (Python v2 programming model).","Requirements":"**Clearance Processing Requirements:**\n- A clearance command sometimes arrives **before** the vessel's cargo manifest has been registered. Such a command cannot be processed yet, but it must not be lost, must not block other vessels' commands, and must be retrievable **individually and exactly** once its manifest arrives — without re-sending it or letting it expire.\n\n**Partner Webhook Requirements:**\n- The customs broker's gateway rate-limits aggressively. If the webhook is down, Event Grid must stop retrying a given event after **at most 10 attempts** and must consider an event expired **1 hour** after publication. Undeliverable events are already captured by an existing dead-letter destination.\n\n**Document Processing Requirements:**\n- When an agent uploads a PDF to `customs-inbound`, a function must begin processing it **within a few seconds**. The current polling-based blob trigger sometimes takes several minutes to fire and scans the container continuously.\n\n**General:**\n- All services authenticate with managed identities.","Review notes":"Deferred commands must be received before their configured TTL expires. Use idempotent processing; neither Service Bus deferral nor Event Grid retries promise exactly-once business effects."},"setId":"quizplay-set-3","reviewDate":"2026-10-11","reviewNote":"Answer and explanation reviewed against the linked product documentation."},{"id":"ai200-s3-10-gantrell-appconfig-snapshot","prompt":"You must implement the Gantrell configuration requirement: each release must promote exactly the set of ~40 App Configuration key-values tested in staging, as one immutable named unit; rollback must restore exactly the previous unit; and later edits to individual keys must not affect what already-released instances load.\n\nWhat should you do?","explanation":"An App Configuration **snapshot** is precisely the required artifact: a **named, immutable, point-in-time subset** of the store's key-values, defined by key/label filters. Creating a snapshot at release time freezes all 40 `Valuation:*` keys as one unit; instances that load from the snapshot always see exactly that tested set, no matter how the live key-values change afterward. Rollback is redeploying with the previous snapshot's name — guaranteed to restore *exactly* the prior unit, because snapshots cannot be modified after creation.\n\n**Why not the other options:**\n- **A label per release** — Labels organize variants, but labeled key-values remain **mutable**: anyone can edit a key under the `release-2026-07-12` label after the release, silently changing what \"released\" instances load on their next refresh. That breaks both immutability and exact-rollback guarantees.\n- **Export/re-import over `prod`** — The imported values are again ordinary, editable key-values, and the import itself is a multi-key write with no atomicity: an instance refreshing mid-import can load a half-old, half-new mixture of the 40 interdependent keys.\n- **`az appconfig kv lock`** — Read-only key-values prevent edits, but they create no *named unit* and no history to roll back to; releasing the next version requires unlocking and mutating the very values the previous release depends on, which is exactly the interference the requirement rules out.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/azure-app-configuration/concept-snapshots","practiceSource":"https://github.com/quizplay-io/quiz-player-quizzes-ai-200-question-set-3/blob/b158ee5f8717ecd671bf6ea2b748cf09e83e048b/questions/10-gantrell-appconfig-snapshot.json","type":"single","options":["At release time, create an App Configuration **snapshot** of the `Valuation:*` key-values (for example `az appconfig snapshot create --snapshot-name release-2026-07-12 ...`); deploy each release pinned to its snapshot name, and roll back by pointing instances at the previous snapshot.","Copy the 40 keys to a new **label** per release (for example `release-2026-07-12`) and have instances load that label; on rollback, load the previous label.","Export the 40 keys to a JSON file at release time and re-import them into the store over the `prod` label during each deployment.","Mark the 40 key-values as read-only with `az appconfig kv lock` after each release so nobody can change what instances load."],"answer":0,"caseId":"quizplay:case_study_gantrell_property","caseTitle":"Gantrell Property","caseData":{"Company Overview":"**Gantrell Property Group** runs an AI-assisted property-valuation platform. A Python scoring service produces automated valuations; every valuation run emits structured telemetry.\n\n**Current Environment:**\n- Application settings and model-tuning parameters (about 40 related keys such as `Valuation:ModelVersion`, `Valuation:ComparableRadiusKm`, `Valuation:ConfidenceFloor`) live in **Azure App Configuration**. The keys are tuned together: a change to one usually requires coordinated changes to several others.\n- All services are instrumented with the **Azure Monitor OpenTelemetry distro** (`azure-monitor-opentelemetry`) and send telemetry to a workspace-based **Application Insights** resource.\n- The valuation service logs one structured trace per completed valuation to `AppTraces`, with the property identifier in the `Properties` dynamic column (`Properties.propertyId`) alongside the valuation status.","Requirements":"**Configuration Requirements:**\n- A release must promote **exactly** the set of App Configuration key-values that was tested in staging — all 40 keys as one immutable, named unit. Rolling back must restore exactly the previous unit. Individual keys continuing to change in the store must not affect what already-released instances load.\n\n**Telemetry Cost Requirements:**\n- The platform now handles ~40 million requests per day and Application Insights ingestion cost has become unacceptable. Ingested trace volume must be cut to roughly **10%**, while request **counts and failure rates shown in Application Insights experiences must remain statistically accurate**, and sampled requests must keep their full end-to-end traces.\n\n**Operations Requirements:**\n- An operations dashboard must show, for **each property**, only the **most recent** valuation trace row (all of its columns), derived from `AppTraces`.","Review notes":"Sampling yields statistical estimates and needs propagated trace context. Use sampling weights for represented request counts. An immutable configuration snapshot does not freeze the contents behind a versionless Key Vault reference."},"setId":"quizplay-set-3","reviewDate":"2026-10-11","reviewNote":"Answer and explanation reviewed against the linked product documentation."},{"id":"ai200-s3-11-gantrell-sampling-ratio","prompt":"You must implement the Gantrell telemetry cost requirement: cut ingested trace volume to roughly 10% of today's ~40 million requests per day, while request counts and failure rates shown in Application Insights remain statistically accurate and sampled requests keep their full end-to-end traces.\n\nWhat should you do?","explanation":"Configure the Azure Monitor fixed-rate sampler with sampling_ratio=0.1 and propagate trace context across instrumented services. This targets approximately 10% of traces, not exactly 10% of all telemetry or cost. Sample weights support estimated counts (for example sum(ItemCount)); plain count() on sampled rows does not reconstruct request totals. Rare failures can be missed and inconsistent instrumentation can leave incomplete traces.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/azure-monitor/app/opentelemetry-sampling","practiceSource":"https://github.com/quizplay-io/quiz-player-quizzes-ai-200-question-set-3/blob/b158ee5f8717ecd671bf6ea2b748cf09e83e048b/questions/11-gantrell-sampling-ratio.json","type":"single","options":["Enable fixed-rate sampling in the Azure Monitor OpenTelemetry distro by passing `sampling_ratio=0.1` to `configure_azure_monitor()` in every service.","Set a daily ingestion cap on the Application Insights resource sized to 10% of the current daily volume.","Raise the logging level so only warnings and errors are exported, cutting the trace volume to roughly one tenth.","In custom middleware, call the instrumentation for only every tenth incoming request and skip telemetry entirely for the rest."],"answer":0,"caseId":"quizplay:case_study_gantrell_property","caseTitle":"Gantrell Property","caseData":{"Company Overview":"**Gantrell Property Group** runs an AI-assisted property-valuation platform. A Python scoring service produces automated valuations; every valuation run emits structured telemetry.\n\n**Current Environment:**\n- Application settings and model-tuning parameters (about 40 related keys such as `Valuation:ModelVersion`, `Valuation:ComparableRadiusKm`, `Valuation:ConfidenceFloor`) live in **Azure App Configuration**. The keys are tuned together: a change to one usually requires coordinated changes to several others.\n- All services are instrumented with the **Azure Monitor OpenTelemetry distro** (`azure-monitor-opentelemetry`) and send telemetry to a workspace-based **Application Insights** resource.\n- The valuation service logs one structured trace per completed valuation to `AppTraces`, with the property identifier in the `Properties` dynamic column (`Properties.propertyId`) alongside the valuation status.","Requirements":"**Configuration Requirements:**\n- A release must promote **exactly** the set of App Configuration key-values that was tested in staging — all 40 keys as one immutable, named unit. Rolling back must restore exactly the previous unit. Individual keys continuing to change in the store must not affect what already-released instances load.\n\n**Telemetry Cost Requirements:**\n- The platform now handles ~40 million requests per day and Application Insights ingestion cost has become unacceptable. Ingested trace volume must be cut to roughly **10%**, while request **counts and failure rates shown in Application Insights experiences must remain statistically accurate**, and sampled requests must keep their full end-to-end traces.\n\n**Operations Requirements:**\n- An operations dashboard must show, for **each property**, only the **most recent** valuation trace row (all of its columns), derived from `AppTraces`.","Review notes":"Sampling yields statistical estimates and needs propagated trace context. Use sampling weights for represented request counts. An immutable configuration snapshot does not freeze the contents behind a versionless Key Vault reference."},"setId":"quizplay-set-3","reviewDate":"2026-10-11","reviewNote":"Sampling preserves correlated decisions only with correctly propagated context; counts are estimates."},{"id":"ai200-s3-12-gantrell-kql-argmax","prompt":"You must build the Gantrell operations dashboard query: from `AppTraces`, return **one row per property** — the most recent valuation trace for that property, with **all** of its columns. The property identifier is in `Properties.propertyId`.\n\nWhich KQL query should you use?","explanation":"`arg_max(TimeGenerated, *)` is the KQL aggregation built for \"latest row per group\": within each `by propertyId` group it finds the row with the maximum `TimeGenerated` and, because of the `*`, returns **that entire row** — every column, exactly as the dashboard needs. The `extend ... tostring(Properties.propertyId)` first materializes the grouping key from the dynamic `Properties` column, since dynamic sub-properties must be converted to a scalar type to be used in `by`.\n\n**Why not the other options:**\n- **`summarize max(TimeGenerated) by propertyId`** — Returns only two columns: the property ID and a timestamp. `max()` aggregates a single value; it does not carry along the rest of the winning row, so the valuation status, message, and other columns are lost.\n- **`order by ... | take 1`** — Sorts the *whole table* and keeps a single row overall — the most recent trace in the entire system, for one property. The dashboard needs the most recent row for **each** property.\n- **`distinct propertyId, Message`** — Returns every unique combination of property and message with no notion of recency: old and new valuations for the same property all appear, and all other columns are dropped.","domain":"operations","source":"https://learn.microsoft.com/en-us/kusto/query/arg-max-aggregation-function","practiceSource":"https://github.com/quizplay-io/quiz-player-quizzes-ai-200-question-set-3/blob/b158ee5f8717ecd671bf6ea2b748cf09e83e048b/questions/12-gantrell-kql-argmax.json","type":"single","options":["AppTraces\n| extend propertyId = tostring(Properties.propertyId)\n| summarize arg_max(TimeGenerated, *) by propertyId","AppTraces\n| extend propertyId = tostring(Properties.propertyId)\n| summarize max(TimeGenerated) by propertyId","AppTraces\n| extend propertyId = tostring(Properties.propertyId)\n| order by TimeGenerated desc\n| take 1","AppTraces\n| extend propertyId = tostring(Properties.propertyId)\n| distinct propertyId, Message"],"answer":0,"caseId":"quizplay:case_study_gantrell_property","caseTitle":"Gantrell Property","caseData":{"Company Overview":"**Gantrell Property Group** runs an AI-assisted property-valuation platform. A Python scoring service produces automated valuations; every valuation run emits structured telemetry.\n\n**Current Environment:**\n- Application settings and model-tuning parameters (about 40 related keys such as `Valuation:ModelVersion`, `Valuation:ComparableRadiusKm`, `Valuation:ConfidenceFloor`) live in **Azure App Configuration**. The keys are tuned together: a change to one usually requires coordinated changes to several others.\n- All services are instrumented with the **Azure Monitor OpenTelemetry distro** (`azure-monitor-opentelemetry`) and send telemetry to a workspace-based **Application Insights** resource.\n- The valuation service logs one structured trace per completed valuation to `AppTraces`, with the property identifier in the `Properties` dynamic column (`Properties.propertyId`) alongside the valuation status.","Requirements":"**Configuration Requirements:**\n- A release must promote **exactly** the set of App Configuration key-values that was tested in staging — all 40 keys as one immutable, named unit. Rolling back must restore exactly the previous unit. Individual keys continuing to change in the store must not affect what already-released instances load.\n\n**Telemetry Cost Requirements:**\n- The platform now handles ~40 million requests per day and Application Insights ingestion cost has become unacceptable. Ingested trace volume must be cut to roughly **10%**, while request **counts and failure rates shown in Application Insights experiences must remain statistically accurate**, and sampled requests must keep their full end-to-end traces.\n\n**Operations Requirements:**\n- An operations dashboard must show, for **each property**, only the **most recent** valuation trace row (all of its columns), derived from `AppTraces`.","Review notes":"Sampling yields statistical estimates and needs propagated trace context. Use sampling weights for represented request counts. An immutable configuration snapshot does not freeze the contents behind a versionless Key Vault reference."},"setId":"quizplay-set-3","reviewDate":"2026-10-11","reviewNote":"Answer and explanation reviewed against the linked product documentation."},{"id":"ai200-s3-13-acr-import-image","prompt":"Orrinbay Freight's policy requires that every image its Container Apps and AKS workloads run is pulled from the company registry `orrinbayacr`. The team needs the vendor-published image `docker.io/vexlorn/ocr-engine:2.4` available in that registry. The CI agents have **no Docker daemon**, and the image must not be rebuilt — the vendor's exact bits must be used.\n\nWhat should you do?","explanation":"`az acr import` performs a **server-side copy**: the registry service itself pulls the image from the source (Docker Hub, MCR, or another ACR) and stores it under your repository and tag. No Docker daemon, no local pull/push through the CI agent, no rebuild — the manifest and layers arrive byte-for-byte identical to what the vendor published, satisfying both the \"exact bits\" and the \"no daemon\" constraints in one command.\n\n**Why not the other options:**\n- **`docker pull` / `tag` / `push`** — Requires a local Docker daemon on the agent, which the scenario rules out; it also funnels every layer down to the agent and back up, which is slower and adds an unnecessary intermediary.\n- **`az acr build`** — ACR Tasks *builds a new image from a Dockerfile and build context* in the cloud. There is no Dockerfile here, and any rebuild would produce new layers rather than the vendor's exact bits.\n- **Referencing Docker Hub directly** — Violates the stated policy that workloads pull only from `orrinbayacr`, and exposes production pulls to Docker Hub rate limiting and availability — the reasons such policies exist.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/container-registry/container-registry-import-images","practiceSource":"https://github.com/quizplay-io/quiz-player-quizzes-ai-200-question-set-3/blob/b158ee5f8717ecd671bf6ea2b748cf09e83e048b/questions/13-acr-import-image.json","type":"single","options":["az acr import --name orrinbayacr --source docker.io/vexlorn/ocr-engine:2.4 --image vexlorn/ocr-engine:2.4","docker pull docker.io/vexlorn/ocr-engine:2.4, then docker tag and docker push the image to orrinbayacr.azurecr.io","az acr build --registry orrinbayacr --image vexlorn/ocr-engine:2.4 .","Reference docker.io/vexlorn/ocr-engine:2.4 directly in the workload manifests and let each node pull it from Docker Hub."],"answer":0,"setId":"quizplay-set-3","reviewDate":"2026-10-11","reviewNote":"Answer and explanation reviewed against the linked product documentation."},{"id":"ai200-s3-14-aks-oomkilled","prompt":"An embedding service on AKS restarts every few minutes under load. `kubectl describe pod` shows:\n\n```text\nLast State:  Terminated\n  Reason:    OOMKilled\n  Exit Code: 137\n```\n\nThe container loads a large in-memory vector table at startup, and its Deployment sets `resources.limits.memory: \"2Gi\"`. You must stop the restarts.\n\nWhat should you do?","explanation":"Inspect the terminated container, memory working set and node events. For the described 2 GiB limit bottleneck, adjust requests and limits to the measured working set and ensure node capacity, or reduce memory use. Exit 137 alone only identifies SIGKILL; OOMKilled plus the resource evidence is needed to diagnose memory exhaustion.","domain":"containers","source":"https://kubernetes.io/docs/concepts/configuration/manage-resources-containers/","practiceSource":"https://github.com/quizplay-io/quiz-player-quizzes-ai-200-question-set-3/blob/b158ee5f8717ecd671bf6ea2b748cf09e83e048b/questions/14-aks-oomkilled.json","type":"single","options":["Measure the container's real working set and raise `resources.requests.memory` and `resources.limits.memory` in the Deployment to accommodate it, for example `limits.memory: \"8Gi\"`.","Increase `resources.limits.cpu` so the process finishes loading the vector table before the kernel intervenes.","Add a HorizontalPodAutoscaler so more replicas share the memory pressure.","Set the pod's `restartPolicy` to `Never` so Kubernetes stops killing the container."],"answer":0,"setId":"quizplay-set-3","reviewDate":"2026-10-11","reviewNote":"OOMKilled can also reflect node memory pressure; the example value is not a universal fix."},{"id":"ai200-s3-15-aca-exec-console","prompt":"A container app named `rag-api` returns wrong answers after a deployment, and you suspect the prompt-template files mounted into the container differ from what the release should contain. You need an **interactive shell inside a running replica** to list the mounted files and inspect environment variables — without redeploying or changing the image.\n\nWhich command should you use?","explanation":"`az containerapp exec` opens an interactive console session **inside a running replica** of a container app — the Container Apps equivalent of `kubectl exec`. With `--command /bin/sh` you get a shell where you can `ls` the mounted template directory, `cat` the files, and run `env` to inspect variables, all against the live replica and with no image change or redeploy. (With multiple replicas, add `--replica` to pick a specific one.)\n\n**Why not the other options:**\n- **`az containerapp logs show --follow`** — Streams the container's stdout/stderr. Useful, but it is read-only observation of what the app chooses to print; it cannot list mounted files or dump the environment interactively.\n- **`kubectl exec`** — Container Apps runs on managed infrastructure whose underlying Kubernetes API is **not exposed to you**: there is no kubeconfig for the environment, so `kubectl` has nothing to connect to. That is AKS tooling.\n- **Baking in an SSH server** — Requires exactly the rebuild/redeploy the question forbids, replaces the replica you wanted to inspect (destroying the evidence), and adds a long-lived remote-access daemon to a production image — a security regression for a one-off inspection the platform already supports.","domain":"containers","source":"https://learn.microsoft.com/en-us/azure/container-apps/container-console","practiceSource":"https://github.com/quizplay-io/quiz-player-quizzes-ai-200-question-set-3/blob/b158ee5f8717ecd671bf6ea2b748cf09e83e048b/questions/15-aca-exec-console.json","type":"single","options":["az containerapp exec --name rag-api --resource-group rg-ai --command /bin/sh","az containerapp logs show --name rag-api --resource-group rg-ai --follow","kubectl exec -it deploy/rag-api -- /bin/sh","Rebuild the image with an SSH server installed, expose port 22 through ingress, and connect with an SSH client."],"answer":0,"setId":"quizplay-set-3","reviewDate":"2026-10-11","reviewNote":"Answer and explanation reviewed against the linked product documentation."},{"id":"ai200-s3-16-ordering-dockerfile-cache","prompt":"Caldermere Insurance builds a Python FastAPI inference image in CI on every commit. Dependencies in `requirements.txt` change rarely; application source changes on almost every build. You must order the Dockerfile instructions so that a source-only change reuses the cached dependency layer instead of re-running `pip install`.\n\nPlace the instructions in the correct order.\nUse the project convention that the startup CMD is the final instruction.","explanation":"Docker's build cache is invalidated **top-down**: the first instruction whose input changes forces every later layer to rebuild. The ordering therefore runs from least- to most-frequently changing:\n\n1. **`FROM` + `WORKDIR`** — Every Dockerfile begins with the base image; `WORKDIR` establishes the path the later `COPY` and `RUN` instructions rely on.\n2. **`COPY requirements.txt .`** — Copy *only* the manifest, so the next layer's cache key depends on nothing but this one file.\n3. **`RUN pip install ...`** — The expensive step. Because its inputs are just the base layers and `requirements.txt`, a build where only source changed reuses this layer straight from cache.\n4. **`COPY src/ ./src/`** — The volatile source comes *after* the install; changing it invalidates only this cheap layer and the ones below it.\n5. **`CMD [...]`** — Metadata-only and effectively free; conventionally last, it defines how the final image starts.\n\n**Why not the other options:**\n- The classic mistake is a single `COPY . .` **before** `pip install` — then any source edit changes the copy layer's checksum, invalidating the install layer, and every CI build re-downloads and compiles all dependencies.\n- Installing dependencies before copying `requirements.txt` cannot work at all: the manifest is not yet in the build context's filesystem when `pip` runs.","domain":"containers","source":"https://docs.docker.com/build/cache/optimize/","practiceSource":"https://github.com/quizplay-io/quiz-player-quizzes-ai-200-question-set-3/blob/b158ee5f8717ecd671bf6ea2b748cf09e83e048b/questions/16-ordering-dockerfile-cache.json","type":"order","options":["Start from the base image and set the working directory: `FROM python:3.12-slim` and `WORKDIR /app`.","Copy only the dependency manifest: `COPY requirements.txt .`","Install the pinned dependencies: `RUN pip install --no-cache-dir -r requirements.txt`","Copy the application source: `COPY src/ ./src/`","Declare the startup command: `CMD [\"uvicorn\", \"src.main:app\", \"--host\", \"0.0.0.0\", \"--port\", \"8000\"]`"],"answer":["Start from the base image and set the working directory: `FROM python:3.12-slim` and `WORKDIR /app`.","Copy only the dependency manifest: `COPY requirements.txt .`","Install the pinned dependencies: `RUN pip install --no-cache-dir -r requirements.txt`","Copy the application source: `COPY src/ ./src/`","Declare the startup command: `CMD [\"uvicorn\", \"src.main:app\", \"--host\", \"0.0.0.0\", \"--port\", \"8000\"]`"],"setId":"quizplay-set-3","reviewDate":"2026-10-11","reviewNote":"Made the otherwise optional position of CMD explicit for deterministic grading."},{"id":"ai200-s3-17-multi-image-size","prompt":"A Python inference image has grown to 6.5 GB. Cold starts and scale-out on Azure Container Apps are slow because every new replica must pull the image. The model weights are already loaded at runtime from Blob Storage, so the size comes from the image itself.\n\nWhich **three** actions reduce the image size? (Select three.)","explanation":"Image size is determined by what ends up in the final image's layers, so the three effective levers are: a **multi-stage build**, which leaves compilers, headers, and build caches behind in the discarded builder stage; a **slim base image**, which drops hundreds of megabytes of OS packages the service never uses; and a **`.dockerignore`**, which keeps repository junk (git history, datasets, notebook checkpoints) out of the build context so a broad `COPY` cannot embed it in a layer.\n\n**Why not the other options:**\n- **`docker save` + gzip** — That compresses a local tarball export. Registry pushes and pulls already transfer layers compressed; the layers stored and pulled by Container Apps are unchanged, so cold-start pull time does not improve.\n- **Baking in the model weights** — Moves gigabytes *into* the image, making the pull that is already the bottleneck several times worse. Runtime loading from Blob Storage (or a volume) is the pattern that keeps images small and models independently versionable.\n- **More CPU/memory** — Image pull speed is dominated by image size and registry/network throughput, not by the replica's compute allocation. This raises cost without addressing the cause.","domain":"containers","source":"https://docs.docker.com/build/building/best-practices/","practiceSource":"https://github.com/quizplay-io/quiz-player-quizzes-ai-200-question-set-3/blob/b158ee5f8717ecd671bf6ea2b748cf09e83e048b/questions/17-multi-image-size.json","type":"multi","options":["Use a multi-stage build: compile wheels and install build tooling in a builder stage, then copy only the installed packages and application code into the final runtime stage.","Base the runtime stage on a slim image such as `python:3.12-slim` instead of the full `python:3.12` image.","Add a `.dockerignore` that excludes `.git`, test data, notebooks, and local caches so they never enter the build context or get swept into `COPY . .`.","Compress the image with `docker save` piped through gzip before pushing it to the registry.","Bake the model weights into the image as well, so replicas skip the Blob Storage download at startup.","Raise the container app's CPU and memory allocation so replicas can pull the image faster."],"answer":[0,1,2],"choose":3,"setId":"quizplay-set-3","reviewDate":"2026-10-11","reviewNote":"Answer and explanation reviewed against the linked product documentation."},{"id":"ai200-s3-18-cosmos-patch-item","prompt":"A service appends a turn to an existing messages array and increments tokensUsed in one Cosmos DB item. Concurrent callers must avoid a client-side read/replace race, and the update should send only changed fields. Which operation should it use?","explanation":"patch_item applies the add and incr operations atomically to one item, without a preliminary client read or resending the full item as the update payload. Up to 10 patch operations are allowed. Patch does not promise a significant RU reduction; measure request charges. Response-body behavior depends on SDK options, and cross-region array conflicts still need consideration.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/cosmos-db/partial-document-update-faq","practiceSource":"https://github.com/quizplay-io/quiz-player-quizzes-ai-200-question-set-3/blob/b158ee5f8717ecd671bf6ea2b748cf09e83e048b/questions/18-cosmos-patch-item.json","type":"single","options":["Use partial document update: `container.patch_item(item=doc_id, partition_key=session_id, patch_operations=[{\"op\": \"add\", \"path\": \"/messages/-\", \"value\": turn}, {\"op\": \"incr\", \"path\": \"/tokensUsed\", \"value\": turn_tokens}])`.","Keep the read-modify-replace flow but pass `etag` and `MatchConditions.IfNotModified` to `replace_item`, retrying in a loop on `412 Precondition Failed`.","Write a stored procedure that appends the message and increments the counter, and invoke it with `scripts.execute_stored_procedure`.","Call `upsert_item` with only the changed fields — Cosmos DB merges partial documents with the stored item automatically."],"answer":0,"setId":"quizplay-set-3","reviewDate":"2026-10-11","reviewNote":"Patch does not guarantee lower RU cost and the response may still include the document."},{"id":"ai200-s3-19-cosmos-autoscale","prompt":"A Cosmos DB container has variable demand below 40000 RU/s, with quiet periods below 4000 RU/s. You want the service to adjust provisioned throughput automatically while retaining a 40000 RU/s ceiling. What should you configure?","explanation":"Autoscale operates between 0.1 × Tmax and Tmax. Migrate the throughput type and separately verify or update the maximum. It does not remove hot-partition limits or prevent 429 responses above available capacity. Billing is based on the highest scaled throughput per hour, with per-partition/region behavior depending on dynamic autoscale settings.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/cosmos-db/provision-throughput-autoscale","practiceSource":"https://github.com/quizplay-io/quiz-player-quizzes-ai-200-question-set-3/blob/b158ee5f8717ecd671bf6ea2b748cf09e83e048b/questions/19-cosmos-autoscale.json","type":"single","options":["Migrate to autoscale, then configure and verify the autoscale maximum of 40000 RU/s; it scales between 4000 and 40000 RU/s.","Keep manual throughput and run a scheduled job that raises provisioned RU/s every morning and lowers it every evening.","Recreate the account in serverless mode so the container has no provisioned throughput at all.","Keep 4,000 RU/s provisioned and configure the SDK's retry policy to absorb 429s during peaks."],"answer":0,"setId":"quizplay-set-3","reviewDate":"2026-10-11","reviewNote":"Autoscale cannot solve demand above Tmax and migration does not set an arbitrary maximum by itself."},{"id":"ai200-s3-20-blob-lifecycle-tiers","prompt":"PDFs are read frequently for the first 90 days after their last modification and rarely thereafter. Automatically move them to cool at day 90, archive at day 180, and delete after the required five-year retention period has elapsed. Which storage feature handles tiering and eligible deletion?","explanation":"A Blob Storage lifecycle policy can filter raw-docs blobs and apply age-based cool, archive and delete actions. Cool remains online; archive requires rehydration. Align age conditions with the actual retention start and any legal holds. Lifecycle management is not immutable WORM protection, and five calendar years should not blindly be equated to 1825 days.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/storage/blobs/lifecycle-management-overview","practiceSource":"https://github.com/quizplay-io/quiz-player-quizzes-ai-200-question-set-3/blob/b158ee5f8717ecd671bf6ea2b748cf09e83e048b/questions/20-blob-lifecycle-tiers.json","type":"single","options":["Add a **lifecycle management policy** on the storage account that moves blobs in `raw-docs` to the cool tier 90 days after last modification, to the archive tier at 180 days, and deletes them after 5 years.","Upload every document directly to the archive tier so all documents get the cheapest storage price from day one.","Deploy a timer-triggered Azure Function that lists the container nightly and calls `set_standard_blob_tier` on blobs older than the thresholds.","Enable blob soft delete with a 5-year retention period so old documents stop incurring standard storage charges."],"answer":0,"setId":"quizplay-set-3","reviewDate":"2026-10-11","reviewNote":"Clarified retention origin and that lifecycle policies do not enforce immutable retention."},{"id":"ai200-s3-21-pgvector-operator-mismatch","prompt":"A retrieval service on Azure Database for PostgreSQL flexible server has this index:\n\n```sql\nCREATE INDEX ON chunks USING hnsw (embedding vector_cosine_ops);\n```\n\nThe embeddings were produced by a model whose similarity metric is **cosine**, but the query was written as:\n\n```sql\nSELECT id, content FROM chunks ORDER BY embedding \u003c-> $1 LIMIT 10;\n```\n\n`EXPLAIN` shows a sequential scan, and relevance is noticeably wrong. What should you do?","explanation":"Use \u003c=> for cosine distance with vector_cosine_ops. \u003c-> is L2 and \u003c#> is negative inner product, so they do not match that index. EXPLAIN confirms the plan: table size, filters and cost estimates can still favor a sequential scan even when the operator matches. For normalized vectors rankings may coincide, but the operator class must still match for index use.","domain":"data","source":"https://github.com/pgvector/pgvector","practiceSource":"https://github.com/quizplay-io/quiz-player-quizzes-ai-200-question-set-3/blob/b158ee5f8717ecd671bf6ea2b748cf09e83e048b/questions/21-pgvector-operator-mismatch.json","type":"single","options":["Change the query to use the cosine distance operator, which matches the index's operator class: `ORDER BY embedding \u003c=> $1`.","Rebuild the HNSW index with a larger `m` and `ef_construction` so it can also serve `\u003c->` queries.","Change the query to `ORDER BY embedding \u003c#> $1` to use the inner-product operator instead.","Normalize all stored vectors to unit length and keep `ORDER BY embedding \u003c-> $1`."],"answer":0,"setId":"quizplay-set-3","reviewDate":"2026-10-11","reviewNote":"An index-compatible operator makes HNSW eligible; the planner may still choose a sequential scan."},{"id":"ai200-s3-22-redis-token-counter","prompt":"Twelve API instances must record completed token usage without losing concurrent increments. Store a separate daily total per user and automatically clean up old totals in Azure Managed Redis. This question concerns accounting, not strict admission control. What should they do?","explanation":"Use a per-user, per-day key and atomic INCRBY. Set the TTL safely, for example with a transaction or script that also handles initialization. Reads use GET. INCRBY does not deduplicate retried requests, and a separate GET followed by a write cannot enforce a strict concurrent budget; that needs an atomic check/reservation and an idempotency strategy.","domain":"data","source":"https://redis.io/docs/latest/commands/incrby/","practiceSource":"https://github.com/quizplay-io/quiz-player-quizzes-ai-200-question-set-3/blob/b158ee5f8717ecd671bf6ea2b748cf09e83e048b/questions/22-redis-token-counter.json","type":"single","options":["Maintain one key per user per day, such as `tokens:{userId}:{yyyyMMdd}`: add usage with `INCRBY` (atomic on the server), set an expiration of about 48 hours when the key is created, and read the total with `GET`.","`GET` the user's counter, add the tokens in Python, and `SET` the new value back with the same key.","Keep the running totals in each instance's process memory and have a background task sum them into Redis every minute.","Add each request's token count as a member of a Redis set per user and compute the total by summing the members at read time."],"answer":0,"setId":"quizplay-set-3","reviewDate":"2026-10-11","reviewNote":"Separated atomic increments from strict quota admission, retries and expiry initialization."},{"id":"ai200-s3-23-multi-cosmos-chat-model","prompt":"You are designing the Azure Cosmos DB for NoSQL data model for an AI assistant. Conversations can run to thousands of turns; some turns include large tool outputs (multi-megabyte JSON or file content). The dominant query loads one conversation's recent turns. Avoid rewriting one ever-growing conversation item.\n\nWhich **three** design decisions should you make? (Select three.)","explanation":"Use a bounded item per turn, a conversation-based partition key for this access pattern, and Blob references for bulk payloads. Cosmos DB items have a 2 MB limit. Monitor hot logical partitions and storage limits; this design does not guarantee constant latency or unlimited growth for a single conversation. Partition or bucket further when measurements require it.","domain":"data","source":"https://learn.microsoft.com/en-us/azure/cosmos-db/partitioning-overview","practiceSource":"https://github.com/quizplay-io/quiz-player-quizzes-ai-200-question-set-3/blob/b158ee5f8717ecd671bf6ea2b748cf09e83e048b/questions/23-multi-cosmos-chat-model.json","type":"multi","options":["Store each turn as its **own item** that carries the conversation's ID, rather than appending turns to one ever-growing conversation document.","Partition the container on the conversation ID (for example `/conversationId`) so loading a conversation is a single-partition query.","Keep multi-megabyte tool outputs in Azure Blob Storage and store only a reference (URL and metadata) in the turn item.","Keep each conversation as one document holding a `turns` array, so the whole conversation is always read and written as a unit.","Partition the container on the calendar date of the message so each day's traffic is spread across a fresh partition.","Store large tool outputs inline in the item, compressed with gzip and base64-encoded to stay within limits."],"answer":[0,1,2],"choose":3,"setId":"quizplay-set-3","reviewDate":"2026-10-11","reviewNote":"Removed an unbounded write-performance guarantee."},{"id":"ai200-s3-24-matching-redis-structures","prompt":"For each Redis data structure, select the application requirement it best satisfies. One requirement is unused.","explanation":"Hash fits independently editable fields; Sorted set fits score-based ranking; List supports a simple FIFO backlog; Stream supports append-only entries, consumer groups and acknowledgements. The unused requirement is a single cached string with SET ... EX. A pop alone does not provide reliable job acknowledgement, and sorted-set range retrieval is O(log N + M), including returned members.","domain":"data","source":"https://redis.io/docs/latest/develop/data-types/","practiceSource":"https://github.com/quizplay-io/quiz-player-quizzes-ai-200-question-set-3/blob/b158ee5f8717ecd671bf6ea2b748cf09e83e048b/questions/24-matching-redis-structures.json","type":"matching","rows":["Hash","Sorted set","List","Stream"],"options":["Store the fields of a signed-in user's session (display name, tier, language) so individual fields can be read or updated without rewriting the rest","Maintain a live ranking of agents by resolved-ticket score with efficient top-10 queries","Hold a backlog of render jobs that workers pop in first-in, first-out order","Keep an append-only log of inference events that multiple consumer groups read independently, each acknowledging entries and able to replay from an ID","Cache a rendered answer string that must expire automatically one hour after it was written"],"answer":["Store the fields of a signed-in user's session (display name, tier, language) so individual fields can be read or updated without rewriting the rest","Maintain a live ranking of agents by resolved-ticket score with efficient top-10 queries","Hold a backlog of render jobs that workers pop in first-in, first-out order","Keep an append-only log of inference events that multiple consumer groups read independently, each acknowledging entries and able to replay from an ID"],"setId":"quizplay-set-3","reviewDate":"2026-10-11","reviewNote":"Adapted the matching orientation so all four targets are answerable and the fifth source remains a distractor."},{"id":"ai200-s3-25-servicebus-receive-mode","prompt":"A Python worker consumes invoice-processing jobs from an Azure Service Bus queue with:\n\n```python\nreceiver = client.get_queue_receiver(\n    queue_name=\"transcribe-jobs\",\n    receive_mode=ServiceBusReceiveMode.RECEIVE_AND_DELETE,\n)\n```\n\nWhen a worker crashes mid-job, that job is **gone** — it is never processed by any worker. Jobs must be processed at least once even if workers crash.\n\nWhat should you do?","explanation":"`RECEIVE_AND_DELETE` is **at-most-once** delivery: the broker deletes the message the moment it hands it over, so a crash between receive and completion destroys the only copy. `PEEK_LOCK` (the SDK default) is the **at-least-once** mode: the message stays in the queue under a time-limited lock while the worker processes it, and it is removed only when the worker explicitly calls `complete_message` after success. If the worker crashes, the lock simply expires and the broker makes the message available again for another worker — exactly the required behavior.\n\n**Why not the other options:**\n- **`try/except` + re-send** — An exception handler never runs when the process crashes, the VM dies, or the container is OOM-killed — precisely the failures described. The window between broker-side deletion and durable re-send is exactly where jobs vanish.\n- **Duplicate detection** — Deduplicates messages with the same `message_id` *on the send path*. It has no record of what consumers processed and cannot resurrect a message the broker already deleted on receive.\n- **`max_delivery_count`** — Counts *failed peek-lock delivery attempts* before dead-lettering. In RECEIVE_AND_DELETE mode every delivery succeeds from the broker's perspective (the handoff completed), so this setting never comes into play.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/service-bus-messaging/message-transfers-locks-settlement","practiceSource":"https://github.com/quizplay-io/quiz-player-quizzes-ai-200-question-set-3/blob/b158ee5f8717ecd671bf6ea2b748cf09e83e048b/questions/25-servicebus-receive-mode.json","type":"single","options":["Switch to `ServiceBusReceiveMode.PEEK_LOCK` and call `receiver.complete_message(msg)` only after the job has been fully processed; a crashed worker's lock expires and the broker redelivers the message.","Keep RECEIVE_AND_DELETE but wrap the processing code in `try/except` and re-send the message to the queue from the exception handler.","Turn on the duplicate-detection feature so the broker restores messages that were deleted but not processed.","Raise `max_delivery_count` on the queue so the broker attempts delivery more times before giving up."],"answer":0,"setId":"quizplay-set-3","reviewDate":"2026-10-11","reviewNote":"Answer and explanation reviewed against the linked product documentation."},{"id":"ai200-s3-26-eventhubs-consumer-groups","prompt":"Thornebridge Energy streams meter telemetry into an Azure Event Hub. Two independent applications read the stream: a real-time anomaly scorer and an archival service. Both were configured to read from the `$Default` consumer group with the same checkpoint container, and now each application receives only part of the stream — the two apps steal partitions and overwrite each other's checkpoints.\n\nWhat should you do?","explanation":"A **consumer group** is an independent *view* (cursor) over the same event stream — this is precisely the mechanism Event Hubs provides for multiple downstream applications. Instances *within* one consumer group cooperatively balance partitions and share checkpoints; two *different applications* in the same group therefore look like one scaled-out app and fight over partitions and offsets, which is the observed failure. With one group (and one checkpoint store) per application, each app independently reads 100% of the stream at its own pace, and scaling instances within an app keeps working as designed.\n\n**Why not the other options:**\n- **A second event hub with double-send** — Duplicates ingestion cost, forces every producer change, and creates two streams that can drift (one send succeeds, the other fails). Consumer groups exist so a single stream can be read many times.\n- **More partitions** — Partition count controls parallelism *within* a consumer group; both apps in `$Default` would still balance the (now larger) partition set between themselves and still each see only a subset. The problem is shared cursors, not partition scarcity.\n- **Service Bus queue** — A queue is *competing consumers*: each message is delivered to exactly one receiver, which is the very behavior to eliminate. (Topics/subscriptions would fan out, but abandon Event Hubs' high-throughput streaming, offset replay, and checkpointing that a telemetry pipeline relies on.)","domain":"services","source":"https://learn.microsoft.com/en-us/azure/event-hubs/event-hubs-features","practiceSource":"https://github.com/quizplay-io/quiz-player-quizzes-ai-200-question-set-3/blob/b158ee5f8717ecd671bf6ea2b748cf09e83e048b/questions/26-eventhubs-consumer-groups.json","type":"single","options":["Create a dedicated **consumer group** on the event hub for each application (for example `anomaly-scoring` and `archival`), give each its own checkpoint store, and have each app read through its own group.","Create a second event hub and change the producers to send every event to both hubs.","Double the event hub's partition count so there are enough partitions for both applications.","Replace the event hub with a Service Bus queue so both applications can receive the same messages."],"answer":0,"setId":"quizplay-set-3","reviewDate":"2026-10-11","reviewNote":"Answer and explanation reviewed against the linked product documentation."},{"id":"ai200-s3-27-durable-fanout-fanin","prompt":"Process approximately 500 contract sections in parallel, then aggregate their summaries after all activities complete. The workflow must recover after host restarts. Which Durable Functions pattern should you use?","explanation":"Fan-out/fan-in schedules section activities and waits for context.task_all before scheduling aggregation. Durable state supports replay and recovery. Activities have at-least-once execution, so both summarization side effects and final writes must be idempotent. Use a stable contract/result key rather than assuming exactly-once execution.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/durable-task/common/programming-model-overview","practiceSource":"https://github.com/quizplay-io/quiz-player-quizzes-ai-200-question-set-3/blob/b158ee5f8717ecd671bf6ea2b748cf09e83e048b/questions/27-durable-fanout-fanin.json","type":"single","options":["A Durable Functions **fan-out/fan-in** orchestration: the orchestrator schedules an activity per section with `tasks = [context.call_activity(\"summarize_section\", s) for s in sections]`, awaits `results = yield context.task_all(tasks)`, then calls the aggregation activity with the results.","An HTTP-triggered function that runs `asyncio.gather` over 500 coroutines, each summarizing one section, and aggregates the results before returning.","A queue-triggered function per section that increments a counter blob when done; a timer-triggered function polls the counter and runs the aggregation when it reaches 500.","A Durable Functions orchestration that calls `yield context.call_activity(\"summarize_section\", s)` for each section in a loop, then aggregates."],"answer":0,"setId":"quizplay-set-3","reviewDate":"2026-10-11","reviewNote":"Durable activity execution is at least once, so side effects need idempotency."},{"id":"ai200-s3-28-apim-rate-limit","prompt":"Partners call an inference API through Azure API Management, each with its own APIM subscription. GPU capacity behind the API is limited, so each partner subscription should be throttled at approximately **100 calls per minute**, with excess calls rejected as `429 Too Many Requests` — and the backend service must not be modified.\n\nWhat should you do?","explanation":"Apply the inbound rate-limit policy with calls=100 and renewal-period=60 to limit calls per subscription and return 429 on excess calls. Distributed counters can permit some overrun; this is not an exact global admission guarantee. Use rate-limit-by-key when the quota key differs from the subscription.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/api-management/rate-limit-policy","practiceSource":"https://github.com/quizplay-io/quiz-player-quizzes-ai-200-question-set-3/blob/b158ee5f8717ecd671bf6ea2b748cf09e83e048b/questions/28-apim-rate-limit.json","type":"single","options":["Add a rate-limiting policy to the API's inbound section, for example `\u003crate-limit calls=\"100\" renewal-period=\"60\" />`, which enforces the cap per subscription and returns 429 when it is exceeded.","Add a `\u003cvalidate-jwt>` policy to the inbound section so only tokens with an approved claim can call the API.","Add an `\u003cip-filter>` policy allowing only the partners' IP address ranges.","Implement a per-caller request counter in the backend API's middleware and return 429 from there."],"answer":0,"setId":"quizplay-set-3","reviewDate":"2026-10-11","reviewNote":"APIM distributed rate-limit enforcement is approximate."},{"id":"ai200-s3-29-ordering-eventhubs-checkpoint","prompt":"Windgale Mobility is building a Python consumer for an existing Azure Event Hub. The consumer must resume where it left off after restarts and share the partitions automatically when more instances are added. Nothing on the consuming side exists yet.\n\nPlace the steps in the correct order.","explanation":"The consumer group and checkpoint container are independent prerequisites and may be created in either order. Construct the client with both, process before checkpointing, then verify scaled-out consumers share ownership. A crash after processing but before checkpointing can replay an event, so processing must be idempotent.","domain":"services","source":"https://learn.microsoft.com/en-us/azure/event-hubs/event-processor-balance-partition-load","practiceSource":"https://github.com/quizplay-io/quiz-player-quizzes-ai-200-question-set-3/blob/b158ee5f8717ecd671bf6ea2b748cf09e83e048b/questions/29-ordering-eventhubs-checkpoint.json","type":"order","options":["Create both prerequisites: a dedicated consumer group and a blob container for checkpoint/ownership data.","Construct a BlobCheckpointStore and EventHubConsumerClient with that consumer group and checkpoint store.","Start receiving; process each event successfully before updating its checkpoint.","Add identical consumers in the same group and verify partition load balancing."],"answer":["Create both prerequisites: a dedicated consumer group and a blob container for checkpoint/ownership data.","Construct a BlobCheckpointStore and EventHubConsumerClient with that consumer group and checkpoint store.","Start receiving; process each event successfully before updating its checkpoint.","Add identical consumers in the same group and verify partition load balancing."],"setId":"quizplay-set-3","reviewDate":"2026-10-11","reviewNote":"Combined independent prerequisites so grading does not impose an arbitrary order."},{"id":"ai200-s3-30-servicebus-message-batch","prompt":"A nightly Python job must publish about 200,000 small notification messages to an Azure Service Bus queue. Sending them one `send_messages(msg)` call at a time takes over an hour. You must maximize send throughput **without ever exceeding the broker's maximum batch size**, regardless of individual message sizes.\n\nWhat should the sender code do?","explanation":"Fill a ServiceBusMessageBatch with add_message. When it is full, send it, create another, and retry the message that did not fit. Flush the final nonempty batch. If one message cannot fit an empty batch, handle it explicitly rather than repeatedly creating empty batches. Measure throughput; no fixed speedup is guaranteed.","domain":"services","source":"https://learn.microsoft.com/en-us/python/api/azure-servicebus/azure.servicebus.servicebusmessagebatch?view=azure-python","practiceSource":"https://github.com/quizplay-io/quiz-player-quizzes-ai-200-question-set-3/blob/b158ee5f8717ecd671bf6ea2b748cf09e83e048b/questions/30-servicebus-message-batch.json","type":"single","options":["Create batches with `batch = sender.create_message_batch()` and fill each with `batch.add_message(msg)`; when adding a message raises the batch-size error, send the current batch with `sender.send_messages(batch)` and start a new one.","Pass the whole list in one call — `sender.send_messages(list_of_200000_messages)` — and let the SDK transmit it as a single operation.","Spawn one thread per 1,000 messages, each with its own `ServiceBusClient`, and send the messages individually in parallel.","Gzip-compress each message body before sending so more messages fit within the hourly window."],"answer":0,"setId":"quizplay-set-3","reviewDate":"2026-10-11","reviewNote":"Included retrying the message that did not fit, final flush and single-message overflow."},{"id":"ai200-s3-31-user-assigned-identity","prompt":"Elmsgarth Analytics deploys a fleet of ~30 short-lived Container Apps jobs that are **deleted and recreated on every release**. All of them need the same access to one Key Vault and one Cosmos DB account. Requirements: role assignments are granted **once, in advance**, must **survive** job recreation, and must not be repeated per job or per release.\n\nHow should the jobs authenticate?","explanation":"The deciding factor is **lifecycle**. A user-assigned managed identity is a standalone Azure resource: it exists before any job does, its two role assignments are made exactly once, and deleting or recreating the jobs that reference it changes nothing — every recreated job reattaches the same identity and inherits the same, already-propagated permissions. Passing the identity's client ID to `DefaultAzureCredential` pins authentication to it even if a job later carries several identities.\n\n**Why not the other options:**\n- **System-assigned identity per job** — A system-assigned identity is created and destroyed **with its resource**. Every release deletes 30 identities and mints 30 new principal IDs, so the pipeline must re-grant roles each time (60 assignments per release), and jobs race RBAC propagation delays at startup — the exact churn the requirements forbid.\n- **App registration + client secret** — Reintroduces a credential to store, distribute to 30 jobs, rotate, and leak. Managed identities exist precisely so workloads running on Azure compute never handle a secret.\n- **Role assignment on the resource group** — Azure RBAC grants a scope's permissions to a *principal*; resources created in a group do not \"inherit\" rights to act — they still need an identity to act *as*. And granting broadly at group scope, even to a real principal, violates least privilege compared with two targeted assignments.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/container-apps/managed-identity","practiceSource":"https://github.com/quizplay-io/quiz-player-quizzes-ai-200-question-set-3/blob/b158ee5f8717ecd671bf6ea2b748cf09e83e048b/questions/31-user-assigned-identity.json","type":"single","options":["Create one **user-assigned managed identity**, grant it the Key Vault and Cosmos DB roles once, attach it to every job, and authenticate in code with `DefaultAzureCredential(managed_identity_client_id=\"\u003cclient-id>\")`.","Enable a **system-assigned managed identity** on each job and grant the roles to each identity as part of every release pipeline.","Create one Microsoft Entra app registration with a client secret, store the secret as a Container Apps secret on each job, and authenticate with `ClientSecretCredential`.","Grant the roles to the resource group so that any resource created inside it inherits the permissions."],"answer":0,"setId":"quizplay-set-3","reviewDate":"2026-10-11","reviewNote":"Answer and explanation reviewed against the linked product documentation."},{"id":"ai200-s3-32-keyvault-cryptography-client","prompt":"A service uses a Key Vault RSA key to encrypt short identifiers and decrypt them later. The private key must remain in Key Vault; access to the public key is permitted. Which SDK client should it use?","explanation":"Use CryptographyClient for the Key Vault key. Decryption uses the private key in the service; the client can perform public-key encryption locally. Do not claim all key material stays outside application memory. RSA only handles small payloads; use envelope encryption for larger data, and treat plaintext and ciphertext as sensitive.","domain":"operations","source":"https://learn.microsoft.com/en-us/python/api/azure-keyvault-keys/azure.keyvault.keys.crypto.cryptographyclient?view=azure-python","practiceSource":"https://github.com/quizplay-io/quiz-player-quizzes-ai-200-question-set-3/blob/b158ee5f8717ecd671bf6ea2b748cf09e83e048b/questions/32-keyvault-cryptography-client.json","type":"single","options":["Create a **key** in Key Vault and use `CryptographyClient` from `azure-keyvault-keys`: `crypto_client.encrypt(EncryptionAlgorithm.rsa_oaep_256, plaintext)` and `crypto_client.decrypt(...)` — the private-key operations execute inside the Key Vault service.","Store a symmetric key as a Key Vault **secret**, fetch it at startup with `SecretClient.get_secret()`, and run AES encryption locally with the `cryptography` package.","Create a Key Vault **certificate**, download it with its private key at startup, and use the private key for local encryption and decryption.","Derive an AES key at startup from a passphrase stored in App Configuration, so no key is ever stored anywhere."],"answer":0,"setId":"quizplay-set-3","reviewDate":"2026-10-11","reviewNote":"Restricted the non-exportability requirement to private key material; public-key operations can be local."},{"id":"ai200-s3-33-appinsights-availability-test","prompt":"Fennwick Marine's public chat endpoint `https://chat.fennwickmarine.example/healthz` must be probed **from outside Azure-hosted app code, from multiple geographic locations, every 5 minutes**; operations must be alerted when the endpoint fails to return `200 OK` within 30 seconds from two or more locations. No application code may be added or changed.\n\nWhat should you configure?","explanation":"**Standard availability tests** are Application Insights' built-in synthetic monitoring: the platform's own probes request your URL on the schedule you set, **from the test locations you pick around the world**, evaluating success criteria such as status code 200 and the 30-second timeout. Results land in the availability experience, and the associated metric alert supports exactly the required condition — fail when N or more locations fail — so operations get paged on real outside-in unavailability with zero code changes.\n\n**Why not the other options:**\n- **Log search alert on `AppRequests`** — `AppRequests` records traffic that *reached the app*. Quiet periods with no users look identical to outages, DNS/TLS/network failures in front of the app never appear at all, and there is no concept of probing from chosen geographies. It observes demand, not availability.\n- **Liveness probe** — Probes run *inside* the environment against the replica, exist to trigger restarts rather than notifications, and say nothing about whether the public URL is reachable from the internet (ingress, DNS, or certificate failures are invisible to them).\n- **Timer-triggered Function** — Hand-builds what the platform ships: you would maintain probe code, multi-region deployment (a function runs in *its* region, not several), storage, and alert plumbing forever. It also violates the spirit of \"no code\" by creating a new codebase to operate.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/azure-monitor/app/availability","practiceSource":"https://github.com/quizplay-io/quiz-player-quizzes-ai-200-question-set-3/blob/b158ee5f8717ecd671bf6ea2b748cf09e83e048b/questions/33-appinsights-availability-test.json","type":"single","options":["A **standard availability test** on the Application Insights resource with the URL, a 30-second timeout, a 5-minute frequency, and several test locations — plus its alert rule set to fire when two or more locations fail.","A log search alert on the `AppRequests` table that fires when no successful request to `/healthz` has been recorded in the last 5 minutes.","A liveness probe on the container app pointing at `/healthz` so the platform detects and restarts an unhealthy replica.","A timer-triggered Azure Function that requests the endpoint every 5 minutes and writes failures to a table monitored by an alert."],"answer":0,"setId":"quizplay-set-3","reviewDate":"2026-10-11","reviewNote":"Answer and explanation reviewed against the linked product documentation."},{"id":"ai200-s3-34-multi-otel-custom-metrics","prompt":"A Python service uses configure_azure_monitor(). It needs custom token-usage and call-count metrics with model attributes. Which three statements describe the OpenTelemetry metrics pipeline?","explanation":"Obtain a meter, create instruments, and record values with attributes. The distro exports custom metrics to Application Insights for analysis in customMetrics/AppMetrics. Exported histogram aggregates do not automatically preserve arbitrary percentiles. Dimensional metric alerts may require enabling dimensions, and high-cardinality tenant identifiers should be avoided or bounded.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/azure-monitor/app/opentelemetry-add-modify","practiceSource":"https://github.com/quizplay-io/quiz-player-quizzes-ai-200-question-set-3/blob/b158ee5f8717ecd671bf6ea2b748cf09e83e048b/questions/34-multi-otel-custom-metrics.json","type":"multi","options":["Obtain a meter with `meter = metrics.get_meter(__name__)` (from `opentelemetry.metrics`) and create instruments such as `meter.create_histogram(\"tokens_per_request\")` and `meter.create_counter(\"model_calls\")`.","Record measurements with attributes — for example `histogram.record(prompt_tokens + completion_tokens, {\"model\": model_name, \"tenant\": tenant_id})` — so charts and alerts can split and filter by those dimensions.","The recorded metrics are exported to Application Insights automatically and can be queried as custom metrics (the `customMetrics` collection, `AppMetrics` in a workspace) for dashboards and alert rules.","Custom metrics must be pushed by calling the Azure Monitor REST ingestion endpoint directly, because the distro exports only traces and logs.","Token counts should instead be embedded in trace message strings and parsed out with KQL string functions at query time, because OpenTelemetry metrics cannot carry numeric values with dimensions."],"answer":[0,1,2],"choose":3,"setId":"quizplay-set-3","reviewDate":"2026-10-11","reviewNote":"Removed unsupported histogram-percentile and automatic dimensional-alert guarantees."},{"id":"ai200-s3-35-kql-dcount-daily","prompt":"Request telemetry in the `AppRequests` table carries the conversation identifier in `Properties.sessionId`. Product management needs the number of **distinct conversations per day** over the last 30 days.\n\nWhich KQL query should you use?","explanation":"Two pieces do the work: `extend ... tostring(Properties.sessionId)` materializes the identifier from the dynamic `Properties` column as a scalar string, and `summarize dcount(sessionId) by bin(TimeGenerated, 1d)` counts **distinct** identifiers within each one-day bucket. `dcount()` is the distinct-count aggregation (a fast approximation suited to dashboards; `dcountif`/`count_distinct` exist for conditional or exact variants), and `bin(..., 1d)` supplies the per-day grouping — one row per day, each with that day's unique conversation count.\n\n**Why not the other options:**\n- **`count() by bin(...)`** — Counts *rows* (requests) per day, not unique conversations: a single chatty conversation with 500 requests inflates the day by 500. Distinctness is the entire point of the metric.\n- **`distinct sessionId | count`** — Collapses the whole 30-day window into one grand total. There is no per-day dimension left, so it cannot show the daily trend management asked for — and a conversation active on several days is counted once overall rather than once per active day.\n- **`count() by sessionId, bin(...)`** — Groups by *both* session and day, returning one row per conversation per day (with its request count) — thousands of rows, not a daily distinct total. It answers \"how many requests did each conversation make each day,\" a different question.","domain":"operations","source":"https://learn.microsoft.com/en-us/kusto/query/dcount-aggregation-function","practiceSource":"https://github.com/quizplay-io/quiz-player-quizzes-ai-200-question-set-3/blob/b158ee5f8717ecd671bf6ea2b748cf09e83e048b/questions/35-kql-dcount-daily.json","type":"single","options":["AppRequests\n| where TimeGenerated > ago(30d)\n| extend sessionId = tostring(Properties.sessionId)\n| summarize ActiveConversations = dcount(sessionId) by bin(TimeGenerated, 1d)","AppRequests\n| where TimeGenerated > ago(30d)\n| summarize ActiveConversations = count() by bin(TimeGenerated, 1d)","AppRequests\n| where TimeGenerated > ago(30d)\n| extend sessionId = tostring(Properties.sessionId)\n| distinct sessionId\n| count","AppRequests\n| where TimeGenerated > ago(30d)\n| extend sessionId = tostring(Properties.sessionId)\n| summarize ActiveConversations = count() by sessionId, bin(TimeGenerated, 1d)"],"answer":0,"setId":"quizplay-set-3","reviewDate":"2026-10-11","reviewNote":"Answer and explanation reviewed against the linked product documentation."},{"id":"ai200-s3-36-functions-keyvault-reference","prompt":"An Azure Functions app reads a third-party translation API key with `os.environ[\"TRANSLATE_API_KEY\"]`. Security now requires the key's value to be managed in Azure Key Vault instead of stored as a literal app setting and to be rotatable centrally — **without changing the application code**, which must keep reading the environment variable.\n\nWhat should you do?","explanation":"Enable managed identity, grant secret-read permission, and use a versionless Key Vault reference in the app setting. The platform resolves the secret into the environment variable, so the value is present in application memory. References normally refresh within 24 hours; force a reference refresh when needed. Updating a secret does not rotate the credential at its issuing service by itself.","domain":"operations","source":"https://learn.microsoft.com/en-us/azure/app-service/app-service-key-vault-references","practiceSource":"https://github.com/quizplay-io/quiz-player-quizzes-ai-200-question-set-3/blob/b158ee5f8717ecd671bf6ea2b748cf09e83e048b/questions/36-functions-keyvault-reference.json","type":"single","options":["Enable the function app's managed identity, grant it read access to the vault's secrets, and set the app setting to a Key Vault reference: `TRANSLATE_API_KEY = @Microsoft.KeyVault(SecretUri=https://\u003cvault>.vault.azure.net/secrets/translate-api-key/)`.","Add the key to the project's `local.settings.json` and publish the app so the setting travels with the deployment.","Replace the environment-variable read with a `SecretClient(vault_url, DefaultAzureCredential()).get_secret(\"translate-api-key\")` call at startup.","Move the key into Azure App Configuration as a plain key-value named `TRANSLATE_API_KEY` and connect the function app to the store."],"answer":0,"setId":"quizplay-set-3","reviewDate":"2026-10-11","reviewNote":"Resolved values exist in application memory; versionless references can refresh after a delay."}]};
